window.UA_ZH_MAP = {"UA04ST/IMS-1-014":{"name":"樱木真乃","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04ST/IMS-1-012":{"name":"风野灯织","effectText":"【登場時】『查看2張』自己卡組上面的卡片。將其中1張卡片放置在自己卡組的上面，其餘卡片依任意順序放置在下面。若自己場上有〈樱木真乃〉或〈八宫巡〉時，則替換成『查看5張』。","triggerText":""},"UA04ST/IMS-1-015":{"name":"樱木真乃","effectText":"【登場時】【攻擊時】選擇最多1張自己場上其他［特徵：illumination STARS］的卡片，在這個回合中，BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04ST/IMS-1-017":{"name":"八宫巡","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA04ST/IMS-1-011":{"name":"风野灯织","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"UA04ST/IMS-1-018":{"name":"八宫巡","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃x1】。","triggerText":""},"UA04ST/IMS-1-001":{"name":"七草羽月","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【黃x1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA04ST/IMS-1-028":{"name":"合體快照","effectText":"選擇1張對手前線BP5000以下的角色卡，【轉為休息】。若自己場上擁有不同卡片名稱［特徵：illumination STARS］的卡片有3種以上時，則替換成【使其退場】。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04ST/IMS-1-030":{"name":"七草羽月 援助","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA04ST/IMS-1-101":{"name":"大崎甘奈","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04ST/IMS-1-102":{"name":"大崎甜花","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04ST/IMS-1-103":{"name":"桑山千雪","effectText":"","triggerText":""},"UA04ST/IMS-1-104":{"name":"风野灯织","effectText":"【登場時】使最多1張自己場外能源需求3以下消耗AP 1的黃色角色卡以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04ST/IMS-1-105":{"name":"樱木真乃","effectText":"【突襲】〈樱木真乃〉置為活動，並可移動至前線\n【攻擊時】選擇最多1張自己場上其他［特徵：illumination STARS］的卡片，在這個回合中，BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04ST/IMS-1-106":{"name":"八宫巡","effectText":"若同一線上有〈樱木真乃〉或〈风野灯织〉時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【登場時】選擇最多1張對手前線BP4000以下的角色卡，轉為休息。下一次無法置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04ST/IMS-1-107":{"name":"绯田美琴","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA04ST/IMS-1-108":{"name":"七草日花","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA04ST/IMS-1-109":{"name":"283藝能經紀公司","effectText":"【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n【啟動主要】【轉為休息】 【使這張卡片退場】抽1張卡片。","triggerText":""},"UA04BT/IMS-1-002":{"name":"大崎甘奈","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-001":{"name":"七草羽月","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【黃×1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA04BT/IMS-1-003":{"name":"大崎甘奈","effectText":"【登場時】將最多2張自己場外的卡片放置在移除區。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-004":{"name":"大崎甘奈","effectText":"若自己場外的卡片在3張以下時，手牌中這張卡片的能源需求減少【黃×1】。\n【突襲】〈大崎甘奈〉置為活動，並可移動至前線\n【攻擊時】將最多2張自己場外的卡片放置在移除區。若自己場外的卡片0張時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-006":{"name":"大崎甜花","effectText":"【登場時】將最多2張自己場外的卡片放置在移除區，對手也將2張自身場外的卡片放置在移除區。","triggerText":""},"UA04BT/IMS-1-007":{"name":"大崎甜花","effectText":"【突襲】〈大崎甜花〉置為活動，並可移動至前線\n若自己場外的卡片在3張以下時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【登場時】將最多3張自己場外的卡片放置在移除區。若自己場外的卡片0張時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-005":{"name":"大崎甜花","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA04BT/IMS-1-008":{"name":"桑山千雪","effectText":"若對手場上有藍色或紅色卡片時，手牌中這張卡片的能源需求減少【黃×1】。","triggerText":""},"UA04BT/IMS-1-009":{"name":"桑山千雪","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA04BT/IMS-1-010":{"name":"桑山千雪","effectText":"【登場時】選擇最多1張對手前線的角色卡，轉為休息。下一次無法置為活動。將最多2張自己場外的卡片放置在移除區。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA04BT/IMS-1-011":{"name":"风野灯织","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"UA04BT/IMS-1-012":{"name":"风野灯织","effectText":"【登場時】『查看2張』自己卡組上面的卡片。將其中1張卡片放置在自己卡組的上面，其餘卡片依任意順序放置在下面。若自己場上有〈樱木真乃〉或〈八宫巡〉時，則替換成『查看5張』。","triggerText":""},"UA04BT/IMS-1-013":{"name":"风野灯织","effectText":"【突襲】〈风野灯织〉置為活動，並可移動至前線\n【攻擊時】公開1張自己卡組上面的卡片。若公開的卡片為［特徵：illumination STARS］時，將該張卡片加入手牌。若公開的卡片為［特徵：illumination STARS］以外的卡片時，放置在自己卡組的上面或下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-015":{"name":"樱木真乃","effectText":"【登場時】【攻擊時】選擇最多1張自己場上其他［特徵：illumination STARS］的卡片，在這個回合中，BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-016":{"name":"樱木真乃","effectText":"若自己場上有〈风野灯织〉時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n若自己場上有〈八宫巡〉時，這張角色卡獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA04BT/IMS-1-014":{"name":"樱木真乃","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-017":{"name":"八宫巡","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-020":{"name":"绯田美琴","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-021":{"name":"绯田美琴","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n若自己場上的角色卡的特徵有3種以上時，手牌中這張卡片的能源需求減少【黃×3】。","triggerText":""},"UA04BT/IMS-1-019":{"name":"八宫巡","effectText":"【突襲】〈八宫巡〉置為活動，並可移動至前線\n【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將放置在移除區而非退場。\n【登場時】這張角色卡在這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-022":{"name":"绯田美琴","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】若自己場上其他的角色卡的特徵有3種以上時，選擇最多1張對手前線BP3500以下的角色卡，使其退場。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA04BT/IMS-1-023":{"name":"七草日花","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-024":{"name":"七草日花","effectText":"【登場時】使最多1張自己手牌中能源需求2以下消耗AP1的黃色角色卡以休息狀態在自己場上登場。","triggerText":""},"UA04BT/IMS-1-025":{"name":"七草日花","effectText":"【突襲】〈七草日花〉置為活動，並可移動至前線\n若自己場上有〈绯田美琴〉時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【登場時】若自己場上其他的角色卡的特徵有3種以上時，抽2張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-018":{"name":"八宫巡","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃×1】。","triggerText":""},"UA04BT/IMS-1-027":{"name":"壓垮","effectText":"查看5張自己卡組上面的卡片。公開其中［特徵：SHHis］的卡片和擁有「SHHis」特徵以外的卡片最多各1張並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-028":{"name":"合體快照","effectText":"選擇1張對手前線BP5000以下的角色卡，【轉為休息】。若自己場上擁有不同卡片名稱［特徵：illumination STARS］的卡片有3種以上時，則替換成【使其退場】。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04BT/IMS-1-029":{"name":"這太恐怖了吧好可怕","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上擁有不同卡片名稱［特徵：SHHis］的卡片有2種以上時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04BT/IMS-1-030":{"name":"七草羽月 援助","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA04BT/IMS-1-031":{"name":"初風Nostalgia","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：ALSTROEMERIA］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-032":{"name":"滿開，美味百合水仙","effectText":"將最多3張自己場外的卡片放置在移除區。選擇最多1張對手前線『BP3000以下』的角色卡，將選擇的角色卡和這張卡片放置在移除區。若自己場上擁有不同卡片名稱［特徵：ALSTROEMERIA］的卡片有3種以上時，則替換成『BP4000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04BT/IMS-1-033":{"name":"七草羽月","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【藍×1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA04BT/IMS-1-034":{"name":"白瀨咲耶","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：L'Antica］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA04BT/IMS-1-035":{"name":"白瀨咲耶","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-036":{"name":"白瀨咲耶","effectText":"【突襲】〈白瀨咲耶〉置為活動，並可移動至前線\n【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）\nBP2500以上的角色卡無法以【狙擊】指定這張角色卡。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-037":{"name":"田中摩美美","effectText":"若對手場上有黃色或紅色卡片時，手牌中這張卡片的能源需求減少【藍×1】。","triggerText":""},"UA04BT/IMS-1-038":{"name":"田中摩美美","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-039":{"name":"田中摩美美","effectText":"【登場時】選擇最多1張對手前線BP2500以下的角色卡，放置在對手卡組的上面或下面。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA04BT/IMS-1-040":{"name":"月冈恋钟","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-041":{"name":"月冈恋钟","effectText":"【登場時】選擇最多1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":""},"UA04BT/IMS-1-042":{"name":"月冈恋钟","effectText":"【突襲】〈月冈恋钟〉置為活動，並可移動至前線\nBP2000以下的角色卡不能防禦這張角色卡。\n這張角色卡攻擊後沒有被防禦時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-043":{"name":"三峰结华","effectText":"【對方回合中】這張角色卡BP+1000。","triggerText":""},"UA04BT/IMS-1-045":{"name":"三峰结华","effectText":"【突襲】〈三峰结华〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【攻擊時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-046":{"name":"幽谷霧子","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA04BT/IMS-1-047":{"name":"幽谷霧子","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍×1】。","triggerText":""},"UA04BT/IMS-1-048":{"name":"幽谷霧子","effectText":"【登場時】抽1張卡片。選擇最多1張自己場上［特徵：L'Antica］的卡片，下一個對方回合中，BP+3000。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-049":{"name":"浅仓透","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-050":{"name":"浅仓透","effectText":"【登場時】可以將1張自己手牌中［特徵：noctchill］的卡片放置在場外。若有執行此動作時，選擇最多1張自己的AP卡，置為活動。","triggerText":""},"UA04BT/IMS-1-051":{"name":"浅仓透","effectText":"【突襲】〈浅仓透〉置為活動，並可移動至前線\n【對方回合中】若同一線上有〈樋口圓香〉時，對手無法使用角色卡效果或事件卡效果選擇這張角色卡。\n【攻擊時】在這個回合中若自己使用了4張以上手牌中的卡片時，這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-052":{"name":"市川雏菜","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-054":{"name":"市川雏菜","effectText":"若同一線上有〈福丸小糸〉時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【登場時】選擇最多1張對手前線BP4000以下的角色卡，放回手牌。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA04BT/IMS-1-055":{"name":"樋口圆香","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA04BT/IMS-1-053":{"name":"市川雏菜","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA04BT/IMS-1-056":{"name":"樋口圆香","effectText":"【登場時】抽1張卡片。","triggerText":""},"UA04BT/IMS-1-044":{"name":"三峰结华","effectText":"【登場時】選擇最多1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":""},"UA04BT/IMS-1-026":{"name":"I'm coming soon","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：illumination STARS］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-058":{"name":"福丸小糸","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-059":{"name":"福丸小糸","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：noctchill］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA04BT/IMS-1-057":{"name":"樋口圆香","effectText":"【突襲】〈樋口圓香〉置為活動，並可移動至前線\n【登場時】在這個回合中若自己使用了3張以上手牌中其他的卡片時，抽3張卡片，並將1張自己的手牌放置在場外。\n【退場時】若同一線上有〈浅仓透〉時，選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-060":{"name":"福丸小糸","effectText":"【突襲】〈福丸小糸〉置為活動，並可移動至前線\n這張角色卡攻擊後被防禦時，抽1張卡片。\n【退場時】若同一線上有〈市川雏菜〉時，將【突襲】狀態的這張角色卡最下面的卡片放回手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-061":{"name":"轟飛黨的漫漫長夏","effectText":"選擇1張對手前線BP5000以下的角色卡，『放回手牌』。若自己場上擁有不同卡片名稱［特徵：noctchill］的卡片有3種以上時，則替換成『放置在對手卡組下面』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04BT/IMS-1-062":{"name":"SIDE：K","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上擁有不同卡片名稱［特徵：L'Antica］的卡片有3種以上時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04BT/IMS-1-063":{"name":"七草羽月 援助","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA04BT/IMS-1-064":{"name":"走馬燈","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：noctchill］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-066":{"name":"faaaar","effectText":"抽1張卡片，並將1張自己的手牌放置在場外。選擇最多1張自己的AP卡，置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-067":{"name":"玩弄by♡time","effectText":"選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-065":{"name":"玫瑰色和聲","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：L'Antica］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-068":{"name":"七草羽月","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紅×1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA04BT/IMS-1-069":{"name":"和泉愛依","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-072":{"name":"芹沢朝日","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-073":{"name":"芹沢朝日","effectText":"【我方回合中】在這個回合中自己每使用1張事件卡，這張角色卡BP+1000。","triggerText":""},"UA04BT/IMS-1-070":{"name":"和泉愛依","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅×1】。","triggerText":""},"UA04BT/IMS-1-071":{"name":"和泉愛依","effectText":"【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，『抽1張卡片』。若使用這個效果放置在場外的卡片為事件卡時，則替換成『抽3張卡片』。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA04BT/IMS-1-075":{"name":"黛冬优子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA04BT/IMS-1-074":{"name":"芹沢朝日","effectText":"【突襲】〈芹沢朝日〉置為活動，並可移動至前線\n【我方回合中】在這個回合中自己每使用1張事件卡，這張角色卡BP+1000。\n依據這張角色卡的BP，這張角色卡獲得以下全數效果。\n・BP4000以上：【攻擊時】抽1張卡片。\n・BP5000以上：【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-076":{"name":"黛冬优子","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張紅色事件卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA04BT/IMS-1-077":{"name":"黛冬优子","effectText":"【突襲】〈黛冬优子〉置為活動，並可移動至前線\n【登場時】將自己場外任意張數的事件卡放置在移除區，選擇最多1張對手前線BP是該張數×1000以下的角色卡，使其退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-079":{"name":"有栖川夏叶","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA04BT/IMS-1-078":{"name":"有栖川夏叶","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA04BT/IMS-1-080":{"name":"有栖川夏叶","effectText":"【登場時】選擇最多1張自己場上［特徵：放學後CLIMAX GIRLS］的卡片，在這個回合中，獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA04BT/IMS-1-081":{"name":"小宮果穗","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-082":{"name":"小宮果穗","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-083":{"name":"小宮果穗","effectText":"【突襲】〈小宮果穗〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【攻擊時】若同一線上沒有其他休息狀態的角色卡時，這張角色卡在這個回合中，BP+500和獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-084":{"name":"西城树里","effectText":"若對手場上有黃色或藍色卡片時，手牌中這張卡片的能源需求減少【紅×1】。","triggerText":""},"UA04BT/IMS-1-085":{"name":"西城树里","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：放學後CLIMAX GIRLS］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA04BT/IMS-1-086":{"name":"西城树里","effectText":"【突襲】〈西城树里〉置為活動，並可移動至前線\n【攻擊時】若同一線上沒有其他休息狀態的角色卡時，這張角色卡在這個回合中，BP+1000和獲得【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA04BT/IMS-1-087":{"name":"园田智代子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA04BT/IMS-1-088":{"name":"园田智代子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【若在能源線時】自己的攻擊階段結束時，可以將這張角色卡移動至前線。","triggerText":""},"UA04BT/IMS-1-089":{"name":"园田智代子","effectText":"【突襲】〈园田智代子〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【若在能源線時】【每回合1】自己場上的角色卡攻擊時，選擇1張自己前線進行攻擊以外的角色卡，可以和這張角色卡互相交換位置。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-092":{"name":"杜野凜世","effectText":"【突襲】〈杜野凜世〉置為活動，並可移動至前線\n【攻擊時】若同一線上沒有其他休息狀態的角色卡時，使最多1張自己手牌中能源需求3以下消耗AP1擁有「放學後CLIMAX GIRLS」特徵的角色卡以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA04BT/IMS-1-093":{"name":"King and Hero","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+2000。選擇最多1張對手前線『BP2000以下』的角色卡，使其退場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-091":{"name":"杜野凜世","effectText":"【登場時】抽1張卡片。","triggerText":""},"UA04BT/IMS-1-094":{"name":"Good Luck Ball","effectText":"若對手的生命值在3以上時，造成對手玩家1傷害。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-095":{"name":"捲捲蓬蓬・圍巾×２","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：放學後CLIMAX GIRLS］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-096":{"name":"不熟悉的非日常","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：Straylight］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-098":{"name":"No墨・勝者face","effectText":"選擇最多1張對手前線『BP2000以下』的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。若自己場上擁有不同卡片名稱［特徵：Straylight］的卡片有3種以上時，則替換成『BP4000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA04BT/IMS-1-099":{"name":"肚子餓了就玩不下去","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。選擇最多1張自己的AP卡，置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-090":{"name":"杜野凜世","effectText":"【登場時】選擇最多1張自己場上其他［特徵：放學後CLIMAX GIRLS］的卡片，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA04BT/IMS-1-100":{"name":"燃起反擊的狼煙！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上擁有不同卡片名稱［特徵：放學後CLIMAX GIRLS］的卡片有3種以上時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX03BT/IMS-2-001":{"name":"大崎甘奈","effectText":"【啟動主要】【轉為休息】只有自己場外的卡片在3張以下時才可以發動。選擇1張自己場上其他［特徵：ALSTROEMERIA］的卡片，在這個回合中，『BP+500』。若自己場外的卡片0張時，則替換成『BP+1000』。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-003":{"name":"桑山千雪","effectText":"【啟動主要】【轉為休息】將1張自己場外的卡片放置在移除區。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-004":{"name":"桑山千雪","effectText":"【啟動主要】【若在前線時】【轉為休息】只有自己場外的卡片0張時才可以發動。選擇1張對手前線BP5000以下的角色卡，將選擇的角色卡和這張角色卡放置在移除區。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-005":{"name":"风野灯织","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-002":{"name":"大崎甜花","effectText":"【我方回合中】若自己場外的卡片0張時，這張角色卡BP+1500。","triggerText":""},"EX03BT/IMS-2-006":{"name":"风野灯织","effectText":"【我方回合中】若自己場上有〈樱木真乃〉和〈八宫巡〉時，這張角色卡BP+500。\n【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：illumination STARS］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。在這個回合中，接下來使用手牌中的〔〈樱木真乃〉或〈八宫巡〉〕的消耗AP-1。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-007":{"name":"樱木真乃","effectText":"【登場時】自己場上的角色卡全數，在這個回合中，BP+500。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX03BT/IMS-2-008":{"name":"樱木真乃","effectText":"【突襲】〈樱木真乃〉置為活動，並可移動至前線\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【我方回合中】若自己場上有〈风野灯织〉時，這張角色卡BP+500。\n【攻擊時】若自己場上有〈八宫巡〉時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+500。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-009":{"name":"八宫巡","effectText":"【若在前線時】對手使用手牌中的事件卡效果，不能選擇自己場上〈八宫巡〉以外的角色卡。","triggerText":""},"EX03BT/IMS-2-010":{"name":"八宫巡","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】可以將1張自己前線活動的角色卡轉為休息。若有執行此動作時，選擇最多1張自己場上其他［特徵：illumination STARS］的卡片，置為活動。","triggerText":""},"EX03BT/IMS-2-011":{"name":"绯田美琴","effectText":"【突襲】〈绯田美琴〉置為活動，並可移動至前線\n【登場時】若自己場上有〈七草日花〉時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+2000。\n【攻擊時】【每回合1】若自己場上其他的角色卡的特徵有3種以上時，選擇〈绯田美琴〉以外〔自己前線的角色卡和自己能源線的角色卡〕各1張，可以互相交換位置。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX03BT/IMS-2-012":{"name":"七草日花","effectText":"【登場時】可以將1張自己手牌中［特徵：SHHis］的卡片放置在場外。若有執行此動作時，查看4張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-013":{"name":"七草日花","effectText":"若自己場上有〈283藝能經紀公司〉時，這張角色卡獲得「這張角色卡在前線時也能產生能源。」和「【我方回合中】這張角色卡BP+500。」。\n【登場時】查看7張自己卡組上面的卡片。公開其中最多1張能源需求1以下消耗AP1的〔角色卡或場域卡〕『並加入手牌』。其餘卡片依任意順序放置在自己卡組下面。若公開的卡片滿足能源需求時，也可以替換成『並以休息狀態在自己場上登場』。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX03BT/IMS-2-014":{"name":"白瀨咲耶","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA04BT/IMS-1-097":{"name":"七草羽月 援助","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"EX03BT/IMS-2-015":{"name":"田中摩美美","effectText":"【登場時】若自己場上其他［特徵：L'Antica］的卡片有4張以上時，選擇最多1張自己場上［特徵：L'Antica］的卡片，在這個回合中，獲得【衝擊（+1）】（衝擊效果造成的傷害+1，若未持有衝擊時，則獲得【衝擊（1）】）。","triggerText":""},"EX03BT/IMS-2-016":{"name":"月冈恋钟","effectText":"【登場時】若對手場上有BP低於原始BP的角色卡時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-017":{"name":"三峰结华","effectText":"【啟動主要】【若在前線時】【將1張手牌放置場外】【每回合1】選擇1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX03BT/IMS-2-018":{"name":"幽谷霧子","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】選擇1張對手場上BP2500以上的角色卡，在這個回合中，BP-2000。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-019":{"name":"幽谷霧子","effectText":"【突襲】〈幽谷霧子〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得「【攻擊時】【每回合1】選擇最多1張對手前線BP低於原始BP的角色卡，使其退場。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-020":{"name":"浅仓透","effectText":"【我方回合中】在這個回合中若自己使用了4張以上手牌中的卡片時，這張角色卡BP+2000。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX03BT/IMS-2-021":{"name":"市川雏菜","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-022":{"name":"市川雏菜","effectText":"【突襲】〈市川雏菜〉置為活動，並可移動至前線\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【每回合1】自己場上其他［特徵：noctchil］的卡片全數，在這個回合中，BP+500。選擇最多1張自己場上的〈福丸小糸〉，在這個回合中，獲得｢【每回合1】這張角色卡攻擊後沒有被防禦時，抽1張卡片。｣。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-024":{"name":"樋口圆香","effectText":"【攻擊時】在這個回合中若自己使用了4張以上手牌中的卡片時，選擇最多1張自己場上［特徵：noctchil］的卡片，在這個回合中，獲得【傷害（+1）】（這張角色卡的攻擊直接造成傷害時，追加1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-025":{"name":"福丸小糸","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX03BT/IMS-2-026":{"name":"福丸小糸","effectText":"【登場時】可以將1張自己場上其他［特徵：noctchil］的卡片放置在自己卡組下面。若有執行此動作時，抽1張卡片，在這個回合中，接下來使用手牌中的〈市川雏菜〉的消耗AP-1。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-027":{"name":"七草羽月","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紫×1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"EX03BT/IMS-2-028":{"name":"大崎甘奈","effectText":"【登場時】抽1張卡片。","triggerText":""},"EX03BT/IMS-2-029":{"name":"大崎甘奈","effectText":"【退場時】將最多2張自己卡組上面的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-031":{"name":"大崎甜花","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-032":{"name":"大崎甜花","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：ALSTROEMERIA］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX03BT/IMS-2-033":{"name":"大崎甜花","effectText":"【啟動主要】【若在前線時】【每回合1】將3張自己場外［特徵：ALSTROEMERIA］的卡片依任意順序放置在自己卡組下面。若有執行此動作時，選擇最多1張自己場上其他［特徵：ALSTROEMERIA］的卡片，在這個回合中，BP+1000和獲得【衝擊（+1）】（衝擊效果造成的傷害+1，若未持有衝擊時，則獲得【衝擊（1）】）。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX03BT/IMS-2-034":{"name":"大崎甜花","effectText":"【突襲】〈大崎甜花〉置為活動，並可移動至前線\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【登場時】可以將5張自己場外［特徵：ALSTROEMERIA］的卡片依任意順序放置在自己卡組下面。若有執行此動作時，抽2張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX03BT/IMS-2-035":{"name":"桑山千雪","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"EX03BT/IMS-2-036":{"name":"桑山千雪","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX03BT/IMS-2-030":{"name":"大崎甘奈","effectText":"【登場時】查看4張自己卡組上面的卡片。將其中最多3張擁有不同卡片名稱［特徵：ALSTROEMERIA］的卡片放置在場外。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-037":{"name":"桑山千雪","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-038":{"name":"桑山千雪","effectText":"【突襲】〈桑山千雪〉置為活動，並可移動至前線\n【登場時】可以將4張自己場外［特徵：ALSTROEMERIA］的卡片依任意順序放置在自己卡組下面。若有執行此動作時，這張角色卡在這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-040":{"name":"白瀨咲耶","effectText":"因為自己的效果將自己卡組中的這張卡片放置在場外時，可以將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求1以下消耗AP1的紫色［特徵：L'Antica］卡片以休息狀態在自己場上登場。","triggerText":""},"EX03BT/IMS-2-041":{"name":"田中摩美美","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-044":{"name":"月冈恋钟","effectText":"【退場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：L'Antica］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"EX03BT/IMS-2-045":{"name":"月冈恋钟","effectText":"【登場時】選擇以下1項。\n・將最多1張自己卡組上面的卡片放置在場外。\n・將最多1張自己場外［特徵：L'Antica］的卡片放置在自己卡組上面。","triggerText":""},"EX03BT/IMS-2-039":{"name":"白瀨咲耶","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫×1】。","triggerText":""},"EX03BT/IMS-2-046":{"name":"月冈恋钟","effectText":"因為自己的效果將自己卡組中的這張卡片放置在場外時，可以將自己場外的這張卡片加入手牌。\n【登場時】查看4張自己卡組上面的卡片。將其中最多1張卡片放置在場外。其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX03BT/IMS-2-042":{"name":"田中摩美美","effectText":"【登場時】查看3張自己卡組上面的卡片。將那些卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-047":{"name":"三峰结华","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-049":{"name":"三峰结华","effectText":"【突襲】〈三峰结华〉置為活動，並可移動至前線\n【登場時】查看5張自己卡組上面的卡片。使其中最多1張能源需求2以下消耗AP1的紫色［特徵：L'Antica］卡片以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。\n【每回合1】這張角色卡攻擊後沒有被防禦時，將最多1張自己卡組上面的卡片放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX03BT/IMS-2-048":{"name":"三峰结华","effectText":"因為自己的效果將自己卡組中的這張卡片放置在場外時，選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-050":{"name":"幽谷霧子","effectText":"因為自己的效果將自己卡組中的這張卡片放置在場外時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX03BT/IMS-2-023":{"name":"樋口圆香","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-052":{"name":"幽谷霧子","effectText":"【突襲】〈幽谷霧子〉置為活動，並可移動至前線\n若自己卡組的卡片在20張以下時，這張角色卡獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-053":{"name":"斑鳩琉夏","effectText":"無論產生能源的顏色皆可滿足手牌中這張卡片的能源需求。\n當對手要使用角色卡效果選擇這張角色卡時，只可以使用原始BP4000的角色卡效果選擇。\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，『BP-2000』。若自己場上有〈283藝能經紀公司〉時，則替換成『BP-4000』。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-054":{"name":"283藝能經紀公司","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-043":{"name":"田中摩美美","effectText":"【突襲】〈田中摩美美〉置為活動，並可移動至前線\n若自己卡組的卡片在20張以下時，這張角色卡獲得【衝擊（1）】。\n【攻擊時】可以將2張自己卡組上面的卡片放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，每有1張使用這個效果放置在場外的［特徵：L'Antica］卡片，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX03BT/IMS-2-055":{"name":"SIDE：Y","effectText":"選擇1張對手前線的角色卡，自己場上每有1張［特徵：L'Antica］的卡片，在這個回合中，BP-1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX03BT/IMS-2-051":{"name":"幽谷霧子","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張卡片放置在場外。其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-056":{"name":"Summer for Us","effectText":"抽3張卡片，並將2張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-059":{"name":"Magical＊Sky Race","effectText":"抽1張卡片。選擇對手前線的角色卡和對手能源線產生能源1以下的角色卡各1張，可以互相交換位置。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-057":{"name":"七草羽月 援助","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"EX03BT/IMS-2-058":{"name":"Noir","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上擁有不同卡片名稱［特徵：ALSTROEMERIA］的卡片有3種以上時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX03BT/IMS-2-060":{"name":"所以，是在說什麼～！？","effectText":"查看5張自己卡組上面的卡片。將其中1張卡片加入手牌，1張卡片放置在場外。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-061":{"name":"和泉愛依","effectText":"【突襲】〈和泉愛依〉置為活動，並可移動至前線\n【我方回合中】若自己場上擁有不同卡片名稱［特徵：Straylight］的卡片有3種以上時，這張角色卡BP+1000。\n【登場時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-062":{"name":"芹沢朝日","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-064":{"name":"芹沢朝日","effectText":"這張角色卡以活動狀態登場。\n【我方回合中】這張角色卡BP+1000。\n【若在前線時】自己的攻擊階段結束時，在這個回合中若自己沒有使用事件卡，使這張角色卡退場。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX03BT/IMS-2-063":{"name":"芹沢朝日","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX03BT/IMS-2-067":{"name":"有栖川夏叶","effectText":"【登場時】可以將1張自己場上〈有栖川夏叶〉以外［特徵：放學後CLIMAX GIRLS］的卡片放回手牌。若有執行此動作時，選擇最多1張自己場上［特徵：放學後CLIMAX GIRLS］的卡片，置為活動。〈有栖川夏叶〉的這個效果一回合只可以發動1次。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX03BT/IMS-2-066":{"name":"黛冬优子","effectText":"這張角色卡以活動狀態登場。\n【攻擊時】查看3張自己卡組上面的卡片。公開其中最多1張能源需求4以下的紅色〔［特徵：Straylight］卡片或事件卡〕並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX03BT/IMS-2-068":{"name":"小宮果穗","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+500。","triggerText":""},"EX03BT/IMS-2-070":{"name":"园田智代子","effectText":"【啟動主要】【每回合1】選擇1張自己前線［特徵：放學後CLIMAX GIRLS］的卡片，置為活動，並在這個回合中，獲得「這張角色卡無法進行攻擊。」。","triggerText":"[抽卡] 抽1張卡片。"},"EX03BT/IMS-2-069":{"name":"西城树里","effectText":"【登場時】選擇最多1張自己場上［特徵：放學後CLIMAX GIRLS］的卡片，在這個回合中，獲得「【每回合1】這張角色卡攻擊後戰勝時，將這張角色卡置為活動。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-072":{"name":"向月亮嚎叫吧","effectText":"選擇1張自己前線的角色卡，在這個回合中，BP+2000。若選擇的角色卡為［特徵：Straylight］的卡片時，在這個回合中，還可以獲得【衝擊（+1）】（衝擊效果造成的傷害+1，若未持有衝擊時，則獲得【衝擊（1）】）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX03BT/IMS-2-071":{"name":"杜野凜世","effectText":"【退場時】使最多1張自己手牌中能源需求3以下消耗AP1的紅色［特徵：放學後CLIMAX GIRLS］卡片以休息狀態在自己場上登場。","triggerText":""},"EX03BT/IMS-2-065":{"name":"黛冬优子","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紅×1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"EX03BT/IMS-2-073":{"name":"無敵的證明！五紋章！","effectText":"選擇1張自己場上［特徵：放學後CLIMAX GIRLS］的卡片，『在這個回合中』，BP+2000。若選擇的角色卡為〈小宮果穗〉時，則替換成『直到下一個我方回合開始前』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-001":{"name":"大崎甘奈","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：ALSTROEMERIA］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在移除區。\n【啟動主要】【若在前線時】【每回合1】僅限自己場外有3張以下卡片時可發動。選擇1張對手前線BP4500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-002":{"name":"大崎甜花","effectText":"【登場時】將最多3張自己場外的卡片放置在移除區。若自己場外沒有卡片時，抽1張卡片。\n【啟動主要】【轉為休息】將1張自己場外的卡片放置在移除區。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-004":{"name":"櫻木真乃","effectText":"【突襲】〈櫻木真乃〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的〈風野燈織〉或〈八宮巡〉，在這個回合中，獲得BP+500與【衝擊（1）】。\n【攻擊時】若自己前線有〈風野燈織〉與〈八宮巡〉時，將這張角色卡置為活動。〈櫻木真乃〉的這個效果每回合僅可發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-005":{"name":"八宮巡","effectText":"【突襲】〈八宮巡〉置為活動，並可移動至前線\n【登場時】從以下選擇『1項』。若自己場上有〈櫻木真乃〉與〈風野燈織〉時，則替換成『2項』。\n・抽1張卡片。\n・在這個回合中，下一張從手牌中使用〔〈櫻木真乃〉或〈風野燈織〉〕的消耗AP-1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-006":{"name":"風野燈織","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n若自己場上有〈櫻木真乃〉與〈八宮巡〉時，這張角色卡BP+500。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-007":{"name":"緋田美琴","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】僅限自己場上其他角色的特徵有3種以上時可發動。選擇1張自己場上［特徵：SHHis］以外的角色卡，在這個回合中，BP+2000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-003":{"name":"桑山千雪","effectText":"【突襲】〈桑山千雪〉置為活動，並可移動至前線\n【我方回合中】自己場上所有其他的［特徵：ALSTROEMERIA］，BP+500。\n【登場時】在這個回合中，下一張從手牌中使用能源需求4以下的［特徵：ALSTROEMERIA］，其消耗AP-1。\n【啟動主要】【每回合1】僅限在這張角色卡登場的回合中可發動。選擇1張自己場上能源需求4以下的［特徵：ALSTROEMERIA］，發動該張角色卡的【登場時】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-008":{"name":"七草日花","effectText":"【突襲】〈七草日花〉置為活動，並可移動至前線\n【登場時】查看7張自己卡組上面的卡片，使最多1張〈283演藝事務所〉或能源需求1以下的黃色角色卡以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【若在前線時】【每回合1】僅限自己場上其他角色的特徵有3種以上時可發動。所有對手前線BP1000以上的角色卡，在這個回合中，BP-500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-009":{"name":"展現自我風格","effectText":"查看6張自己卡組上面的卡片，公開其中最多1張能源需求2以下的黃色［特徵：ALSTROEMERIA］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。將這張卡片放置在移除區。若自己場外沒有卡片時，使最多1張自己手牌中能源需求1以下消耗AP1的黃色［特徵：ALSTROEMERIA］以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC01BT/IMS-3-011":{"name":"田中摩美美","effectText":"使這張角色卡以活動狀態登場。\n【登場時】這張角色卡在這個回合中，獲得「【攻擊時】選擇最多1張對手前線BP2000以下的角色卡，放回手牌。」。\n【啟動主要】【若在前線時】【每回合1】選擇1～2張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC01BT/IMS-3-012":{"name":"月岡戀鐘","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【我方回合中】若自己場上有2種以上不同卡片名稱的其他［特徵：L'Antica］時，這張角色卡BP+500。\n【退場時】可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-010":{"name":"白瀨咲耶","effectText":"【突襲】〈白瀨咲耶〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手場上BP2500以上的角色卡，在這個回合中，BP-2000。\n【攻擊時】若對手場上有BP比原本BP還低的角色卡時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-014":{"name":"幽谷霧子","effectText":"【登場時】選擇最多1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。\n【攻擊時】若對手場上有BP比原本BP還低的角色卡時，從以下選擇1項。\n・這張角色卡在這個回合中，BP+1000。\n・這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-015":{"name":"淺倉透","effectText":"【攻擊時】若在這個回合中自己從手牌使用了4張以上的卡片時，選擇最多1張對手前線BP4000～5000的角色卡，轉為休息。〈淺倉透〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-016":{"name":"市川雛菜","effectText":"【我方回合中】若自己場上有〈福丸小糸〉時，這張角色卡BP+1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-017":{"name":"樋口圓香","effectText":"在這個回合中，若自己已從手牌中不支付AP使用過其他的〈樋口圓香〉時，這張角色卡無法登場。\n若自己前線有〈淺倉透〉，且自己場上有〈市川雛菜〉與〈福丸小糸〉時，手牌中這張卡片的消耗AP-2。\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】抽1張卡片。將1張自己場上其他的［特徵：noctchill］放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC01BT/IMS-3-018":{"name":"福丸小糸","effectText":"【突襲】〈福丸小糸〉置為活動，並可移動至前線\n【我方回合中】若自己場上有〈市川雛菜〉時，這張角色卡BP+500。\n【每回合1】這張角色卡攻擊後戰勝時，將這張角色卡置為活動。\n【登場時】查看7張自己卡組上面的卡片，公開其中最多1張〈市川雛菜〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-013":{"name":"三峰結華","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-021":{"name":"大崎甜花","effectText":"【登場時】將最多2張自己卡組上面的卡片放置在場外。\n【啟動主要】【每回合1】將3張自己場外的［特徵：ALSTROEMERIA］依任意順序放置在自己卡組下面。若有執行此動作時，這張角色卡在這個回合中，獲得「這張角色卡若在前線時也可產生能源。」。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-022":{"name":"桑山千雪","effectText":"當這張角色卡被突襲時，可將1張自己場外的［特徵：ALSTROEMERIA］放置在自己卡組下面。若有執行此動作時，使突襲的角色卡在這個回合中，獲得BP+1000與「這張角色卡攻擊後戰勝時，可抽最多1張卡片。」。（突襲的角色卡的【登場時】與這個效果可以依任意順序處理）","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-023":{"name":"白瀨咲耶","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：L'Antica］並加入手牌，或將其放置在場外。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n【攻擊時】若自己的卡組在20張以下時，這張角色卡在這個回合中，BP+1000，並選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-024":{"name":"田中摩美美","effectText":"當這張卡片因自己的效果從自己卡組放置在場外時，從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・選擇最多1張自己場上的［特徵：L'Antica］，直到下一個我方回合開始前，獲得【衝擊無效】與「這張角色卡不會被對手的角色卡效果選擇。」。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-020":{"name":"大崎甘奈","effectText":"【突襲】〈大崎甘奈〉置為活動，並可移動至前線\n【我方回合中】若在這個回合中，有將自己場外的卡片放置在自己的卡組時，這張角色卡獲得【衝擊（1）】。\n【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。抽1張卡片。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的［特徵：ALSTROEMERIA］，在這個回合中，BP+1000。將最多1張自己卡組上面的卡片放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-019":{"name":"加油！慢吞吞號","effectText":"抽1張卡片。若自己場上有［特徵：noctchill］時，將1張自己的AP卡置為活動。","triggerText":""},"PC01BT/IMS-3-025":{"name":"月岡戀鐘","effectText":"【登場時】將最多1張自己場外能源需求3以下的紫色［特徵：L'Antica］放置在自己卡組的上面。\n【退場時】將最多1張自己卡組上面的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-026":{"name":"三峰結華","effectText":"若自己場上有3種以上不同卡片名稱的其他［特徵：L'Antica］時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-028":{"name":"斑鳩琉花","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在移除區。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-030":{"name":"斑鳩琉花","effectText":"【我方回合中】若自己移除區有3張以上卡片時，這張角色卡BP+1000。\n【登場時】將1張自己卡組上面的卡片放置在移除區。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"PC01BT/IMS-3-029":{"name":"斑鳩琉花","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：CoMETIK］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在移除區。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-031":{"name":"斑鳩琉花","effectText":"【突襲】〈斑鳩琉花〉置為活動，並可移動至前線\n【登場時】抽2張卡片，並將2張自己的手牌放置在移除區。之後，若自己移除區有3張以上卡片時，選擇最多1張對手前線的角色卡，在這個回合中，『BP-2000』。若自己移除區有6張以上卡片時，則替換成『BP-3000』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-032":{"name":"郁田陽希","effectText":"當這張卡片因自己紫色的［特徵：CoMETIK］的效果被放置在移除區時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-033":{"name":"郁田陽希","effectText":"【登場時】【若在能源線時】若自己移除區有3張以上卡片時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"PC01BT/IMS-3-034":{"name":"郁田陽希","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-035":{"name":"郁田陽希","effectText":"【突襲】〈郁田陽希〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】僅限自己移除區有6張以上卡片時可發動。自己前線所有的［特徵：CoMETIK］，在這個回合中，BP+1000。選擇最多1張自己場上的［特徵：CoMETIK］，在這個回合中，獲得【衝擊（1）】。\n【退場時】若自己移除區有3張以上卡片時，將最多1張這張角色卡的突襲來源卡放回手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-036":{"name":"鈴木羽那","effectText":"當這張卡片因自己紫色的［特徵：CoMETIK］的效果而被放置在移除區時，選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。〈鈴木羽那〉的這個效果，無法選擇在本回合中已經選擇過的角色卡。","triggerText":""},"PC01BT/IMS-3-037":{"name":"鈴木羽那","effectText":"若自己移除區有3張以上卡片時，這張角色卡BP+1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-038":{"name":"鈴木羽那","effectText":"【攻擊時】若自己移除區有6張以上卡片時，選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-039":{"name":"鈴木羽那","effectText":"發動這張卡片的突襲時，若自己移除區有3張以上卡片時，這張卡片的能源需求減少【紫×2】。\n【突襲】〈鈴木羽那〉置為活動，並可移動至前線\n【攻擊時】抽1張卡片。若自己移除區有6張以上卡片時，可將1張自己移除區中〈鈴木羽那〉以外的［特徵：CoMETIK］加入手牌。若有執行此動作時，將1張自己的手牌放置在移除區。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-040":{"name":"黑色彗星","effectText":"抽2張卡片。\n當這張卡片因自己紫色的［特徵：CoMETIK］的效果而被放置在移除區時，抽1張卡片。","triggerText":""},"PC01BT/IMS-3-041":{"name":"※CAUTION※","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有3張以上［特徵：CoMETIK］時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"PC01BT/IMS-3-042":{"name":"和泉愛依","effectText":"【突襲】〈和泉愛依〉置為活動，並可移動至前線\n【若在前線時】自己因「有指定BP範圍的效果」選擇對手場上的角色卡時，可指定的BP範圍+1000。（包含【顏色觸發】）\n【登場時】查看3張自己卡組上面的卡片，公開其中最多各1張［特徵：Straylight］與事件卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC01BT/IMS-3-043":{"name":"芹澤朝日","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態，且在這個回合中自己使用了事件卡時可發動。選擇1張自己場上的［特徵：Straylight］，在這個回合中，BP+1000。若選擇的角色卡為這張角色卡以外時，這張角色卡再於這個回合中獲得【衝擊（1）】。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-044":{"name":"黛冬優子","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張［特徵：Straylight］與最多1張事件卡放置在場外。其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-045":{"name":"有栖川夏葉","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【我方回合中】在這個回合中，若自己的［特徵：放學後CLIMAX GIRLS］曾從場上放回手牌，或因自己的效果從手牌登場時，這張角色卡BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"PC01BT/IMS-3-047":{"name":"西城樹里","effectText":"使這張角色卡以活動狀態在場上登場。\n【啟動主要】【每回合1】將1張自己場上其他的［特徵：放學後CLIMAX GIRLS］放回手牌。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。\n【攻擊時】若在同一條戰線上沒有其他休息狀態的角色卡時，抽1張卡片，這張角色卡在這個回合中，獲得【傷害（2）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC01BT/IMS-3-048":{"name":"園田智代子","effectText":"【登場時】若在這個回合中自己的［特徵：放學後CLIMAX GIRLS］有從場上放回手牌，或因自己的效果從手牌登場時，從以下選擇1項。\n・抽1張卡片。\n・若為我方回合中，選擇最多2張自己場上的［特徵：放學後CLIMAX GIRLS］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-049":{"name":"杜野凜世","effectText":"【登場時】從以下選擇1項。\n・查看3張自己卡組上面的卡片。公開其中最多1張［特徵：放學後CLIMAX GIRLS］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n・選擇最多1張自己場上其他的［特徵：放學後CLIMAX GIRLS］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-050":{"name":"我們要拿下了！","effectText":"抽1張卡片，並將1張自己的手牌放置在場外。從自己場外使最多1張原始BP為3000以下的紅色［特徵：Straylight］以休息狀態在自己場上登場，或發動突襲。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06ST/TOA-1-068":{"name":"奧爾芬","effectText":"若自己的生命值在4以下時，這張角色卡BP+500。","triggerText":""},"UA06ST/TOA-1-075":{"name":"希儂","effectText":"【登場時】若自己場上有〈奧爾芬〉時，查看2張自己卡組上面的卡片。將其中任意張數的卡片以任意順序放置在自己卡組的上面，其餘卡片以任意順序放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06ST/TOA-1-076":{"name":"希儂","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06ST/TOA-1-077":{"name":"希儂","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA06ST/TOA-1-080":{"name":"鐵假面","effectText":"這張卡片也視為〈奧爾芬〉。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC01BT/IMS-3-046":{"name":"小宮果穗","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【突襲】〈小宮果穗〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+500。\n【攻擊時】【每回合1】若在同一條戰線上沒有其他休息狀態的角色卡時，可將1張自己場上其他的［特徵：放學後CLIMAX GIRLS］放回手牌。若有執行此動作時，使最多1張自己手牌中能源需求3以下消耗AP1的紅色［特徵：放學後CLIMAX GIRLS］以活動狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06ST/TOA-1-084":{"name":"伏露露","effectText":"【啟動主要】【轉為休息】 【每回合1】在這個回合中，這張角色卡的產生能源+【紅】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA06ST/TOA-1-087":{"name":"琳薇爾","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA06ST/TOA-1-096":{"name":"緋炎衝・開","effectText":"選擇1張對手前線『BP3000』以下的角色卡，使其退場。若自己場上有〈奧爾芬〉，且自己的生命值在5以下時，則替換成『BP5000以下』。","triggerText":"[最終] 選擇1張對手前線的角色卡，使其退場。"},"UA06ST/TOA-1-097":{"name":"兩人的羈絆","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[特別] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA06ST/TOA-1-101":{"name":"奧爾芬","effectText":"【啟動主要】【每回合1】這張角色卡在這個回合中，BP+1000。將1張自己生命區的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC01BT/IMS-3-027":{"name":"幽谷霧子","effectText":"【登場時】【攻擊時】【若在前線時】若自己卡組在20張以下時，將這張角色卡置為活動。〈幽谷霧子〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇最多1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06ST/TOA-1-102":{"name":"奧爾芬","effectText":"【突襲】〈奧爾芬〉置為活動，並可移動至前線。\n【攻擊時】這張角色卡在這個回合中，可獲得【傷害（2）】（這張角色卡的攻擊直接造成傷害時，這張角色卡造成的直接傷害為2）。若有執行此動作時，將1張自己生命區的卡片放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06ST/TOA-1-103":{"name":"希儂","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，獲得BP+2000與【衝擊（+1）】（衝擊造成的傷害+1，若未持有衝擊，則獲得【衝擊（1）】）。在這個回合中，自己無法因自己的效果將生命區的卡片放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06ST/TOA-1-105":{"name":"伏露露","effectText":"【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA06ST/TOA-1-104":{"name":"齊爾法","effectText":"【登場時】選擇最多1張對手前線BP3000以下的角色卡，使其退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06ST/TOA-1-106":{"name":"琳薇爾","effectText":"","triggerText":""},"UA06ST/TOA-1-107":{"name":"洛","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06ST/TOA-1-109":{"name":"羈絆之光","effectText":"查看4張自己卡組上面的卡片。從中公開最多2張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"UA06ST/TOA-1-108":{"name":"紅之鴉的根據地","effectText":"【啟動主要】【轉為休息】 【使這張卡片退場】選擇最多1張自己的AP卡，置為活動。抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-002":{"name":"奧爾芬","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-004":{"name":"奇莎蘭","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-005":{"name":"奇莎蘭","effectText":"【對方回合中】這張角色卡BP+1000。","triggerText":""},"UA06BT/TOA-1-007":{"name":"奇莎蘭","effectText":"【突襲】〈奇莎蘭〉置為活動，並可移動至前線\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【每回合1】這張角色卡攻擊後沒有被防禦時，可以查看2張自己卡組上面的卡片。若有執行此動作時，將其中1張卡片加入手牌，其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06BT/TOA-1-008":{"name":"希儂","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA06BT/TOA-1-010":{"name":"希儂","effectText":"【突襲】〈希儂〉置為活動，並可移動至前線\nBP2000以下的角色卡不能防禦這張角色卡。\n【登場時】抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-011":{"name":"杜歐哈林","effectText":"【登場時】若自己場上有〈奇莎蘭〉時，選擇最多1張自己場上的角色卡，在這個回合中，獲得「【每回合1】這張角色卡攻擊後沒有被防禦時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-006":{"name":"奇莎蘭","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【對方回合中】當對手因角色卡的效果或事件卡的效果而選擇這張角色卡時，必須追加支付1AP才可以選擇。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA06BT/TOA-1-012":{"name":"杜歐哈林","effectText":"【登場時】若自己場上有〈奇莎蘭〉時，選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":""},"UA06BT/TOA-1-009":{"name":"希儂","effectText":"若對手場上有綠色或紅色卡片時，手牌中這張卡片的能源需求減少【藍×1】。","triggerText":""},"UA06BT/TOA-1-001":{"name":"奧爾芬","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA06BT/TOA-1-014":{"name":"杜歐哈林","effectText":"若自己前線有〈奇莎蘭〉時，手牌中這張卡片的消耗AP-1。\n【登場時】選擇最多1張自己場上其他的角色卡，直到下一個我方回合開始前，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-003":{"name":"奧爾芬","effectText":"【突襲】〈奧爾芬〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP3000以下的角色卡，放回手牌。\n【啟動主要】【將1張手牌放置場外】這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-017":{"name":"伏露露","effectText":"【啟動主要】【轉為休息】【將1張手牌放置場外】【使這張卡片退場】將1張自己場外的事件卡加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-016":{"name":"伏露露","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-013":{"name":"杜歐哈林","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍x1】。","triggerText":""},"UA06BT/TOA-1-019":{"name":"琳薇爾","effectText":"【登場時】查看5張自己卡組上面的卡片。公開其中最多1張〈空壓刃〉或〈轟雷刃〉或〈白薙・神鳴〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA06BT/TOA-1-018":{"name":"琳薇爾","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-021":{"name":"琳薇爾","effectText":"【突襲】〈琳薇爾〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。在這個回合中，接下來使用手牌中的事件卡的消耗AP-1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06BT/TOA-1-015":{"name":"伏露露","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【藍x1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA06BT/TOA-1-020":{"name":"琳薇爾","effectText":"【登場時】查看3張自己卡組上面的卡片。將其中1張卡片加入手牌。其餘卡片依任意順序放置在自己卡組下面。在這個回合中，接下來使用手牌中的〈空壓刃〉或〈轟雷刃〉或〈白薙・神鳴〉的消耗AP-1。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA06BT/TOA-1-022":{"name":"洛","effectText":"【登場時】若自己場上有〈琳薇爾〉時，抽1張卡片。","triggerText":""},"UA06BT/TOA-1-023":{"name":"洛","effectText":"【登場時】若自己場上有〈琳薇爾〉時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-024":{"name":"洛","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA06BT/TOA-1-025":{"name":"洛","effectText":"若自己前線有〈琳薇爾〉時，手牌中這張卡片的消耗AP-1。\n依據自己場外的事件卡張數，這張角色卡獲得以下全數效果。\n・5張以上：【傷害（2）】\n・7張以上：【攻擊時】選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-026":{"name":"貓頭鷹之森","effectText":"這張場域卡以活動狀態登場。\n【啟動主要】【轉為休息】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA06BT/TOA-1-028":{"name":"轟雷刃","effectText":"選擇1張對手前線的角色卡，轉為休息。可以將1張自己手牌中的事件卡放置在場外。若有執行此動作時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-030":{"name":"白薙・神鳴","effectText":"選擇1張對手前線『BP2000』以下的角色卡，使其退場。若自己場上有〈琳薇爾〉時，自己場外每有1張事件卡，可選擇的卡片『BP+1000』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA06BT/TOA-1-029":{"name":"守護方陣","effectText":"選擇『1張』自己前線的角色卡，直到下一個我方回合開始前，獲得「對手無法使用角色卡效果・事件卡效果・觸發效果選擇這張角色卡。」。若自己場上有〈奇莎蘭〉時，則替換成『1～2張』。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-031":{"name":"聖煌割碎壁","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈奇莎蘭〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA06BT/TOA-1-027":{"name":"空壓刃","effectText":"在使用這張卡片時，可以將1張自己手牌中的事件卡放置在場外。\n選擇1張對手前線『BP3000以下』的角色卡，放回手牌。若使用這張卡片的效果將事件卡放置在場外時，則替換成『BP4000以下』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-032":{"name":"大型魚魚排","effectText":"選擇1張自己場上的角色卡，『在這個回合中』、BP+1000。若自己場上有〈奇莎蘭〉時，則替換成『直到下一個我方回合開始前』。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-034":{"name":"伏露露鬆餅","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+2500。若自己場上有〈琳薇爾〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-033":{"name":"兩人的羈絆","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA06BT/TOA-1-036":{"name":"奧爾芬","effectText":"若自己場上有〈希儂〉時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害。）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-035":{"name":"奧爾芬","effectText":"【登場時】若自己場上有〈希儂〉時，抽1張卡片。","triggerText":""},"UA06BT/TOA-1-038":{"name":"奧爾芬","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【綠x1】。","triggerText":""},"UA06BT/TOA-1-037":{"name":"奧爾芬","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-040":{"name":"奧爾芬","effectText":"若自己前線有〈希儂〉時，手牌中這張卡片的消耗AP-1。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【登場時】選擇1張對手前線BP5000以下的角色卡，可以使其退場。若有執行此動作時，使1張自己能源線的角色卡退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-039":{"name":"奧爾芬","effectText":"【攻擊時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"UA06BT/TOA-1-041":{"name":"奇莎蘭","effectText":"【登場時】若自己場上有〈杜歐哈林〉時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA06BT/TOA-1-043":{"name":"奇莎蘭","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA06BT/TOA-1-042":{"name":"奇莎蘭","effectText":"【登場時】若自己場上有〈杜歐哈林〉時，使最多1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以休息狀態在自己場上登場。","triggerText":""},"UA06BT/TOA-1-044":{"name":"奇莎蘭","effectText":"若自己前線有〈杜歐哈林〉時，手牌中這張卡片的消耗AP-1。\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，獲得「對手必須盡可能防禦這張角色卡的攻擊。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-046":{"name":"希儂","effectText":"若自己的產生能源有6以上時，這張角色卡BP+1000。","triggerText":""},"UA06BT/TOA-1-045":{"name":"希儂","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-047":{"name":"希儂","effectText":"這張角色卡在前線時也能產生能源。\n【登場時】使最多1張自己場外能源需求3以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA06BT/TOA-1-048":{"name":"希儂","effectText":"【突襲】〈希儂〉置為活動，並可移動至前線\n這張角色卡在前線時也能產生能源。\n【登場時】查看2張自己卡組上面的卡片。將其中1張卡片加入手牌，其餘卡片放置場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06BT/TOA-1-049":{"name":"杜歐哈林","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-050":{"name":"杜歐哈林","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-053":{"name":"伏露露","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【綠x1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA06BT/TOA-1-054":{"name":"琳薇爾","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-055":{"name":"琳薇爾","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA06BT/TOA-1-056":{"name":"琳薇爾","effectText":"【突襲】〈琳薇爾〉置為活動，並可移動至前線\n【登場時】抽2張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-057":{"name":"洛","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA06BT/TOA-1-058":{"name":"洛","effectText":"若對手場上有藍色或紅色卡片時，手牌中這張卡片的能源需求減少【綠×1】。","triggerText":""},"UA06BT/TOA-1-059":{"name":"洛","effectText":"【突襲】〈洛〉置為活動，並可移動至前線\n【攻擊時】自己前線的角色卡全數，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-052":{"name":"杜歐哈林","effectText":"【突襲】〈杜歐哈林〉置為活動，並可移動至前線\n【啟動主要】【每回合1】在這個回合中只有自己使用事件卡時才可以發動。選擇1張自己場上其他的角色卡，在這個回合中，獲得「BP+1000和【衝擊（+1）】」或「BP+1000和【傷害（2）】」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06BT/TOA-1-060":{"name":"梅南希亞","effectText":"【每回合1】自己場上的角色卡攻擊後戰勝時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-051":{"name":"杜歐哈林","effectText":"【啟動主要】【若在前線時】【每回合1】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。在這個回合中若自己使用事件卡時，抽1張卡片。\n【退場時】抽1張卡片。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA06BT/TOA-1-062":{"name":"地質分裂","effectText":"選擇最多1張對手前線『BP3000以下』的角色卡，使其退場。選擇最多1張自己前線的角色卡，在這個回合中，BP+1000。若自己場上有〈杜歐哈林〉時，則替換成『BP4000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA06BT/TOA-1-061":{"name":"劇烈野火","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈希儂〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA06BT/TOA-1-065":{"name":"負能源之門","effectText":"選擇最多1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。『抽1張卡片』。若自己場上有〈杜歐哈林〉時，則替換成『抽2張卡片』。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-063":{"name":"希儂特製鬆餅","effectText":"若自己場上有〈希儂〉時，手牌中這張卡片的能源需求減少【綠×1】。\n使最多1張自己手牌中能源需求3以下消耗AP1以下的角色卡以休息狀態在自己能源線登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-066":{"name":"應急治療","effectText":"將最多1張自己場外的角色卡加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-070":{"name":"奧爾芬","effectText":"【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n自己的攻擊階段結束時，將1張自己生命區的卡片放置在場外。\n【突襲】〈奧爾芬〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP3000以下的角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA06BT/TOA-1-069":{"name":"奧爾芬","effectText":"【登場時】選擇最多1張對手前線BP4000以下的角色卡，可以使其退場。若有執行此動作時，將1張自己生命區的卡片放置在場外。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA06BT/TOA-1-064":{"name":"杜歐哈林特製鬆餅","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+1000和獲得【衝擊（+1）】（衝擊效果造成的傷害+1，若未持有衝擊時，則獲得【衝擊（1）】）。若自己場上有〈杜歐哈林〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-071":{"name":"奇莎蘭","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA06BT/TOA-1-068":{"name":"奧爾芬","effectText":"若自己的生命在4以下時，這張角色卡BP+500。","triggerText":""},"UA06BT/TOA-1-072":{"name":"奇莎蘭","effectText":"若對手場上有藍色或綠色卡片，手牌中這張卡片的能源需求減少【紅×1】。","triggerText":""},"UA06BT/TOA-1-073":{"name":"奇莎蘭","effectText":"【突襲】〈奇莎蘭〉置為活動，並可移動至前線\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【對方回合中】這張角色卡BP+500。\n【退場時】選擇最多1張自己能源線的角色卡，移動至前線。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-067":{"name":"兩人的羈絆","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA06BT/TOA-1-075":{"name":"希儂","effectText":"【登場時】若自己場上有〈奧爾芬〉時，查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組上面，其餘卡片依任意順序放置在下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-076":{"name":"希儂","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-078":{"name":"希儂","effectText":"【登場時】自己在這個回合中，無法使用自己的效果將生命區的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-077":{"name":"希儂","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅x1】。","triggerText":""},"UA06BT/TOA-1-079":{"name":"希儂","effectText":"若自己前線有〈奧爾芬〉時，手牌中這張卡片的消耗AP-1。\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【將1張手牌放置場外】【每回合1】自己在這個回合中，無法使用自己的效果將生命區的卡片放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-080":{"name":"鐵面人","effectText":"這張卡片也視為〈奧爾芬〉。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-081":{"name":"杜歐哈林","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA06BT/TOA-1-074":{"name":"希儂","effectText":"【登場時】若自己場上有〈奧爾芬〉時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA06BT/TOA-1-083":{"name":"杜歐哈林","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【突襲】〈杜歐哈林〉置為活動，並可移動至前線\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，獲得【衝擊（+1）】（衝擊效果造成的傷害+1，若未持有衝擊時，則獲得【衝擊（1）】）或【傷害（2）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-082":{"name":"杜歐哈林","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-084":{"name":"伏露露","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紅x1】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA06BT/TOA-1-086":{"name":"琳薇爾","effectText":"【登場時】若自己場上有〈洛〉時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-085":{"name":"琳薇爾","effectText":"【登場時】若自己場上有〈洛〉時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA06BT/TOA-1-087":{"name":"琳薇爾","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA06BT/TOA-1-088":{"name":"琳薇爾","effectText":"若自己前線有〈洛〉時，手牌中這張卡片的消耗AP-1。\n【登場時】查看6張自己卡組上面的卡片。公開其中最多1張能源需求2以下的紅色事件卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-089":{"name":"洛","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA06BT/TOA-1-090":{"name":"洛","effectText":"【我方回合中】若自己場外的事件卡有4張以上時，這張角色卡BP+1000。","triggerText":""},"UA06BT/TOA-1-091":{"name":"洛","effectText":"若自己場外的事件卡有5張以上時，這張角色卡以活動狀態登場。\n【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA06BT/TOA-1-093":{"name":"火焰之門","effectText":"【啟動主要】【使這張卡片退場】在這個回合中只有對手場上原本BP4000以上的角色卡退場時才可以發動。抽2張卡片。","triggerText":""},"UA06BT/TOA-1-094":{"name":"刈包","effectText":"抽1張卡片，並將1張自己的手牌放置在場外。若自己場上有〈洛〉時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-095":{"name":"迅雷狼影腳","effectText":"選擇1張對手前線『BP3000』以下的角色卡，使其退場。若自己場上有〈洛〉時，在這個回合中自己每使用1張其他的事件卡，可選擇的卡片『BP+1000』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA06BT/TOA-1-096":{"name":"緋炎衝・開","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈奧爾芬〉，且自己的生命在5以下時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA06BT/TOA-1-097":{"name":"兩人的羈絆","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA06BT/TOA-1-098":{"name":"麻婆咖哩","effectText":"選擇1張自己場上的角色卡，在這個回合中，BP+1000。若選擇的角色卡為〈奧爾芬〉時，還可以置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-099":{"name":"魔王炎擊破","effectText":"選擇最多1張對手前線BP2500以下的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。將1張自己生命區的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA06BT/TOA-1-100":{"name":"連牙彈","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+2000。若自己場上有〈洛〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-001":{"name":"巴茲","effectText":"這張卡片也視為〈巴茲B〉。\n【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈巴茲B〉或〈優谷拉姆・哈修瓦特〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-002":{"name":"優果","effectText":"這張卡片也視為〈優谷拉姆・哈修瓦特〉。\n【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-004":{"name":"石田雨龍","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【支付1AP】僅限這張卡片在自己的手牌中時可發動。將自己移除區的〈黑崎一護〉4張以上放置在場外。若有執行此動作時，使這張卡片以活動狀態在自己前線登場。〈石田雨龍〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-005":{"name":"傑拉爾德・瓦爾奇利","effectText":"【退場時】從以下選擇最多1項。\n・將1張自己的生命卡加入手牌。若有執行此動作時，使這張卡片以休息狀態在自己場上登場。\n・將2張自己的手牌放置在場外。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA06BT/TOA-1-092":{"name":"洛","effectText":"【突襲】〈洛〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】依據在這個回合中自己使用的事件卡張數，發動以下全數效果。\n・1張以上：抽1張卡片。\n・2張以上：選擇最多1張自己的AP卡，置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX15BT/BLC-4-007":{"name":"巴茲B","effectText":"【啟動主要】僅限自己場外沒有〈優哈巴哈〉，且這張角色卡的能源需求為5以上時可發動。將這張角色卡置為活動。〈巴茲B〉的這個效果每回合僅可發動1次。","triggerText":""},"EX15BT/BLC-4-006":{"name":"巴茲B","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若自己場外沒有〈優哈巴哈〉，且自己場上有〈優谷拉姆・哈修瓦特〉時，這張角色卡BP+1000。","triggerText":""},"EX15BT/BLC-4-008":{"name":"巴茲B","effectText":"【登場時】若自己場外沒有〈優哈巴哈〉時，可使1張自己場上其他的〈巴茲B〉退場。若有執行此動作時，選擇最多1張對手前線BP為該退場角色卡的能源需求數量×1000以下的角色卡，使其退場，並將這張角色卡置為活動。若以這個效果使自己能源需求5以上的角色卡退場時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-009":{"name":"班比艾塔・巴斯塔拜","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-003":{"name":"阿斯金・納克瓦爾","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【退場時】若為我方回合中時，選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-011":{"name":"優谷拉姆・哈修瓦特","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。選擇1張自己場上其他的角色卡，在這個回合中，其能源需求增加2。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX15BT/BLC-4-012":{"name":"優谷拉姆・哈修瓦特","effectText":"【突襲】〈優谷拉姆・哈修瓦特〉置為活動，並可移動至前線\n【若在前線時】自己場上其他的角色卡退場時，抽最多1張卡片。〈優谷拉姆・哈修瓦特〉的這個效果每回合僅可發動1次。\n【我方回合中】【若在前線時】自己場上其他所有角色卡的能源需求增加2。\n【登場時】若自己場上的卡片不具備「星十字騎士團」以外的特徵時，從自己手牌中，使最多1張能源需求2以下且消耗AP1的黃色角色卡以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX15BT/BLC-4-010":{"name":"沛尼達・帕倫卡傑斯","effectText":"【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】僅限自己場上有〈優哈巴哈〉時可發動。選擇1張對手場上BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-013":{"name":"優哈巴哈","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。","triggerText":""},"EX15BT/BLC-4-014":{"name":"優哈巴哈","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"EX15BT/BLC-4-017":{"name":"吉賽爾・茱耶爾","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】【使這張卡片退場】選擇1張自己場上的［特徵：殭屍］，在這個回合中，使其獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。〈吉賽爾・茱耶爾〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-016":{"name":"里傑・巴洛","effectText":"【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。使1張自己場上其他的角色卡退場。若有執行此動作時，這張角色卡直到下一個我方回合開始前，產生能源+【黃】，並從以下選擇1項。\n・抽1張卡片。\n・選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-018":{"name":"莉露多托・藍帕德","effectText":"【退場時】若為我方回合中時，從以下選擇1項。\n・選擇最多1張自己場上其他的［特徵：班比小隊］或〈班比艾塔・巴斯塔拜〉，置為活動。\n・選擇最多1張自己場上其他的［特徵：班比小隊］或〈班比艾塔・巴斯塔拜〉，直到下一個我方回合開始前，使其獲得「這張角色卡不會被對手的效果選擇。」。對手前線所有BP1000以上的角色卡在這個回合中，BP-500。","triggerText":""},"EX15BT/BLC-4-015":{"name":"優哈巴哈","effectText":"當這張卡片被放置在場外時，將這張卡片從場外放置在自己卡組下面。\n【啟動主要】【若在前線時】【每回合1】使1張自己場上其他的角色卡退場。若有執行此動作時，將這張角色卡置為活動，查看3張自己卡組上面的卡片，將其中1張加入手牌。其餘卡片依任意順序放置在自己卡組下面。若以這個效果使自己能源需求4以上的角色卡退場時，這張角色卡直到下一個我方回合開始前，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-019":{"name":"滅卻師完聖體","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX15BT/BLC-4-022":{"name":"井上織姬","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張能源需求1以下的藍色角色卡加入手牌，或使其以休息狀態在自己場上登場。\n【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。選擇1張自己場上的角色卡，直到下一個我方回合開始前，使其獲得「這張角色卡不會被對手的效果選擇。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-021":{"name":"燃火全指","effectText":"這張卡片僅限自己場上有〈巴茲B〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。若自己場上有能源需求5以上的〈巴茲B〉時，選擇最多1張自己場上的〈巴茲B〉，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX15BT/BLC-4-024":{"name":"浦原喜助","effectText":"【登場時】選擇最多1張自己場上不具備特徵的其他角色卡，移動至另一條線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-025":{"name":"黑崎一護","effectText":"【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】抽1張卡片。","triggerText":""},"EX15BT/BLC-4-027":{"name":"黑崎一護","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【每回合1】將1張自己手牌中卡片名稱含有「斬月」或「月牙」的卡片放置在場外。若有執行此動作時，抽1張卡片，這張角色卡在這個回合中，獲得BP+1500與「【若在能源線時】自己攻擊階段開始時，若自己前線有空格時，將這張角色卡移動至前線。」及「這張角色卡不會被觸發的效果選擇。」。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-020":{"name":"一起成為最強的滅卻師吧","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX15BT/BLC-4-028":{"name":"茶渡泰虎","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡直到下一個我方回合開始前，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-026":{"name":"黑崎一護","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX15BT/BLC-4-023":{"name":"浦原喜助","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-029":{"name":"志波岩鷲","effectText":"這張角色卡不會被BP2000以下的角色卡防禦。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-030":{"name":"四楓院夜一","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或下面，並抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-032":{"name":"四楓院夜一","effectText":"【我方回合中】若自己場上有〈黑崎一護〉或〈浦原喜助〉時，這張角色卡BP+1000。\n【若在能源線時】【每回合1】自己的角色卡攻擊結束時，選擇1張自己前線在這個回合中尚未攻擊的角色卡，可使其與這張角色卡交換位置。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX15BT/BLC-4-031":{"name":"四楓院夜一","effectText":"【登場時】若這張角色卡是因自己的效果而登場時，抽1張卡片。","triggerText":""},"EX15BT/BLC-4-033":{"name":"四楓院夜一","effectText":"【突襲】〈四楓院夜一〉置為活動，並可移動至前線\n【登場時】選擇最多1張自己場上其他不具備特徵的角色卡，置為活動。\n【退場時】若自己場上有〈浦原喜助〉時，使最多1張這張角色卡的突襲元卡以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX15BT/BLC-4-034":{"name":"毒峰莉露卡","effectText":"因自己的〈黑崎一護〉效果而將自己的手牌放置在場外時，若這張角色卡下面沒有背面朝上卡片，可將活動的這張角色卡轉為休息。若有執行此動作時，將因該〈黑崎一護〉的效果而放置在場外的卡片最多1張，以背面朝上放置在這張角色卡下面。\n【登場時】【若在能源線時】將這張角色卡置為活動。\n【啟動主要】【轉為休息】【使這張卡片退場】將這張角色卡下面的背面朝上卡片最多1張加入手牌。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX15BT/BLC-4-037":{"name":"涅里耶爾・圖・歐黛爾休凡克","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【支付1AP】【每回合1】發動這張角色卡的【登場時】。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-035":{"name":"古里姆喬・賈喀傑克","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-038":{"name":"朽木露琪亞","effectText":"【我方回合中】若自己前線有原始消耗AP2以上的角色卡時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-036":{"name":"古里姆喬・賈喀傑克","effectText":"因自己的〈黑崎一護〉或〈浦原喜助〉的效果而使這張卡片從自己的手牌放置在場外時，若自己的藍色能源為4以上，且自己場上的卡片不具備「破面」以外的特徵，可支付1AP。若有執行此動作時，使這張卡片以活動狀態在自己場上登場。〈古里姆喬・賈喀傑克〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-040":{"name":"涅音夢","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-039":{"name":"朽木露琪亞","effectText":"【登場時】【若在能源線時】若自己前線有原始消耗AP2以上的角色卡時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。若所選角色卡的原始消耗AP為2以上，可將1張自己的手牌放置在場外。若有執行此動作時，將該角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-041":{"name":"涅音夢","effectText":"在我方回合開始時，使這張角色卡退場。\n【登場時】若自己前線有〈涅繭利〉時，可使1張自己場上其他的角色卡退場。若有執行此動作時，將這張角色卡置為活動，並使這張角色卡在這個回合中獲得「對手必須盡可能防禦這張角色卡的攻擊。」與【衝擊（1）】。\n【退場時】將這張卡片放置在移除區。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX15BT/BLC-4-043":{"name":"眠七號","effectText":"這張卡片也視為〈涅音夢〉。\n【登場時】查看2張自己卡組上面的卡片，將其中最多1張藍色〔〈涅繭利〉或〈涅音夢〉或［特徵：涅骸部隊］〕放置在場外。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-042":{"name":"涅繭利","effectText":"【登場時】從以下選擇1項。\n・查看2張自己卡組上面的卡片，將任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。\n・可將2張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張〈涅繭利〉或〈涅音夢〉加入手牌。\n・可使1張自己場上其他的角色卡退場。若有執行此動作時，從自己手牌中，使最多1張藍色〈涅骸部隊〉以活動狀態在自己能源線登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-044":{"name":"瞬閧・雷神戰形","effectText":"選擇1張自己場上的〈四楓院夜一〉，在這個回合中，使其獲得BP+2000與「這張角色卡在這個回合中進行第一次攻擊時，直到該次攻擊結束前，獲得【衝擊（1）】與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。」。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX15BT/BLC-4-045":{"name":"瞬神","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX15BT/BLC-4-046":{"name":"井上織姬","effectText":"【登場時】選擇最多1張自己場上的紫色〈黑崎一護〉，在這個回合中，BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-048":{"name":"阿散井戀次","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張紫色〔〈阿散井戀次〉或〈朽木露琪亞〉〕放置在場外。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-049":{"name":"阿散井戀次","effectText":"若在這個回合中已因自己紫色卡片的效果支付AP時，這張角色卡BP+2000。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】僅限自己場上有〈朽木露琪亞〉時可發動。從以下選擇1項。\n・抽1張卡片。\n・將這張角色卡置為活動。選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-047":{"name":"魂","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己場外，使最多1張能源需求0的紫色〈黑崎一護〉以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-051":{"name":"朽木白哉","effectText":"【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・若對手前線有BP低於原始BP的角色卡時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-052":{"name":"朽木白哉","effectText":"若對手前線有BP低於原始BP的角色卡時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-050":{"name":"阿散井戀次","effectText":"若在這個回合中已因自己紫色卡片的效果支付AP時，從手牌使用這張卡片發動突襲時，消耗AP-1。若在這個回合中已從手牌使用其他〈阿散井戀次〉且未支付AP，這個效果無效。\n【突襲】〈阿散井戀次〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】從以下選擇1項。\n・這張角色卡在這個回合中，獲得【衝擊（1）】。\n・選擇1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX15BT/BLC-4-053":{"name":"朽木白哉","effectText":"【突襲】〈朽木白哉〉置為活動，並可移動至前線\n這張角色卡攻擊並在對戰中獲勝時，將這張角色卡置為活動。〈朽木白哉〉的這個效果每回合僅可發動1次。\n【我方回合中】若對手前線有3張以上BP低於原始BP的角色卡時，這張角色卡獲得【傷害（2）】。\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX15BT/BLC-4-054":{"name":"朽木露琪亞","effectText":"【登場時】若自己場上有〈阿散井戀次〉時，可支付1AP。若有執行此動作時，抽1張卡片，並從自己手牌中，使最多1張滿足能源需求且消耗AP1的〔〈阿散井戀次〉或〈朽木露琪亞〉〕以休息狀態在自己場上登場，或發動突襲。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX15BT/BLC-4-055":{"name":"兵主部一兵衛","effectText":"【登場時】可將1張自己場上其他的角色卡放置在移除區。若有執行此動作時，從以下選擇1項。\n・在這個回合中，下一張從手牌中使用的［特徵：零番隊］或〈靈王宮〉的消耗AP-1。\n・選擇最多2張自己場上其他的［特徵：零番隊］，在這個回合中，BP+2000。","triggerText":""},"EX15BT/BLC-4-056":{"name":"兵主部一兵衛","effectText":"【登場時】抽1張卡片。可將1張自己手牌中的［特徵：零番隊］放置在移除區。若有執行此動作時，將這張角色卡置為活動。\n【退場時】將這張卡片放置在移除區。從自己手牌中，使最多1張能源需求為『0』以下且消耗AP1的紫色〔〈黑崎一護〉或〈靈王宮〉或［特徵：零番隊］〕以休息狀態在自己場上登場。自己移除區中每有1種持有不同卡片名稱的［特徵：零番隊］，以這個效果登場的角色卡的能源需求範圍+1。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-058":{"name":"雙王蛇尾丸","effectText":"這張卡片僅限自己場上有〈阿散井戀次〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。若在這個回合中已因自己紫色卡片的效果支付AP時，可抽1張卡片。若有執行此動作時，將1張自己的手牌放置在場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX15BT/BLC-4-060":{"name":"藍染惣右介","effectText":"這張卡片無法在前線登場，且無法以自己的效果以外的方式移動至前線。\n【登場時】選擇最多1張自己場上〈藍染惣右介〉以外的角色卡，移動至另一條線。\n【啟動主要】【若在能源線時】將2張自己前線活動的角色卡轉為休息。若有執行此動作時，將這張角色卡移動至前線。\n【攻擊時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-059":{"name":"卍解","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX15BT/BLC-4-061":{"name":"猿柿日代里","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-057":{"name":"“真打”『白筆一文字』","effectText":"選擇最多1張對手前線的角色卡，直到下一個我方回合開始前，使其獲得「這張角色卡失去所有原始效果，且無法攻擊也無法防禦。」。若自己場上或移除區有〈兵主部一兵衛〉時，抽2張卡片，並將1張自己的手牌放置在移除區。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX15BT/BLC-4-065":{"name":"伊勢七緒","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】若自己能源線有〈京樂春水〉時，這張角色卡BP+1500。\n【啟動主要】僅限自己在這個回合中已使用〈神劍・八鏡劍〉時可發動。將這張角色卡置為活動。〈伊勢七緒〉的這個效果每回合僅可發動1次。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX15BT/BLC-4-064":{"name":"伊勢七緒","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張綠色事件卡或綠色場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX15BT/BLC-4-066":{"name":"卯之花烈","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或下面，並抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-067":{"name":"京樂春水","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-069":{"name":"京樂春水","effectText":"【突襲】〈京樂春水〉置為活動，並可移動至前線\n這張角色卡的攻擊結束時，若自己場外綠色〔事件卡與場域卡〕的卡片名稱合計有4種以上時，選擇最多1張自己能源線的角色卡，與這張角色卡交換位置。\n【登場時】在這個回合中，下一張從手牌中使用的［特徵：花天狂骨］消耗AP-1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX15BT/BLC-4-068":{"name":"京樂春水","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【若在前線時】【支付1AP】僅限這張角色卡為休息時可發動。將這張角色卡置為活動，並選擇最多1張對手前線的角色卡，轉為休息。〈京樂春水〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-062":{"name":"矢胴丸麗莎","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-063":{"name":"綾瀨川弓親","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，『BP+1000』。若以這個效果選擇的角色卡為〈更木劍八〉、〈草鹿八千流〉、〈斑目一角〉或〈綾瀨川弓親〉時，改為『BP+2000』。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-070":{"name":"更木劍八","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n這張角色卡必須盡可能防禦對手的攻擊。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-071":{"name":"碎蜂","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】將這張角色卡置為活動。〈碎蜂〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-075":{"name":"浮竹十四郎","effectText":"這張卡片無法在前線登場，且無法移動至前線。\n【突襲】〈浮竹十四郎〉置為活動，並可移動至前線\n這張角色卡的產生能源+【綠】。\n【登場時】抽1張卡片。\n【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。選擇1張自己場上其他的［特徵：護廷十三隊］，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX15BT/BLC-4-076":{"name":"花天","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己場外，使最多1張能源需求2以下的綠色〈京樂春水〉以活動狀態在自己能源線登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX15BT/BLC-4-073":{"name":"斑目一角","effectText":"【我方回合中】若自己場上有〈更木劍八〉時，這張角色卡BP+1500。","triggerText":""},"EX15BT/BLC-4-072":{"name":"平子真子","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外，使最多1張滿足能源需求且消耗AP1的［特徵：假面軍勢］以休息狀態在自己場上登場。","triggerText":""},"EX15BT/BLC-4-077":{"name":"狂骨","effectText":"【登場時】從自己場外將最多1張〈神劍・八鏡劍〉加入手牌。\n【啟動主要】【轉為休息】【使這張卡片退場】選擇最多1張自己場上的卡片，置為活動。選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX15BT/BLC-4-078":{"name":"黑棺","effectText":"若自己場上沒有〈藍染惣右介〉時，在所有區域這張卡片的卡片名稱變為〈滲出的混濁紋章 不遜的瘋狂容器 湧起・否定・麻痺・瞬間・妨礙睡眠 爬行的鐵之公主 不斷自毀的泥偶 結合吧 反彈吧 充滿大地並知曉自身的無力 破道之九十・黑棺〉。\n選擇1張對手前線BP4000以下的角色卡，使其退場。","triggerText":""},"EX15BT/BLC-4-080":{"name":"卍解","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX15BT/BLC-4-081":{"name":"花天狂骨枯松心中","effectText":"這張卡片僅限自己場上有〈京樂春水〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。選擇最多1張自己能源線的〈花天〉或〈狂骨〉，置為活動。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX15BT/BLC-4-074":{"name":"山本重國","effectText":"這張卡片也視為〈山本元柳齋重國〉。\n【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA01DC/BLC-1-034":{"name":"石田雨龍","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA01DC/BLC-1-039":{"name":"黑崎一護","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA01DC/BLC-1-037":{"name":"浦原喜助","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA01DC/BLC-1-040":{"name":"黑崎一護","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX15BT/BLC-4-079":{"name":"神劍・八鏡劍","effectText":"從以下選擇1項。之後，可將1張自己場上活動的〔〈京樂春水〉或〈伊勢七緒〉〕轉為休息。若有執行此動作時，將1張自己的AP卡置為活動。\n・抽1張卡片。\n・選擇最多1張自己場上的〈伊勢七緒〉，在這個回合中，使其獲得BP+3000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":""},"UA01DC/BLC-1-041":{"name":"黑崎一護","effectText":"【突襲】〈黑崎一護〉置為活動，並可移動至前線。\n【登場時】將2張自己卡組上面的卡片放置在場外。將自己場外任意張數的卡片放置在移除區。若有執行此動作時，選擇最多1張對手前線的角色卡，每有1張以這個效果放置在移除區的卡片，該角色卡在這個回合中，BP-500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA01DC/BLC-1-051":{"name":"朽木露琪亞","effectText":"【退場時】將2張自己卡組上面的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA01DC/BLC-1-036":{"name":"井上織姬","effectText":"【登場時】將2張自己卡組上面的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA01DC/BLC-1-049":{"name":"朽木白哉","effectText":"【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-500。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA01DC/BLC-1-053":{"name":"朽木露琪亞","effectText":"【突襲】〈朽木露琪亞〉置為活動，並可移動至前線。\n【登場時】抽3張卡片，並將2張自己的手牌放置在場外。\n【啟動主要】【將1張手牌放置在場外】【每回合1】選擇最多1張自己場上的角色卡，在這個回合中，BP+500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA01DC/BLC-1-064":{"name":"月牙天衝","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈黑崎一護〉時，改為『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA01DC/BLC-1-066":{"name":"卍解","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA01DC/BLC-1-103":{"name":"黑崎一護","effectText":"【攻擊時】這張角色卡在這個回合中，BP+1000。","triggerText":""},"UA01DC/BLC-1-104":{"name":"黑崎一護","effectText":"【突襲】〈黑崎一護〉置為活動，並可移動至前線。\n【啟動主要】【每回合1】將自己場外的4張卡片放置在移除區。若有執行此動作時，抽1張卡片，這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA01DC/BLC-2-052":{"name":"阿散井戀次","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA01DC/BLC-2-050":{"name":"浦原喜助","effectText":"【登場時】查看5張自己卡組上面的卡片，公開其中最多1張不具備特徵且不持有【突襲】的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA01DC/BLC-2-054":{"name":"朽木露琪亞","effectText":"【我方回合中】若在這個回合中已將自己的手牌放置在場外時，這張角色卡BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA01DC/BLC-4-083":{"name":"朽木露琪亞","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n當這張角色卡被突襲時，從以下選擇1項。（發動突襲的角色卡的【登場時】與這個效果可以依任意順序處理）\n・查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。\n・選擇最多1張自己場上的〈朽木露琪亞〉，在這個回合中，使其獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。\n【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA01DC/BLC-4-082":{"name":"黑崎一護","effectText":"【登場時】查看2張自己卡組上面的卡片，將任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。若以這個效果放置在場外的卡片中有能源需求3以上的卡片時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC02BT/NIK-2-001":{"name":"艾芙","effectText":"這張卡片也視為〈格拉維〉。\n【啟動主要】【轉為休息】僅限自己移除區有10張以上卡片時可發動。將這張角色卡放置在移除區，並抽1張卡片。在這個回合中，下一張從手牌中使用，原始能源需求為10以上的〈灰姑娘〉，其能源需求減少【黃×6】。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-003":{"name":"瑪麗安","effectText":"【登場時】【若在能源線時】將這張角色卡置為活動。\n【啟動主要】【轉為休息】僅限在這個回合中自己已使用〈記憶〉時可發動。從以下選擇1項。在這個回合中〈瑪麗安〉已選擇的效果無法選擇。\n・選擇1張自己場上的［特徵：反擊部隊］，在這個回合中，BP+2000。\n・選擇1張對手前線BP2500以上的角色卡，在這個回合中，BP-2000。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"PC02BT/NIK-2-004":{"name":"拉毗","effectText":"【我方回合中】在這個回合中自己使用了事件卡時，這張角色卡BP+1000。\n當這張角色卡被突襲時，若這張角色卡下面有背面朝上的卡片時，抽1張卡片。（發動突襲的角色卡的【登場時】與這個效果可以依任意順序處理）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-005":{"name":"拉毗：小紅帽","effectText":"這張卡片也視為〈拉毗〉。\n當自己不持有【突襲】的〈拉毗〉攻擊結束時，若該角色卡下面有背面朝上的卡片，且滿足這張卡片的能源需求時，可從手牌中使這張卡片對該〈拉毗〉發動突襲。〈拉毗：小紅帽〉的這個效果每回合僅可發動1次。\n【突襲】〈拉毗〉置為活動，並可移動至前線\n【登場時】若自己場上有〈阿妮斯〉與〈尼恩〉時，這張角色卡在這個回合中，獲得BP+2000與【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-006":{"name":"毒蛇","effectText":"【突襲】〈毒蛇〉置為活動，並可移動至前線\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【啟動主要】【若在前線時】【每回合1】將1張自己前線活動狀態的其他〔［特徵：外來者部隊］或［特徵：警備衛士部隊］〕轉為休息。若有執行此動作時，選擇1張自己場上的〔［特徵：外來者部隊］或［特徵：警備衛士部隊］〕，在這個回合中，BP+2000並獲得【衝擊（1）】，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-007":{"name":"阿妮斯：閃耀夏日","effectText":"這張卡片也視為〈阿妮斯〉。\n若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【我方回合中】在這個回合中自己使用了事件卡時，這張角色卡BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC02BT/NIK-2-008":{"name":"阿妮斯：閃耀夏日","effectText":"這張卡片也視為〈阿妮斯〉。\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】抽2張卡片，並將2張自己的手牌放置在場外。","triggerText":""},"PC02BT/NIK-2-009":{"name":"格拉維","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：遠古故事］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在移除區。","triggerText":""},"PC02BT/NIK-2-002":{"name":"尼恩：藍色海洋","effectText":"這張卡片也視為〈尼恩〉。\n【我方回合中】在這個回合中若自己已使用事件卡時，這張角色卡BP+1000。\n這張角色卡的攻擊沒有被防禦時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-010":{"name":"格拉維","effectText":"【登場時】若此角色卡從自己的手牌登場時，可支付1AP。若有執行此動作時，抽1張卡片。之後，可將1張自己手牌中的〈灰姑娘〉放置在移除區。若有執行此動作時，發動該張卡片的【觸發】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-013":{"name":"灰姑娘","effectText":"【登場時】若自己移除區有3張以上卡片時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-011":{"name":"格拉維","effectText":"【突襲】〈格拉維〉置為活動，並可移動至前線\n【登場時】將2張自己卡組上面的卡片放置在移除區。可將1張自己的手牌放置在移除區。若有執行此動作時，使最多1張自己移除區中能源需求『0』以下消耗AP1的黃色［特徵：遠古故事］以休息狀態在自己場上登場。若為我方回合中，自己移除區每有1張卡片，藉由此效果登場的角色卡的能源需求範圍+1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-015":{"name":"灰姑娘","effectText":"使這張角色卡以活動狀態在自己場上登場。\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【若在前線時】自己場上〈灰姑娘〉以外的角色卡，不會被對手的效果選擇。\n【登場時】選擇最多1張對手前線的角色卡，使其退場。〈灰姑娘〉的這個效果每回合僅可發動1次。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"PC02BT/NIK-2-012":{"name":"灰姑娘","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張放置在移除區。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-017":{"name":"小美人魚","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【攻擊時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或移除區。之後，若自己移除區有6張以上卡片時，抽1張卡片。\n【退場時】將這張卡片放置在移除區。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"PC02BT/NIK-2-018":{"name":"繼承","effectText":"查看2張自己卡組上面的卡片，將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。可從自己場外使最多1張能源需求2以下的〈拉毗〉以活動狀態在自己場上登場。若有執行此動作時，使該張〈拉毗〉在這個回合中，BP+2500，並將這張卡片以背面朝上放置在該張〈拉毗〉下面。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"PC02BT/NIK-2-019":{"name":"桃樂絲","effectText":"【登場時】若自己場上擁有6張以上不持有【觸發】的卡片時，將這張角色卡置為活動。〈桃樂絲〉的這個效果每回合僅可發動1次。\n【退場時】可將1張自己手牌中不持有【觸發】的卡片放置在場外。若有執行此動作時，選擇最多1張對手前線持有【觸發】的角色卡，使其轉為休息。","triggerText":""},"PC02BT/NIK-2-020":{"name":"皇冠","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：白騎士］或［特徵：開拓者部隊］或〈神罰〉放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-021":{"name":"皇冠","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：白騎士］或［特徵：開拓者部隊］或〈神罰〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"PC02BT/NIK-2-016":{"name":"小美人魚","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【我方回合中】若自己移除區有3張以上卡片時，這張角色卡BP+1000。\n【退場時】將這張卡片放置在移除區。","triggerText":""},"PC02BT/NIK-2-023":{"name":"特羅姆貝","effectText":"【登場時】若自己場上有〈皇冠〉時，從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・在這個回合中，若曾因自己的效果將自己的手牌放置在場外時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-022":{"name":"皇冠","effectText":"【突襲】〈皇冠〉/〈特羅姆貝〉置為活動，並可移動至前線\n【登場時】抽1張卡片。之後，可將1張自己的手牌放置在場外。若有執行此動作時，從自己手牌中，使最多1張能源需求3以下消耗AP1的紫色〔［特徵：白騎士］或［特徵：開拓者部隊］或〈神罰〉〕以休息狀態在自己場上登場。\n【啟動主要】【每回合1】這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。將自己所有的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-024":{"name":"紅蓮：暗影","effectText":"這張卡片也視為〈紅蓮〉。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-025":{"name":"紅蓮：暗影","effectText":"這張卡片也視為〈紅蓮〉。\n這張角色卡不會被BP2000以下的角色卡防禦。\n若這張角色卡的BP在6000以上時，這張角色卡獲得【傷害（2）】。\n【登場時】若自己場上此卡以外的［特徵：女神部隊］的原始卡片名稱有3種以上時，將這張角色卡置為活動。〈紅蓮：暗影〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC02BT/NIK-2-026":{"name":"白雪公主：純真年代","effectText":"這張卡片也視為〈白雪公主〉。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC02BT/NIK-2-027":{"name":"白雪公主：純真年代","effectText":"這張卡片也視為〈白雪公主〉。\n【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：女神部隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-014":{"name":"灰姑娘","effectText":"【突襲】〈灰姑娘〉置為活動，並可移動至前線\n【登場時】選擇最多1張自己場上的［特徵：遠古故事］，置為活動。\n【退場時】查看3張自己卡組上面的卡片，將其中1張加入手牌，其餘卡片放置在移除區。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-029":{"name":"桃樂絲","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【我方回合中】若自己場上此卡以外的角色卡的原始卡片名稱有3種以上時，這張角色卡BP+1000。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"PC02BT/NIK-2-030":{"name":"長髮公主：純潔恩典","effectText":"這張卡片也視為〈長髮公主〉。\n【攻擊時】若這張卡片以外自己場上［特徵：女神部隊］的原始卡片名稱有3種以上時，可抽1張卡片。若有執行此動作時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-032":{"name":"莉莉維絲","effectText":"自己場上每有1種［特徵：女神部隊］的原始卡片名稱，手牌中這張卡片的能源需求減少【紫×1】。","triggerText":""},"PC02BT/NIK-2-031":{"name":"長髮公主：純潔恩典","effectText":"這張卡片也視為〈長髮公主〉。\n【登場時】從自己場外將〈長髮公主：純潔恩典〉以外能源需求3以下消耗AP1的［特徵：女神部隊］最多1張加入手牌。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"PC02BT/NIK-2-033":{"name":"小紅帽","effectText":"【登場時】選擇最多『1張』自己場上的［特徵：女神部隊］，在這個回合中，BP+1000。若這張角色卡是因自己的〈小紅帽〉的效果而登場時，則替換成『2張』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-034":{"name":"小紅帽","effectText":"【登場時】可將1張自己場上能源需求3以下的其他［特徵：女神部隊］放回手牌。若有執行此動作時，選擇最多1張自己場上的［特徵：女神部隊］，『在這個回合中，BP+1000』。若這張角色卡是因自己的〈小紅帽〉的效果而登場時，則替換成『置為活動，並在這個回合中，BP+1000』。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-035":{"name":"小紅帽","effectText":"若這張卡片以外自己場上［特徵：女神部隊］的原始卡片名稱有3種以上時，這張角色卡的產生能源+【紫】。\n【登場時】若這張角色卡是因自己的〈小紅帽〉的效果而登場時，自己直到下一個我方回合開始前，獲得「若自己前線有〈小紅帽〉時，對手以效果選擇〈小紅帽〉以外自己場上的角色卡時，必須追加將1張自身手牌放置在場外才可以選擇。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-028":{"name":"白雪公主：純真年代","effectText":"這張卡片也視為〈白雪公主〉。\n【突襲】〈白雪公主：純真年代〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的［特徵：女神部隊］，在這個回合中，BP+1000。\n【攻擊時】若自己場上有〈小紅帽〉時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-036":{"name":"小紅帽","effectText":"若這張角色卡的BP在6000以上時，這張角色卡獲得【衝擊（1）】。\n【突襲】〈小紅帽〉置為活動，並可移動至前線\n在這張角色卡的攻擊結束時，將最多1張這張角色卡的突襲來源卡以休息狀態在自己場上登場。\n【登場時】這張角色卡在這個回合中，獲得「這張角色卡不會被對手的觸發效果選擇。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-037":{"name":"紅蓮","effectText":"【突襲】〈紅蓮〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【使這張卡片退場】從自己手牌中，使最多1張能源需求5以下的紫色［特徵：開拓者部隊］以活動狀態在自己場上登場。\n【退場時】使最多1張這張角色卡的突襲來源卡以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"PC02BT/NIK-2-039":{"name":"雪與狼","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈白雪公主：純真年代〉或〈小紅帽〉時，則替換成『BP4000以下』。若自己場上有〈白雪公主：純真年代〉與〈小紅帽〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"PC02BT/NIK-2-040":{"name":"愛麗絲：仙境兔女郎","effectText":"這張卡片也視為〈愛麗絲〉。\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】從自己場外，使最多1張能源需求『0』以下消耗AP1的綠色［特徵：泰特拉］以活動狀態在自己場上登場，或發動突襲。自己場上卡片下面的每1張背面朝上卡片，藉由此效果登場或發動突襲的角色卡的能源需求範圍+1。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC02BT/NIK-2-041":{"name":"諾亞爾","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。\n【登場時】抽1張卡片，並將1張自己的手牌以背面朝上放置在自己場上［特徵：泰特拉］的下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-042":{"name":"布蘭兒","effectText":"【登場時】從以下選擇1項。\n・若自己場上卡片下面的背面朝上卡片合計在2張以上時，抽1張卡片。\n・可將1張自己場上卡片下面的背面朝上卡片放置在場外。若有執行此動作時，選擇最多1張自己場上的［特徵：泰特拉］，在這個回合中，BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-043":{"name":"露姬","effectText":"若這張角色卡下面有背面朝上卡片時，這張角色卡的產生能源+【綠】。\n【啟動主要】【轉為休息】【每回合1】將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-045":{"name":"伊萊格：BOOM與驚嚇","effectText":"這張卡片也視為〈伊萊格〉。\n使這張角色卡以活動狀態登場。\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【每回合1】從以下選擇最多2項。\n・選擇最多1張自己場上其他的［特徵：米西利斯］，在這個回合中，BP+1000。\n・選擇最多1張自己場上其他的［特徵：米西利斯］，在這個回合中，獲得【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"PC02BT/NIK-2-046":{"name":"蒂亞","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：米西利斯］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-038":{"name":"勝利女神","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"PC02BT/NIK-2-047":{"name":"娜嘉","effectText":"【登場時】查看『1張』自己卡組上面的卡片，將最多1張放置在卡組上面，其餘卡片依任意順序放置在卡組下面。自己前線每有1張BP4000以上的［特徵：米西利斯］，藉由此效果查看的卡組張數+1。","triggerText":"[抽卡] 抽1張卡片。"},"PC02BT/NIK-2-048":{"name":"德雷克","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡的BP在4000以上時可發動。選擇1張自己場上其他的［特徵：米西利斯］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-049":{"name":"拉普拉斯","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。\n【每回合1】當這張角色卡的BP增加時，若為我方回合中，這張角色卡在這個回合中，BP+500。","triggerText":""},"EX10BT/AOT-2-001":{"name":"葉蓮娜","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"PC02BT/NIK-2-050":{"name":"拉普拉斯","effectText":"【突襲】〈拉普拉斯〉置為活動，並可移動至前線\n若這張角色卡的BP在6000以上時，這張角色卡獲得【衝擊（1）】。\n【登場時】抽1張卡片。這張角色卡在這個回合中，BP+1000。若這張角色卡的突襲來源BP在4000以上時，再抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-002":{"name":"欧良果彭","effectText":"【登場時】從自己手牌中，使最多1張［特徵：地鳴］以外，能源需求3以下消耗AP1的黃色角色卡以休息狀態在自己場上登場。無法使用這個效果使自己場上已有的同名卡片登場。","triggerText":""},"EX10BT/AOT-2-003":{"name":"賈碧・布朗","effectText":"【登場時】若自己場上［特徵：地鳴］以外的黃色角色卡的卡片名稱有4種以上時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-004":{"name":"奇優宓・阿茲瑪比托","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"PC02BT/NIK-2-051":{"name":"GOLDEN COIN RUSH","effectText":"選擇1張對手前線『BP3000』以下的角色卡，使其退場。自己場上［特徵：777］與卡片名稱包含「兔女郎」的角色卡的合計張數每有1張，藉由此效果可選擇的角色卡的BP範圍+1000。選擇1張自己場上的角色卡，在這個回合中，BP+500，並將1張自己卡組上面的卡片以背面朝上放置在該角色卡下面。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX10BT/AOT-2-005":{"name":"柯尼・史普林格","effectText":"若自己場上［特徵：地鳴］以外的黃色角色卡的卡片名稱有4種以上時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-006":{"name":"約翰・基爾休坦","effectText":"【我方回合中】若自己場上［特徵：地鳴］以外的黃色角色卡的卡片名稱有4種以上時，這張角色卡BP+1500。","triggerText":""},"EX10BT/AOT-2-007":{"name":"漢吉・佐耶","effectText":"使這張角色卡以活動狀態在場上登場。\n對手攻擊階段結束時，使這張角色卡退場。\n【每回合1】這張角色卡攻擊後與BP5000以上的角色卡對戰戰勝時，將這張角色卡置為活動，且這張角色卡在這個回合中，失去【狙擊】。\n【登場時】若自己場上擁有不同卡片名稱的［特徵：地鳴］以外的黃色角色卡有4種以上時，這張角色卡在這個回合中，獲得BP+2000與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"PC02BT/NIK-2-044":{"name":"索達：閃亮兔女郎","effectText":"這張卡片也視為〈索達〉。\n【登場時】可將自己場上卡片下面的背面朝上卡片任意張數移動至這張角色卡下面。若移動了2張以上時，將這張角色卡置為活動。〈索達：閃亮兔女郎〉的這個效果每回合僅可發動1次。\n【攻擊時】可將這張角色卡下面背面朝上的卡片任意張數放置在場外。若有執行此動作時，每有1張以此效果放置在場外的卡片，這張角色卡在這個回合中BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-008":{"name":"米卡莎・阿卡曼","effectText":"BP5000以上的角色卡無法防禦這張角色卡。\n若對手的生命值為1時，這張角色卡獲得【衝擊（1）】。\n【登場時】若自己場上擁有不同卡片名稱的［特徵：地鳴］以外的黃色角色卡有4種以上，且對手的生命值在5以下時，將這張角色卡置為活動。〈米卡莎・阿卡曼〉的這個效果每回合僅可發動1次。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX10BT/AOT-2-009":{"name":"里維","effectText":"【我方回合中】這張角色卡BP+1000。\n【啟動主要】【支付1AP】僅限自己場上擁有不同卡片名稱的［特徵：地鳴］以外的黃色角色卡有4種以上時可發動。從以下選擇『1個』。可將1張自己的手牌放置在場外。若有執行此動作時，則替換成『2個』。〈里維〉的這個效果每回合僅可發動1次。\n・將這張角色卡置為活動。\n・這張角色卡在這個回合中，獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX10BT/AOT-2-012":{"name":"阿爾敏・亞魯雷特","effectText":"【登場時】『抽1張卡片，並將1張自己的手牌放置在場外』。若自己場上擁有「地鳴」特徵以外不同卡片名稱的黃色角色卡有4種以上時，則替換成『抽1張卡片』。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-011":{"name":"阿爾敏・亞魯雷特","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-010":{"name":"亞妮・雷恩哈特","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"EX10BT/AOT-2-013":{"name":"阿爾敏・亞魯雷特（超大型巨人）","effectText":"若自己場上擁有「地鳴」特徵以外不同卡片名稱的黃色角色卡有4種以上時，在場上以外的所有區域，這張卡片的能源需求減少【黃×3】。\n【若在前線時】自己前線可放置的卡片張數減少1張。\n【突襲】〈阿爾敏・亞魯雷特〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】【若在前線時】選擇最多1張對手前線BP6000以下的角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-014":{"name":"皮可・芬格爾","effectText":"【登場時】【若在能源線時】若自己場上擁有「地鳴」特徵以外不同卡片名稱的黃色角色卡有4種以上時，使這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX10BT/AOT-2-016":{"name":"法爾科・葛萊斯","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張「地鳴」特徵以外的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX10BT/AOT-2-017":{"name":"法爾可・葛萊斯（顎之巨人）","effectText":"【突襲】〈法爾可・葛萊斯〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場技能】從自己場上或場外，選擇最多合計3張卡片名稱各不相同，擁有「地鳴」特徵以外且能源需求為3以下的角色卡，以背面朝上放置在這張角色卡下面。\n【啟動主要】【轉為休息】查看這張角色卡下面的背面朝上卡片，並將其中最多1張卡片加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-020":{"name":"艾連・葉卡","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX10BT/AOT-2-021":{"name":"艾連・葉卡","effectText":"若自己場上或場外有〈始祖尤米爾〉時，這張角色卡的產生能源+【黃】。","triggerText":""},"EX10BT/AOT-2-022":{"name":"艾連・葉卡（終尾的巨人）","effectText":"若自己場上有卡片名稱包含「吉克」的角色卡，且沒有〈艾連・葉卡（終尾的巨人）〉時，在場上以外的所有區域，這張卡片的能源需求減少【黃×5】。\n這張角色卡無法防禦擁有【衝擊】的角色卡。\n【突襲】〈艾連・葉卡〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】從自己手牌或場外，使最多1張［特徵：歷代九大巨人］以活動狀態在自己場上登場。\n【啟動主要】【支付1AP】【每回合1】在這張角色卡登場的回合中無法發動。發動這張角色卡的【登場時】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-023":{"name":"吉克・葉卡","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX10BT/AOT-2-024":{"name":"吉克・葉卡","effectText":"【登場時】選擇以下1項。\n・查看3張自己卡組上面的卡片。從中將最多1張卡片放置在場外。其餘卡片依任意順序放置在自己卡組下面。\n・若這張角色卡是從場外登場時，抽1張卡片。","triggerText":""},"EX10BT/AOT-2-019":{"name":"萊納・布朗（鎧之巨人）","effectText":"【突襲】〈萊納・布朗〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】若自己場上擁有「地鳴」特徵以外不同卡片名稱的黃色角色卡有4種以上時，這張角色卡直到下一個我方回合開始前，獲得BP+1000與【衝擊（1）】，且對手使用角色卡效果或事件卡效果選擇這張角色卡時，必須追加支付1AP才可以選擇。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-018":{"name":"萊納・布朗","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-026":{"name":"顎之巨人","effectText":"若自己場上有卡片名稱包含「艾連」的角色卡與卡片名稱包含「吉克」的角色卡時，這張角色卡獲得「這張角色卡在位於前線時也能產生能源。」。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-025":{"name":"吉克・葉卡（獸之巨人）","effectText":"【突襲】〈吉克・葉卡〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得【衝擊（1）】，選擇最多1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有卡片名稱包含「艾連」的角色卡，且自己場上或場外有〈始祖尤米爾〉時，則替換成『BP4000以下』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-015":{"name":"法爾科・葛萊斯","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-028":{"name":"戰鎚巨人","effectText":"若自己場上有卡片名稱包含「艾連」的角色卡，以及卡片名稱包含「吉克」的角色卡時，這張角色卡獲得「不會因對手角色卡的效果〔退場，且BP不會被減少〕。」與【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-027":{"name":"獸之巨人","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】若自己場上有卡片名稱包含「艾連」的角色卡與卡片名稱包含「吉克」的角色卡時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-030":{"name":"湯姆・庫沙瓦","effectText":"【登場時】【退場時】公開2張自己卡組上面的卡片。從其中將最多1張卡片名稱包含「吉克」的卡片加入手牌。將其餘卡片放置在場外。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-032":{"name":"庫沙瓦先生，請你看著我吧！！","effectText":"將1張自己場上卡片名稱包含「吉克」的黃色角色卡退場。若有執行此動作時，選擇最多1張對手前線BP5000以下的角色卡，使其退場，並從以下效果中選擇最多1項。\n・查看7張自己卡組上面的卡片。公開其中最多1張〈始祖尤米爾〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n・若自己場上或場外有〈始祖尤米爾〉時，使最多1張自己場外不具備【突襲】的黃色〈吉克・葉卡〉以休息狀態在自己場上登場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX10BT/AOT-2-031":{"name":"始祖尤米爾","effectText":"僅在自己場上有卡片名稱包含「葉卡」的角色卡時，這張場域卡才可登場。\n【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：巨人繼承者］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】【將2張手牌放置在場外】【支付1AP】使1張自己場外能源需求2以下，卡片名稱包含「葉卡」的黃色角色卡以休息狀態在自己場上登場。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX10BT/AOT-2-033":{"name":"抱歉 我辦不到","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX10BT/AOT-2-035":{"name":"是自由的","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX10BT/AOT-2-034":{"name":"地鳴","effectText":"將1張自己場上卡片名稱包含「吉克」的黃色角色卡退場。若有執行此動作時，選擇最多1張對手前線BP5000以下的角色卡，使其退場，並從以下效果中選擇最多1項。\n・查看7張自己卡組上面的卡片。公開其中最多1張〈始祖尤米爾〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n・若自己場上或場外有〈始祖尤米爾〉時，使最多1張自己場外不具備【突襲】的黃色〈吉克・葉卡〉以休息狀態在自己場上登場。","triggerText":""},"EX10BT/AOT-2-036":{"name":"快走吧 去拯救世界","effectText":"查看5張自己卡組上面的卡片。公開其中最多3張，卡片名稱各不相同且不具備［特徵：地鳴］的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-038":{"name":"漢吉・佐耶","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX10BT/AOT-2-039":{"name":"漢吉・佐耶","effectText":"【登場時】選擇最多1張對手前線BP2500以上的角色卡，在這個回合中，BP-2000。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-040":{"name":"里維","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己前線的活動角色卡轉為休息。若如此做，這張角色卡在這個回合中，產生能源+【藍】。","triggerText":""},"EX10BT/AOT-2-041":{"name":"里維","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【攻擊時】可以支付1AP。若有執行此動作時，選擇最多2張自己場上的角色卡，在這個回合中，BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-043":{"name":"莎夏・布勞斯","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-042":{"name":"里維","effectText":"【突襲】〈里維〉置為活動，並可移動至前線\n【登場時】抽1張卡片。之後，可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己的AP卡，置為活動。\n【攻擊時】可以支付1AP。若有執行此動作時，從以下選擇1項。\n・抽1張卡片，這張角色卡在這個回合中，BP+1000。\n・這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-044":{"name":"希絲特莉亞・雷斯","effectText":"【啟動主要】【轉為休息】 僅在自己場外有6張以上事件卡時，選擇1張自己場上其他［特徵：104期兵］的卡片，在這個回合中，BP+1000。","triggerText":""},"EX10BT/AOT-2-037":{"name":"我來動手 大家一起合作","effectText":"若自己場上不具備［特徵：地鳴］的黃色角色卡有4種以上不同卡片名稱時，手牌中這張卡片的消耗AP-1。\n選擇1張對手前線『BP5000以下』的角色卡，使其退場。若自己場上有〈米卡莎・阿卡曼〉時，則替換成『BP8000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX10BT/AOT-2-029":{"name":"超大型巨人","effectText":"若自己場上有卡片名稱包含「艾連」的角色卡，以及卡片名稱包含「吉克」的角色卡時，手牌中這張卡片的能源需求減少【黃×2】。\n這張卡片無法在能源線登場。\n【若在前線時】自己前線可放置的卡片張數減少1張。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-045":{"name":"希絲特莉亞・雷斯","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・若自己場外有2張以上事件卡時，抽1張卡片。\n・若自己場外有6張以上事件卡時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-046":{"name":"米卡莎・阿卡曼","effectText":"依據自己場外的事件卡張數，這張角色卡獲得以下全數效果。\n・2張以上：BP+1000。\n・4張以上：【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-049":{"name":"雷槍","effectText":"選擇1張對手前線BP2500以下或BP4500以上的角色卡，使其退場。","triggerText":""},"EX10BT/AOT-2-052":{"name":"吉克・葉卡","effectText":"【登場時】查看5張自己卡組上面的卡片。公開其中最多1張［特徵：無垢的巨人］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-048":{"name":"甜～甜的糖果","effectText":"查看4張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。使最多1張自己手牌中能源需求3以下消耗AP1的藍色角色卡以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-053":{"name":"吉克・葉卡（獸之巨人）","effectText":"【突襲】〈吉克・葉卡〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP3000以下的角色卡，使其退場。若使用這個效果使角色卡退場時，可支付1AP。若有執行此動作時，使最多1張自己場外［特徵：無垢的巨人］以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-047":{"name":"阿爾敏・亞魯雷特","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張事件卡放置在場外。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-054":{"name":"皮可・芬格爾","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX10BT/AOT-2-056":{"name":"皮可・芬格爾（車力巨人）","effectText":"【突襲】〈皮可・芬格爾〉置為活動，並可移動至前線\n【若在前線時】若為這張角色卡登場的回合中，這張角色卡獲得【衝擊（1）】。\n【登場時】可將這張角色卡在這個回合中，BP-2000。若有執行此動作時，這張角色卡在這個回合中，獲得「可從能源線攻擊。」與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。\n【退場時】將最多1張這張角色卡的突襲來源卡片放回手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-050":{"name":"賈碧・布朗","effectText":"【攻擊時】選擇最多1張自己場上其他［特徵：瑪雷的戰士］的卡片，『在這個回合中，BP+1000』。若選擇的角色卡為突襲狀態時，則替換成『該張角色卡與這張角色卡在這個回合中，BP+2000』。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX10BT/AOT-2-055":{"name":"皮可・芬格爾","effectText":"【登場時】選擇最多1張自己場上其他［特徵：瑪雷的戰士］，在這個回合中，『BP+1000』。若選擇的角色卡為突襲狀態時，則替換成『BP+2000』。","triggerText":""},"EX10BT/AOT-2-058":{"name":"波爾克・賈利亞德（顎之巨人）","effectText":"【突襲】〈波爾克・賈利亞德〉置為活動，並可移動至前線\n【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：瑪雷的戰士］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n【攻擊時】若這張角色卡的BP在6000以上時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX10BT/AOT-2-060":{"name":"萊納・布朗（鎧之巨人）","effectText":"【突襲】〈萊納・布朗〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，這張角色卡在這個回合中，BP+2000。\n【攻擊時】若這張角色卡的BP在6000以上時，抽1張卡片，這張角色卡在這個回合中獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-059":{"name":"萊納＆貝爾托特＆亞妮","effectText":"這張卡片也視為〈萊納・布朗〉、〈貝爾托特・胡佛〉及〈亞妮・雷恩哈特〉。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-051":{"name":"法爾科・葛萊斯","effectText":"【登場時】【若在能源線時】使這張角色卡置為活動。\n【啟動主要】【轉為休息】【將1張手牌放置在場外】選擇1張自己場上其他［特徵：瑪雷的戰士］的卡片，在這個回合中，『BP+1000』。若選擇的角色卡為突襲狀態時，則替換成『BP+2000』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-061":{"name":"偷襲","effectText":"使最多1張自己場上卡片名稱包含「皮克・芬格」的角色卡退場。選擇最多1張對手前線『BP3000以下』的角色卡，使其退場。若自己場外有卡片名稱包含「皮克・芬格」的角色卡時，則替換成『BP5000以下』。之後，若使用這張卡片的效果使自己場上的角色卡退場時，將最多1張自己場外卡片名稱包含「皮克・芬格」的角色卡加入手牌。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX10BT/AOT-2-057":{"name":"波爾克・賈利亞德","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-062":{"name":"尼柯洛","effectText":"【登場時】在這個回合中，接下來使用［特徵：食材］的消耗AP-1。","triggerText":""},"EX10BT/AOT-2-064":{"name":"約翰・基爾休坦","effectText":"【攻擊時】查看3張自己卡組上面的卡片。將其依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-063":{"name":"柯尼・史普林格","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"EX10BT/AOT-2-065":{"name":"莎夏・布勞斯","effectText":"【登場時】若在這個回合中自己已使用［特徵：食材］時，使這張角色卡置為活動。〈莎夏・布勞斯〉的這個效果每回合僅能發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-066":{"name":"米卡莎・阿卡曼","effectText":"在自己結束階段開始時，若在這個回合的攻擊階段中自己場上的紅色［特徵：104期兵］有放回手牌，可將手牌中這張卡片以休息狀態在自己前線登場。〈米卡莎・阿卡曼〉的這個效果每回合僅可發動1次。","triggerText":""},"EX10BT/AOT-2-070":{"name":"艾連・葉卡","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：104期兵］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-067":{"name":"米卡莎・阿卡曼","effectText":"這張卡片僅能藉由自己的效果或突襲登場。\n【突襲】〈米卡莎・阿卡曼〉置為活動，並可移動至前線\n【登場時】選擇以下1項。\n・將最多1張自己場外能源需求3以下且不持有【突襲】的［特徵：104期兵］卡片加入手牌。\n・選擇最多1張對手前線的角色卡。若該張角色卡的BP在5000以上時，可將2張自己的手牌放置在場外。若執行此動作，使該張角色卡退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-068":{"name":"阿爾敏・亞魯雷特","effectText":"〈阿爾敏・亞魯雷特（超大型巨人）〉突襲至這張角色卡上時，該張卡片的能源需求減少【紅×2】。","triggerText":"[抽卡] 抽1張卡片。"},"EX10BT/AOT-2-071":{"name":"艾連・葉卡","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【啟動主要】【每回合1】將1張自己生命區的卡片加入手牌。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。\n【攻擊時】『查看1張自己卡組上面的卡片，若該張卡片為能源需求3以下［特徵：104期兵］時，可公開並加入手牌。若不加入手牌時，將該張卡片放置在自己卡組的上面或下面』。若自己的生命值在3以下時，則替換成『抽1張卡片』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX10BT/AOT-2-072":{"name":"艾連・葉卡（進擊的巨人）","effectText":"【突襲】〈艾連・葉卡〉置為活動，並可移動至前線\n【登場時】這張角色卡直到下一個我方回合開始前，BP+1000。從以下選擇1項。\n・選擇最多1張對手前線BP3000以下的角色卡，使其退場。\n・將1張自己生命區的卡片加入手牌，並選擇最多1張對手前線BP5000以下的角色卡，使其退場。\n・若自己的生命值在3以下時，選擇最多1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX10BT/AOT-2-073":{"name":"海產","effectText":"從以下選擇1項。\n・選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。抽2張卡片。\n・選擇最多2張自己場上的角色卡，在這個回合中，BP+1000。抽1張卡片。\n・選擇最多3張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-003":{"name":"葛城莉莉亞","effectText":"當這張角色卡因自己或對手的效果而離場時，從自己手牌中，使最多1張能源需求3以下消耗AP1的黃色〈葛城莉莉亞〉以休息狀態在自己場上登場。\n【我方回合中】若自己場上擁有4種以上不同卡片名稱的［特徵：1年級］，或有〈紫雲清夏〉時，這張角色卡BP+1000。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX13BT/GIM-2-002":{"name":"葛城莉莉亞","effectText":"【每回合1】當〈紫雲清夏〉在與這張角色卡不同的線登場時，可將這張角色卡移動至另一線。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-004":{"name":"倉本千奈","effectText":"【登場時】選擇最多1張自己場上的［特徵：1年級］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-005":{"name":"倉本千奈","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：1年級］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-006":{"name":"紫雲清夏","effectText":"【我方回合中】若自己場上擁有4種以上不同卡片名稱的［特徵：1年級］，或有〈葛城莉莉亞〉時，這張角色卡BP+1500。","triggerText":""},"EX13BT/GIM-2-007":{"name":"紫雲清夏","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】『抽1張卡片，並將1張自己的手牌放置在場外』。若自己場上擁有4種以上不同卡片名稱的［特徵：1年級］，或有〈葛城莉莉亞〉時，可替換成『抽1張卡片』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-009":{"name":"雨夜燕","effectText":"【登場時】查看2張自己卡組上面的卡片，將最多1張［特徵：3年級］放置在場外，其餘卡片依任意順序放置在自己卡組上面。","triggerText":""},"EX13BT/GIM-2-008":{"name":"篠澤 廣","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-010":{"name":"雨夜燕","effectText":"若自己場上有4張以上［特徵：3年級］時，這張角色卡的產生能源+【黃】。","triggerText":""},"EX13BT/GIM-2-001":{"name":"根緒亞紗里","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"EX13BT/GIM-2-011":{"name":"雨夜燕","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】若自己場上有〈十王星南〉時，這張角色卡BP+1000。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX13BT/GIM-2-013":{"name":"有村麻央","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX13BT/GIM-2-014":{"name":"有村麻央","effectText":"【登場時】抽1張卡片。","triggerText":""},"EX13BT/GIM-2-017":{"name":"姬崎莉波","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":""},"EX13BT/GIM-2-012":{"name":"雨夜燕","effectText":"【突襲】〈雨夜燕〉置為活動，並可移動至前線\n若自己場上有〈十王星南〉時，這張角色卡獲得【傷害（2）】。\n【退場時】可將1張自己手牌中不持有【觸發】的卡片放置在場外。若有執行此動作時，將這張卡片以休息狀態在自己前線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX13BT/GIM-2-018":{"name":"姬崎莉波","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中任意張數以任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。","triggerText":""},"EX13BT/GIM-2-016":{"name":"有村麻央","effectText":"【突襲】〈有村麻央〉置為活動，並可移動至前線\n若自己場上有〈十王星南〉時，這張角色卡獲得【衝擊（1）】。\n【登場時】這張角色卡在這個回合中，BP+1000。\n【啟動主要】【若在前線時】【每回合1】從自己場外將最多1張能源需求3以下不持有【觸發】的黃色［特徵：3年級］加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX13BT/GIM-2-019":{"name":"姬崎莉波","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：3年級］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX13BT/GIM-2-021":{"name":"秦谷美鈴","effectText":"若自己場上有4種以上不同卡片名稱的［特徵：1年級］或〈月村手毬〉時，這張角色卡BP+1000。","triggerText":""},"EX13BT/GIM-2-020":{"name":"姬崎莉波","effectText":"【突襲】〈姬崎莉波〉置為活動，並可移動至前線\n若自己場上有〈十王星南〉時，這張角色卡獲得【衝擊無效】。\n【登場時】從以下選擇1項。\n・從自己手牌中，使最多1張能源需求3以下消耗AP1不持有【觸發】的黃色［特徵：3年級］以休息狀態在自己場上登場。\n・選擇最多1張對手前線的角色卡，使其轉為休息。\n【退場時】將最多1張這張角色卡的突襲來源卡放回手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX13BT/GIM-2-023":{"name":"花海佑芽","effectText":"【每回合1】當〈花海咲季〉在與這張角色卡不同的線登場時，可將這張角色卡移動至另一線。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-022":{"name":"秦谷美鈴","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-024":{"name":"花海佑芽","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n若自己場上有4種以上不同卡片名稱的［特徵：1年級］或〈花海咲季〉時，這張角色卡不會因自己或對手的效果而放回手牌，並獲得「這張角色卡攻擊後戰勝時，可抽最多1張卡片。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX13BT/GIM-2-025":{"name":"月村手毬","effectText":"在自己攻擊階段結束時，若與這張角色卡位於同一線上有〈秦谷美鈴〉或〈葛城莉莉亞〉時，可將這張角色卡移動至另一線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-015":{"name":"有村麻央","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【啟動主要】【若在前線時】【每回合1】查看1張自己卡組上面的卡片，若該張卡片不持有【觸發】時，可將其放置在場外。若沒有放置在場外時，將該張卡片放置在自己卡組的上面。","triggerText":""},"EX13BT/GIM-2-026":{"name":"月村手毬","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n這張角色卡的攻擊結束時，可將這張角色卡放置在自己卡組下面。若有執行此動作時，抽1張卡片，並選擇最多1張對手前線的角色卡，使其轉為休息。下一次無法置為活動。","triggerText":""},"EX13BT/GIM-2-028":{"name":"花海咲季","effectText":"【若在能源線時】自己攻擊階段結束時，若自己場上擁有4種以上不同卡片名稱的［特徵：1年級］或有〈花海佑芽〉時，可將這張角色卡移動至前線。\n【退場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX13BT/GIM-2-027":{"name":"花海咲季","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"EX13BT/GIM-2-030":{"name":"藤田琴音","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX13BT/GIM-2-032":{"name":"十王星南","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己場外，使最多1張〈十王星南〉以外能源需求1以下的黃色［特徵：3年級］以休息狀態在自己場上登場。","triggerText":""},"EX13BT/GIM-2-034":{"name":"十王星南","effectText":"【啟動主要】【若在前線時】【每回合1】從以下選擇最多2項。\n・選擇1張自己場上不持有【觸發】的［特徵：3年級］。從自己手牌中，使最多1張滿足能源需求的角色卡，對選擇的角色卡發動突襲。\n・若自己前線有3張以上持有【突襲】的［特徵：3年級］時，將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX13BT/GIM-2-029":{"name":"花海咲季","effectText":"【啟動主要】【若在前線時】【每回合1】僅限自己場上擁有4種以上不同卡片名稱的［特徵：1年級］或有〈花海佑芽〉時可發動。選擇1張〈花海咲季〉以外自己場上休息狀態的［特徵：1年級］角色卡，置為活動，並在這個回合中，獲得「攻擊階段結束時，將這張角色卡放回手牌。」。若以此效果選擇了BP4000以上的角色卡時，這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX13BT/GIM-2-035":{"name":"教室","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，將這張場域卡置為活動。\n【啟動主要】【轉為休息】【支付1AP】抽1張卡片。從自己手牌中，使最多1張滿足能源需求且消耗AP為1的［特徵：1年級］以活動狀態在自己場上登場。給予該張角色卡在這個回合中，「攻擊階段結束時，將這張角色卡放回手牌。」的效果。無法以此效果使自己場上已有的同名卡片登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX13BT/GIM-2-036":{"name":"妳還是老樣子，這麼笨拙呢","effectText":"查看3張自己卡組上面的卡片，公開其中最多1張［特徵：3年級］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若加入手牌的卡片不持有【觸發】時，從自己場外將最多1張〈十王 星南〉加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-031":{"name":"藤田琴音","effectText":"這張角色卡的攻擊結束時，可將這張角色卡放置在自己卡組下面。若有執行此動作時，抽1張卡片，並選擇最多1張〈藤田琴音〉以外自己能源線的［特徵：1年級］，移動至前線，並在這個回合中，BP+2000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX13BT/GIM-2-033":{"name":"十王星南","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張並加入手牌。其餘卡片依任意順序放置在自己卡組上面。若有將持有【觸發】的卡片加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX13BT/GIM-2-037":{"name":"這就是我們的，這三年","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-038":{"name":"來吧，再戰一場！","effectText":"選擇1張對手前線BP為（自己場上［特徵：3年級］的張數×1000）以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX13BT/GIM-2-040":{"name":"不是很適合嗎？","effectText":"選擇1張自己場上的角色卡，置為活動。若選擇的角色卡為［特徵：1年級］時，將1張自己的AP卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-041":{"name":"好，大家也一起來♪","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-039":{"name":"這就是食慾之秋嘛","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-042":{"name":"再一次，從頭開始！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。若自己場上擁有4種以上不同卡片名稱的［特徵：1年級］時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX13BT/GIM-2-043":{"name":"倉本千奈","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-046":{"name":"篠澤 廣","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態時可發動。查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-045":{"name":"篠澤 廣","effectText":"【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-044":{"name":"倉本千奈","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【退場時】若這張角色卡因對戰而退場，且自己場上有〈篠澤 廣〉時，從自己場外將這張卡片以外不持有【突襲】且原始BP2500以下的角色卡最多1張加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-047":{"name":"篠澤 廣","effectText":"【突襲】〈篠澤 廣〉置為活動，並可移動至前線\n【登場時】【若在前線時】若自己場上有〈倉本千奈〉時，抽3張卡片。\n【我方回合中】若自己前線有原始BP2500以下的其他角色卡時，這張角色卡BP+1500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX13BT/GIM-2-048":{"name":"十王星南","effectText":"【啟動主要】【每回合1】僅限自己場上有〈花海佑芽〉與〈秦谷美鈴〉，且在這張角色卡登場的回合中可發動。選擇1張自己場上持有【啟動主要】的〔〈花海佑芽〉或〈秦谷美鈴〉〕，置為活動。","triggerText":""},"EX13BT/GIM-2-049":{"name":"秦谷美鈴","effectText":"【啟動主要】【轉為休息】 【每回合1】將1張自己前線的活動角色卡轉為休息。若如此做，這張角色卡在這個回合中，產生能源+【青】。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-050":{"name":"秦谷美鈴","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】這張角色卡BP+1000。\n休息狀態的這張角色卡因效果置為活動時，從以下選擇1項。\n・這張角色卡在這個回合中，獲得【衝擊（1）】。\n・查看2張自己卡組上面的卡片，將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。\n【啟動主要】【每回合1】將活動狀態的這張角色卡轉為休息。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX13BT/GIM-2-053":{"name":"我喜歡你們","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-055":{"name":"來享受夏天吧！","effectText":"選擇最多1張自己場上原始BP為2500以下的角色卡，在這個回合中，BP+1500。將1張自己的AP卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-054":{"name":"閃閃發光好漂亮～！","effectText":"查看6張自己卡組上面的卡片，公開其中最多各1張〈花海佑芽〉、〈秦谷美鈴〉與〈十王星南〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-051":{"name":"花海佑芽","effectText":"【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，從以下選擇1項。\n・選擇最多1張自己場上原始BP為2500以下的其他角色卡，在這個回合中，BP+1500。\n・從自己場外將最多1張不持有【特殊觸發】與【最終觸發】的事件卡加入手牌。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX13BT/GIM-2-056":{"name":"製作還真是辛苦呢","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-058":{"name":"葛城莉莉亞","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張能源需求2以下的事件卡加入手牌。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX13BT/GIM-2-057":{"name":"葛城莉莉亞","effectText":"若自己前線有〈紫雲清夏〉時，這張角色卡的產生能源+【紅】。","triggerText":""},"EX13BT/GIM-2-059":{"name":"紫雲清夏","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-060":{"name":"紫雲清夏","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【突襲】〈紫雲清夏〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+1000。\n【登場時】在這個回合中自己使用了事件卡時，從自己手牌中，使最多1張能源需求3以下的紅色〔〈葛城莉莉亞〉或〈紫雲清夏〉〕以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX13BT/GIM-2-061":{"name":"月村手毬","effectText":"【啟動主要】【將1張手牌放置在場外】 【每回合1】這張角色卡在這個回合中，BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-052":{"name":"花海佑芽","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-063":{"name":"花海咲季","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若自己前線有〈月村手毬〉與〈藤田琴音〉時，這張角色卡BP+1500。","triggerText":""},"EX13BT/GIM-2-065":{"name":"藤田琴音","effectText":"【若在前線時】【每回合1】自己的〈月村手毬〉攻擊後沒有被防禦時，這張角色卡在這個回合中，BP+1000。\n【若在前線時】【每回合1】自己的〈花海咲季〉攻擊後戰勝時，可抽最多1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-066":{"name":"好溫暖呢","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-062":{"name":"月村手毬","effectText":"【我方回合中】若自己場上有〈花海咲季〉與〈藤田琴音〉時，這張角色卡獲得BP+1000與「這張角色卡攻擊後戰勝時，可抽最多1張卡片。」。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX13BT/GIM-2-067":{"name":"你是我媽嗎！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX13BT/GIM-2-068":{"name":"就是從這裡開始的呢！","effectText":"查看6張自己卡組上面的卡片。公開其中最多1張紅色的〔〈葛城莉莉亞〉或〈紫雲清夏〉〕並加入手牌。其餘卡片依任意順序放置在自己卡組下面。抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-064":{"name":"藤田琴音","effectText":"【登場時】選擇最多1張自己場上的〈花海咲季〉或〈月村手毬〉或其他〈藤田琴音〉，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX13BT/GIM-2-070":{"name":"我要盡情享受夏天！","effectText":"這張卡片僅限自己場上有〈花海咲季〉與〈月村手毬〉與〈藤田琴音〉時才能使用。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX12BT/KMR-2-001":{"name":"假面騎士VALEN CHOCODON形態","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片名稱包含「GAVV」或「VALEN」或「VRAM」的角色卡或〈口嚼獸〉放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-002":{"name":"假面騎士VALEN FRAPPE形態","effectText":"【啟動主要】【每回合1】僅限這張角色卡為休息狀態時可發動。將1張自己場上的〈口嚼獸〉退場。若有執行此動作時，將這張角色卡置為活動。\n【啟動主要】【若在前線時】【轉為休息】【每回合1】選擇1張對手前線BP3000以下的角色卡，使其轉為休息。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX13BT/GIM-2-069":{"name":"差不多烤好了嗎？","effectText":"抽2張卡片。在這個回合中若自己已使用事件卡時，再抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-003":{"name":"假面騎士VRAM A LA MODE形態","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】將1張自己場上活動狀態的〈口嚼獸〉轉為休息。若有執行此動作時，這張角色卡直到下一個我方回合開始前，獲得「這張角色卡若在前線時也可產生能源。」。","triggerText":""},"EX12BT/KMR-2-004":{"name":"假面騎士VRAM PUDDING形態","effectText":"【登場時】可將1張自己場上活動狀態的〈口嚼獸〉轉為休息。若有執行此動作時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-007":{"name":"假面騎士GAVV ZAKUZAKUCHIPS形態","effectText":"【啟動主要】【若在前線時】【每回合1】使1張自己場上的〈口嚼獸〉退場。若有執行此動作時，這張角色卡在這個回合中，BP+2000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-008":{"name":"假面騎士GAVV BLIZZARDSORBET形態","effectText":"【我方回合中】若在這個回合中自己場上的〈口嚼獸〉有退場時，這張角色卡獲得BP+1000與「【若在能源線時】自己場上角色卡的攻擊結束時，若自己前線有空格時，可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡移動至前線。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-006":{"name":"假面騎士GAVV CAKING形態","effectText":"【啟動主要】【每回合1】僅限自己場上與場外合計有3張以上〈口嚼獸〉時可發動。這張角色卡直到下一個我方回合開始前，產生能源+【黃】。\n【啟動主要】【轉為休息】使1張自己場上的〈口嚼獸〉退場。若有執行此動作時，使最多1張自己手牌中能源需求1以下不具備特徵的黃色角色卡以休息狀態在自己場上登場。","triggerText":""},"EX12BT/KMR-2-009":{"name":"假面騎士GAVV FUWAMALLOW形態","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【對方回合中】與BP3000以下的角色卡對戰戰敗的這張角色卡，將移動至能源線而非退場。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-010":{"name":"假面騎士GAVV POPPINGUMMY形態","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-005":{"name":"假面騎士GAVV OVER形態","effectText":"【突襲】卡片名稱包含「GAVV」的角色卡 置為活動，並可移動至前線\n若這張角色卡是在這個回合中因自己的效果而登場時，這張角色卡獲得BP+3000與「不會被對手的效果選擇。」。\n在這張角色卡的攻擊結束時，若自己在這個攻擊階段沒有發動突襲，可「公開1張自己手牌中的〈假面騎士GAVV MASTER形態〉，並將1張自己場上的〈口嚼獸〉退場。」。若有執行此動作時，將突襲狀態的這張角色卡最上面的卡片放回手牌，並使公開的卡片對這張角色卡的突襲來源卡發動突襲。\n【登場時】【攻擊時】將最多1張自己場外的〈口嚼獸〉加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-012":{"name":"假面騎士GAVV MASTER形態","effectText":"【突襲】卡片名稱包含「GAVV」的角色卡 置為活動，並可移動至前線\n若這張角色卡在這個回合中是因自己的效果而登場時，這張角色卡獲得BP+1000與【衝擊（1）】。\n這張角色卡的攻擊結束時，若自己在這個攻擊階段沒有發動突襲時，可執行「公開1張自己手牌中的〈假面騎士GAVV OVER形態〉，並使1張自己場上的〈口嚼獸〉退場。」。若有執行此動作時，將突襲狀態的這張角色卡最上面的卡片放回手牌，並將公開的卡片對這張角色卡的突襲來源卡發動突襲。\n【登場時】【攻擊時】使最多1張自己手牌中的〈口嚼獸〉以休息狀態在自己能源線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-013":{"name":"口嚼獸","effectText":"※這張卡片在卡組中最多可放入10張。\n【登場時】若自己場上沒有角色卡時，抽1張卡片，並將1張自己的手牌放置在場外。\n【退場時】抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-011":{"name":"假面騎士GAVV POPPINGUMMY形態","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「GAVV」或「VALEN」或「VRAM」的角色卡或〈口嚼獸〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX12BT/KMR-2-014":{"name":"快樂調色","effectText":"使這張場域卡以活動狀態在場上登場。\n【啟動主要】【轉為休息】【將1張手牌放置在場外】【支付1AP】使最多1張自己場外的〈口嚼獸〉以活動狀態在自己能源線登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-015":{"name":"從今以後不再和黑暗點心扯上關係,還是在這裡被我打倒","effectText":"選擇1張對手前線BP5000以下的角色卡，放置在對手卡組上面或下面的『對手所選擇的一方』。若自己場上有卡片名稱包含「GAVV」的角色卡時，則替換成『自己所選擇的一方』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX12BT/KMR-2-018":{"name":"假面騎士Geiz Wizard裝甲","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・可公開1張自己手牌中BP4000以下且持有【突襲】的黃色以外的角色卡。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-016":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX12BT/KMR-2-017":{"name":"假面騎士Woz 未來連結忍者","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己前線的活動角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，產生能源+【黃】。","triggerText":""},"EX12BT/KMR-2-019":{"name":"假面騎士ZI-O 逢魔型態","effectText":"【突襲】卡片名稱包含「ZI-O」的角色卡 置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【我方回合中】自己場上所有黃色以外的角色卡，獲得「這張角色卡在戰鬥中獲勝時，可抽最多1張卡片。」。〈假面騎士ZI-O 逢魔型態〉的這個效果不重複。\n【登場時】從自己場外，將任意張數BP4000以下且持有【突襲】的黃色以外的角色卡加入手牌。\n【啟動主要】【若在前線時】【每回合1】使1張自己手牌中BP4000以下且持有【突襲】的黃色以外的角色卡以活動狀態在自己前線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-020":{"name":"假面騎士ZERO-ONE 粉粹巨牙象","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"EX12BT/KMR-2-021":{"name":"假面騎士ZERO-ONE 地獄騰蝗形態","effectText":"【我方回合中】這張角色卡BP+1000。\n這張角色卡的攻擊結束時，可從自己手牌中，使最多1張〈假面騎士ZERO-ONE 實現蝗蟲型態〉突襲至這張角色卡上。\n【登場時】可將1張自己的手牌與1張自己的生命卡放置在場外。若有執行此動作時，抽2張卡片，並將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-022":{"name":"假面騎士Para-DX 完美擊倒玩家 Level 99","effectText":"【啟動主要】【若在前線時】從以下選擇1項。〈假面騎士Para-DX 完美擊倒玩家 Level 99〉的這個效果每回合僅可發動1次。\n・抽1張卡片，並將1張自己的手牌以背面朝上方式放置在這張角色卡或自己場上卡片名稱包含「EX-AID」的角色卡下面。\n・將自己場上角色卡下面的背面朝上卡片合計3張放置在場外。若有執行此動作時，選擇1張這張角色卡或自己場上卡片名稱包含「EX-AID」的角色卡，在這個回合中，獲得【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-024":{"name":"假面騎士ooo 鳥系聯組永恆","effectText":"這張卡片也視為〈安酷〉。\n這張角色卡以活動狀態登場。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】可將1張自己移除區的〈安酷〉放置在場外。若有執行此動作時，將1張自己的AP卡置為活動。\n【退場時】可將1張自己場外〈安酷〉以外卡片名稱包含「ooo」的角色卡放置在移除區。若有執行此動作時，從自己場外將最多1張能源需求0的〈安酷〉加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-025":{"name":"假面騎士ooo 爬蟲系聯組","effectText":"【登場時】從自己場外將最多2張能源需求0的〔場域卡或事件卡或卡片名稱包含「ooo」的角色卡〕加入手牌。若加入了2張手牌時，將1張自己的手牌放置在場外。\n【啟動主要】【每回合1】將3張自己手牌中能源需求相同的卡片放置在場外。若有執行此動作時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000，並在這個主要階段結束時，抽3張卡片。","triggerText":""},"EX12BT/KMR-2-026":{"name":"老虎硬幣","effectText":"這張卡片也視為〈安酷〉及〈核心硬幣〉。\n因自己的效果而放置在場外的這張卡片，其能源需求也視為【イ藍×3】。\n這張卡片僅限自己能源線有卡片名稱包含「ooo」的角色卡時才能使用。\n從自己手牌中，使最多1張能源需求3以下消耗AP1且卡片名稱包含「ooo」的藍色角色卡以休息狀態在自己場上登場。將這張卡片放置在移除區。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-027":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX12BT/KMR-2-029":{"name":"假面騎士Fourze 電力型態","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-030":{"name":"假面騎士Fourze 宇宙型態","effectText":"【我方回合中】當這張卡片因自己的效果放置在移除區時，可將這張卡片以休息狀態在自己場上登場。\n【我方回合中】若自己場上有3張以上卡片名稱不包含「Fourze」且具備［特徵：天之川高中］的卡片時，這張角色卡獲得【衝擊（1）】。\n【突襲】將卡片名稱包含「Fourze」的角色卡置為活動，並可移動至前線\n【攻擊時】可選擇1張對手前線的角色卡，將該張角色卡、這張角色卡與這張角色卡的突襲來源卡放置在移除區。（若放置在移除區時，這次攻擊結束）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-031":{"name":"假面騎士Fourze 火焰型態","effectText":"若自己場上有3張以上其他［特徵：天之川高中］時，這張角色卡的產生能源+【藍】。","triggerText":""},"EX12BT/KMR-2-023":{"name":"假面騎士EX-AID 狩獵躍動玩家 Level 5","effectText":"【我方回合中】若這張角色卡下面有背面朝上卡片時，這張角色卡BP+1500。\n【登場時】可選擇1張自己場上其他能源需求2以下且卡片名稱包含「EX-AID」的角色卡。若有執行此動作時，將該角色卡與其下面的背面朝上卡片以背面朝上方式放置在這張角色卡下面，抽1張卡片，並從自己手牌中，使最多1張能源需求2以下消耗AP1的［特徵：醫生］以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-032":{"name":"假面騎士Fourze 基本型態","effectText":"【我方回合中】當這張卡片因自己的效果放置在移除區時，可將這張卡片加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-033":{"name":"假面騎士Fourze 基本型態","effectText":"這張角色卡被防禦時，可抽1張卡片。若有執行此動作時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-028":{"name":"假面騎士NADESHIKO","effectText":"當卡片名稱包含「Fourze」的角色卡從自己移除區登場時，可「使活動狀態的這張角色卡退場，並將1張自己的手牌放置在場外。」。若有執行此動作時，選擇最多1張登場的卡片名稱包含「Fourze」的角色卡，將其置為活動。","triggerText":""},"EX12BT/KMR-2-035":{"name":"假面騎士Fourze 火箭型態","effectText":"【我方回合中】當這張卡片因自己的效果放置在移除區時，可將這張卡片『加入手牌』。若是因這張角色卡的效果而放置在移除區時，則替換成『可將這張卡片以休息狀態在自己場上登場』。\n【我方回合中】這張角色卡在對戰中戰敗的攻擊結束時，若自己場上有3張以上卡片名稱不包含「Fourze」且具備［特徵：天之川高中］的卡片時，將這張角色卡與防禦這張角色卡的角色卡放置在移除區。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX12BT/KMR-2-034":{"name":"假面騎士Fourze 磁鐵型態","effectText":"【突襲】將卡片名稱包含「Fourze」的角色卡置為活動，並可移動至前線\n【登場時】這張角色卡直到下一個我方回合開始前，獲得「【若在前線時】自己場上〈假面騎士Fourze 磁鐵型態〉以外的［特徵：天之川高中］，不會被對手的〔角色卡・觸發〕效果選擇。」。可選擇1張自己場上能源需求3以下的卡片。若有執行此動作時，可從自己手牌中，使最多1張與選擇的卡片能源需求相同且消耗AP為1的［特徵：天之川高中］以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-036":{"name":"假面騎士Meteor","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-037":{"name":"假面騎士Meteor","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX12BT/KMR-2-039":{"name":"假面騎士Meteor 流星風暴","effectText":"【突襲】〈假面騎士Meteor〉置為活動，並可移動至前線\n這張角色卡的以下效果，每回合僅可擇一發動1次。\n・這張角色卡攻擊後沒有被防禦時，抽最多1張卡片。\n・這張角色卡被防禦時，若自己場上有3張以上卡片名稱不包含「Meteor」的［特徵：天之川高中］時，可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動，並在這個回合中，獲得【傷害（2）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-040":{"name":"Power Dizer (威力金剛)","effectText":"【若在能源線時】自己攻擊階段結束時，可將這張角色卡移動至前線。\n【啟動主要】【轉為休息】選擇1張自己場上卡片名稱包含「Fourze」的角色卡，在這個回合中，獲得「當這張角色卡在戰鬥中敗北的攻擊結束時，將這張角色卡與防禦此攻擊的角色卡放置在移除區。」。","triggerText":""},"EX10BT/AOT-2-069":{"name":"阿爾敏・亞魯雷特（超大型巨人）","effectText":"【若在前線時】自己可放置在前線的卡片張數減少1張。\n【突襲】〈阿爾敏・亞魯雷特〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【若在前線時】自己因「有指定BP範圍的效果」選擇角色卡時，可指定的BP範圍+1000。（包含【顏色觸發】）\n【登場時】【若在前線時】抽3張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-041":{"name":"天之川高中","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：天之川高中］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若將卡片名稱不包含「Fourze」的卡片加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-038":{"name":"假面騎士Meteor","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【我方回合中】若自己場上擁有3張以上卡片名稱不包含「Meteor」的［特徵：天之川高中］時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-044":{"name":"騎士火箭鑽踢","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有卡片名稱包含「Fourze」的角色卡時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX12BT/KMR-2-045":{"name":"假面騎士ACCEL","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX12BT/KMR-2-043":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX12BT/KMR-2-047":{"name":"假面騎士SKULL","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【緑】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"EX12BT/KMR-2-048":{"name":"假面騎士W 旋風王牌","effectText":"【登場時】從以下選擇最多1項。\n・查看5張自己卡組上面的卡片。公開其中最多1張〈切換記憶體〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n・若這張角色卡是因〈切換記憶體〉的效果而登場時，可支付1AP。若有執行此動作時，這張角色卡在這個回合中，獲得「【每回合1】這張角色卡被防禦時，將這張角色卡置為活動。」的效果。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX12BT/KMR-2-050":{"name":"假面騎士W 旋風扳機","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-051":{"name":"假面騎士W 旋風金屬","effectText":"【對方回合中】這張角色卡BP-1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-042":{"name":"宇宙來了!","effectText":"抽2張卡片。可將1張自己場上卡片名稱包含「Fourze」的角色卡放置在移除區。若有執行此動作時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-049":{"name":"假面騎士W 旋風王牌極限","effectText":"【突襲】卡片名稱包含「W」與「王牌」的角色卡 置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】若自己場上擁有4種以上卡片名稱包含「W」且必要能源各不相同的角色卡時，選擇最多1張對手前線的角色卡，使其移動至能源線，並直到下一個我方回合開始為止，使其失去所有原本的效果。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-046":{"name":"假面騎士ACCEL 加速試驗","effectText":"【我方回合中】這張角色卡BP+1000。\n【登場時】若自己場上沒有其他能源需求4以上的卡片時，將這張角色卡置為活動。","triggerText":""},"EX12BT/KMR-2-053":{"name":"假面騎士W 炙熱扳機","effectText":"【我方回合中】這張角色卡BP+1000。","triggerText":""},"EX12BT/KMR-2-052":{"name":"假面騎士W 炙熱王牌","effectText":"【登場時】選擇最多1張自己場上能源需求2以下，卡片名稱包含「W」的角色卡，在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-055":{"name":"假面騎士W 尖牙王牌","effectText":"這張角色卡僅能藉由突襲登場。\n【攻擊時】【每回合1】可將1張自己前線活動狀態，卡片名稱包含「W」的角色卡轉為休息。若有執行此動作時，將這張角色卡置為活動，並在這個回合中，BP+500。\n【突襲】卡片名稱包含「W」與「王牌」的角色卡 置為活動，並可移動至前線\n【登場時】將1張這張角色卡的突襲來源卡放回手牌，並將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-056":{"name":"假面騎士W 月神王牌","effectText":"【登場時】【若在前線時】可從自己手牌中，使最多1張BP1500以下，卡片名稱包含「W」的緑色角色卡以休息狀態在自己場上登場。〈假面騎士W 月神王牌〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-054":{"name":"假面騎士W 炙熱金屬","effectText":"這張角色卡被防禦時，『查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面』。若在這個回合中，這張角色卡因〈切換記憶體〉的效果而登場時，可替換成『抽最多1張卡片』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-057":{"name":"假面騎士W 月神扳機","effectText":"【登場時】『抽1張卡片』。若這張角色卡因〈切換記憶體〉的效果而登場時，可替換成『查看3張自己卡組上面的卡片，將其中1張加入手牌。將其餘卡片依任意順序放置在自己卡組的上面』。","triggerText":""},"EX12BT/KMR-2-058":{"name":"假面騎士W 月神金屬","effectText":"【登場時】選擇最多1張自己場上能源需求2以下，卡片名稱包含「W」的角色卡，在這個回合中，獲得「不會被BP4000以上的角色卡防禦。」。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-063":{"name":"假面騎士DIEND","effectText":"【登場時】查看5張自己卡組上面的卡片。公開其中最多1張［特徵：重新想像］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。從自己手牌中，使最多2張能源需求2以下消耗AP1的緑色［特徵：重新想像］以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-062":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX12BT/KMR-2-061":{"name":"好了, 來細數你的罪惡吧","effectText":"選擇1張對手前線BP在（自己場上卡片名稱包含「W」的角色卡與〈切換記憶體〉的合計張數×1000）以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX12BT/KMR-2-064":{"name":"假面騎士DECADE","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-065":{"name":"假面騎士DECADE","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「DECADE」的角色卡或［特徵：重新想像］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-060":{"name":"不准問我問題!","effectText":"抽1張卡片，並從自己手牌中，使最多1張能源需求1以下消耗AP1的緑色角色卡以休息狀態在自己場上登場。藉由此效果登場的角色卡的【登場時】無法發動。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-059":{"name":"切換記憶體","effectText":"使這張場域卡以活動狀態在場上登場。\n【啟動主要】【轉為休息】使1張自己場上活動狀態，能源需求2以下，卡片名稱包含「W」的角色卡退場。若有執行此動作時，抽1張卡片，並從自己手牌中，使最多1張卡片名稱與退場的角色卡不同，能源需求2以下，卡片名稱包含「W」的緑色角色卡以活動狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-067":{"name":"假面騎士DECADE","effectText":"【啟動主要】【若在前線時】【每回合1】將1張自己場外的［特徵：重新想像］放置在移除區。若有執行此動作時，這張角色卡直到下一個我方回合開始前，獲得因這個效果而放置在移除區的卡片所擁有的所有【我方回合中】與【對方回合中】效果。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX12BT/KMR-2-068":{"name":"假面騎士DECADE 激情態","effectText":"【突襲】〈假面騎士DECADE〉置為活動，並可移動至前線\n【登場時】抽1張卡片，並將最多2張自己手牌中的［特徵：重新想像］放置在移除區。選擇最多1張對手前線BP在（因這個效果而放置在移除區的卡片的BP合計）以下的角色卡，使其退場。這張角色卡直到下一個我方回合開始前，獲得因這個效果而放置在移除區的卡片所擁有的所有【我方回合中】與【對方回合中】效果。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-066":{"name":"假面騎士DECADE","effectText":"此角色為活動狀態時，此角色的產生能源+【緑】。","triggerText":""},"EX12BT/KMR-2-070":{"name":"假面騎士AGITO（DCD）","effectText":"【我方回合中】若自己場上擁有卡片名稱包含「DECADE」的角色卡時，這張角色卡獲得「這張角色卡若在前線時也可產生能源。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-071":{"name":"假面骑士KABUTO(DCD)","effectText":"【對方回合中】若自己場上擁有卡片名稱包含「DECADE」的角色卡時，對手以角色卡的效果或事件卡的效果選擇這張角色卡時，必須追加支付1AP才可以選擇。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-072":{"name":"假面騎士KIVA（DCD）","effectText":"【我方回合中】若自己場上擁有卡片名稱包含「DECADE」的角色卡時，這張角色卡獲得BP+500與「BP2000以下的角色卡不能防禦這張角色卡。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-073":{"name":"假面騎士KUUGA（DCD）","effectText":"若自己場上擁有卡片名稱包含「DECADE」的角色卡時，手牌中這張卡片的消耗AP-1。\n【我方回合中】這張角色卡獲得BP+1000與【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-074":{"name":"假面騎士響鬼（DCD）","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【緑×2】。\n【對方回合中】若自己場上擁有卡片名稱包含「DECADE」或「DIEND」的角色卡時，這張角色卡獲得BP+1000與【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）。","triggerText":""},"EX12BT/KMR-2-069":{"name":"假面騎士DECADE 完全形態","effectText":"【突襲】〈假面騎士DECADE〉置為活動，並可移動至前線\n【登場時】抽1張卡片，從自己手牌中使最多1張消耗AP1的緑色［特徵：重新想像］以活動狀態在自己場上登場，並在這個回合中，獲得該角色卡「這張角色卡無法攻擊。」。\n【攻擊時】可將1張自己前線活動狀態的［特徵：重新想像］轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得BP+3000與「這張角色卡的攻擊沒有被防禦時，抽1張卡片。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-078":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX12BT/KMR-2-077":{"name":"終極攻擊駕馭 DECADE","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有卡片名稱包含「DECADE」的角色卡時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX12BT/KMR-2-075":{"name":"假面騎士BLADE（DCD）","effectText":"【我方回合中】若自己場上擁有卡片名稱包含「DECADE」的角色卡時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-076":{"name":"我只是個路過的假面騎士","effectText":"查看6張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「DECADE」的緑色角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-079":{"name":"假面騎士電王 羽翼型態","effectText":"這張卡片也可視為〈齊格〉。\n【突襲】〈齊格〉置為活動，並可移動至前線\n【每回合1】這張角色卡被防禦時，若自己場上擁有合計2張以上，［特徵：異魔神］與卡片名稱包含「電王」的其他角色卡時，將這張角色卡置為活動。\n【退場時】將最多1張這張角色卡的突襲來源卡片以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-081":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX12BT/KMR-2-082":{"name":"假面騎士KAIXA","effectText":"若自己前線沒有卡片名稱包含「555」的角色卡時，手牌中這張卡片的能源需求減少【紅×2】。\n【我方回合中】若自己前線有卡片名稱包含「555」的角色卡時，這張角色卡BP+1000。\n【登場時】可將1張自己手牌中卡片名稱包含「555」的角色卡放置在場外。若有執行此動作時，查看4張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"EX12BT/KMR-2-084":{"name":"假面騎士王蛇","effectText":"【登場時】可以支付1AP，並將1張自己手牌的〈終極降臨〉放置在場外。若有執行此動作時，選擇最多1張對手前線BP5000以下的角色卡，使其退場，並從自己場外，將最多1張與因這個效果而退場的角色卡有相同BP的角色卡加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-085":{"name":"假面騎士鐵兵","effectText":"【啟動主要】【每回合1】將1張自己手牌的〈終極降臨〉放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得BP+1000與「這張角色卡可從能源線攻擊。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-083":{"name":"假面騎士555","effectText":"這張角色卡被防禦的攻擊結束時，選擇最多1張防禦此攻擊的BP3000以下的角色卡，使其退場。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-086":{"name":"假面騎士夜騎","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張卡片名稱包含「龍騎」或「夜騎」的角色卡，或［特徵：鏡怪獸］的卡片放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-087":{"name":"假面騎士夜騎","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「龍騎」或「夜騎」的角色卡，或［特徵：鏡怪獸］的卡片並加入手牌。將其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-089":{"name":"假面騎士夜騎 生存形態","effectText":"【突襲】〈假面騎士夜騎〉置為活動，並可移動至前線\n【登場時】查看6張自己卡組上面的卡片。公開其中最多1張［特徵：契約卡］並加入手牌。將其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【若在前線時】【每回合1】僅限在這個回合中自己使用了［特徵：契約卡］時可發動。選擇1張自己場上卡片名稱包含「龍騎」的角色卡，或［特徵：契約卡］的卡片，置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-090":{"name":"假面騎士龍騎","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX12BT/KMR-2-091":{"name":"假面騎士龍騎","effectText":"【我方回合中】若自己場上有卡片名稱包含「夜騎」的角色卡時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-080":{"name":"齊格","effectText":"在自己主要階段開始時，使這張角色卡退場。從自己場外，使最多1張〈齊格〉以外能源需求1以下的紅色［特徵：異魔神］或〈假面騎士電王 月台形態〉以休息狀態在自己場上登場。\n【登場時】查看3張自己卡組上面的卡片。將其中最多1張放置在場外。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX12BT/KMR-2-093":{"name":"假面騎士龍騎","effectText":"【登場時】若自己場上有卡片名稱包含「夜騎」的角色卡時，抽1張卡片。","triggerText":""},"EX12BT/KMR-2-094":{"name":"假面騎士龍騎 生存形態","effectText":"【突襲】〈假面騎士龍騎〉置為活動，並可移動至前線\n【登場時】抽1張卡片。之後，可將1張自己的手牌放置在場外。若有執行此動作時，在這個回合中，下一次從手牌中使用［特徵：契約卡］的消耗AP-1。\n【退場時】若自己場上有卡片名稱包含「夜騎」的角色卡時，選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-095":{"name":"黑翼","effectText":"若自己場上有〈假面騎士夜騎 生存形態〉時，自己場上的這張角色卡卡片名稱變為〈疾風之翼〉，並獲得「BP4000以上的角色卡無法防禦這張角色卡。」。\n【登場時】選擇最多1張自己場上卡片名稱包含「夜騎」的角色卡，在這個回合中，獲得「這張角色卡不會被觸發的效果選擇。」。","triggerText":""},"EX12BT/KMR-2-088":{"name":"假面騎士夜騎","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【攻擊時】可以將1張自己手牌的〈終極降臨〉放置在場外。若有執行此動作時，抽1張卡片，這張角色卡在這個回合中，BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-096":{"name":"無雙龍","effectText":"若自己場上有〈假面騎士龍騎 生存形態〉時，自己場上的這張角色卡卡片名稱變為〈烈火龍〉，並獲得「【我方回合中】這張角色卡BP+1000。」。\n【登場時】選擇最多1張自己場上卡片名稱包含「龍騎」的角色卡，在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":""},"EX12BT/KMR-2-092":{"name":"假面騎士龍騎","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"EX12BT/KMR-2-100":{"name":"終極降臨","effectText":"選擇1張自己場上的角色卡，在這個回合中，獲得BP+2500與「這張角色卡攻擊後戰勝時，抽1張卡片。」。若選擇的角色卡為卡片名稱包含「龍騎」的角色卡時，再於這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX12BT/KMR-2-098":{"name":"變身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX11BT/ARK-2-001":{"name":"米莎","effectText":"【登場時】可將最多2張自己場上能源需求為0的活動角色轉為休息。若未將2張轉為休息時，則將此角色返回手牌。","triggerText":""},"EX11BT/ARK-2-002":{"name":"Guard","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX12BT/KMR-2-097":{"name":"武器降臨","effectText":"使這張場域卡以活動狀態在場上登場。\n【啟動主要】【轉為休息】選擇1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX11BT/ARK-2-003":{"name":"W","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己能源線能源需求4以下的角色卡，與這張角色卡交換位置。","triggerText":""},"EX11BT/ARK-2-004":{"name":"W","effectText":"【突襲】〈W〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【每回合1】當這張角色卡從前線移動至能源線時，選擇最多1張對手前線的角色卡，使其退場。選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【退場時】抽2張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX12BT/KMR-2-099":{"name":"契約獸降臨","effectText":"從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。之後，從自己場外使最多1張［特徵：鏡怪獸］以休息狀態在自己場上登場。\n・選擇最多1張自己場上的［特徵：鏡怪獸］，並發動該角色卡的【登場時】。將1張自己的AP卡置為活動。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX11BT/ARK-2-006":{"name":"愛國者","effectText":"【登場時】對手將2張自身場上活動狀態的角色卡轉為休息。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-005":{"name":"塔露拉","effectText":"【登場時】可將2張自己場上活動狀態的角色卡轉為休息。若有執行此動作時，使最多1張自己手牌中能源需求2以下消耗AP1的黃色角色卡以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-007":{"name":"愛國者","effectText":"【我方回合中】若對手場上有2張以上休息的角色卡時，這張角色卡獲得【衝擊（1）】與【傷害（2）】。\n【登場時】選擇最多1張對手能源線的角色卡，轉為休息。下一次無法置為活動。這張角色卡直到下一個我方回合開始時為止，BP+1000。\n【啟動主要】【若在前線時】【每回合1】發動這張角色卡的【登場時】效果。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX11BT/ARK-2-009":{"name":"Mephisto・歌者","effectText":"【突襲】〈梅菲斯特〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】發動這張角色卡的【退場時】效果。\n【退場時】所有對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX11BT/ARK-2-010":{"name":"霜星","effectText":"【登場時】每有2張對手場上休息的角色卡，便抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-011":{"name":"整合運動的「暴君」","effectText":"抽1張卡片，並將自己能源線上所有休息狀態的角色卡置為活動。若因此效果將3張以上的卡片置為活動時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-008":{"name":"梅菲斯特","effectText":"【我方回合中】當這張角色卡因自己的效果離場時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-013":{"name":"盾兵","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈迷迭香〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX11BT/ARK-2-012":{"name":"傳承的意志","effectText":"使最多1張自己場外能源需求1以下消耗AP1的黃色角色卡以休息狀態在自己場上登場，或發動突襲。之後，自己場上所有能源需求2以下的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-014":{"name":"阿米婭","effectText":"這張角色卡必須盡可能攻擊。\n【登場時】若自己能源線上有BP4000以上的角色卡時，將這張角色卡置為活動。\n【攻擊時】選擇以下其中1項。\n・這張角色卡下一次無法置為活動。\n・選擇1張自己場上的角色卡，使其退場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-016":{"name":"凱爾希","effectText":"【登場時】查看3張自己卡組上面的卡片。將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-017":{"name":"凱爾希","effectText":"【登場時】將最多1張自己場外〈凱爾希〉以外能源需求『3以下』的角色卡加入手牌。可支付1AP。若有執行此動作時，則替換成『4以上』。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-015":{"name":"極境","effectText":"【啟動主要】【轉為休息】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：羅德島製藥］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。這張角色卡在這個回合中，獲得「主要階段結束時，使這張角色卡退場。」。〈極境〉的這個效果每回合只能發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-018":{"name":"臨光","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【退場時】若自己的生命在6以下時，可將1張自己的手牌放置在場外。若有執行此動作時，將這張卡片以正面朝上放置在自己的生命區。","triggerText":""},"EX11BT/ARK-2-019":{"name":"華法琳","effectText":"【啟動主要】【轉為休息】【每回合1】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+2000。這張角色卡在這個回合中，獲得BP+2000與「主要階段結束時，使這張角色卡退場。」。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-021":{"name":"迷迭香","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX11BT/ARK-2-022":{"name":"迷迭香","effectText":"【攻擊時】選擇最多1張對手前線BP1500以下的角色卡，轉為休息。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-023":{"name":"迷迭香","effectText":"【突襲】〈迷迭香〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，轉為休息。下一次無法置為活動。\n【啟動主要】【若在前線時】【每回合1】抽1張卡片。對手所有前線BP2500以上的角色卡，在這個回合中，BP-2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX11BT/ARK-2-020":{"name":"煌","effectText":"【攻擊時】可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張對手前線BP1000以下的角色卡，使其退場。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"EX11BT/ARK-2-025":{"name":"阿麗娜","effectText":"這張卡片無法在前線登場，且無法移動至前線。\n【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX11BT/ARK-2-024":{"name":"「如你所願」","effectText":"選擇最多1張對手前線BP5000以下的角色卡，『放回手牌』。若自己場上有〈迷迭香〉時，則替換成『使其退場』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX11BT/ARK-2-027":{"name":"阿麗娜","effectText":"【若在能源線時】自己的攻擊階段結束時，可選擇1張自己前線BP1500以上的角色卡，與這張角色卡互相交換位置。\n【退場時】抽1張卡片。將3張自己卡組上面的卡片放置在場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX11BT/ARK-2-028":{"name":"伊諾","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【退場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-029":{"name":"皇帝的利刃","effectText":"【登場時】抽1張卡片。之後，選擇最多1張對手場上的場域卡，使其退場。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-030":{"name":"科西切","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上其他的角色卡，在這個回合中，給予「這張角色卡若在前線時也會產生能源。」的效果。\n【退場時】可將這張卡片以背面朝上放置在自己場上1張卡片名稱包含「塔露拉」的角色卡下面。若有執行此動作時，將3張自己卡組上面的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-031":{"name":"薩沙","effectText":"【啟動主要】【若在前線時】【每回合1】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-032":{"name":"W","effectText":"【登場時】選擇以下其中1項。\n・若自己場外有15張以上的卡片時，選擇最多1張自己場上的［特徵：整合運動］，在這個回合中，給予其【衝擊（+1）】。\n・若自己移除區有9張以上的卡片時，選擇最多1張自己場上的［特徵：羅德島製藥］，在這個回合中，給予其【衝擊（+1）】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-033":{"name":"W","effectText":"【登場時】可公開1張自己手牌中擁有【特殊觸發】的卡片，並將其以背面朝上放置在這張角色卡下面。若有執行此動作時，將這張角色卡置為活動，並將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。\n【退場時】公開這張角色卡下面所有背面朝上卡片並加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-035":{"name":"陳","effectText":"【登場時】將最多1張自己場外的卡片放置在移除區。之後，若自己移除區有3張以上的卡片時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX11BT/ARK-2-034":{"name":"陳","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-036":{"name":"陳","effectText":"【我方回合中】若自己移除區有3張以上的卡片時，這張角色卡獲得【傷害（+1）】（這張角色卡的攻擊直接造成傷害時，追加1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-037":{"name":"陳","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】將1張自己場外的卡片放置在移除區。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-038":{"name":"陳","effectText":"【突襲】〈陳〉置為活動，並可移動至前線\n【啟動主要】自己移除區每有3張卡片，這張角色卡在這個回合中，獲得【傷害（+1）】。〈陳〉的這個效果每回合只能發動1次。\n【啟動主要】【若在前線時】【每回合1】抽1張卡片。將最多1張自己場外的卡片放置在移除區。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX11BT/ARK-2-040":{"name":"鬥士塔露拉","effectText":"若自己場外有15張以上的卡片時，這張卡片的卡片名稱變為〈不死黑蛇 塔露拉〉。\n【登場時】【若在能源線時】將1張自己的手牌放置在場外。若以此效果放置在場外的卡片為〈科西切〉時，可發動該卡片的【退場時】。","triggerText":""},"EX11BT/ARK-2-039":{"name":"鬥士塔露拉","effectText":"若自己場外有15張以上的卡片時，這張卡片的卡片名稱變為〈不死黑蛇 塔露拉〉。\n若自己場外有15張以上的卡片時，這張角色卡的產生能源+【紫】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-041":{"name":"鬥士塔露拉","effectText":"若自己場外有15張以上的卡片時，這張卡片的卡片名稱變為〈不死黑蛇 塔露拉〉。\n【啟動主要】【轉為休息】【每回合1】選擇1張自己場上BP1000以下的角色卡，使其移動至別的線。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-042":{"name":"鬥士塔露拉","effectText":"若自己場外有15張以上卡片時，這張卡片的卡片名稱變為〈不死黑蛇 塔露拉〉。\n【突襲】〈鬥士 塔露拉〉／〈不死黑蛇 塔露拉〉置為活動，並可移動至前線\n【登場時】抽1張卡片。\n【攻擊時】【每回合1】可將1張自己前線BP1000以下的活動狀態角色卡轉為休息。若有執行此動作時，將這張角色卡置為活動，之後，可將1張自己能源線BP1000以下的活動狀態角色卡轉為休息。若有執行此動作時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX11BT/ARK-2-043":{"name":"愛國者","effectText":"【若在前線時】自己場上原本BP為1000以下的角色卡，不會受到BP減少的效果影響。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-044":{"name":"不死黑蛇 塔露拉","effectText":"【突襲】〈不死黑蛇 塔露拉〉置為活動，並可移動至前線\n【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-5000。\n【啟動主要】【若在前線時】【每回合1】若這張角色卡下面有背面朝上卡片時，選擇1張對手前線的角色卡，直到下一個我方回合開始時，BP-2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX11BT/ARK-2-045":{"name":"霜星","effectText":"自己場外每有5張卡片，這張角色卡BP+500。","triggerText":""},"EX11BT/ARK-2-046":{"name":"霜星","effectText":"【登場時】在這個回合中，下一張從手牌中使用BP1000以下的角色卡時，其消耗AP-1。","triggerText":""},"EX11BT/ARK-2-047":{"name":"阿米婭","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX11BT/ARK-2-048":{"name":"阿米婭","effectText":"【登場時】若自己場上有〈陳〉時，選擇以下其中1項。\n・抽1張卡片。\n・將最多2張自己場外的卡片放置在移除區。","triggerText":""},"EX11BT/ARK-2-049":{"name":"阿米婭","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：羅德島製藥］或〈陳〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX11BT/ARK-2-050":{"name":"阿米婭","effectText":"【突襲】〈阿米婭〉置為活動，並可移動至前線\n【每回合1】這張角色卡攻擊後沒有被防禦時，可將最多1張自己場外的卡片放置在移除區。\n【登場時】抽1張卡片。之後，可使最多1張自己手牌中能源需求『1以下』消耗AP1的紫色角色卡以休息狀態在自己場上登場。若自己移除區有3張以上卡片時，則替換成『3以下』。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX11BT/ARK-2-051":{"name":"阿米婭","effectText":"【突襲】〈阿米婭〉置為活動，並可移動至前線\n根據自己移除區的卡片張數，這張角色卡獲得以下所有效果。\n・3張以上：【登場時】選擇最多1張對手前線BP3000以下的角色卡，使其退場。\n・6張以上：【衝擊（1）】\n・9張以上：【啟動主要】【每回合1】選擇最多1張自己場上的〈陳〉。這張角色卡在這個回合中，獲得BP+1000與所選擇的〈陳〉數量相同的【傷害（+1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX11BT/ARK-2-053":{"name":"博士","effectText":"當這張卡片被放置在場外時，可將這張卡片從場外放置在移除區。若有執行此動作時，發動這張卡片的【登場時】效果。\n這張卡片無法在前線登場，且無法移動至前線。\n【登場時】選擇最多1張自己場上〈博士〉以外的紫色〔［特徵：羅德島製藥］或〈陳〉〕，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-052":{"name":"凱爾希","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"EX11BT/ARK-2-055":{"name":"切爾諾伯格中樞區劃","effectText":"使這張場域卡以活動狀態在場上登場。\n【啟動主要】【轉為休息】選擇1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX11BT/ARK-2-054":{"name":"迷迭香","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-056":{"name":"決戰","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX11BT/ARK-2-058":{"name":"赤霄＆影霄","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈阿米婭〉或〈陳〉時，則替換成『BP4000以下』。若自己場上有〈阿米婭〉與〈陳〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX11BT/ARK-2-057":{"name":"不止惡炎","effectText":"選擇1張對手前線的角色卡，在這個回合中，BP-4000。若自己場上有〈不死黑蛇 塔露拉〉時，對手前線所有角色卡在這個回合中，BP-1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX11BT/ARK-2-059":{"name":"遙遠日子的回憶","effectText":"查看4張自己卡組上面的卡片。將其中最多2張加入手牌，其餘卡片放置在移除區。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-060":{"name":"不屈","effectText":"將最多1張自己場外的角色卡加入手牌。若自己場上有卡片名稱包含「塔露拉」的角色時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-061":{"name":"烈焰之中","effectText":"這張卡片僅限自己場外沒有角色卡時才可使用。\n選擇以下其中1項。\n・抽3張卡片。\n・選擇最多1張自己場上的〈阿米婭〉，在這個回合中，給予其BP+1000與【衝擊（+3）】（衝擊造成的傷害+3，若沒有衝擊時，則獲得衝擊（3））。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-063":{"name":"能天使","effectText":"【對方回合中】【若在前線時】這張角色卡BP-2000。\n【退場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：企鵝物流］或BP為2500的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"EX11BT/ARK-2-062":{"name":"莫斯提馬","effectText":"【登場時】在這個回合中，給予對手前線所有的角色卡「這張角色卡防禦並在對戰中獲勝時，將這張角色卡移動至能源線。」的效果。","triggerText":""},"EX11BT/ARK-2-064":{"name":"可頌","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【防禦時】可將1張自己前線原始BP為2500的活動狀態角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，BP+2500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-065":{"name":"空","effectText":"這張角色卡無法攻擊。\n【啟動主要】【轉為休息】選擇以下其中1項。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+500。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1500。將這張卡片放回手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-066":{"name":"德克薩斯","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【退場時】使最多1張自己手牌中〈德克薩斯〉以外BP2500消耗AP1的紅色角色卡以休息狀態在自己前線登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-068":{"name":"陳","effectText":"【退場時】抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-067":{"name":"詩懷雅","effectText":"【退場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+3000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-069":{"name":"陳","effectText":"【啟動主要】【每回合1】僅限當與這張角色卡位於同一線上有持有【雙重防禦】的角色卡時才可發動。這張角色卡在這個回合中，獲得【傷害（2）】。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-070":{"name":"星熊","effectText":"【雙重防禦】（當這張角色卡在這個回合中第一次進行防禦時，將其置為活動）\n【若在前線時】【每回合1】當自己一次受到2點以上傷害時，可改為受到1點傷害。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX11BT/ARK-2-072":{"name":"林","effectText":"【若在前線時】若這張角色卡為休息狀態時，自己前線〈林〉以外的角色卡，不會被對手事件卡的效果選擇。\n【我方回合中】在結束階段時，可不將這張角色卡置為活動。","triggerText":""},"EX11BT/ARK-2-073":{"name":"充滿謎團的物流公司","effectText":"查看5張自己卡組上面的卡片。從其中公開任意張數合計BP在7500以下的紅色角色卡，並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-002":{"name":"丘比","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-003":{"name":"曉美焰","effectText":"【登場時】從以下選擇1項。在這個回合中，〈曉美焰〉已選擇的效果無法選擇。\n・若自己場上有〈最終形態鹿目圓〉，且這張角色卡是從手牌登場時，抽1張卡片。\n・可將1張自己移除區的〈最終形態鹿目圓〉放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-004":{"name":"鹿目圓","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【登場時】查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX11BT/ARK-2-071":{"name":"星熊","effectText":"【雙重防禦】（當這張角色卡在這個回合中第一次進行防禦時，將其置為活動）\n【啟動主要】【若在前線時】【每回合1】僅限對手前線有角色卡時才可發動。選擇1張自己場上持有【傷害（2）】的角色卡，置為活動。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX11BT/ARK-2-026":{"name":"阿麗娜","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX16BT/MMM-2-005":{"name":"佐倉杏子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【對方回合中】這張角色卡BP+1000。","triggerText":""},"EX16BT/MMM-2-001":{"name":"最終形態鹿目圓","effectText":"【突襲】〈鹿目圓〉置為活動，並可移動至前線\n【登場時】抽1張卡片。之後，可將1張自己的手牌放置在移除區。若有執行此動作時，從自己的移除區，使最多1張〈鹿目圓〉以外能源需求3以下消耗AP1的黃色［特徵：魔法少女］以休息狀態在自己場上登場。\n【退場時】將這張角色卡放置在移除區。將最多1張自己場外的角色卡放置在移除區。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX16BT/MMM-2-006":{"name":"巴麻美","effectText":"若自己場外有4張以上事件卡時，這張角色卡BP+1000。","triggerText":""},"EX16BT/MMM-2-010":{"name":"下次見，小焰","effectText":"抽『2張』卡片，並將這張卡片與1張自己的手牌放置在移除區。若自己場上有〈鹿目圓〉時，則替換成『3張』。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-008":{"name":"美樹沙耶香","effectText":"【啟動主要】【轉為休息】僅限在這個回合中有角色卡從自己的移除區登場時可發動。抽1張卡片，並將1張自己的手牌放置在場外。〈美樹沙耶香〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-009":{"name":"挑戰手作蛋糕中","effectText":"選擇最多2張自己場上的角色卡，在這個回合中，BP+2000。抽『1張』卡片。若自己場外有6張以上其他的事件卡時，則替換成『2張』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-007":{"name":"巴麻美","effectText":"若自己場上有〈巴麻美〉以外的［特徵：魔法少女］時，這張卡片無法登場。\n以自己的效果參照自己場外事件卡的張數時，該張數視為多1張。〈巴麻美〉的這個效果不重複。\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n【啟動主要】【轉為休息】【每回合1】僅限自己場外有6張以上事件卡時可發動。發動這張角色卡的【登場時】。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-011":{"name":"最終形態鹿目圓","effectText":"這張卡片也視為〈鹿目圓〉。\n我方回合中，這張角色卡從自己場上放回手牌時，可將1張自己手牌中的紫色〈最終形態鹿目圓〉放置在場外。若有執行此動作時，從自己手牌或場外，使最多1張能源需求1以下的紫色角色卡以休息狀態在自己場上登場，並選擇最多1張自己場上的〈鹿目圓〉，置為活動，在這個回合中，BP+2500。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX16BT/MMM-2-013":{"name":"曉美焰","effectText":"【我方回合中】若自己場上有〈鹿目圓〉時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-016":{"name":"百江渚","effectText":"【啟動主要】【每回合1】使1張自己場上其他能源需求4以下的角色卡退場。若有執行此動作時，抽1張卡片，並將這張角色卡置為活動。\n【啟動主要】【若在前線時】【每回合1】公開1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。依據公開的紫色卡片的能源需求，這張角色卡在這個回合中獲得以下所有效果。\n・2以下：這張角色卡不會被BP4000以上的角色卡防禦。\n・1以下：這張角色卡不會被BP2000以下的角色卡防禦。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-017":{"name":"巴麻美","effectText":"自己卡組中的紫色卡片能源需求減少1。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-015":{"name":"鹿目圓","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX16BT/MMM-2-014":{"name":"曉美焰","effectText":"【登場時】若在我方回合中，且這張角色卡是因自己的效果登場時，選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-018":{"name":"將回憶珍藏於心","effectText":"從自己場外，使最多各1張能源需求1以下的紫色〔〈曉美焰〉與〈鹿目圓〉〕以休息狀態在自己場上登場。若自己前線有〈惡魔焰〉時，將1張自己的AP卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-021":{"name":"環羽衣","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"EX16BT/MMM-2-019":{"name":"秋野楓","effectText":"【啟動主要】【轉為休息】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX16BT/MMM-2-022":{"name":"十咎桃子","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX16BT/MMM-2-024":{"name":"水波玲奈","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX16BT/MMM-2-023":{"name":"美國織莉子","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求3以下消耗AP1的綠色〈吳紀里香〉以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX16BT/MMM-2-025":{"name":"環彩羽","effectText":"【啟動主要】【每回合1】選擇1張自己前線其他的［特徵：三日月莊小隊］，使其移動至能源線。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-012":{"name":"惡魔焰","effectText":"這張卡片也視為〈曉美焰〉。\n【啟動主要】【若在前線時】【每回合1】將1張自己場上的〈鹿目圓〉放回手牌。若有執行此動作時，查看2張自己卡組上面的卡片，將最多1張加入手牌，其餘卡片放置在場外。\n【啟動主要】從自己場外選擇任意張〈鹿目圓〉，使其能源需求合計為4以上，並依任意順序放置在自己卡組下面。若有執行此動作時，將這張角色卡置為活動。〈惡魔焰〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX16BT/MMM-2-020":{"name":"吳紀里香","effectText":"【我方回合中】若自己場上有〈美國織莉子〉時，這張角色卡BP+1000。\n【退場時】選擇最多1張自己場上的〈美國織莉子〉，在這個回合中，BP+1000。","triggerText":""},"EX16BT/MMM-2-028":{"name":"環彩羽","effectText":"【突襲】〈環彩羽〉置為活動，並可移動至前線\n若在這個回合中，自己場上已有3種以上不同卡片名稱的［特徵：三日月莊小隊］登場時，這張角色卡不會被BP4000以上的角色卡防禦。\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n【啟動主要】【若在前線時】【每回合1】選擇最多2張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX16BT/MMM-2-027":{"name":"環彩羽","effectText":"【登場時】若在這個回合中，自己場上已有3種以上不同卡片名稱的［特徵：三日月莊小隊］登場時，抽1張卡片。","triggerText":""},"EX16BT/MMM-2-030":{"name":"七海八千代","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-029":{"name":"七海八千代","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-026":{"name":"環彩羽","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈環羽衣〉或［特徵：三日月莊小隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX16BT/MMM-2-031":{"name":"七海八千代","effectText":"【登場時】若在我方回合中，可將1張自己場上能源需求2以下的［特徵：三日月莊小隊］放回手牌。若有執行此動作時，從自己手牌中，使最多1張能源需求3以下消耗AP1的綠色［特徵：三日月莊小隊］以休息狀態在自己場上登場。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX16BT/MMM-2-032":{"name":"七海八千代","effectText":"【突襲】〈七海八千代〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n若在這個回合中，自己場上已有3種以上不同卡片名稱的［特徵：三日月莊小隊］登場時，這張角色卡獲得【衝擊（1）】。\n【登場時】從自己手牌中，使最多1張能源需求3以下消耗AP1的綠色［特徵：三日月莊小隊］以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX16BT/MMM-2-034":{"name":"二葉紗奈","effectText":"若自己前線有2種以上不同卡片名稱的［特徵：三日月莊小隊］時，這張角色卡的產生能源+【綠】。","triggerText":""},"EX16BT/MMM-2-033":{"name":"二葉紗奈","effectText":"【登場時】若這張角色卡是因自己的效果而登場時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-035":{"name":"二葉紗奈","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【若在能源線時】自己的攻擊階段結束時，可選擇1張自己前線具有「三日月莊小隊」特徵的角色卡，與這張角色卡互相交換位置。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-036":{"name":"深月菲莉西亞","effectText":"【我方回合中】這張角色卡BP+500。","triggerText":""},"EX16BT/MMM-2-038":{"name":"深月菲莉西亞","effectText":"若在這個回合中，自己場上已有3種以上不同卡片名稱的［特徵：三日月莊小隊］登場時，這張角色卡BP+1000。\n【攻擊時】若對手前線有角色卡，且這張角色卡BP為5000以上時，這張角色卡在這個回合中，獲得【傷害（2）】。〈深月菲莉西亞〉的這個效果每回合僅發動1次。\n這張角色卡攻擊後沒有被防禦時，這張角色卡在這個回合的結束階段不會置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-039":{"name":"由比鶴乃","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：三日月莊小隊］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-040":{"name":"由比鶴乃","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的［特徵：三日月莊小隊］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-037":{"name":"深月菲莉西亞","effectText":"若在這個回合中，自己場上已有3種以上不同卡片名稱的［特徵：三日月莊小隊］登場時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-041":{"name":"由比鶴乃","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】這張角色卡在這個回合中，獲得【雙重攻擊】。\n【攻擊時】【每回合1】若在這個回合中，自己場上已有3種以上不同卡片名稱的［特徵：三日月莊小隊］登場時，查看3張自己卡組上面的卡片，公開其中最多1張［特徵：三日月莊小隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX16BT/MMM-2-042":{"name":"阿莉娜・格雷","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX16BT/MMM-2-043":{"name":"阿莉娜・格雷","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。\n【啟動主要】【若在前線時】【每回合1】將1張自己場上其他的角色卡放置在自己卡組的上面。若有執行此動作時，這張角色卡在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-045":{"name":"阿莉娜・格雷","effectText":"每有2張對手前線的角色卡，這張角色卡BP+500。\n【突襲】〈阿莉娜・格雷〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，使其移動至能源線。公開1張自己卡組上面的卡片並加入手牌。若公開卡片的能源需求為5以上時，選擇最多1張對手能源線的角色卡，並獲得「這張角色卡無法移動。」，直到下一個我方回合開始為止。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX16BT/MMM-2-046":{"name":"里見燈花","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：Magius］或［特徵：Magius之翼］放置在場外。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-047":{"name":"里見燈花","effectText":"【啟動主要】【每回合1】將1張自己的手牌放置在自己卡組的上面。若有執行此動作時，這張角色卡在這個回合中，產生能源+【綠】。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX16BT/MMM-2-044":{"name":"阿莉娜・格雷","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】公開1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。\n【啟動主要】僅限在這個回合中有從自己卡組公開能源需求5以上的卡片時可發動。將這張角色卡置為活動。〈阿莉娜・格雷〉的這個效果每回合僅可發動1次。","triggerText":""},"EX16BT/MMM-2-048":{"name":"里見燈花","effectText":"【登場時】查看3張自己卡組上面的卡片，並依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-051":{"name":"柊音夢","effectText":"【登場時】【若在能源線時】可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】【支付1AP】【每回合1】公開1張自己卡組上面的卡片並加入手牌。若公開卡片的能源需求為5以上時，在這個回合中，下一張從手牌中使用，原本能源需求為5以上的卡片，其消耗AP-1。","triggerText":""},"EX16BT/MMM-2-053":{"name":"天音月夜","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-052":{"name":"天音月咲","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-050":{"name":"柊音夢","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Magius］或［特徵：Magius之翼］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-054":{"name":"梓美冬","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【綠】。","triggerText":""},"EX16BT/MMM-2-055":{"name":"梓美冬","effectText":"我方回合中，這張卡片從自己卡組被公開時，選擇最多1張自己場上的［特徵：Magius］，在這個回合中，獲得BP+1000與【衝擊（1）】。〈梓美冬〉的這個效果每回合僅可發動1次。\n手牌中這張卡片的能源需求減少【綠×2】。\n【我方回合中】若自己場上有3種以上不同卡片名稱的［特徵：Magius］時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-057":{"name":"三日月莊小隊——！","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己手牌或場外，使最多1張〈三日月莊小隊——！〉以外能源需求0以下的綠色［特徵：三日月莊小隊］以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-058":{"name":"回去吧，回到我們的家","effectText":"查看5張自己卡組上面的卡片。從中公開最多3張不同卡片名稱的［特徵：三日月莊小隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-059":{"name":"沉默的魔女化身","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈環彩羽〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX16BT/MMM-2-049":{"name":"里見燈花","effectText":"【突襲】〈里見燈花〉置為活動，並可移動至前線\n這張角色卡若在前線時也可產生能源。\n【登場時】抽2張卡片，並將1張自己的手牌放置在自己卡組的上面或場外。\n【啟動主要】【若在前線時】【每回合1】抽1張卡片，並將1張自己的手牌放置在自己卡組的上面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX16BT/MMM-2-056":{"name":"聖麻美","effectText":"若在這個回合中有從自己卡組公開能源需求5以上的卡片時，這張角色卡獲得【傷害（2）】。\n【登場時】將這張角色卡置為活動。若自己場上有3種以上不同卡片名稱的［特徵：Magius］時，從以下選擇1項。在這個回合中，〈聖麻美〉已選擇的效果無法選擇。\n・將1張自己的AP卡置為活動。這張角色卡在這個回合中，BP+1000。\n・這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-060":{"name":"箱庭創造者","effectText":"手牌中這張卡片的能源需求減少【綠×2】。\n查看4張自己卡組上面的卡片，將最多2張加入手牌。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-062":{"name":"歡迎來到八雲偵探事務所","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX16BT/MMM-2-064":{"name":"鹿目圓","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-065":{"name":"佐倉杏子","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【登場時】若自己在這個回合中已將生命區的卡片加入手牌時，抽1張卡片。","triggerText":""},"EX16BT/MMM-2-063":{"name":"曉美焰","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或下面，並抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-061":{"name":"Marigold Dadaism","effectText":"選擇1張對手前線BP為自己場上［特徵：Magius］與［特徵：Magius之翼］合計張數×1000以下的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX16BT/MMM-2-066":{"name":"佐倉杏子","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張〈佐倉杏子〉或〈美樹沙耶香〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX16BT/MMM-2-067":{"name":"佐倉杏子","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【我方回合中】若自己場上除這張卡片以外的［特徵：魔法少女］有4種以上不同卡片名稱，或自己在這個回合中已將生命區的卡片加入手牌時，這張角色卡BP+1000。\n這張角色卡被突襲時，選擇最多1張自己場上的角色卡，在這個回合中，獲得「這張角色卡攻擊後沒有被防禦時，抽最多1張卡片。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-070":{"name":"美樹沙耶香","effectText":"【啟動主要】【轉為休息】僅限自己在這個回合中已將生命區的卡片加入手牌時可發動。抽1張卡片。將這張角色卡以正面朝上放置在自己的生命區。〈美樹沙耶香〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-071":{"name":"美樹沙耶香","effectText":"【啟動主要】【每回合1】將1張自己生命區的卡片加入手牌。若有執行此動作時，這張角色卡在這個回合中，BP+2000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX16BT/MMM-2-072":{"name":"美樹沙耶香","effectText":"【啟動主要】【每回合1】從以下選擇最多2項。\n・這張角色卡在這個回合中，BP+1000。\n・若自己場上除這張卡片以外的［特徵：魔法少女］有4種以上不同卡片名稱，或自己在這個回合中已將生命區的卡片加入手牌時，選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX16BT/MMM-2-069":{"name":"巴麻美","effectText":"【突襲】〈巴麻美〉置為活動，並可移動至前線\n【登場時】查看4張自己卡組上面的卡片，公開其中最多1張［特徵：魔法少女］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n【退場時】若自己場上除這張卡片以外的［特徵：魔法少女］有4種以上不同卡片名稱時，可發動這張卡片的【登場時】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX16BT/MMM-2-068":{"name":"巴麻美","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX16BT/MMM-2-073":{"name":"懷抱各自的心意","effectText":"〈懷抱各自的心意〉在1個回合中只能使用1張。\n抽1張卡片。選擇最多1張自己場上的［特徵：魔法少女］，在這個回合中，BP+2000。若選擇的角色卡為〈鹿目圓〉時，在這個回合中，再獲得【衝擊（1）】。若自己場上的［特徵：魔法少女］有5種以上不同卡片名稱時，將1張自己的AP卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-002":{"name":"雪露·諾姆","effectText":"【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。從以下選擇1項。\n・將1張自己的生命卡加入手牌。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。\n・若自己在這個回合中已將生命卡加入手牌時，抽1張卡片。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"EX14BT/MCR-2-005":{"name":"蘭花·李","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-003":{"name":"雪露·諾姆","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若自己在這個回合中已將生命卡加入手牌時，這張角色卡BP+1000。\n【啟動主要】【每回合1】將1張自己的生命卡加入手牌。","triggerText":""},"EX14BT/MCR-2-001":{"name":"雪露·諾姆","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-006":{"name":"蘭花·李","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"EX14BT/MCR-2-007":{"name":"蘭花·李","effectText":"【啟動主要】僅限自己在這個回合中已將生命卡加入手牌時可發動。將這張角色卡置為活動，直到下一個我方回合開始前，這張角色卡BP+500。〈蘭花·李〉的這個效果每回合僅可發動1次。","triggerText":""},"EX14BT/MCR-2-009":{"name":"方尖碑","effectText":"從以下選擇最多『1項』。若自己在這個回合中已將生命卡加入手牌時，則替換成『2項』。\n・抽2張卡片。\n・選擇1張自己場上的角色卡，在這個回合中，BP+3000。\n・若自己的生命值為1，且自己移除區沒有〈方尖碑〉時，將1張自己卡組上面的卡片以正面朝上放置在自己的生命區。將這張卡片放置在移除區。","triggerText":""},"EX14BT/MCR-2-011":{"name":"VF-19EF/A 伊薩姆特別版","effectText":"【若在前線時】我方攻擊階段結束時，抽1張卡片，並將這張角色卡放置在自己卡組下面。選擇最多1張自己能源線中卡片名稱不含「伊薩姆」的角色卡，移動至前線。\n【登場時】【若在前線時】將這張角色卡置為活動。〈VF-19EF/A 伊薩姆特別版〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-004":{"name":"雪露·諾姆","effectText":"【突襲】〈雪露·諾姆〉置為活動，並可移動至前線\n若自己前線有〈蘭花·李〉時，這張角色卡獲得以下全部效果。\n・【衝擊（1）】\n・【啟動主要】【若在前線時】【每回合1】將1張自己的生命卡加入手牌。若有執行此動作時，抽1張卡片。在這個回合中，下一張從手牌使用的［特徵：歌（雪露）］消耗AP-1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-010":{"name":"放學後Overflow","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+2000。若自己場外有3種以上不同卡片名稱的黃色［特徵：歌（蘭花）］時，抽2張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-012":{"name":"雪露·諾姆","effectText":"【登場時】查看2張自己卡組上面的卡片，公開其中最多1張卡片名稱含有「阿爾特」的卡片或〈戀離飛翼 ～the end of triangle～〉並加入手牌。將剩餘卡片依照期望順序放置在卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】僅限自己在這個回合中已使用〈戀離飛翼 ～the end of triangle～〉時可發動。查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-013":{"name":"蘭花·李","effectText":"【登場時】查看2張自己卡組上面的卡片，公開其中最多1張卡片名稱含有「阿爾特」的卡片或〈戀離飛翼 ～the end of triangle～〉並加入手牌。將剩餘卡片依照期望順序放置在卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】僅限自己在這個回合中已使用〈戀離飛翼 ～the end of triangle～〉時可發動。查看3張自己卡組上面的卡片，依照期望順序放置在卡組上面。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-017":{"name":"VF-25G 龍捲風彌賽亞女武神（米歇爾·布朗）","effectText":"【若在前線時】自己場上突襲狀態的〈奎德蘭·蕾亞（克蘭·克蘭）〉退場時，將最多1張該角色卡的突襲元卡以活動狀態在自己場上登場。\n【啟動主要】【每回合1】僅限這張角色卡擁有【衝擊】時可發動。這張角色卡在這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX14BT/MCR-2-014":{"name":"VF-27γSP 超級路西法女武神（布雷拉·斯特恩）","effectText":"【啟動主要】【若在前線時】【轉為休息】【使這張卡片退場】僅限自己場上有〈蘭花·李〉時可發動。選擇最多1張對手前線BP3000以下的角色卡，使其退場。若自己在這個回合中已使用〈戀離飛翼 ～the end of triangle～〉時，抽1張卡片。","triggerText":""},"EX14BT/MCR-2-016":{"name":"YF-29 杜蘭朵女武神（早乙女阿爾特）","effectText":"【突襲】〈早乙女阿爾特〉置為活動，並可移動至前線\n這張角色卡的攻擊結束時，若自己前線沒有活動角色卡時，可使這張角色卡退場。\n【登場時】將自己場外最多1張〈戀離飛翼 ～the end of triangle～〉加入手牌。\n【退場時】若為我方回合中時，將最多1張這張角色卡的突襲元卡以活動狀態在自己場上登場，並使該角色卡在這個回合中獲得「這張角色卡不會被BP3000以下的角色卡防禦。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-015":{"name":"早乙女阿爾特","effectText":"【我方回合中】若自己場上有〈雪露·諾姆〉與〈蘭花·李〉時，這張角色卡BP+1000。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX14BT/MCR-2-008":{"name":"蘭花·李","effectText":"【突襲】〈蘭花·李〉置為活動，並可移動至前線\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】僅限自己在這個回合中已將生命卡加入手牌時可發動。從以下選擇1項。在這個回合中，自己的其他〈蘭花·李〉已選擇過的效果無法選擇。\n·將1張自己卡組上面的卡片以正面朝上放置在自己的生命區。\n·選擇1張對手前線的角色卡，直到下一個我方回合開始前，使其獲得「這張角色卡無法攻擊。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-018":{"name":"戀離飛翼 ～the end of triangle～","effectText":"〈戀離飛翼 ～the end of triangle～〉每回合僅可使用1張。\n若自己場上有〈雪露·諾姆〉與〈蘭花·李〉時，手牌中這張卡片的消耗AP-2。\n對手前線所有BP1500以上的角色卡，在這個回合中，BP-1000。抽1張卡片。","triggerText":""},"EX14BT/MCR-2-020":{"name":"疾風·因梅爾曼","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX14BT/MCR-2-021":{"name":"疾風·因梅爾曼","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Δ小隊］或〈弗蕾亞·維恩〉並加入手牌。將剩餘卡片依照期望順序放置在卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX14BT/MCR-2-019":{"name":"海因茨·涅利希·溫德米爾","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】僅限自己前線有［特徵：空中騎士團］時可發動。對手前線所有角色卡，在這個回合中，BP-1000。〈海因茨·涅利希·溫德米爾〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-022":{"name":"疾風·因梅爾曼","effectText":"【若在前線時】在這張角色卡登場回合以外的自己主要階段中，因自己的效果抽卡時，將這張角色卡置為活動。\n【啟動主要】【若在前線時】【轉為休息】這張角色卡在這個回合中，BP+1000。\n【攻擊時】若這張角色卡的BP在5000以上時，查看2張自己卡組上面的卡片，將其中任意張數以任意順序放置在自己卡組的上面，其餘卡片放置在場外。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX14BT/MCR-2-023":{"name":"米拉潔·法莉娜·吉納斯","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"EX14BT/MCR-2-024":{"name":"米拉潔·法莉娜·吉納斯","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"EX14BT/MCR-2-026":{"name":"梅薩·伊雷菲爾特","effectText":"","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-025":{"name":"米拉潔·法莉娜·吉納斯","effectText":"【登場時】若自己前線有卡片名稱不包含「米拉潔」的突襲狀態的［特徵：Δ小隊］時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-027":{"name":"梅薩·伊雷菲爾特","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-029":{"name":"奏芽·巴卡妮雅","effectText":"【登場時】從自己手牌中，使最多1張能源需求2以下消耗AP1的紫色［特徵：Walküre］以休息狀態在自己場上登場。","triggerText":""},"EX14BT/MCR-2-030":{"name":"奏芽·巴卡妮雅","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Walküre］並加入手牌。將剩餘卡片依照期望順序放置在卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-028":{"name":"奏芽·巴卡妮雅","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"EX14BT/MCR-2-032":{"name":"弗蕾亞·維恩","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-031":{"name":"奏芽·巴卡妮雅","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外使最多1張能源需求2以下的紫色［特徵：Walküre］以休息狀態在自己場上登場。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"EX14BT/MCR-2-033":{"name":"弗蕾亞·維恩","effectText":"【登場時】抽1張卡片。","triggerText":""},"EX14BT/MCR-2-034":{"name":"弗蕾亞·維恩","effectText":"【我方回合中】若自己場上擁有不同卡片名稱的［特徵：Walküre］卡片有3種以上時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-035":{"name":"弗蕾亞·維恩","effectText":"【啟動主要】【轉為休息】僅限自己前線有卡片名稱包含「疾風」的角色卡時可發動。從以下選擇1項。〈弗蕾亞·維恩〉的這個效果每回合僅可發動1次。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・將1張自己的生命卡加入手牌。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-036":{"name":"弗蕾亞·維恩","effectText":"從手牌使用這張卡片發動突襲時，若自己場上有5種以上不同卡片名稱的［特徵：Walküre］卡片時，消耗AP-1。若在這個回合中，已不支付AP對其他〈弗蕾亞·維恩〉發動突襲，則此效果無效。\n【突襲】〈弗蕾亞·維恩〉置為活動，並可移動至前線\n【攻擊時】若自己場上有3種以上不同卡片名稱的［特徵：Walküre］卡片時，自己場上所有的角色卡在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-037":{"name":"瑪機奈·中島","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":""},"EX14BT/MCR-2-038":{"name":"瑪機奈·中島","effectText":"【登場時】查看5張自己卡組上面的卡片，公開其中最多1張卡片名稱包含「VF」的［特徵：Δ小隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"EX14BT/MCR-2-039":{"name":"瑪機奈·中島","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】若自己場上有3種以上不同卡片名稱的［特徵：Walküre］卡片時，選擇最多1張自己場上其他的角色卡，在這個回合中，『BP+1000』。若有5種以上時，則替換成『BP+2000』。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-041":{"name":"美雲·基努美爾","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：Walküre］放置在場外，其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-040":{"name":"瑪機奈·中島","effectText":"若自己前線有2張以上［特徵：Walküre］時，這張角色卡的產生能源+【紫】。\n【登場時】若自己場上有〈蕾娜・普勞拉〉時，查看2張自己卡組上面的卡片，將其中任意張數以任意順序放置在自己卡組的上面，其餘卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-043":{"name":"美雲·基努美爾","effectText":"【登場時】若自己場上擁有不同卡片名稱的［特徵：Walküre］卡片有3種以上時，將最多1張自己場外能源需求2以下的［特徵：歌（Walküre）］放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-045":{"name":"美雲·基努美爾","effectText":"【突襲】〈美雲·基努美爾〉置為活動，並可移動至前線\n【我方回合中】若自己場上有3種以上不同卡片名稱的［特徵：Walküre］卡片時，這張角色卡獲得【衝擊（1）】。\n【攻擊時】從以下選擇最多2項。\n・將1張自己場外的［特徵：歌（Walküre）］放置在移除區。若有執行此動作時，抽1張卡片。\n・若自己場上有5種以上不同卡片名稱的［特徵：Walküre］卡片時，這張角色卡直到下一個我方回合開始前，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-044":{"name":"美雲·基努美爾","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n若自己場上擁有不同卡片名稱的［特徵：Walküre］卡片有3種以上時，這張角色卡BP+1000。","triggerText":""},"EX14BT/MCR-2-042":{"name":"美雲·基努美爾","effectText":"這張角色卡不會被對手的角色卡效果選擇。\n【若在前線時】【每回合1】當自己將一次受到2點以上傷害時，可改為受到1點傷害。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-048":{"name":"蕾娜·普勞拉","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Walküre］並放置在卡組上面。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-051":{"name":"Sv-262Hs 龍III（基斯·愛羅·溫德米爾）","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-3000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX14BT/MCR-2-047":{"name":"蕾娜·普勞拉","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX14BT/MCR-2-050":{"name":"Sv-262Ba 龍III（伯格·空法爾特）","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張不持有【突襲】的角色卡加入手牌。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-046":{"name":"蕾娜·普勞拉","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-054":{"name":"VF-31J 齊格菲（疾風·因梅爾曼）","effectText":"【突襲】〈疾風·因梅爾曼〉置為活動，並可移動至前線\n【若在前線時】在自己的主要階段中，因自己的效果抽卡時，將這張角色卡置為活動。\n【啟動主要】【若在前線時】【轉為休息】從以下選擇1項。在這個回合中這張角色卡已選擇過的效果無法選擇。\n・從自己手牌中，使最多1張能源需求1以下的紫色角色卡以休息狀態在自己場上登場。\n・選擇1張自己場上的角色卡，在這個回合中，BP+2000。\n・選擇1張對手前線的角色卡，在這個回合中，BP-1500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-053":{"name":"VF-31C 齊格菲（米拉潔·法莉娜·吉納斯）","effectText":"【突襲】〈米拉潔·法莉娜·吉納斯〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上卡片名稱包含「疾風」的角色卡。若有執行此動作時，抽1張卡片，並使選擇的角色卡在這個回合中獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-049":{"name":"蕾娜·普勞拉","effectText":"【啟動主要】【轉為休息】從以下選擇1項。\n・選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。\n・若自己場上有〈瑪機奈·中島〉時，選擇1張自己場上其他的角色卡，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。〈蕾娜・普勞拉〉的這個效果每回合僅可選擇1次。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-052":{"name":"VF-31F 齊格菲（梅薩・伊雷菲爾特）","effectText":"【突襲】〈梅薩·伊雷菲爾特〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-2500。\n【攻擊時】若這張角色卡的BP在6000以上時，這張角色卡直到下一個我方回合開始前，獲得【傷害（2）】與【衝擊無效】。\n【退場時】查看7張自己卡組上面的卡片，公開其中最多1張卡片名稱包含「VF」但不包含「梅薩」的［特徵：Δ小隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-055":{"name":"裸喰娘娘","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】抽1張卡片。使最多1張自己手牌中能源需求3以下消耗AP1的紫色角色卡以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX14BT/MCR-2-057":{"name":"守護是我的工作","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有卡片名稱包含「疾風」的角色卡時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX14BT/MCR-2-056":{"name":"要做好覺悟喔","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX14BT/MCR-2-059":{"name":"禁忌的邊界線","effectText":"查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Walküre］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。在這個回合中，下一張從手牌中使用［特徵：Walküre］的消耗AP-1。","triggerText":""},"EX14BT/MCR-2-060":{"name":"若是僅此一次的戀愛","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上擁有不同卡片名稱的［特徵：Walküre］卡片有3種以上時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX14BT/MCR-2-061":{"name":"GIRAFFE BLUES","effectText":"抽1張卡片。之後，從以下選擇1項。\n・選擇最多1張對手前線的角色卡，直到下一個我方回合開始前，獲得「這張角色卡無法攻擊。」。\n・選擇最多1張對手前線突襲狀態的角色卡，將該突襲狀態最上面的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-062":{"name":"阿里耶斯·特納","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態時可發動。將1張自己的手牌放置在自己卡組下面。若有執行此動作時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-063":{"name":"工藤真","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"EX14BT/MCR-2-058":{"name":"AXIA～又愛又恨～","effectText":"選擇1張自己場上的［特徵：Δ小隊］或［特徵：Walküre］，在這個回合中，BP+2000。將1張自己的AP卡置為活動。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-065":{"name":"莎拉·諾姆","effectText":"【登場時】從以下選擇1項。\n·選擇最多1張自己場上其他角色卡，在這個回合中，BP+1000。\n·若這張角色卡是因自己的效果登場時，選擇最多1張自己場上原始BP3500以下的其他角色卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX14BT/MCR-2-064":{"name":"工藤真","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張原始BP3500以下且不具備特徵的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"EX14BT/MCR-2-067":{"name":"羅伊·福克","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【啟動主要】【每回合1】僅限這張角色卡的BP高於原始BP時可發動。這張角色卡在這個回合中，BP+500。","triggerText":""},"EX14BT/MCR-2-069":{"name":"VF-0D 鳳凰（工藤真）","effectText":"【突襲】〈工藤真〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】這張角色卡在這個回合中，BP+1000。\n【攻擊時】【每回合1】將1張自己卡組下面的卡片放置在場外。若放置在場外的卡片為紅色的〔〈莎拉·諾姆〉或〈瑪歐·諾姆〉〉〕時，可使該卡片以休息狀態在自己場上登場。若放置在場外的卡片不具備特徵時，可將該卡片加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX14BT/MCR-2-068":{"name":"VF-0S 鳳凰（羅伊·福克）","effectText":"【登場時】從自己手牌中，使最多1張BP3500以下消耗AP1的紅色角色卡以休息狀態在自己場上登場，或發動突襲。\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡的BP在5000以上時可發動。將這張角色卡置為活動。從以下選擇1項。\n・抽1張卡片。\n・選擇1張自己場上其他角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX14BT/MCR-2-066":{"name":"瑪歐·諾姆","effectText":"【啟動主要】【轉為休息】選擇最多1張自己場上原始BP3500以下的其他角色卡，在這個回合中，獲得【衝擊（1）】或「這張角色卡不會被BP4000以上的角色卡防禦。」。將這張角色卡放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-070":{"name":"ARKAN","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX14BT/MCR-2-071":{"name":"鳥之人","effectText":"這張卡片僅限自己場上有2張以上BP4000以上的角色卡時才能使用。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。可將自己場上的〈莎拉·諾姆〉放置在自己卡組下面。若有執行此動作時，抽1張卡片。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX14BT/MCR-2-073":{"name":"萊莎·霍利","effectText":"【若在前線時】自己場上突襲狀態且卡片名稱包含「巴薩拉」的角色卡退場時，可將活動狀態的這張角色卡轉為休息。若有執行此動作時，將最多1張退場角色卡的突襲元卡加入手牌。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-076":{"name":"米蓮·菲亞·吉納斯","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「吉納斯」的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-077":{"name":"米蓮·菲亞·吉納斯","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"EX14BT/MCR-2-075":{"name":"熱氣巴薩拉","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n這張角色卡攻擊後戰勝時，抽1張卡片，且在這場對戰中戰敗的對手角色卡將放置在對手卡組下面而非退場。\n【若在前線時】自己場上卡片名稱包含「巴薩拉」的角色卡之效果中記載的「放回手牌而非退場。」將替換為「放置在對手卡組下面而非退場。」。\n【登場時】自己與對手各抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX14BT/MCR-2-074":{"name":"熱氣巴薩拉","effectText":"這張角色卡攻擊後戰勝時，抽1張卡片，且在這場對戰中戰敗的對手角色卡將放回手牌而非退場。\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態時可發動。對手抽1張卡片。選擇最多1張自己場上其他的［特徵：Fire Bomber］，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-001":{"name":"阿爾馮斯・愛力克","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37ST/FMA-1-005":{"name":"伊茲米・卡迪斯","effectText":"【我方回合中】這張角色卡BP+500。\n【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】選擇1張自己場上的〈愛德華・愛力克〉或〈阿爾馮斯・愛力克〉，置為活動。","triggerText":""},"UA37ST/FMA-1-006":{"name":"馮・霍恩海姆","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA37ST/FMA-1-007":{"name":"溫莉・洛克貝爾","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-009":{"name":"愛德華・愛力克","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37ST/FMA-1-003":{"name":"阿爾馮斯・愛力克","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】將1張自己場外不持有【突襲】的〈愛德華・愛力克〉，以正面朝上放置在1張自己前線持有【突襲】且非突襲狀態的〈愛德華・愛力克〉下面。若有執行此動作時，將該角色卡置為活動。（成為突襲狀態）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37ST/FMA-1-015":{"name":"特麗莎・愛力克","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA37ST/FMA-1-031":{"name":"等價交換","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA37ST/FMA-1-033":{"name":"鋼之鍊金術師","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈愛德華・愛力克〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX14BT/MCR-2-072":{"name":"艾爾瑪·霍利","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張能源需求3以下的〈熱氣巴薩拉〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-101":{"name":"阿爾馮斯・愛力克","effectText":"【登場時】若這張角色卡是因自己的效果登場時，抽1張卡片。\n【啟動主要】【將2張手牌放置在場外】【每回合1】將這張角色卡置為活動，這張角色卡在這個回合中，BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37ST/FMA-1-102":{"name":"愛德華・愛力克","effectText":"【登場時】查看2張自己卡組上面的卡片。從中選擇任意張數的卡片，以任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。","triggerText":""},"UA37ST/FMA-1-103":{"name":"愛德華・愛力克","effectText":"【突襲】〈愛德華・愛力克〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】可「查看6張自己卡組上面的卡片。公開其中最多1張角色卡或場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。」。若有執行此動作時，將1張這張角色卡的突襲來源卡放置在場外。（這張角色卡不再是突襲狀態）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37ST/FMA-1-105":{"name":"馬斯・休斯","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-104":{"name":"比拿可・洛克貝爾","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37ST/FMA-1-106":{"name":"莉莎・霍克愛","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-107":{"name":"羅伊・馬斯坦古","effectText":"【登場時】選擇最多1張對手前線BP3000以下的角色卡，放置在移除區。","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-108":{"name":"洛克貝爾家","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「愛力克」或「洛克貝爾」的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37ST/FMA-1-109":{"name":"一起回家吧","effectText":"將最多1張自己場外的〈愛德華・愛力克〉或〈阿爾馮斯・愛力克〉加入手牌。可從自己手牌，使最多1張滿足能源需求且消耗AP為1的〔〈愛德華・愛力克〉或〈阿爾馮斯・愛力克〉〕以休息狀態在自己場上登場，或使其發動突襲。","triggerText":""},"UA37ST/FMA-1-110":{"name":"亞力士・路易・阿姆斯壯","effectText":"【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）","triggerText":""},"UA37ST/FMA-1-111":{"name":"羅伊・馬斯坦古","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n若自己的手牌為0張時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA37ST/FMA-1-112":{"name":"父親大人","effectText":"若自己場外有20張以上卡片時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【登場時】使最多1張自己場外能源需求2以下消耗AP1的［特徵：人造人］以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37ST/FMA-1-113":{"name":"金格・布拉德雷","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，獲得「這張角色卡不會被對手的觸發效果選擇。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-001":{"name":"阿爾馮斯・愛力克","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-002":{"name":"阿爾馮斯・愛力克","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-003":{"name":"阿爾馮斯・愛力克","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】將1張自己場外不持有【突襲】的〈愛德華・愛力克〉，以正面朝上放置在1張自己前線持有【突襲】且非突襲狀態的〈愛德華・愛力克〉下面。若有執行此動作時，將該角色卡置為活動。（進入突襲狀態）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-006":{"name":"馮・霍恩海姆","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA37BT/FMA-1-007":{"name":"溫莉・洛克貝爾","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-005":{"name":"伊茲米・卡迪斯","effectText":"【我方回合中】這張角色卡BP+500。\n【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】選擇1張自己場上的〈愛德華・愛力克〉或〈阿爾馮斯・愛力克〉，置為活動。","triggerText":""},"UA37BT/FMA-1-008":{"name":"溫莉・洛克貝爾","effectText":"若自己前線有〈愛德華・愛力克〉時，這張角色卡的產生能源+【黃】。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-009":{"name":"愛德華・愛力克","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-012":{"name":"愛德華・愛力克","effectText":"【突襲】〈愛德華・愛力克〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+500。\n【登場時】選擇以下其中最多1項。\n・抽2張卡片，並將1張自己的手牌放置在場外。\n・若為我方回合中，可使1張自己場外能源需求3以下消耗AP1的〈阿爾馮斯・愛力克〉以休息狀態在自己場上登場。若有執行此動作時，將這張角色卡的突襲來源卡放置在場外。（這張角色卡不再是突襲狀態）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-004":{"name":"阿爾馮斯・愛力克","effectText":"【若在場外時】若自己場上有〈真理之門〉時，在場外的這張卡片的能源需求減少【黃×1】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】可支付1AP。若有執行此動作時，選擇以下其中『1項』。若此角色卡是因自己的效果登場時，則改為選擇『全部』。\n・選擇最多1張對手前線的角色卡，轉為休息。\n・將這張角色卡置為活動。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA37BT/FMA-1-011":{"name":"愛德華・愛力克","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n若自己場上有〈真理之門〉時，這張角色卡BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-014":{"name":"提姆・馬可","effectText":"若對手場上有藍色或紫色卡片時，手牌中這張卡片的能源需求減少【黃×1】。","triggerText":""},"UA37BT/FMA-1-015":{"name":"托莉夏・愛力克","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA37BT/FMA-1-013":{"name":"傷痕男(斯卡)","effectText":"使這張角色卡以活動狀態在場上登場。\n【登場時】選擇最多1張對手前線的角色卡，轉為休息。若自己產生能源在7以上時，這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【攻擊時】對手將2張自己場外的卡片依任意順序放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-010":{"name":"愛德華・愛力克","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈愛德華・愛力克〉或〈阿爾馮斯・愛力克〉或〈真理之門〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA37BT/FMA-1-020":{"name":"張梅","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA37BT/FMA-1-018":{"name":"胡","effectText":"【我方回合中】若自己產生能源在7以上時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-019":{"name":"張梅","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-021":{"name":"張梅","effectText":"【突襲】〈張梅〉置為活動，並可移動至前線\n這張角色卡的產生能源+【黃】。\n【登場時】【若在能源線時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-022":{"name":"蘭芳","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：清國］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-016":{"name":"尤基","effectText":"【對方回合中】【若在前線時】自己場上〈尤基〉以外的角色卡獲得「對手以事件卡的效果選擇這張角色卡時，必須追加將1張自身手牌放置在場外才可以選擇。」。〈尤基〉的這個效果不重複。","triggerText":""},"UA37BT/FMA-1-023":{"name":"蘭芳","effectText":"根據自己的產生能源，這張角色卡獲得以下所有效果。\n・5以上：這張角色卡BP+500。\n・6以上：BP4000以上的角色卡不能防禦這張角色卡。\n・7以上：【登場時】可支付1AP。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-025":{"name":"姚麟","effectText":"【登場時】使最多1張自己手牌中能源需求2以下消耗AP1的黃色［特徵：清國］角色卡，以休息狀態在自己場上登場。","triggerText":""},"UA37BT/FMA-1-026":{"name":"姚麟","effectText":"根據自己的產生能源，這張角色卡獲得以下所有效果。\n・6以上：【登場時】抽最多1張卡片。\n・7以上：【攻擊時】選擇最多1張自己場上其他的［特徵：清國］，在這個回合中，獲得「BP4000以上的角色卡不能防禦這張角色卡。」。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA37BT/FMA-1-027":{"name":"古利德","effectText":"【突襲】〈姚麟〉置為活動，並可移動至前線\n這張角色卡BP+1000。\n【登場時】這張角色卡在這個回合中，獲得「對手必須盡可能防禦這張角色卡的攻擊。」。\n【退場時】可以將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求4以下消耗AP1的〈姚麟〉以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-028":{"name":"真理之門","effectText":"這張場域卡不會被對手的效果選擇。\n【登場時】若自己場上有〈愛德華・愛力克〉或〈阿爾馮斯・愛力克〉時，抽2張卡片，並將2張自己的手牌放置在場外。\n【啟動主要】【轉為休息】將1張自己生命區的卡片放置在場外。若有執行此動作時，查看6張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-017":{"name":"小梅","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈張梅〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-029":{"name":"機械鎧","effectText":"選擇1張自己場上的角色卡，在這個回合中，BP+2000。若選擇的角色卡為〈愛德華・愛力克〉時，則再於這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）或【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-032":{"name":"為什麼是二選一？","effectText":"選擇以下『1項』。若自己場上有〈阿爾馮斯・愛力克〉時，則替換成『全部』。\n・查看3張自己卡組上面的卡片。將它們以任意張數及任意順序，分別放置在自己卡組的上面與下面。\n・抽2張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-031":{"name":"等價交換","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA37BT/FMA-1-030":{"name":"來自清國的旅人","effectText":"選擇1張對手前線BP為自己場上［特徵：清國］的卡片張數×1000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA37BT/FMA-1-033":{"name":"鋼之鍊金術師","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈愛德華・愛力克〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA37BT/FMA-1-035":{"name":"亞力士・路易・阿姆斯壯","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-037":{"name":"亞力士・路易・阿姆斯壯","effectText":"【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【每回合1】這張角色卡攻擊後戰勝時，抽2張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-034":{"name":"亞力士・路易・阿姆斯壯","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-036":{"name":"亞力士・路易・阿姆斯壯","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-038":{"name":"伊茲米・卡迪斯","effectText":"這張角色卡攻擊後沒有被防禦時，抽1張卡片。","triggerText":""},"UA37BT/FMA-1-039":{"name":"愛德華・愛力克","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA37BT/FMA-1-040":{"name":"愛德華・愛力克","effectText":"【登場時】可將1張自己生命區的卡片加入手牌。若有執行此動作時，將這張角色卡置為活動。\n【啟動主要】【將2張手牌放置在場外】【每回合1】這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-042":{"name":"約翰・哈博克","effectText":"【退場時】使最多1張自己手牌中，〈約翰‧哈博克〉以外，能源需求3以下、消耗AP1的藍色角色卡，以休息狀態在自己場上登場。","triggerText":""},"UA37BT/FMA-1-043":{"name":"海曼斯・普雷達","effectText":"若對手場上有黃色或紫色卡片時，手牌中這張卡片的能源需求減少【藍×1】。","triggerText":""},"UA37BT/FMA-1-044":{"name":"黑色疾風號","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈莉莎‧霍克愛〉或〈肯恩‧菲利〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-046":{"name":"馬斯・休斯","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】在這個回合中，這張角色卡BP+1000。\n【退場時】若自己的手牌在2張以下時，抽1張卡片。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA37BT/FMA-1-047":{"name":"瑪麗亞・羅斯","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA37BT/FMA-1-048":{"name":"莉莎・霍克愛","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-024":{"name":"姚麟","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-050":{"name":"莉莎・霍克愛","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數依任意順序放置在自己卡組的上面，其餘卡片依任意順序放置在自己卡組的下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-041":{"name":"肯恩・菲利","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-052":{"name":"羅伊・馬斯坦古","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-051":{"name":"莉莎・霍克愛","effectText":"【突襲】〈莉莎・霍克愛〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。查看4張自己卡組上面的卡片。將其中最多1張放置在自己卡組上面，其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【若在前線時】【每回合1】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-053":{"name":"羅伊・馬斯坦古","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":""},"UA37BT/FMA-1-045":{"name":"馬斯・休斯","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA37BT/FMA-1-054":{"name":"羅伊・馬斯坦古","effectText":"【我方回合中】若自己的手牌在2張以下時，這張角色卡BP+1000。\n【攻擊時】若自己的手牌為0張時，抽最多1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-058":{"name":"奧莉薇・米拉・阿姆斯壯","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：布里克斯］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA37BT/FMA-1-055":{"name":"羅伊・馬斯坦古","effectText":"【突襲】〈羅伊・馬斯坦古〉置為活動，並可移動至前線\n若自己的手牌為0張時，這張角色卡獲得【衝擊（1）】。\n【登場時】抽1張卡片。\n【攻擊時】將任意張數的自己手牌放置在場外，並選擇最多1張對手前線『BP1000』以下的角色卡，使其退場。每有1張以此效果放置在場外的卡片，此效果可選擇的角色卡BP範圍+1000。以此效果使其退場時，可追加將1張自己的手牌放置在場外。若有執行此動作時，則替換成放置在移除區。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-057":{"name":"奧莉薇・米拉・阿姆斯壯","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-049":{"name":"莉莎・霍克愛","effectText":"【登場時】若自己場上有〈羅伊・馬斯坦古〉時，抽1張卡片。","triggerText":""},"UA37BT/FMA-1-061":{"name":"巴卡尼亞","effectText":"若自己場上有3張以上［特徵：布里克斯］時，手牌中這張卡片的消耗AP-1。\n【啟動主要】【每回合1】這張角色卡直到下一個自己回合開始為止，獲得BP+1000、【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）與「對手攻擊階段結束時，使這張角色卡退場，並抽1張卡片。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-059":{"name":"奧莉薇・米拉・阿姆斯壯","effectText":"【登場時】若在這個回合中自己場上已有消耗AP2以上的卡片登場時，選擇最多1張自己的AP卡，置為活動。〈奧莉薇・米拉・阿姆斯壯〉的這個效果每回合只能發動1次。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA37BT/FMA-1-062":{"name":"邁爾斯","effectText":"若自己場上有3張以上其他［特徵：布里克斯］時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA37BT/FMA-1-056":{"name":"瓦特・法爾曼","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-060":{"name":"奧莉薇・米拉・阿姆斯壯","effectText":"【突襲】〈奧莉薇・米拉・阿姆斯壯〉置為活動，並可移動至前線\n【登場時】將自己場上所有［特徵：布里克斯］置為活動。\n【攻擊時】可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上消耗AP2以上的角色卡，置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-063":{"name":"布里克斯要塞","effectText":"【登場時】在這個回合中，下一次從手牌中使用［特徵：布里克斯］時，其消耗AP-1。\n【啟動主要】【轉為休息】僅限在這個回合中自己場上已有消耗AP2以上的卡片登場時可發動。抽1張卡片。〈布里克斯要塞〉的這個效果每回合只能發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-064":{"name":"軍隊有危險了！！","effectText":"抽2張卡片。之後，若自己的手牌為2張時，可再抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-065":{"name":"國家鍊金術師","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA37BT/FMA-1-067":{"name":"焰之鍊金術師","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈羅伊・馬斯坦古〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA37BT/FMA-1-066":{"name":"布里克斯的北壁","effectText":"選擇1張對手前線BP5000以下的角色卡，『使其轉為休息。下一次無法置為活動』。若自己場上有〈奧莉薇・米拉・阿姆斯壯〉時，可替換成『使其退場』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA37BT/FMA-1-070":{"name":"佐魯夫・J・金普利","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-069":{"name":"修・塔克","effectText":"【登場時】可將2張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外的〈妮娜＆亞歷山大〉以休息狀態在自己場上登場，或使其發動突襲。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-073":{"name":"佐魯夫・J・金普利","effectText":"【突襲】〈佐爾夫・J・金普利〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP3000以下的角色卡，使其退場。\n【啟動主要】【每回合1】將1張自己場外的〈賢者之石〉放置在移除區。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-071":{"name":"佐魯夫・J・金普利","effectText":"【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-074":{"name":"妮娜＆亞歷山大","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA37BT/FMA-1-075":{"name":"恩維","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-076":{"name":"恩維","effectText":"持有【突襲】的角色卡可對此角色發動突襲。\n【登場時】若自己場外有10張以上卡片時，選擇最多1張對手前線BP3000以下的角色卡，轉為休息。","triggerText":""},"UA37BT/FMA-1-079":{"name":"父親大人","effectText":"這張卡片僅在自己場外有20張以上卡片，且自己場上沒有與此卡相同卡片編號的卡片時才可登場。\n使這張角色卡以活動狀態在場上登場。\n【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）\n【登場時】選擇最多1張對手前線的角色卡，使其退場。\n【啟動主要】【若在場外時】僅在自己場外有20張以上卡片時可發動。將3張自己手牌中的紫色卡片放置在場外。若有執行此動作時，將場外的這張卡片加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-077":{"name":"恩維","effectText":"【突襲】〈恩維〉置為活動，並可移動至前線\n【登場時】在這個回合中，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。\n【退場時】選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-080":{"name":"庫拉多尼","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA37BT/FMA-1-068":{"name":"妮娜＆亞歷山大","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。之後，若這張角色卡為突襲狀態時，抽1張卡片。\n【突襲】〈妮娜＆亞歷山大〉置為活動，並可移動至前線\n這張角色卡的產生能源+【紫】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-081":{"name":"庫拉多尼","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】 在這個回合中，這張角色卡獲得【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）與「這張角色卡攻擊後戰勝時，抽1張卡片。」。","triggerText":""},"UA37BT/FMA-1-078":{"name":"父親大人","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：人造人］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA37BT/FMA-1-083":{"name":"斯洛烏斯","effectText":"若對手場上有黃色或藍色卡片時，手牌中這張卡片的能源需求減少【紫×1】。","triggerText":""},"UA37BT/FMA-1-072":{"name":"佐魯夫・J・金普利","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，抽『1張』卡片。若以此效果放置在場外的卡片為〈賢者之石〉時，則替換成『2張』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-085":{"name":"普萊德","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA37BT/FMA-1-084":{"name":"塞利姆・布拉德雷","effectText":"這張卡片也視為〈普萊德〉。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-086":{"name":"普萊德","effectText":"【啟動主要】【每回合1】使1張自己場上的〔〈佐爾夫・J・金普利〉或能源需求4以上的角色卡〕退場。若有執行此動作時，抽1張卡片，這張角色卡在這個回合中，獲得BP+2000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA37BT/FMA-1-087":{"name":"燒瓶裡的小人","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-090":{"name":"拉斯多","effectText":"【突襲】〈拉斯多〉置為活動，並可移動至前線\n【登場時】抽2張卡片，並將2張自己的手牌放置在場外。之後，若自己場外有10張以上的卡片時，則再抽1張卡片。\n【退場時】將最多1張這張角色卡的突襲來源卡放回手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-088":{"name":"拉斯多","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-089":{"name":"拉斯多","effectText":"【登場時】查看1張自己卡組上面的卡片，若該卡片為［特徵：人造人］，可公開並加入手牌。若不加入手牌，則將該卡片放置在自己卡組的上面或場外。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA37BT/FMA-1-082":{"name":"古利德","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-091":{"name":"金格・布拉德雷","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-095":{"name":"國土鍊成陣","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己卡組上面的卡片放置在場外。之後，若自己場外有20張以上卡片時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA37BT/FMA-1-092":{"name":"金格・布拉德雷","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA37BT/FMA-1-093":{"name":"金格・布拉德雷","effectText":"【突襲】〈金格・布拉德雷〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得BP+500與【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。\n【啟動主要】【若在前線時】【每回合1】選擇1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA37BT/FMA-1-096":{"name":"我討厭像你這種直覺敏銳的小鬼","effectText":"對手選擇「手牌中有〈妮娜＆亞歷山大〉。」或「手牌中沒有〈妮娜＆亞歷山大〉。」其中一項。之後，自己抽3張卡片，並公開所有手牌。若與對手選擇的相符時，將3張自己的手牌放置在移除區。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-094":{"name":"拉斯","effectText":"這張卡片也視為〈金格・布拉德雷〉。\n若自己場外有20張以上卡片時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA37BT/FMA-1-098":{"name":"最強之眼","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈金格・布拉德雷〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA37BT/FMA-1-099":{"name":"人造人","effectText":"將2張自己卡組上面的卡片放置在場外。之後，將最多1張自己場外的紫色［特徵：人造人］加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA37BT/FMA-1-100":{"name":"我收下了！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有4張以上［特徵：人造人］時，選擇以下其中1項。\n・則替換成『BP5000以下』。\n・將2張自己卡組上面的卡片放置在場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA38BT/WBK-1-002":{"name":"橘琴葉","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA38BT/WBK-1-001":{"name":"櫻遙","effectText":"【登場時】使最多1張自己手牌中能源需求2以下消耗AP1的綠色［特徵：多聞眾］以休息狀態在自己場上登場。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA37BT/FMA-1-097":{"name":"賢者之石","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA38BT/WBK-1-004":{"name":"鹿沼稔","effectText":"【啟動主要】【轉為休息】將這張卡片與1張自己場外的〈有馬雪成〉放置在移除區。若有執行此動作時，抽2張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-005":{"name":"佐狐浩太","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-003":{"name":"有馬雪成","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA38BT/WBK-1-006":{"name":"佐狐浩太","effectText":"【登場時】抽1張卡片。\n【退場時】將1張自己的手牌放置在場外。","triggerText":""},"UA38BT/WBK-1-008":{"name":"十龜條","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-009":{"name":"十龜條","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈兔耳山丁子〉或〈十龜條〉或〈獵戶座〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在移除區。","triggerText":""},"UA38BT/WBK-1-007":{"name":"佐狐浩太","effectText":"【突襲】〈佐狐浩太〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+1000。\n【攻擊時】若自己前線有〈柊登馬〉或自己場外沒有角色卡時，抽最多1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-010":{"name":"十龜條","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數依任意順序放置在自己卡組的上面，其餘卡片依任意順序放置在自己卡組的下面。","triggerText":""},"UA38BT/WBK-1-011":{"name":"十龜條","effectText":"若自己場上有〈兔耳山丁子〉時，手牌中這張卡片的消耗AP-1。\n【我方回合中】若自己場外沒有角色卡時，這張角色卡BP+500。\n【登場時】將最多2張自己場外的［特徵：獅子頭連］放置在移除區。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-012":{"name":"十龜條","effectText":"【突襲】〈十龜條〉置為活動，並可移動至前線\n【登場時】對手前線所有BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【若在前線時】【每回合1】僅在自己場上有〈兎耳山丁子〉時可發動。選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。將最多2張自己場外的［特徵：獅子頭連］放置在移除區。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA38BT/WBK-1-013":{"name":"兔耳山丁子","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-014":{"name":"兔耳山丁子","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-016":{"name":"兔耳山丁子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【退場時】可以將1張自己的手牌放置在移除區。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA38BT/WBK-1-015":{"name":"兔耳山丁子","effectText":"【我方回合中】這張角色卡BP+500。\n【登場時】若自己場外沒有角色卡時，將這張角色卡置為活動。〈兔耳山丁子〉的這個效果每回合只能發動1次。","triggerText":""},"UA38BT/WBK-1-018":{"name":"梅宮一","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA38BT/WBK-1-019":{"name":"梅宮一","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":""},"UA38BT/WBK-1-017":{"name":"兔耳山丁子","effectText":"【突襲】〈兔耳山丁子〉置為活動，並可移動至前線\n若自己場外沒有角色卡時，這張角色卡獲得【衝擊（1）】。\n【若在前線時】自己場上〈兔耳山丁子〉以外的［特徵：獅子頭連］將離場時，可改為將該角色卡及其突襲來源卡放置在移除區。\n【登場時】這張角色卡在這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA38BT/WBK-1-020":{"name":"梅宮一","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：防風鈴］或〈橘琴葉〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA38BT/WBK-1-021":{"name":"梅宮一","effectText":"【登場時】使最多1張自己手牌中能源需求2以下消耗AP1的綠色［特徵：多聞眾］以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-022":{"name":"櫻遙","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-023":{"name":"櫻遙","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA38BT/WBK-1-024":{"name":"櫻遙","effectText":"從手牌使用這張卡片發動突襲時，若自己場上有5種以上卡片名稱的［特徵：防風鈴］卡片時，消耗AP-1。若在這個回合中，已從手牌不支付AP使用過其他〈櫻遙〉，則此效果無效。\n【突襲】〈櫻遙〉置為活動，並可移動至前線\n這張角色卡若在前線時，也可產生能源。\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA38BT/WBK-1-026":{"name":"蘇枋隼飛","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n若自己場上有5種以上卡片名稱的［特徵：防風鈴］卡片時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-027":{"name":"杉下京太郎","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-025":{"name":"蘇枋隼飛","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張黃色的［特徵：防風鈴］放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-028":{"name":"杉下京太郎","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-032":{"name":"柊登馬","effectText":"【攻擊時】若自己場上有〈梅宮一〉時，抽最多1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-033":{"name":"獵戶座","effectText":"此場域卡以活動狀態登場。\n【啟動主要】【轉為休息】選擇以下其中1項。\n・將最多2張自己場外的［特徵：獅子頭連］放置在移除區。\n・若自己場外沒有角色卡時，選擇最多1張自己場上的［特徵：獅子頭連］，在這個回合中，獲得「BP3000以下的角色卡不能防禦這張角色卡。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-030":{"name":"楡井秋彦","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】使最多1張自己場外〈楡井秋彦〉以外，能源需求1以下的黃色［特徵：防風鈴］以休息狀態在自己場上登場。","triggerText":""},"UA38BT/WBK-1-034":{"name":"喫茶Pothos","effectText":"【登場時】查看2張自己卡組上面的卡片。公開其中最多1張［特徵：防風鈴］或〈橘琴葉〉並加入手牌。將其餘卡片以任意張數及任意順序分別放置在自己卡組的上面與下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-035":{"name":"我100%不會輸","effectText":"選擇1張對手前線BP為自己場上［特徵：防風鈴］的張數×1000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA38BT/WBK-1-037":{"name":"打架就是一種〝對話〞喔","effectText":"選擇任意張數自己場上的［特徵：防風鈴］，在這個回合中，獲得BP+1000與「這張角色卡在戰鬥中勝利時，抽最多1張卡片。」。此效果不能選擇卡片名稱相同的角色卡。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-031":{"name":"柊登馬","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA38BT/WBK-1-038":{"name":"這次就一起尋找答案吧","effectText":"查看7張自己卡組上面的卡片。從其中公開最多各1張〈兔耳山丁子〉與〈十龜條〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-040":{"name":"全部都不需要","effectText":"若自己場上有〈兔耳山丁子〉時，手牌中這張卡片的消耗AP-1。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA38BT/WBK-1-036":{"name":"這裡不是垃圾該待的地方","effectText":"在這個回合中，下一張從手牌中使用［特徵：獅子頭連］的消耗AP-1。從自己場外將最多2張［特徵：獅子頭連］放置在移除區。之後，若自己場外沒有角色卡時，抽最多1張卡片。","triggerText":""},"UA38BT/WBK-1-039":{"name":"我絕不違背自我！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA38BT/WBK-1-041":{"name":"力量的絕對信仰","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA38BT/WBK-1-042":{"name":"橘琴葉","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA38BT/WBK-1-029":{"name":"杉下京太郎","effectText":"【突襲】〈杉下京太郎〉置為活動，並可移動至前線\n這張角色卡若在前線時，也可產生能源。\n【登場時】這張角色卡在這個回合中，BP+1000。\n【退場時】若自己場上有〈梅宮一〉時，可將1張自己的手牌放置在場外。若有執行此動作時，使這張卡片以休息狀態在自己前線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA38BT/WBK-1-043":{"name":"梅宮一","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-045":{"name":"杏西雅紀","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA38BT/WBK-1-044":{"name":"梅宮一","effectText":"【登場時】從自己場外將〈梅宮一〉以外的〔能源需求2以下的綠色角色卡與能源需求3以上的綠色角色卡〕最多各1張加入手牌。若以此效果將〈橘琴葉〉加入手牌時，將這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-046":{"name":"榎本健史","effectText":"【登場時】選擇最多1張自己場上的〈梶蓮〉，在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-048":{"name":"梶蓮","effectText":"使這張角色卡以活動狀態在場上登場。\n【我方回合中】這張角色卡攻擊後戰勝時，將這張角色卡放置在自己卡組下面，並使最多1張自己手牌中能源需求2以下的綠色［特徵：多聞眾］以休息狀態在自己場上登場。\n【登場時】查看5張自己卡組上面的卡片。使其中最多1張能源需求2以下的綠色［特徵：多聞眾］以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-047":{"name":"梶蓮","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-049":{"name":"桐生三輝","effectText":"【啟動主要】【轉為休息】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。將這張卡片放回手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-050":{"name":"桐生三輝","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】選擇最多1張我方場上的其他角色，此回合中，BP+1000。","triggerText":""},"UA38BT/WBK-1-051":{"name":"楠見結斗","effectText":"【登場時】選擇最多1張自己場上的〈梶蓮〉，在這個回合中，獲得「這張角色卡攻擊後戰勝時，抽最多1張卡片。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-053":{"name":"櫻遙","effectText":"此角色為活動狀態時，此角色的產生能源+【綠】。","triggerText":""},"UA38BT/WBK-1-054":{"name":"櫻遙","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己能源線的角色卡，使其轉為休息或置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-052":{"name":"櫻遙","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-055":{"name":"櫻遙","effectText":"【突襲】〈櫻遙〉置為活動，並可移動至前線\n【每回合1】當自己場上擁有【衝擊無效】的角色卡攻擊後沒有被防禦時，將這張角色卡置為活動。\n【登場時】這張角色卡直到下一個我方回合開始時，獲得【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA38BT/WBK-1-057":{"name":"蘇枋隼飛","effectText":"【啟動主要】【若在能源線時】【每回合1】僅限這張角色卡為休息狀態時可發動。查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":""},"UA38BT/WBK-1-060":{"name":"蘇枋隼飛","effectText":"【若在能源線時】當活動狀態的這張角色卡因自己的角色卡效果而轉為休息時，可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上的角色卡，置為活動。〈蘇枋隼飛〉的這個效果每回合只能發動1次。\n【登場時】選擇最多1張自己場上的角色卡，直到下一個我方回合開始時，獲得「【對方回合中】對手以角色卡的效果或事件卡的效果選擇這張角色卡時，必須追加支付1AP才可以選擇。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-059":{"name":"蘇枋隼飛","effectText":"【登場時】可將1張自己場上活動狀態的〈蘇枋隼飛〉轉為休息。若有執行此動作時，查看2張自己卡組上面的卡片。將其中1張加入手牌，其餘放置在場外。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA38BT/WBK-1-061":{"name":"蘇枋隼飛","effectText":"【突襲】〈蘇枋隼飛〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【對方回合中】對手以角色卡的效果或事件卡的效果選擇這張角色卡時，必須將1張自己前線活動狀態BP3000以上的角色卡轉為休息才可以選擇。\n【防禦時】可將2張自己能源線活動狀態的〈蘇枋隼飛〉轉為休息。若有執行此動作時，這張角色卡不會因這場對戰的敗北而退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA38BT/WBK-1-058":{"name":"蘇枋隼飛","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若自己場上有其他擁有【衝擊無效】的角色卡時，這張角色卡BP+1000。","triggerText":""},"UA38BT/WBK-1-062":{"name":"杉下京太郎","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-063":{"name":"杉下京太郎","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態時可發動。將3張自己場上活動狀態的角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得「【攻擊時】抽最多1張卡片。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-064":{"name":"杉下京太郎","effectText":"這張角色卡攻擊後被防禦時，可抽1張卡片。若有執行此動作時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-056":{"name":"蘇枋隼飛","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-065":{"name":"杉下京太郎","effectText":"【衝擊無效】（與此角色進行對戰的角色，在該場對戰中會失去【衝擊】）\n【我方回合中】若自己場上有其他擁有【衝擊無效】的角色卡時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-067":{"name":"柘浦大河","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-068":{"name":"楡井秋彦","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：防風鈴］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-069":{"name":"楡井秋彦","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】將1張自己場外能源需求3以下的綠色角色卡加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-070":{"name":"楡井秋彦","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：防風鈴］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-072":{"name":"柊登馬","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上其他的角色卡，在這個回合中，BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-073":{"name":"柊登馬","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-074":{"name":"風鈴高中","effectText":"這張場域卡以活動狀態在場上登場。\n【每回合1】當自己場上的角色卡攻擊並在戰鬥中獲勝時，可將活動狀態的這張場域卡轉為休息。若有執行此動作時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-075":{"name":"要不要登上大人的階梯呢","effectText":"選擇1張對手前線BP5000以下的角色卡，放置在對手卡組上面或下面的『對手所選擇的一方』。若自己場上有〈蘇枋隼飛〉時，則替換成『自己所選擇的一方』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA38BT/WBK-1-071":{"name":"楡井秋彦","effectText":"【啟動主要】【轉為休息】選擇以下其中1項。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n・選擇最多1張自己場上擁有【衝擊無效】的角色卡，在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-066":{"name":"柘浦大河","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-076":{"name":"我可是來打架稱霸的喔？","effectText":"選擇最多1張自己前線的角色卡，在這個回合中，獲得BP+2000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。若自己場上有〈櫻 遙〉時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA38BT/WBK-1-079":{"name":"巡視街道","effectText":"查看6張自己卡組上面的卡片。公開其中最多1張綠色的［特徵：防風鈴］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA38BT/WBK-1-080":{"name":"這不是帥爆了嗎！！！！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈櫻遙〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA38BT/WBK-1-077":{"name":"很難受對不對呀…小弟弟","effectText":"將最多1張自己場外的〈蘇枋隼飛〉加入手牌。可從自己手牌中，使最多1張滿足能源需求且消耗AP為1的〈蘇枋隼飛〉以休息狀態在自己場上登場，或發動突襲。","triggerText":""},"UA39BT/KIN-1-001":{"name":"惡魔將軍","effectText":"這張角色卡無法在前線登場，且無法在移動階段進行移動。\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】查看5張自己卡組上面的卡片。使其中最多1張能源需求3以下消耗AP1的紫色［特徵：惡魔超人］以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【若在能源線時】選擇2張〈惡魔將軍〉以外自己能源線活動狀態的［特徵：惡魔超人］。若有執行此動作時，將選擇的角色卡與這張角色卡移動至前線。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA38BT/WBK-1-078":{"name":"防風鈴將進行肅清！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA39BT/KIN-1-002":{"name":"阿修羅人","effectText":"【啟動主要】【若在前線時】【每回合1】僅限自己能源線上的卡片在2張以下時可發動。這張角色卡直到下一個我方回合開始前，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-004":{"name":"THE魔雲天","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":""},"UA39BT/KIN-1-005":{"name":"陽光人","effectText":"【啟動主要】【若在前線時】【每回合1】僅限自己能源線上的卡片在2張以下時可發動。這張角色卡在這個回合中，獲得BP+500與「這張角色卡若在前線時也可產生能源。」。","triggerText":""},"UA39BT/KIN-1-007":{"name":"彈簧人","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。","triggerText":""},"UA39BT/KIN-1-003":{"name":"亞特蘭蒂斯","effectText":"【退場時】若自己場上擁有3張以上其他［特徵：惡魔超人］時，抽1張卡片。","triggerText":""},"UA39BT/KIN-1-006":{"name":"廢品人","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】在這個回合中，這張角色卡的BP增加（因這個效果而放置在場外的卡片的能源需求數量×500）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-008":{"name":"彈簧人","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：惡魔超人］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA39BT/KIN-1-009":{"name":"水牛人","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-010":{"name":"水牛人","effectText":"若自己場上擁有3張以上其他［特徵：惡魔超人］時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA39BT/KIN-1-012":{"name":"水牛人","effectText":"【突襲】〈水牛人〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP4000以下的角色卡，放回手牌。之後，若對手的手牌在4張以上時，對手將1張自身的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-013":{"name":"黑洞","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-014":{"name":"黑洞","effectText":"這張卡片從手牌放置在場外時，可將這張卡片以背面朝上放置在自己場上〈五角星〉或能源需求3以上［特徵：惡魔超人］的下面。\n這張背面朝上卡片從自己場上角色卡的下面放置在場外時，可將1張自己的手牌放置在場外。若有執行此動作時，將這張卡片以休息狀態在自己前線登場。〈黑洞〉的這個效果每回合僅可發動1次。","triggerText":""},"UA39BT/KIN-1-011":{"name":"水牛人","effectText":"這張角色卡不會因對手效果而轉為休息，且不會獲得「這張角色卡無法攻擊。」、「這張角色卡無法防禦。」與「這張角色卡無法攻擊也無法防禦。」。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-015":{"name":"黑洞","effectText":"【突襲】〈黑洞〉置為活動，並可移動至前線\n若這張角色卡下方有背面朝上卡片時，這張角色卡獲得【衝擊（1）】。\n【登場時】抽1張卡片。之後，可將1張自己的手牌放置在場外。若有執行此動作時，將最多1張自己場外的〈五角星〉或能源需求3以下［特徵：惡魔超人］的卡片加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-017":{"name":"擊破人","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-018":{"name":"死神","effectText":"【我方回合中】若自己場外有原本BP4000以上的［特徵：完美超人］時，這張角色卡BP+1000。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-016":{"name":"卡門先生","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA39BT/KIN-1-020":{"name":"壯武道","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":""},"UA39BT/KIN-1-021":{"name":"壯武道","effectText":"這張角色卡被BP3000以下的角色卡防禦時，這張角色卡在這個回合中，獲得【衝擊（1）】。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【登場時】若自己場上的角色卡全部為［特徵：完美超人］時，可選擇1張對手前線BP5000以下的角色卡，放置在對手卡組下面。若有執行此動作時，對手可從自身場外，使最多1張能源需求0的角色卡以休息狀態在自身前線登場。藉由此效果登場的角色卡的【登場時】無法發動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-022":{"name":"渦輪人","effectText":"【登場時】若自己的生命值在5以下時，可以支付1AP。若有執行此動作時，選擇最多1張自己或對手前線其他的角色卡，在這個回合中，『BP+1000』。之後，若被選擇的角色卡的BP在5500以上時，使該張角色卡退場。若自己的生命值在2以下時，則替換成『BP+2000』。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-025":{"name":"涅墨西斯","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA39BT/KIN-1-026":{"name":"涅墨西斯","effectText":"【突襲】〈涅墨西斯〉置為活動，並可移動至前線\n這張角色卡被BP3000以下的角色卡防禦時，抽2張卡片，並將1張自己的手牌放置在場外。\n【登場時】若自己場上的角色卡全部為［特徵：完美超人］時，使最多1張自己手牌中能源需求3以下消耗AP1的紫色角色卡以休息狀態在自己場上登場。\n【啟動主要】【若在前線時】【每回合1】選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-019":{"name":"傑克・齊","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA39BT/KIN-1-024":{"name":"涅墨西斯","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-027":{"name":"躲貓貓","effectText":"【我方回合中】若對手場外有2張以上擁有【特殊觸發】的卡片時，這張角色卡BP+2500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-028":{"name":"極地人","effectText":"【我方回合中】這張角色卡BP+1000。","triggerText":""},"UA39BT/KIN-1-030":{"name":"魔法師人","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA39BT/KIN-1-031":{"name":"馬克斯・拉吉亞爾","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-032":{"name":"完美・無量大數軍","effectText":"依據自己場上［特徵：完美・無量大數軍］的卡片名稱種類數，這張場域卡獲得以下全數效果。\n・3種以上：【登場時】抽1張卡片。\n・5種以上：【啟動主要】【轉為休息】【使這張卡片退場】選擇1張自己場上的［特徵：完美・無量大數軍］，置為活動。\n・7種以上：【啟動主要】【轉為休息】【每回合1】選擇1張對手前線BP3000以下的角色卡，使其退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-029":{"name":"躲貓貓人","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA39BT/KIN-1-033":{"name":"為惡魔加油的話，是長不成正直的大人的","effectText":"使最多1張自己場外能源需求2以下的［特徵：惡魔超人］以休息狀態在自己場上登場。若使用這個效果使〈亞特蘭蒂斯〉登場技能，將該角色卡置為活動，並在這個回合中，獲得「攻擊階段結束時，使這張角色卡退場。」與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-034":{"name":"吸引黑洞","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈黑洞〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA39BT/KIN-1-036":{"name":"一切都是為了那位大人！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA39BT/KIN-1-037":{"name":"零的悲劇","effectText":"選擇1張對手前線BP5000以下的角色卡，放置在對手卡組下面。對手可從自身場外，使最多1張能源需求0的角色卡以休息狀態在自身前線登場。因這個效果登場的角色卡的【登場時】效果不會發動。若自己場上擁有3張以上［特徵：完美超人］時，自己抽1張卡片。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA39BT/KIN-1-035":{"name":"彈簧火箭炮","effectText":"選擇以下1項。\n・若自己場上有〈水牛人〉時，選擇1張對手前線的角色卡，在這個回合中，BP-5000。\n・抽1張卡片。選擇最多1張自己場上的〈彈簧人〉，在這個回合中，獲得BP+2500與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA39BT/KIN-1-039":{"name":"完美・無量大數軍的第二陣來了！！","effectText":"查看5張自己卡組上面的卡片。從中公開最多3張不同卡片名稱的［特徵：完美・無量大數軍］卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-038":{"name":"對手就讓你來選吧！","effectText":"查看7張自己卡組上面的卡片。對手從中隨機選擇1張。自己將被選擇的卡片以外的卡片依任意順序放置在卡組下面。公開被選擇的卡片，若公開的卡片為［特徵：完美・無量大數軍］時，以休息狀態在自己場上登場。若公開的卡片為［特徵：完美・無量大數軍］以外的卡片時，將公開的卡片加入自己的手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-023":{"name":"大麥町人","effectText":"【登場時】查看2張自己卡組上面的卡片。從其中將最多1張［特徵：完美・無量大數軍］放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-041":{"name":"委員長","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA39BT/KIN-1-040":{"name":"我不是叫你不要被迷惑嗎！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA39BT/KIN-1-043":{"name":"戰爭人","effectText":"若自己前線有其他擁有【攻擊時】效果的［特徵：正義超人］時，這張角色卡的產生能源+【紅】。\n【攻擊時】這張角色卡在這個回合中，BP+1000。","triggerText":""},"UA39BT/KIN-1-044":{"name":"戰爭人","effectText":"【突襲】〈戰爭人〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【攻擊時】【每回合1】依據自己場上擁有【攻擊時】效果的其他［特徵：正義超人］的卡片張數，這張角色卡在這個回合中，獲得以下全數效果。\n・2張以上：【每回合1】這張角色卡的攻擊被防禦的攻擊結束時，可以將這張角色卡在這個回合中BP-1000。若有執行此動作時，將這張角色卡置為活動。\n・4張以上：【每回合1】這張角色卡攻擊後沒有被防禦時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-045":{"name":"加拿大人＆特別人","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紅】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA39BT/KIN-1-046":{"name":"金肉人","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-047":{"name":"金肉人","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈金肉人〉或〈泰利人〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-048":{"name":"金肉人","effectText":"這張卡片無法在前線登場。","triggerText":""},"UA39BT/KIN-1-051":{"name":"金肉人","effectText":"【突襲】〈金肉人〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，從以下選擇『1項』。若自己的生命值在1以下時，則替換成『2項』。\n・獲得選擇的角色卡「這張角色卡無法攻擊。」與「這張角色卡無法防禦。」的效果，直到下一個我方回合開始為止。\n・若選擇的角色卡因［特徵：正義超人］的效果而持有「這張角色卡無法攻擊。」或「這張角色卡無法防禦。」，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-042":{"name":"戰爭人","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-049":{"name":"金肉人","effectText":"【啟動主要】【若在前線時】 【轉為休息】【每回合1】選擇1張對手前線的角色卡，在這個回合中，獲得「這張角色卡不能防禦。」。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA39BT/KIN-1-052":{"name":"傑羅尼莫","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA39BT/KIN-1-053":{"name":"傑羅尼莫","effectText":"【啟動主要】【若在前線時】 【轉為休息】【每回合1】將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。\n【攻擊時】可以將1張這張角色卡下面的背面朝上卡片放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，使其移動至能源線，並獲得「這張角色卡無法移動。」，直到下一個我方回合開始為止。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-054":{"name":"瓷磚人","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA39BT/KIN-1-055":{"name":"泰利人","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-050":{"name":"金肉人","effectText":"【突襲】〈金肉人〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【登場時】抽1張卡片。\n【攻擊時】這張角色卡在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-056":{"name":"泰利人","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA39BT/KIN-1-057":{"name":"泰利人","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】若自己前線有〈金肉人〉時，抽1張卡片。","triggerText":""},"UA39BT/KIN-1-060":{"name":"米特","effectText":"若自己前線有〈金肉人〉時，這張角色卡的產生能源+【紅】。\n【啟動主要】【轉為休息】【將1張手牌放置在場外】選擇1張自己場上的〈金肉人〉，移動至別的線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-061":{"name":"布羅肯Jr.","effectText":"【攻擊時】若自己場上有2張以上擁有【攻擊時】的其他［特徵：正義超人］時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA39BT/KIN-1-059":{"name":"米特","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-062":{"name":"布羅肯Jr.","effectText":"【攻擊時】查看3張自己卡組上面的卡片。公開其中最多1張〈柏林的紅雨〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA39BT/KIN-1-063":{"name":"布羅肯Jr.","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。若使用這個效果將能源需求0的卡片放置在場外時，選擇最多1張對手前線BP2000以下的角色卡，轉為休息。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-058":{"name":"泰利人","effectText":"【突襲】〈泰利人〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【每回合1】這張角色卡從能源線移動至前線時，選擇最多1張對手前線的角色卡，獲得「這張角色卡無法攻擊。」，直到下一個我方回合開始為止。\n【啟動主要】【若在能源線時】【每回合1】選擇1張自己前線的〈金肉人〉，與這張角色卡互相交換位置。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-065":{"name":"拉麵人","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-066":{"name":"拉麵人","effectText":"【攻擊時】若自己場上有2張以上擁有【攻擊時】的其他［特徵：正義超人］時，這張角色卡在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-064":{"name":"五角星","effectText":"【啟動主要】【支付1AP】僅限這張卡片在自己手牌中，且自己的紫色產生能源在5以上時，才可發動。將1張自己前線的〈黑洞〉放回手牌。若有執行此動作時，使手牌中這張卡片以休息狀態在自己前線登場。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。可以選擇1張對手前線的活動角色卡。若有執行此動作時，將選擇的角色卡轉為休息，並將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-067":{"name":"拉麵人","effectText":"【登場時】若自己場上有4張以上擁有【攻擊時】的其他［特徵：正義超人］時，可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多2張自己場上的角色卡置為活動，或選擇最多2張自己的AP卡置為活動。\n【攻擊時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA39BT/KIN-1-068":{"name":"羅賓假面","effectText":"【攻擊時】若自己場上有4張以上擁有【攻擊時】的其他［特徵：正義超人］時，這張角色卡在這個回合中，BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-070":{"name":"羅賓假面","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【攻擊時】可以將1張自己的手牌放置在場外。若有執行此動作時，這張角色卡在這個回合中，BP+2000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-069":{"name":"羅賓假面","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：正義超人］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA39BT/KIN-1-072":{"name":"海神人","effectText":"【登場時】抽1張卡片。","triggerText":""},"UA39BT/KIN-1-073":{"name":"三屬性超人不可侵條約","effectText":"自己的攻擊階段結束時，若在這個回合中自己的角色卡曾進行攻擊時，使這張場域卡退場。\n對手的攻擊階段開始時，對手將1張自身前線的活動狀態角色卡轉為休息。〈三屬性超人互不侵犯條約〉的這個效果每回合僅能發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-075":{"name":"金肉爆裂","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈金肉人〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA39BT/KIN-1-076":{"name":"螺旋起子","effectText":"選擇1張自己場上的角色卡，在這個回合中，『BP+500』，並選擇最多1張自己的AP卡，置為活動。若選擇的角色卡為〈戰爭人〉時，則替換成『BP+1000』。若為能源需求4以上的〈戰爭人〉時，則替換成『BP+2000』。若為能源需求4以上且為突襲狀態的〈戰爭人〉時，則替換成『BP+6000』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-077":{"name":"倫敦鐵橋","effectText":"若自己場上有〈羅賓假面〉時，手牌中這張卡片的消耗AP-1。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。選擇最多1張自己場上的〈羅賓假面〉，在這個回合中，獲得「當對手因【特殊觸發】使這張角色卡退場時，對手改為將該張擁有【特殊觸發】的卡片加入手牌。」。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA39BT/KIN-1-071":{"name":"羅賓假面","effectText":"【突襲】〈羅賓假面〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】將1張自己場上擁有【攻擊時】的活動狀態的其他［特徵：正義超人］轉為休息。若有執行此動作時，選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，『BP-500』。若在這張角色卡登場的回合中，則替換成『BP-1000』。\n【攻擊時】選擇最多1張對手前線BP1000以下的角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA39BT/KIN-1-074":{"name":"牛丼","effectText":"查看6張自己卡組上面的卡片。公開其中最多1張紅色的〈金肉人〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA39BT/KIN-1-078":{"name":"風林火山","effectText":"選擇1張自己前線的角色卡，在這個回合中，BP+2000。若自己場上有〈金肉人〉時，再於這個回合中獲得該角色卡【衝擊（+1）】（衝擊造成的傷害+1，若沒有衝擊時，則獲得【衝擊（1）】）。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-079":{"name":"柏林的紅雨","effectText":"抽1張卡片。若自己前線有紅色的〈布羅肯Jr.〉時，選擇最多1張對手前線BP2500以上的角色卡，在這個回合中，BP-2000。\n【啟動主要】【若在場外時】【將1張手牌放置在場外】 僅限自己前線有紅色的〈布羅肯Jr.〉時可發動。將場外的這張卡片加入手牌。〈柏林的紅雨〉的這個效果每回合僅限發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA39BT/KIN-1-080":{"name":"友情力量","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40ST/REZ-1-001":{"name":"卡包","effectText":"這張卡片在所有區域也視為事件卡。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40ST/REZ-1-016":{"name":"雷姆","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA40ST/REZ-1-010":{"name":"拉姆","effectText":"【登場時】若自己場上有〈雷姆〉或〈羅茲瓦爾・L・梅札斯〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA40ST/REZ-1-007":{"name":"拉姆","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA40ST/REZ-1-022":{"name":"愛蜜莉雅","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40ST/REZ-1-024":{"name":"愛蜜莉雅","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA40ST/REZ-1-029":{"name":"E・M・T","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40ST/REZ-1-028":{"name":"菲魯特","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA40ST/REZ-1-033":{"name":"精靈術師","effectText":"選擇1張對手前線BP5000以下的角色卡，『轉為休息』。若自己場上有〈愛蜜莉雅〉時，則替換成『使其退場』。之後，若自己場上有〈愛蜜莉雅〉與〈帕克〉時，查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40ST/REZ-1-102":{"name":"萊因哈魯特・范・阿斯特雷亞","effectText":"【我方回合中】若自己場上有〈菲魯特〉時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40ST/REZ-1-103":{"name":"雷姆","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40ST/REZ-1-101":{"name":"菜月昴","effectText":"【我方回合中】若這張角色卡下面有背面朝上的卡片時，這張角色卡BP+1000。\n【退場時】若自己場上有〈愛蜜莉雅〉，且這張角色卡下面沒有背面朝上的卡片時，可以將1張自己的手牌放置在場外。若有執行此動作時，使這張角色卡以休息狀態在自己前線登場，並將因這個效果而放置在場外的卡片背面朝上放置在這張角色卡的下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40ST/REZ-1-107":{"name":"菲魯特","effectText":"【登場時】可以支付1AP。若有執行此動作時，選擇以下其中1項。\n・對手將1張自身的手牌放置在場外，自己抽1張卡片。\n・使這張角色卡置為活動，並將最多1張自己場外的〈徽章〉加入手牌。\n【啟動主要】【若在能源線時】【每回合1】這張角色卡在這個回合中，獲得「BP4000以上的角色卡無法防禦這張角色卡。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40ST/REZ-1-108":{"name":"羅茲瓦爾宅邸","effectText":"【啟動主要】【轉為休息】【每回合1】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40ST/REZ-1-106":{"name":"愛蜜莉雅","effectText":"【突襲】〈愛蜜莉雅〉置為活動，並可移動至前線\n若自己場外的事件卡在6張以上時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。\n【攻擊時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。若在這個回合中自己有使用事件卡時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40ST/REZ-1-109":{"name":"徽章","effectText":"查看5張自己卡組上面的卡片。公開其中最多1張［特徵：王選候補者］的卡片或事件卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若公開的卡片為［特徵：王選候補者］時，選擇最多1張自己的AP卡，置為活動。","triggerText":""},"UA40ST/REZ-1-110":{"name":"雷姆","effectText":"若自己前線有〈菜月昴〉時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA40ST/REZ-1-113":{"name":"艾姬多娜","effectText":"【登場時】可以將1張自己的手牌放置在場外，或將1張自己前線的活動角色卡轉為休息。若有執行此動作時，將1張自己場外的〈”聖域”的”試煉”〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA40ST/REZ-1-111":{"name":"庫珥修＆菲莉絲","effectText":"這張卡片可視為〈庫珥修・卡爾斯滕〉也可視為〈菲莉絲〉。\n【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組上面，其餘卡片放置在場外。","triggerText":""},"UA40ST/REZ-1-105":{"name":"愛蜜莉雅","effectText":"【我方回合中】若在這個回合中自己有使用事件卡時，這張角色卡BP+1000。","triggerText":""},"UA40ST/REZ-1-104":{"name":"雷姆","effectText":"這張角色卡以活動狀態登場。\n【登場時】選擇最多2張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【攻擊時】若對手前線有BP比原本的BP還低的角色卡時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40ST/REZ-1-112":{"name":"碧翠絲","effectText":"【我方回合中】在這個回合中若自己從卡組使角色卡登場或發動突襲時，這張角色卡BP+500。\n【登場時】若這張角色卡因自己的效果登場技能，將這張角色卡置為活動。","triggerText":""},"UA40BT/REZ-1-003":{"name":"法蘭黛莉卡・鮑曼","effectText":"若對手場上有藍色或紫色卡片時，手牌中這張卡片的能源需求減少【黃×1】。","triggerText":""},"UA40BT/REZ-1-002":{"name":"帕克","effectText":"這張卡片在所有區域也視為事件卡。\n【我方回合中】若自己場上有〈愛蜜莉雅〉，且自己場外有4張以上事件卡時，這張角色卡BP+1000。\n【登場時】若自己場上有〈愛蜜莉雅〉，且自己場外有6張以上事件卡時，可以將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-004":{"name":"碧翠絲","effectText":"【登場時】抽1張卡片。若在這個回合中自己使用了事件卡時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-005":{"name":"佩特拉・萊特","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-001":{"name":"帕克","effectText":"這張卡片在所有區域也視為事件卡。 \n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-007":{"name":"拉姆","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-006":{"name":"拉姆","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA40BT/REZ-1-008":{"name":"拉姆","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-010":{"name":"拉姆","effectText":"【登場時】若自己場上有〈雷姆〉或〈羅茲瓦爾・L・梅札斯〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-009":{"name":"拉姆","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈拉姆〉或〈雷姆〉或〈羅茲瓦爾・L・梅札斯〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA40BT/REZ-1-011":{"name":"拉姆","effectText":"【突襲】〈拉姆〉置為活動，並可移動至前線\n【對方回合中】【若在前線時】自己場上的〈雷姆〉因對手效果退場時，可使這張角色卡退場作為代替。\n【登場時】從以下選擇1項。\n・所有對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n・選擇最多1張對手前線BP2500以上的角色卡，在這個回合中，BP-2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-012":{"name":"雷姆","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-016":{"name":"雷姆","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA40BT/REZ-1-015":{"name":"雷姆","effectText":"【突襲】〈雷姆〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+500。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【若在前線時】【每回合1】選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【攻擊時】若自己場上所有角色卡皆為〈雷姆〉時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-014":{"name":"雷姆","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA40BT/REZ-1-013":{"name":"雷姆","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-018":{"name":"雷姆","effectText":"【登場時】選擇最多1張對手前線BP2500以上的角色卡，在這個回合中，BP-2000。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA40BT/REZ-1-017":{"name":"雷姆","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-020":{"name":"雷姆","effectText":"【突襲】〈雷姆〉置為活動，並可移動至前線\n【登場時】若自己場上的角色卡全部沒有特徵時，這張角色卡在這個回合中，獲得【衝擊（1）】。\n【啟動主要】【每回合1】這張角色卡在這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）與「BP4000以上的角色卡無法以【狙擊】指定這張角色卡。」。將1張這張角色卡的突襲來源卡片放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-023":{"name":"愛蜜莉雅","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-022":{"name":"愛蜜莉雅","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-021":{"name":"羅茲瓦爾・L・梅札斯","effectText":"【啟動主要】【若在前線時】【每回合1】僅限自己場上有〈拉姆〉與〈雷姆〉時可發動。抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-024":{"name":"愛蜜莉雅","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA40BT/REZ-1-027":{"name":"愛蜜莉雅","effectText":"【突襲】〈愛蜜莉雅〉置為活動，並可移動至前線\n【登場時】在這個回合中，下一次從手牌中使用能源需求3以下的事件卡的消耗AP-1。若自己場外的事件卡在4張以上時，選擇最多1張對手前線的角色卡，轉為休息。若自己場外的事件卡在8張以上時，選擇的角色卡下一次無法置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-028":{"name":"菲魯特","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA40BT/REZ-1-026":{"name":"愛蜜莉雅","effectText":"【登場時】若在這個回合中自己使用了事件卡時，抽1張卡片。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA40BT/REZ-1-019":{"name":"雷姆","effectText":"【突襲】〈雷姆〉置為活動，並可移動至前線\n【登場時】使最多1張自己手牌中能源需求3以下消耗AP1的黃色〔〈拉姆〉或〈雷姆〉〕以休息狀態在自己場上登場。\n【啟動主要】【若在前線時】【每回合1】選擇最多1張自己場上的〈拉姆〉或其他〈雷姆〉，在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-025":{"name":"愛蜜莉雅","effectText":"【登場時】查看3張自己卡組上面的卡片。將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-029":{"name":"E.M.T. (愛蜜莉雅真是天使)","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40BT/REZ-1-031":{"name":"鬼族之力","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈雷姆〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-030":{"name":"鬼族姊妹","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40BT/REZ-1-032":{"name":"終焉的獸","effectText":"選擇最多1張自己場上的〈帕克〉，在『這個回合中』，使其BP+2000並獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。若自己場外有6張以上其他的事件卡時，則替換成『直到下一個我方回合開始前』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-034":{"name":"威爾海姆・范・阿斯特雷亞","effectText":"【登場時】若在我方回合中，可支付1AP。若有執行此動作時，選擇最多1張對手前線BP4500以上的角色卡，使其退場。\n【啟動主要】【每回合1】公開1張自己的手牌，並放置在自己卡組的下面。若公開的卡片為BP4000以上的角色卡時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-036":{"name":"特蕾西亞・范・阿斯特雷亞","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-035":{"name":"奧托・蘇文","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-037":{"name":"菜月昴","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA40BT/REZ-1-038":{"name":"菜月昴","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-040":{"name":"菜月昴","effectText":"【突襲】〈菜月昴〉置為活動，並可移動至前線\n【登場時】抽1張卡片。\n【退場時】將這張角色卡的突襲來源卡片最多1張以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-033":{"name":"精靈術師","effectText":"選擇1張對手前線BP5000以下的角色卡，『轉為休息』。若自己場上有〈愛蜜莉雅〉時，則替換成『使其退場』。之後，若自己場上有〈愛蜜莉雅〉與〈帕克〉時，查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-041":{"name":"帕特拉修","effectText":"【我方回合中】若自己前線有能源需求0的藍色〈菜月昴〉時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-039":{"name":"菜月昴","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-043":{"name":"菲利斯","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA40BT/REZ-1-046":{"name":"由里烏斯・尤克歷烏斯","effectText":"【登場時】可以將1張自己場上能源需求0的藍色〈菜月昴〉放回手牌。若有執行此動作時，將這張角色卡置為活動，並在這個回合中，BP+1000。","triggerText":""},"UA40BT/REZ-1-044":{"name":"菲利斯","effectText":"【突襲】〈菲莉絲〉置為活動，並可移動至前線\n【登場時】公開最多1張自己的手牌，並放置在自己卡組的下面。若公開的卡片為角色卡時，從自己場外，將1張〈菲莉絲〉以外消耗AP為1且BP在公開的卡片BP以下的藍色角色卡加入手牌，或以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-047":{"name":"里卡多・威尔金","effectText":"【啟動主要】【支付1AP】僅限這張卡片在自己手牌中，且滿足能源需求時可以發動。公開這張卡片，若BP在4000以上時，將這張卡片以休息狀態在自己場上登場，並選擇最多1張自己場上其他的角色卡，置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-048":{"name":"雷姆","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-049":{"name":"雷姆","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈菜月昴〉或〈雷姆〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-050":{"name":"雷姆","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA40BT/REZ-1-045":{"name":"蜜蜜・帕爾巴頓","effectText":"【啟動主要】【每回合1】公開1張自己的手牌，並放置在自己卡組的下面。若公開的卡片為BP4000以上的角色卡時，這張角色卡在這個回合中，BP+2500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-052":{"name":"雷姆","effectText":"【登場時】從以下選擇1項。\n・使最多1張自己場外能源需求0的藍色〈菜月昴〉以活動狀態在自己場上登場。\n・可以將1張自己場上的角色卡放回手牌。若有執行此動作時，使這張角色卡置為活動，並使最多1張自己場外滿足能源需求且消耗AP1的藍色〈菜月昴〉以休息狀態在自己場上登場，或發動突襲。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-051":{"name":"雷姆","effectText":"【突襲】〈雷姆〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線『BP1000』以下的角色卡，使其退場。每有1張自己場上能源需求0的藍色〈菜月昴〉，這個效果可選擇的角色卡BP範圍+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-054":{"name":"安娜塔西亞・合辛","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA40BT/REZ-1-053":{"name":"雷姆","effectText":"【突襲】〈雷姆〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】使最多1張自己場外能源需求0的藍色〈菜月昴〉以休息狀態在自己場上登場。\n【攻擊時】選擇最多1張自己場上能源需求0的藍色〈菜月昴〉，在這個回合中，該卡片獲得「不會被BP4000以上的角色卡防禦。」","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-055":{"name":"庫珥修・卡爾斯騰","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-057":{"name":"庫珥修・卡爾斯滕","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈庫珥修・卡爾斯滕〉或〈菲莉絲〉或〈威爾海姆・梵・阿斯特雷亞〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA40BT/REZ-1-056":{"name":"庫珥修・卡爾斯滕","effectText":"【登場時】抽1張卡片。","triggerText":""},"UA40BT/REZ-1-058":{"name":"庫珥修・卡爾斯滕","effectText":"【突襲】〈庫珥修・卡爾斯滕〉置為活動，並可移動至前線\n【若在前線時】因自己的效果參照自己手牌中角色卡的BP時，可視為其BP+1000。\n【登場時】查看2張自己卡組上面的卡片。將其中1張卡片加入手牌，其餘卡片放置在場外。\n【啟動主要】【若在前線時】【每回合1】選擇最多1張自己或對手場上的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-060":{"name":"普魯蓋爾大樹","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】公開1張自己的手牌，並放置在自己卡組下面。若公開的卡片為角色卡時，選擇最多1張對手前線BP為公開卡片BP以下的角色卡，使其退場。〈弗琉蓋爾的大樹〉的這個效果每回合只能發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-059":{"name":"普莉希拉・跋利耶爾","effectText":"若對手場上有黃色或紫色卡片時，手牌中這張卡片的能源需求減少【藍×1】。","triggerText":""},"UA40BT/REZ-1-061":{"name":"從一開始……不，是從零開始！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40BT/REZ-1-062":{"name":"我拿到你的證詞了！","effectText":"選擇1張自己場上的〈雷姆〉，在這個回合中，獲得其BP+1000與【衝擊（+1）】（衝擊造成的傷害+1，若未持有衝擊，則獲得【衝擊（1）】），並抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-064":{"name":"全員，跟上那群笨蛋！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40BT/REZ-1-065":{"name":"區區一個怪物——！","effectText":"因自己的效果從自己手牌中公開的這張卡片，也可視為原本BP為4000的角色卡。\n選擇1張對手前線BP4500以上的角色卡，使其退場。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-067":{"name":"加菲爾・汀澤爾","effectText":"這張角色卡以活動狀態登場。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-2500。\n【啟動主要】【若在前線時】【每回合1】將這張角色卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-066":{"name":"百人一太刀","effectText":"這張卡片僅限自己場上有〈庫珥修・卡爾斯滕〉時才能使用。選擇1張對手前線BP5000以下的角色卡，使其退場。在這個回合中，因自己的效果參照自己手牌中角色卡的BP時，可視為其BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-063":{"name":"嗅聞昴君的味道，是雷姆的特權——！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈雷姆〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-069":{"name":"菜月昴","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈菜月昴〉或〈碧翠絲〉或〈禁書庫〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA40BT/REZ-1-068":{"name":"菜月昴","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-070":{"name":"菜月昴","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在自己卡組的上面或場外。\n・可支付1AP。若有執行此動作時，公開1張自己卡組上面的卡片，並『將該張卡片加入手牌』。若公開的卡片為滿足能源需求的〈碧翠絲〉時，可替換成『以休息狀態在自己場上登場或發動突襲』。","triggerText":""},"UA40BT/REZ-1-071":{"name":"菜月昴","effectText":"【突襲】〈菜月昴〉置為活動，並可移動至前線\n【登場時】查看2張自己卡組上面的卡片。將其中最多1張卡片放置在場外。其餘卡片依任意順序放置在自己卡組的上面。抽1張卡片。\n【攻擊時】【每回合1】可支付1AP。若有執行此動作時，公開1張自己卡組上面的卡片，並『將該張卡片加入手牌』。若公開的卡片為滿足能源需求的〈碧翠絲〉時，可替換成『以休息狀態在自己場上登場或發動突襲』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-072":{"name":"碧翠絲","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-073":{"name":"碧翠絲","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-075":{"name":"碧翠絲","effectText":"【登場時】若這張角色卡是因自己的效果而登場技能，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-076":{"name":"碧翠絲","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【啟動主要】【若在前線時】【每回合1】將1張自己的手牌放置在自己卡組的上面。若有執行此動作時，這張角色卡在這個回合中，BP+1000。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA40BT/REZ-1-077":{"name":"碧翠絲","effectText":"【突襲】〈碧翠絲〉置為活動，並可移動至前線\n【我方回合中】若自己場上有〈菜月昴〉時，這張角色卡BP+500。\n【登場時】選擇最多1張對手前線的角色卡，移動至能源線。若這張角色卡是以自己的效果登場技能，則選擇的角色卡直到下一個我方回合開始為止，無法移動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-074":{"name":"碧翠絲","effectText":"【登場時】選擇最多1張自己場上的〈菜月昴〉。直到下一個我方回合開始前，若該角色卡因放回手牌效果以外的對手效果而離場時，則改為放回手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-078":{"name":"碧翠絲","effectText":"【突襲】〈碧翠絲〉置為活動，並可移動至前線\n若自己場上有〈菜月昴〉時，這張角色卡獲得【衝擊（1）】。\n【登場時】選擇最多1張自己場上的〈菜月昴〉，置為活動。若這張角色卡是以自己的效果登場技能，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-079":{"name":"拉姆","effectText":"若對手場上有黃色或藍色卡片時，手牌中這張卡片的能源需求減少【紫×1】。","triggerText":""},"UA40BT/REZ-1-081":{"name":"愛蜜莉雅","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-083":{"name":"愛蜜莉雅","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-082":{"name":"愛蜜莉雅","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA40BT/REZ-1-084":{"name":"愛蜜莉雅","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-086":{"name":"愛蜜莉雅","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA40BT/REZ-1-087":{"name":"愛蜜莉雅","effectText":"【我方回合中】這張角色卡BP+1000。\n【登場時】可以將1張自己場外的〈”聖域”的”試煉”〉放置在移除區。若有執行此動作時，使這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-088":{"name":"愛蜜莉雅","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡在這回合中曾因自己的效果從活動轉為休息時才可發動。使這張角色卡置為活動，這張角色卡直到下一個我方回合開始前，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA40BT/REZ-1-089":{"name":"愛蜜莉雅","effectText":"【突襲】〈愛蜜莉雅〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\nBP2000以下的角色卡不能防禦這張角色卡。\n這張角色卡攻擊後沒有被防禦時，選擇最多1張對手前線的角色卡，轉為休息。\n【啟動主要】【若在能源線時】【每回合1】選擇1張自己前線的角色卡，可以與這張角色卡互相交換位置。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-091":{"name":"艾姬多娜","effectText":"【登場時】查看7張自己卡組上面的卡片。公開其中最多1張〈”聖域”的”試煉”〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA40BT/REZ-1-090":{"name":"愛蜜莉雅","effectText":"【突襲】〈愛蜜莉雅〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-3500。\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為休息狀態時才可發動。選擇最多1張對手前線BP1500以下的角色卡，使其退場。使這張角色卡置為活動，並在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-092":{"name":"艾姬多娜","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-094":{"name":"禁書庫","effectText":"【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，將這張場域卡置為活動。\n【啟動主要】【轉為休息】【每回合1】抽1張卡片，並將1張自己的手牌放置在自己卡組的上面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA40BT/REZ-1-093":{"name":"艾姬多娜","effectText":"【突襲】〈艾姬多娜〉置為活動，並可移動至前線\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【每回合1】將1張自己前線的活動角色卡轉為休息。若有執行此動作時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA40BT/REZ-1-096":{"name":"艾爾・米娜","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈碧翠絲〉時，則替換成『BP4000以下』。若自己場上有〈碧翠絲〉與〈菜月昴〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-095":{"name":"我愛你，貝子！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA40BT/REZ-1-080":{"name":"拉姆","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA40BT/REZ-1-097":{"name":"選擇我吧！碧翠絲！","effectText":"查看3張自己卡組上面的卡片。將其中任意張數以任意順序放置在自己卡組的上面，其餘卡片放置在場外。之後，公開1張自己卡組上面的卡片並『加入手牌』。若公開的卡片為滿足能源需求的〔〈菜月昴〉或〈碧翠絲〉〕時，可替換成『以休息狀態在自己場上登場，或發動突襲』。","triggerText":"[抽卡] 抽1張卡片。"},"UA40BT/REZ-1-098":{"name":"”聖域”的”試煉”","effectText":"抽2張卡片，並將1張自己的手牌放置在場外。之後，可以將1張自己前線的活動角色卡轉為休息。若有執行此動作時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA40BT/REZ-1-099":{"name":"兩個人，我都最喜歡了","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX17BT/REZ-2-001":{"name":"帕克","effectText":"這張卡片在所有區域也視為事件卡。\n【啟動主要】【若在能源線時】【轉為休息】【使這張卡片退場】從自己場外，使最多1張能源需求0的黃色〈愛蜜莉雅〉以休息狀態在自己能源線登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-002":{"name":"法蘭黛莉卡・鮑曼","effectText":"【登場時】【若在能源線時】若自己在這個回合中使用了事件卡，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA40BT/REZ-1-100":{"name":"我不會再讓你逃走了！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈愛蜜莉雅〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-042":{"name":"菲利斯","effectText":"【登場時】選擇最多1張自己或對手場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-003":{"name":"佩特拉・萊特","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・從自己場外，將最多1張黃色〈菜月昴〉加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-005":{"name":"拉姆","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若自己場上有〈雷姆〉或〈羅茲瓦爾・L・梅札斯〉時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-004":{"name":"拉姆","effectText":"【我方回合中】若對手前線有BP比原本BP還低的角色卡時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-006":{"name":"拉姆","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【攻擊時】若對手前線有BP比原本BP還低的角色卡時，從以下選擇1項。\n・抽1張卡片。\n・這張角色卡在這個回合中，BP+1000。","triggerText":""},"EX17BT/REZ-2-007":{"name":"雷姆","effectText":"當這張角色卡被突襲時，若自己場上的角色卡全部為〈雷姆〉時，抽1張卡片。（發動突襲的角色卡的【登場時】與這個效果可以依任意順序處理）","triggerText":""},"EX17BT/REZ-2-008":{"name":"雷姆","effectText":"【登場時】『抽1張卡片，並將1張自己的手牌放置在場外』。若對手前線有BP比原本BP還低的角色卡時，可替換成『抽1張卡片』。","triggerText":""},"EX17BT/REZ-2-010":{"name":"雷姆","effectText":"【登場時】若自己場上的角色卡全部為〈雷姆〉時，可將自己場上1張能源需求3以下的角色卡放回手牌。若如此，在這個回合中，下一張從手牌中使用的不持有【突襲】的〈雷姆〉消耗AP-1。〈雷姆〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX17BT/REZ-2-009":{"name":"雷姆","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【登場時】查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-011":{"name":"愛蜜莉雅","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】在這個回合中，下一張從手牌中使用能源需求『1』以下的事件卡的消耗AP-1。自己場外每有2張事件卡，以此效果消耗AP-1的事件卡的能源需求範圍+1。〈愛蜜莉雅〉的這個效果每回合僅發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-012":{"name":"我的名字是愛蜜莉雅。就只是愛蜜莉雅。","effectText":"這張卡片僅限自己場上有〈愛蜜莉雅〉時才能使用。\n若自己場外有4張以上事件卡時，手牌中這張卡片的能源需求減少【黃×1】。\n抽2張卡片。從自己手牌中，使最多1張能源需求3以下消耗AP1的黃色〈菜月昴〉以活動狀態在自己場上登場。選擇最多1張自己場上的〈菜月昴〉，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX17BT/REZ-2-014":{"name":"菜月昴","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-013":{"name":"威爾海姆・范・阿斯特雷亞","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】僅限自己場上有〈庫珥修・卡爾斯滕〉時可發動。若對手前線有BP4500以上的角色卡，或這張角色卡的BP在5000以上時，將這張角色卡置為活動。〈威爾海姆・范・阿斯特雷亞〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-1-029":{"name":"UNION ARENA｜UNIONARENA","effectText":"選擇關鍵字效果\n不指定\n突襲\n雙重攻擊\n雙重防禦\n衝擊（1）\n衝擊（2）\n衝擊（3）\n衝擊（4）\n衝擊（+1）\n衝擊（+3）\n衝擊無效\n階梯\n傷害（2）\n傷害（3）\n傷害（7）\n傷害（+1）\n狙擊","triggerText":"取消設定\n有\n無\n選擇觸發效果種類\n不指定\n獲得\n顏色\n抽卡\n活動\n突襲\n最終\n特別"},"EX17BT/REZ-2-017":{"name":"雷姆","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張〈菜月昴〉或〈雷姆〉放置在場外，其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-015":{"name":"菲莉絲","effectText":"【攻擊時】若自己場上有〈庫珥修・卡爾斯滕〉，且這張角色卡的BP在4000以上時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-016":{"name":"菲莉絲","effectText":"【登場時】【若在能源線時】若自己場上有〈庫珥修・卡爾斯滕〉時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】從以下選擇1項。\n・選擇1張自己或對手場上其他的角色卡，在這個回合中，BP+1000。\n・公開1張自己的手牌，並放置在自己卡組的下面。若有執行此動作時，選擇最多1張自己或對手場上其他的角色卡，在這個回合中，BP+2000。若公開的卡片為BP4000以上的角色卡時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-018":{"name":"雷姆","effectText":"【登場時】從以下選擇1項。在這個回合中〈雷姆〉已選擇的效果無法選擇。\n・從自己場外，使最多1張能源需求0的藍色〈菜月昴〉以休息狀態在自己場上登場。使該角色卡在這個回合中，獲得「主要階段結束時，使這張角色卡退場。」。\n・選擇最多1張自己場上能源需求0的藍色〈菜月昴〉，在這個回合中，使所選角色卡獲得「【每回合1】當這張角色卡攻擊後在對戰中敗北時，將這張角色卡置為活動。」。","triggerText":""},"EX17BT/REZ-2-019":{"name":"庫珥修・卡爾斯滕","effectText":"【啟動主要】【每回合1】僅限這張角色卡的BP在5000以上時可發動。這張角色卡直到下一個我方回合開始前，獲得【雙重防禦】與【衝擊無效】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-022":{"name":"菜月昴","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張〈菜月昴〉或〈碧翠絲〉或〈禁書庫〉放置在場外，其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-021":{"name":"菜月昴的侍從 雷姆","effectText":"這張卡片僅限自己場上有〈菜月昴〉與〈雷姆〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。若自己前線有突襲狀態的〈雷姆〉時，選擇最多1張自己場上能源需求0的〈菜月昴〉，在這個回合中，BP+1500。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA40BT/REZ-1-085":{"name":"愛蜜莉雅","effectText":"【啟動主要】【若在前線時】【每回合1】僅限在這個回合中，這張角色卡曾因自己的效果從活動轉為休息時可發動。在這個回合中，下一張從手牌中使用〈愛蜜莉雅〉的能源需求減少【紫×1】。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-023":{"name":"福爾圖娜","effectText":"【登場時】將這張角色卡置為活動。這張角色卡在這個回合中，獲得「這張角色卡無法攻擊。」。\n【退場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外使最多1張能源需求0的紫色〈愛蜜莉雅〉以休息狀態在自己能源線登場。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-027":{"name":"愛蜜莉雅","effectText":"【啟動主要】【若在前線時】【每回合1】僅限在這個回合中，這張角色卡曾因自己的效果從活動轉為休息時可發動。將這張角色卡置為活動。","triggerText":""},"EX17BT/REZ-2-025":{"name":"碧翠絲","effectText":"【登場時】自己在這個回合中，獲得「對手以效果選擇自己場上的〈菜月昴〉時，對手必須追加將1張自己的手牌放置在場外才可以選擇。」。從以下選擇1項。\n・若自己場上有〈菜月昴〉時，抽1張卡片。\n・在這個回合的攻擊階段開始時，將1張自己的AP卡置為活動。","triggerText":""},"EX17BT/REZ-2-024":{"name":"碧翠絲","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【啟動主要】【支付1AP】【每回合1】將1張自己的手牌放置在自己卡組的上面。若有執行此動作時，這張角色卡在這個回合中，BP+2000，且在這個回合的攻擊階段開始時，將1張自己的AP卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-020":{"name":"庫珥修・卡爾斯滕","effectText":"當這張卡片因自己的效果而從自己的手牌公開並放置在卡組下面時，選擇最多1張自己或對手場上的角色卡，在這個回合中，BP+1000。\n這張角色卡無法在前線〔登場・移動〕。\n當這張角色卡被突襲時，抽1張卡片。（發動突襲的角色卡的【登場時】與這個效果可以依任意順序處理）","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX17BT/REZ-2-026":{"name":"琉茲・梅耶爾","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】僅限自己場上有〈艾姬多娜〉或〈碧翠絲〉時可發動。從自己場外將最多1張不持有【特殊觸發】與【最終觸發】且能源需求3以下的紫色事件卡加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-028":{"name":"愛蜜莉雅","effectText":"【登場時】若自己場上有［特徵：魔女］時，抽1張卡片。\n【啟動主要】【將1張手牌放置在場外】【每回合1】這張角色卡在這個回合中，產生能源+【紫】。","triggerText":""},"EX17BT/REZ-2-031":{"name":"魔晶石","effectText":"抽1張卡片。從自己場外將最多1張〈碧翠絲〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-030":{"name":"艾姬多娜","effectText":"【登場時】選擇最多1張自己場上具有特徵的角色卡，在這個回合中，獲得「這張角色卡無法攻擊。」，並使其移動至另一條線。\n【啟動主要】【每回合1】僅限在這張角色卡登場的回合中可發動。將1張自己前線的活動角色卡轉為休息。若有執行此動作時，從以下選擇1項。\n・選擇最多1張對手前線BP2000以上的角色卡，在這個回合中，BP-1500。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-032":{"name":"阿爾","effectText":"若這張角色卡下面有背面朝上卡片時，這張角色卡獲得BP+500、【衝擊無效】與「BP500以上的這張角色卡將退場時，改為將1張這張角色卡下面的背面朝上卡片放置在場外。」。\n【登場時】若自己場上有〈普莉希拉・跋利耶爾〉時，可使1張〔〈普莉希拉・跋利耶爾〉與〈阿爾〉〕以外自己場上其他的角色卡退場。若有執行此動作時，將退場的卡片背面朝上放置在這張角色卡下面，並將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX17BT/REZ-2-034":{"name":"加菲爾・汀澤爾","effectText":"這張角色卡攻擊後戰勝時，若自己場上有4種以上不同卡片名稱的綠色角色卡時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-033":{"name":"奧托・蘇文","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【綠】。","triggerText":""},"EX17BT/REZ-2-036":{"name":"奇利塔卡・謬茲","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的〈莉莉安娜・瑪斯柯瑞德〉，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-035":{"name":"加菲爾・汀澤爾","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-037":{"name":"修爾特","effectText":"【登場時】選擇最多『1張』自己場上其他的角色卡，在這個回合中，BP+500。若自己場上有〈普莉希拉・跋利耶爾〉時，可替換成『2張』。","triggerText":""},"EX17BT/REZ-2-039":{"name":"菜月昴","effectText":"發動這張卡片的【顏色觸發】時，可將效果所記載的「能源需求2以下」改為「原始BP2500」。\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】從自己場外，使最多1張〈菜月昴〉以外原始BP2500的綠色角色卡以休息狀態在自己場上登場，並將該角色卡或這張角色卡置為活動。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX17BT/REZ-2-029":{"name":"艾姬多娜","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或下面，並抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-040":{"name":"海因格・阿斯特雷亞","effectText":"【退場時】選擇最多1張對手前線BP4500以上的角色卡，轉為休息。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-042":{"name":"碧翠絲","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":""},"EX17BT/REZ-2-041":{"name":"184號","effectText":"這張卡片也視為〈席爾菲〉。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-045":{"name":"約書亞・尤克歷烏斯","effectText":"【退場時】若自己場上有〈安娜塔西亞・合辛〉或4種以上不同卡片名稱的其他綠色角色卡時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-046":{"name":"萊因哈魯特・范・阿斯特雷亞","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-047":{"name":"萊因哈魯特・范・阿斯特雷亞","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【啟動主要】【若在前線時】【每回合1】抽1張卡片。\n【啟動主要】【若在前線時】可將1張自己手牌中的綠色卡片放置在場外，並發動該卡片的【觸發】。〈萊因哈魯特・范・阿斯特雷亞〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX17BT/REZ-2-043":{"name":"蜜蜜・帕爾巴頓","effectText":"【我方回合中】若自己場上有〈安娜塔西亞・合辛〉或4種以上不同卡片名稱的綠色角色卡時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-048":{"name":"莉亞拉・湯普森","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"EX17BT/REZ-2-050":{"name":"莉莉安娜・瑪斯柯瑞德","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"EX17BT/REZ-2-051":{"name":"莉莉安娜・瑪斯柯瑞德","effectText":"若自己場上有4種以上不同卡片名稱的綠色角色卡時，這張角色卡的產生能源+【綠】。\n【啟動主要】【若在能源線時】【每回合1】僅限自己場上有6種以上不同卡片名稱的綠色角色卡時可發動。將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+500。","triggerText":""},"EX17BT/REZ-2-052":{"name":"路斯貝爾＆緹娜","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"EX17BT/REZ-2-054":{"name":"安娜塔西亞・合辛","effectText":"【登場時】從以下選擇1項。\n・查看等同於自己場上不同卡片名稱的綠色角色卡種類數的自己卡組上面的卡片，公開其中最多1張能源需求5以下的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n・選擇最多2張自己場上其他的角色卡，在這個回合中，BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-049":{"name":"里卡多・威爾金","effectText":"【我方回合中】若自己場上有〈安娜塔西亞・合辛〉或4種以上不同卡片名稱的綠色角色卡時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-055":{"name":"愛蜜莉雅","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-044":{"name":"由里烏斯・尤克歷烏斯","effectText":"【啟動主要】【每回合1】僅限自己場上有〈安娜塔西亞・合辛〉或4種以上不同卡片名稱的綠色角色卡時可發動。這張角色卡在這個回合中，獲得以下1項。\n・【攻擊時】抽1張卡片。\n・BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-038":{"name":"菜月昴","effectText":"【登場時】從自己手牌中，使最多1張能源需求3以下消耗AP1的綠色角色卡以休息狀態在自己場上登場。無法以此效果使自己場上已有的同名卡片登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-056":{"name":"愛蜜莉雅","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"EX17BT/REZ-2-059":{"name":"庫珥修・卡爾斯滕","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-058":{"name":"愛蜜莉雅","effectText":"【突襲】〈愛蜜莉雅〉置為活動，並可移動至前線\n這張角色卡的攻擊結束時，可將1張自己前線原始BP2500的活動角色卡轉為休息。若有執行此動作時，將這張角色卡置為活動。\n【登場時】這張角色卡在這個回合中，獲得【雙重攻擊】與「這張角色卡不會被對手的效果選擇。」。\n【攻擊時】【每回合1】這張角色卡在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX17BT/REZ-2-057":{"name":"愛蜜莉雅","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈愛蜜莉雅〉或〈水門都市 普利斯提拉〉或原始BP2500的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-060":{"name":"菲魯特","effectText":"【對方回合中】這張角色卡BP-1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-065":{"name":"普莉希拉・跋利耶爾","effectText":"【突襲】〈普莉希拉・跋利耶爾〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+1000。\n【啟動主要】【每回合1】根據自己場上BP比原本BP還高的角色卡張數，這張角色卡在這個回合中，獲得以下所有效果。\n・3張以上：【傷害（2）】\n・5張以上：【衝擊（1）】\n【攻擊時】抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX17BT/REZ-2-064":{"name":"普莉希拉・跋利耶爾","effectText":"【登場時】查看自己卡組上面的『2張』卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。若自己場上有4種以上不同卡片名稱的綠色角色卡時，則替換成『4張』。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"EX17BT/REZ-2-063":{"name":"普莉希拉・跋利耶爾","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"EX17BT/REZ-2-068":{"name":"歐呀！歐呀！歐呀啊！","effectText":"選擇1張自己場上的〈愛蜜莉雅〉，在這個回合中，獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。","triggerText":""},"EX17BT/REZ-2-053":{"name":"雷姆","effectText":"這張卡片無法在前線〔登場・移動〕。\n【啟動主要】【每回合1】僅限在這個回合中自己場上有〈菜月昴〉登場時可發動。將1張自己的手牌放置在場外。若有執行此動作時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-067":{"name":"「我相信你」","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX17BT/REZ-2-066":{"name":"水門都市 普利斯提拉","effectText":"【登場時】抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-062":{"name":"菲魯特","effectText":"【突襲】〈菲魯特〉置為活動，並可移動至前線\n【登場時】抽1張卡片，或選擇最多1張自己場上其他的角色卡，置為活動。\n【啟動主要】【若在前線時】【每回合1】從以下選擇1項。\n・這張角色卡直到下一個我方回合開始前，獲得BP+1000與「這張角色卡不會被BP4000以上的角色卡防禦。」。\n・選擇1張自己場上其他的角色卡，在這個回合中，獲得「這張角色卡若在前線時也可產生能源。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"EX17BT/REZ-2-061":{"name":"菲魯特","effectText":"【登場時】選擇最多1張自己場上原始BP2500的角色卡，在這個回合中，BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-068":{"name":"神谷薰","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"EX17BT/REZ-2-071":{"name":"靈光一閃!!","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"EX17BT/REZ-2-073":{"name":"『龍劍』雷德","effectText":"選擇1張對手前線的角色卡，使其退場。\n當這張卡片因自己場上綠色〈萊因哈魯特・范・阿斯特雷亞〉的效果而從自己的手牌放置在場外時，選擇最多1張自己場上的〈萊因哈魯特・范・阿斯特雷亞〉，置為活動。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"EX17BT/REZ-2-070":{"name":"華麗老虎","effectText":"選擇1張自己場上的〈加菲爾・汀澤爾〉，在這個回合中，獲得BP+3000與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-078":{"name":"三條燕","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA41ST/RNK-1-070":{"name":"神谷薰","effectText":"【登場時】【若在能源線時】可以將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-069":{"name":"我的名字是菜月昴――","effectText":"從以下選擇1項。\n・從自己場外，使最多1張原始BP2500且消耗AP2的綠色角色卡以休息狀態在自己場上登場。\n・從自己場外，使最多2張原始BP2500且消耗AP1的綠色角色卡以休息狀態在自己場上登場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41ST/RNK-1-074":{"name":"相樂左之助","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41ST/RNK-1-096":{"name":"不殺之誓","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41ST/RNK-1-081":{"name":"高荷惠","effectText":"此角色為活動狀態時，此角色產生能源+【紅】。","triggerText":""},"UA41ST/RNK-1-085":{"name":"緋村劍心","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。（移動時若能源線沒有空格，對手需選擇1張能源線的卡片放置在移除區後再進行移動）","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41ST/RNK-1-103":{"name":"相樂左之助","effectText":"這張角色卡以活動狀態在場上登場。\n【若在前線時】【每回合1】當活動狀態的這張角色卡因自己或對手的效果而轉為休息時，將這張角色卡置為活動。\n【登場時】這張角色卡在這個回合中，獲得「對手必須盡可能防禦這張角色卡的攻擊。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"EX17BT/REZ-2-072":{"name":"『陽劍』","effectText":"這張卡片僅限自己場上有〈普莉希拉・跋利耶爾〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。若自己場上有4張以上BP比原本BP還高的角色卡時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41ST/RNK-1-101":{"name":"神谷薰","effectText":"自己的攻擊階段結束時，若在這個回合中對手的角色卡沒有退場，可將活動狀態的這張角色卡轉為休息。若有執行此動作時，抽1張卡片。〈神谷薰〉的這個效果每回合僅能發動1次。\n【登場時】【若在能源線時】可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-102":{"name":"齋藤一","effectText":"【攻擊時】可將1張自己前線活動狀態的角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-080":{"name":"高荷惠","effectText":"【登場時】選擇最多1張我方場上的其他角色，此回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-100":{"name":"龍槌閃","effectText":"選擇最多1張對手前線BP5000以下的角色卡，『使其移動至能源線』。若自己場上有〈緋村劍心〉時，可替換成『放置在對手卡組下面』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41ST/RNK-1-104":{"name":"關原妙＆三條燕","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41ST/RNK-1-105":{"name":"緋村劍心","effectText":"【我方回合中】這張角色卡BP-1000。\n【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-106":{"name":"緋村劍心","effectText":"選擇1張對手前線的角色卡，轉為休息。\n當這張卡片因自己場上紅色的〈緋村劍心〉的效果而從自己手牌放置在場外時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41ST/RNK-1-109":{"name":"逆刃刀","effectText":"抽1張卡片。選擇最多1張自己場上的〈緋村劍心〉，在這個回合中，獲得「【攻擊時】抽1張卡片。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-107":{"name":"明神彌彥","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA41ST/RNK-1-111":{"name":"比古清十郎","effectText":"這張卡片無法在前線登場，且無法透過此卡片效果以外的方式移動至前線。\n【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片以任意順序放置在自己卡組上面，其餘卡片放置在場外。\n【啟動主要】【將2張手牌放置在場外】【每回合1】僅在自己場上有〈緋村劍心〉時可發動。將這張角色卡移動至另一線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41ST/RNK-1-108":{"name":"神谷道場","effectText":"【啟動主要】【轉為休息】抽1張卡片，將自己1張手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41ST/RNK-1-113":{"name":"齋藤一","effectText":"【攻擊時】可抽1張卡片。若有執行此動作時，這張角色卡下一次無法置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-112":{"name":"志志雄真實","effectText":"【登場時】將1張自己的手牌放置在自己卡組上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-002":{"name":"心太","effectText":"這張卡片也視為〈緋村劍心〉。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-001":{"name":"新井青空","effectText":"【登場時】查看7張自己卡組上面的卡片。公開其中最多1張〈逆刃刀・真打〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA41ST/RNK-1-110":{"name":"四乃森蒼紫","effectText":"【突襲】〈四乃森蒼紫〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：御庭番眾］的卡片或卡片名稱包含「回天劍舞」的事件卡，並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-004":{"name":"高荷惠","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA41BT/RNK-1-005":{"name":"武田觀柳","effectText":"【登場時】選擇以下其中1項。\n・選擇最多1張對手前線BP2000以下的角色卡，使其退場。\n・可使1張自己場上［特徵：御庭番眾］的卡片退場。若有執行此動作時，抽1張卡片，並選擇最多1張對手前線BP4000以下的角色卡，使其退場。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-007":{"name":"比古清十郎","effectText":"【我方回合中】在這個回合中若自己使用了〈九頭龍閃〉或〈求生意志〉時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-008":{"name":"比古清十郎","effectText":"【突襲】〈比古清十郎〉置為活動，並可移動至前線\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\nBP2000以下的角色卡不能防禦這張角色卡。\n【我方回合中】這張角色卡BP+3000。\n【登場時】將最多1張自己場外的事件卡加入手牌。\n【啟動主要】【每回合1】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-010":{"name":"緋村劍心","effectText":"【啟動主要】【若在能源線時】【每回合1】將1張自己場外的〈求生意志〉放置在自己卡組下面。若有執行此動作時，將這張角色卡移動至前線，這張角色卡在這個回合中，BP+1000。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA41BT/RNK-1-009":{"name":"緋村劍心","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】查看2張自己卡組上面的卡片。將其中任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。","triggerText":""},"UA41BT/RNK-1-011":{"name":"緋村劍心","effectText":"【突襲】〈緋村劍心〉置為活動，並可移動至前線\n若這張角色卡的BP在6000以上時，這張角色卡獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。\n【啟動主要】【每回合1】若在這個回合中自己已使用〈生存的意志〉，則在這個回合中，這張角色卡BP+1000。\n【攻擊時】若自己的手牌在3張以下時，抽最多1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-013":{"name":"式尉","effectText":"【我方回合中】【若在前線時】自己場上的〈四乃森蒼紫〉因對手的效果將離場時，可改為將活動狀態的這張角色卡退場。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-015":{"name":"四乃森蒼紫","effectText":"【我方回合中】這張角色卡BP+1000。","triggerText":""},"UA41BT/RNK-1-014":{"name":"四乃森蒼紫","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-017":{"name":"四乃森蒼紫","effectText":"【登場時】可將1張自己前線活動狀態的其他［特徵：御庭番眾］轉為休息。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-012":{"name":"柏崎念至","effectText":"若對手場上有紫色或紅色卡片時，手牌中這張卡片的能源需求減少【藍×1】。","triggerText":""},"UA41BT/RNK-1-019":{"name":"般若","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】在這個回合中，這張角色卡BP+1000。\n【退場時】可以將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求2以下的藍色〈四乃森蒼紫〉以休息狀態在自己場上登場。","triggerText":""},"UA41BT/RNK-1-016":{"name":"四乃森蒼紫","effectText":"【登場時】若這張角色卡是因自己的角色卡效果或事件卡效果登場時，抽1張卡片。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA41BT/RNK-1-018":{"name":"四乃森蒼紫","effectText":"【突襲】〈四乃森蒼紫〉置為活動，並可移動至前線\n【登場時】在這個回合中，這張角色卡BP+1000。\n【啟動主要】使這張角色卡的突襲來源卡以活動狀態在自己場上登場，並使該角色卡在這個回合中，獲得「這張角色卡無法攻擊。」與「自己的攻擊階段結束時，若這張角色卡為活動時，使其退場。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-020":{"name":"火男","effectText":"【退場時】若自己場上有〈四乃森蒼紫〉時，抽1張卡片。","triggerText":""},"UA41BT/RNK-1-023":{"name":"卷町操","effectText":"此角色為活動狀態時，此角色的產生能源+【藍】。","triggerText":""},"UA41BT/RNK-1-022":{"name":"卷町操","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-021":{"name":"癋見","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈高荷惠〉或［特徵：御庭番眾］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-024":{"name":"卷町操","effectText":"【登場時】選擇以下1項。\n・在這張回合中，這張角色卡的產生能源+【藍】。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。將這張卡片放回手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-025":{"name":"卷町操","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【登場時】查看3張自己卡組上面的卡片。將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-027":{"name":"求生意志","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41BT/RNK-1-028":{"name":"回天劍舞","effectText":"選擇1張對手前線『BP3000』以下的角色卡，使其退場。自己場上每有1張〈四乃森蒼紫〉，此效果可選擇的角色卡BP範圍+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41BT/RNK-1-026":{"name":"修行","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈比古清十郎〉或〈緋村劍心〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若將能源需求4以上的卡片加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-029":{"name":"回天劍舞六連","effectText":"選擇1張自己場上的〈四乃森蒼紫〉，在這個回合中，獲得BP-1000與「這張角色卡攻擊結束時，可將1張自己場上活動狀態的〈四乃森蒼紫〉轉為休息。若有執行此動作時，將這張角色卡置為活動。」。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41BT/RNK-1-031":{"name":"最強的證明","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41BT/RNK-1-032":{"name":"逆刃刀・真打","effectText":"選擇1張自己場上的〈緋村劍心〉，在這個回合中，BP+2000。選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-003":{"name":"高荷惠","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA41BT/RNK-1-030":{"name":"九頭龍閃","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈比古清十郎〉時，則替換成『BP5000以下』，並選擇最多1張自己場上的〈緋村劍心〉，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41BT/RNK-1-035":{"name":"齋藤一","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-034":{"name":"駒形由美","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【退場時】若自己前線有〈志志雄真實〉時，選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-037":{"name":"齋藤一","effectText":"【登場時】選擇最多1張自己場上的〔〈緋村劍心〉或〈齋藤一〉或〈相樂左之助〉〕，移動至別的線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-038":{"name":"齋藤一","effectText":"若自己場上沒有卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【攻擊時】可將1張自己前線的〔〈緋村劍心〉或其他〈齋藤一〉或〈相樂左之助〉〕放回手牌。若有執行此動作時，這張角色卡在這個回合中，BP+1500。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA41BT/RNK-1-039":{"name":"齋藤一","effectText":"【突襲】〈齋藤一〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\nBP2000以下的角色卡不能防禦這張角色卡。\n【登場時】查看5張自己卡組上面的卡片。公開其中最多1張〈緋村劍心〉或〈齋藤一〉或〈相樂左之助〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-033":{"name":"流水的動作","effectText":"使最多1張自己手牌或場外的能源需求2以下消耗AP1的〈四乃森蒼紫〉以活動狀態在自己場上登場，在這個回合中，並該角色卡獲得「這張角色卡無法攻擊。」與「自己攻擊階段結束時，若這張角色卡為活動狀態，使其退場。」的效果。若該卡是從手牌登場時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-036":{"name":"齋藤一","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈緋村劍心〉或〈齋藤一〉或〈相樂左之助〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-006":{"name":"比古清十郎","effectText":"【登場時】選擇最多1張自己場上的〈緋村劍心〉，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-041":{"name":"相樂左之助","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA41BT/RNK-1-042":{"name":"相樂左之助","effectText":"【登場時】可支付1AP。若有執行此動作時，選擇最多1張對手場上的場域卡，使其退場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-040":{"name":"齋藤一","effectText":"【突襲】〈齋藤一〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】若自己場上沒有擁有特徵的卡片時，這張角色卡在這個回合中，獲得以下全數效果。\n・BP+1000與「這張角色卡可以從能源線攻擊。」\n・「這張角色卡從能源線攻擊時，將這張角色卡移動至前線，且這張角色卡在這個回合中，獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。」","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-043":{"name":"志志雄真實","effectText":"若這張角色卡的BP在5000以上時，這張角色卡獲得【衝擊（1）】。\n【啟動主要】【若在前線時】【每回合1】將1張自己卡組上面的卡片放置在場外。在這個回合中，這張角色卡的BP+（以此效果放置在場外的卡片的能源需求數×500）。","triggerText":""},"UA41BT/RNK-1-044":{"name":"志志雄真實","effectText":"在使用這張卡片時，可以將1張自己手牌中的〈志志雄真實〉或〈駒形由美〉或［特徵：十本刀］的卡片放置在場外。若有執行此動作時，使這張角色卡以活動狀態在場上登場。\n【登場時】將1張自己卡組上面的卡片放置在場外，並選擇最多1張對手前線BP為該卡片能源需求數量×1000以下的角色卡，使其退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-045":{"name":"緋村劍心","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中最多1張沒有特徵的紫色卡片放置在場外。將其餘卡片依任意順序放置在自己卡組上面。","triggerText":""},"UA41BT/RNK-1-047":{"name":"緋村劍心","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA41BT/RNK-1-046":{"name":"緋村劍心","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】在這個回合中，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-048":{"name":"緋村劍心","effectText":"使這張角色卡以活動狀態在場上登場。\n【登場時】在這個回合中，接下來從手牌中使用能源需求3以下的〈齋藤一〉時，其消耗AP-1。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-049":{"name":"三島榮次","effectText":"【啟動主要】【轉為休息】【每回合1】此角色在此回合中，獲得產生能源\n+【紫】與「主要階段結束時，此角色退場。」。","triggerText":""},"UA41BT/RNK-1-050":{"name":"魚沼宇水","effectText":"【攻擊時】查看這張角色卡下面的背面朝上卡片，並將其中最多1張加入手牌。\n【防禦時】可以將1張自己前線其他的角色卡退場。若有執行此動作時，將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面，在這個回合中，這張角色卡BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-051":{"name":"刈羽蝙也","effectText":"若對手場上有藍色或紅色卡片時，手牌中這張卡片的能源需求減少【紫×1】。","triggerText":""},"UA41BT/RNK-1-052":{"name":"佐渡島方治","effectText":"若自己場上合計有3張以上〈志志雄真實〉或〈駒形由美〉或其他［特徵：十本刀］的卡片時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA41BT/RNK-1-054":{"name":"澤下條張","effectText":"【突襲】〈澤下條張〉置為活動，並可移動至前線\n【登場時】若對手前線有空格時，可公開1張自己手牌中的〈志志雄真實〉或〈駒形由美〉或［特徵：十本刀］並放置在自己卡組上面。若有執行此動作時，選擇最多1張對手能源線產生能源1以下的角色卡，使其移動至前線。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-055":{"name":"瀨田宗次郎","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-056":{"name":"瀨田宗次郎","effectText":"當這張卡片因自己的效果從自己卡組放置在場外時，若有執行此動作時，從自己場外使這張卡片以休息狀態在自己場上登場。〈瀨田宗次郎〉的這個效果每回合只能發動1次。","triggerText":""},"UA41BT/RNK-1-057":{"name":"瀨田宗次郎","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈志志雄真實〉或〈駒形由美〉或［特徵：十本刀］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-058":{"name":"瀨田宗次郎","effectText":"【啟動主要】【若在前線時】【每回合1】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA41BT/RNK-1-059":{"name":"瀨田宗次郎","effectText":"當這張卡片因自己的效果從自己卡組放置在場外時，若這張卡片滿足能源需求時，可從自己場外使這張卡片發動突襲。\n【突襲】〈瀨田宗次郎〉置為活動，並可移動至前線\n【登場時】若這張角色卡從手牌以外登場時，抽最多1張卡片，這張角色卡在這個回合中，獲得【衝擊（1）】。\n【啟動主要】【若在前線時】將突襲狀態的這張角色卡最上面的卡片放置在自己卡組上面。〈瀨田宗次郎〉的這個效果每回合只能發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-060":{"name":"本條鐮足","effectText":"【登場時】選擇最多1張自己場上的〈志志雄真實〉或〈駒形由美〉或其他［特徵：十本刀］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-061":{"name":"悠久山安慈","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇自己場上1名角色，將其直置，此回合中，該角色BP+3000。"},"UA41BT/RNK-1-063":{"name":"惡・即・斬","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41BT/RNK-1-064":{"name":"牙突","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈齋藤一〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41BT/RNK-1-066":{"name":"十本刀集結","effectText":"選擇1張對手前線BP為自己場上〈志志雄真實〉、〈駒形由美〉與［特徵：十本刀］合計張數×1000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA41BT/RNK-1-067":{"name":"幕末的亡靈","effectText":"將1張自己場外的〈志志雄真實〉、〈駒形由美〉或［特徵：十本刀］卡片放置在自己卡組上面。選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-068":{"name":"神谷薰","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-065":{"name":"盜國開始","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41BT/RNK-1-069":{"name":"神谷薰","effectText":"【登場時】選擇最多1張我方場上的其他角色，此回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-053":{"name":"澤下條張","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-072":{"name":"齋藤一","effectText":"【登場時】選擇最多1張自己場上的〈緋村劍心〉，在這個回合中，使其失去【我方回合中】的效果。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-070":{"name":"神谷薰","effectText":"【登場時】【若在能源線時】 可以將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。\n【啟動主要】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-071":{"name":"神谷薰","effectText":"若自己前線有〈緋村劍心〉時，這張角色卡的產生能源+【紅】。\n【啟動主要】【每回合1】僅限這張角色卡登場的回合中可發動。選擇1張自己前線的〈緋村劍心〉，直到下一個我方回合開始時，獲得「對手以效果選擇這張角色卡時，必須追加將1張自身手牌放置在場外才可以選擇。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-062":{"name":"大型甲鐵艦煉獄","effectText":"【登場時】選擇最多1張自己場上的〈志志雄真實〉或〈駒形由美〉或其他［特徵：十本刀］，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-074":{"name":"相樂左之助","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-073":{"name":"相樂左之助","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-077":{"name":"相樂左之助","effectText":"【突襲】〈相樂左之助〉置為活動，並可移動至前線\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n這張角色卡攻擊後被防禦時，可以將1張自己前線活動狀態的〈相樂左之助〉轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。\n【登場時】抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-075":{"name":"相樂左之助","effectText":"這張角色卡攻擊後沒有被防禦時，抽1張卡片。","triggerText":""},"UA41BT/RNK-1-078":{"name":"三條燕","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA41BT/RNK-1-076":{"name":"相樂左之助","effectText":"【我方回合中】這張角色卡BP+1000。\n【若在能源線時】【每回合1】自己場上的角色卡攻擊結束時，可以將1張自己的手牌放置在場外。若有執行此動作時，可以選擇1張自己前線在這個回合中尚未攻擊的角色卡，與這張角色卡互相交換位置。","triggerText":""},"UA41BT/RNK-1-080":{"name":"高荷惠","effectText":"【登場時】選擇最多1張我方場上的其他角色，此回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-079":{"name":"關原妙","effectText":"若對手場上有藍色或紫色卡片時，手牌中這張卡片的能源需求減少【紅×1】。","triggerText":""},"UA41BT/RNK-1-081":{"name":"高荷惠","effectText":"此角色為活動狀態時，此角色產生能源+【紅】。","triggerText":""},"UA41BT/RNK-1-084":{"name":"月岡津南","effectText":"【登場時】從以下選擇1項。\n・選擇最多1張自己前線休息狀態的〈相樂左之助〉，置為活動。\n・可將1張自己前線活動狀態的〈相樂左之助〉轉為休息。若有執行此動作時，選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-083":{"name":"塚山由太郎","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA41BT/RNK-1-086":{"name":"緋村劍心","effectText":"【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。\n【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈緋村劍心〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-087":{"name":"緋村劍心","effectText":"【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。（移動時若能源線沒有空格，對手需選擇1張能源線的卡片放置在移除區後再進行移動）","triggerText":""},"UA41BT/RNK-1-088":{"name":"緋村劍心","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。\n【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA41BT/RNK-1-089":{"name":"緋村劍心","effectText":"這張角色卡以活動狀態登場。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【若在前線時】【每回合1】將1張自己場外的〈不殺的誓言〉放置在移除區。若有執行此動作時，抽1張卡片，自己在這個回合中，獲得「自己場上所有〈緋村劍心〉失去【我方回合中】的效果。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-090":{"name":"緋村劍心","effectText":"【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。\n【突襲】〈緋村劍心〉置為活動，並可移動至前線\n【攻擊時】【每回合1】可以將1張自己的手牌放置在場外。若有執行此動作時，使這張角色卡置為活動。\n【登場時】抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA41BT/RNK-1-091":{"name":"明神彌彥","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-085":{"name":"緋村劍心","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】與這張角色卡對戰戰敗的對手角色卡，將移動至能源線而非退場。（移動時若能源線沒有空格，對手需選擇1張能源線的卡片放置在移除區後再進行移動）","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-092":{"name":"明神彌彥","effectText":"若自己場上沒有卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA41BT/RNK-1-082":{"name":"高荷惠","effectText":"【登場時】從以下選擇1項。\n・將最多1張自己場外能源需求1以下的角色卡加入手牌。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1500。","triggerText":"[活動] 選擇自己場上1名角色，將其直置，此回合中，該角色BP+3000。"},"UA41BT/RNK-1-093":{"name":"明神彌彥","effectText":"【啟動主要】【支付1AP】【每回合1】抽1張卡片。這張角色卡在這個回合中，BP+1000。\n【攻擊時】可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上在這個回合中沒有攻擊的角色卡，置為活動。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA41BT/RNK-1-094":{"name":"赤牛","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若加入手牌的卡片為〈相樂左之助〉以外的卡片時，將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA41BT/RNK-1-095":{"name":"惡一文字","effectText":"選擇最多1張自己場上的〈相樂左之助〉，在這個回合中，獲得BP+1500與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害），並抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-096":{"name":"不殺之誓","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41BT/RNK-1-097":{"name":"絕對不能輸！！！","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA41BT/RNK-1-099":{"name":"二重之極","effectText":"這張卡片僅限自己場上有〈相樂左之助〉時才可使用。\n選擇1張對手前線BP5000以下的角色卡，『使其退場』。可將1張自己前線活動狀態的〈相樂左之助〉轉為休息。若有執行此動作時，則替換成『放置在移除區』。","triggerText":"[特別] 選擇1張對手前線L的角色，使其退場。"},"UA41BT/RNK-1-098":{"name":"飛天御劍流","effectText":"選擇1張對手前線的角色卡，轉為休息。\n當這張卡片因自己場上紅色的〈緋村劍心〉的效果而從自己手牌放置在場外時，抽1張卡片。","triggerText":""},"UA42ST/MGS-1-035":{"name":"阿良良木曆","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42ST/MGS-1-041":{"name":"忍野忍","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA42ST/MGS-1-049":{"name":"忍野咩咩","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[抽卡] 抽1張卡片。"},"UA42ST/MGS-1-039":{"name":"阿良良木曆","effectText":"【我方回合中】若自己場上有〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉或〈羽川翼〉時，這張角色卡BP+1000。\n【退場時】將最多1張〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉從自己場外加入手牌。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA42ST/MGS-1-054":{"name":"羽川翼","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"UA42ST/MGS-1-055":{"name":"羽川翼","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42ST/MGS-1-056":{"name":"羽川翼","effectText":"【衝擊無效】（與此角色進行對戰的角色，在該場對戰中會失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA41BT/RNK-1-100":{"name":"龍槌閃","effectText":"選擇最多1張對手前線BP5000以下的角色卡，『移動至能源線』。若自己場上有〈緋村劍心〉時，可替換成『放置在對手卡組下面』。","triggerText":"[特別] 選擇1張對手前線L的角色，使其退場。"},"UA42ST/MGS-1-101":{"name":"阿良良木曆","effectText":"【突襲】〈阿良良木暦〉置為活動，並可移動至前線。\n【登場時】這張角色卡在這個回合中，BP+1000並獲得「對手必須盡可能防禦這張角色卡的攻擊。」。\n【退場時】若自己場上有〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉時，可將最多1張這張角色卡的突襲來源卡片以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42ST/MGS-1-067":{"name":"妖刀心渡","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉或〈忍野忍〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42ST/MGS-1-103":{"name":"姬絲秀忒・雅賽蘿拉莉昂・刃下心","effectText":"【登場時】可使1張自己場上其他的角色卡退場。若有執行此動作時，抽2張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42ST/MGS-1-104":{"name":"姬絲秀忒・雅賽蘿拉莉昂・刃下心","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【退場時】從自己場外將最多1張〈阿良良木暦〉加入手牌。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA42ST/MGS-1-106":{"name":"劊子手","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA42ST/MGS-1-102":{"name":"章節","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA42ST/MGS-1-105":{"name":"姬絲秀忒・雅賽蘿拉莉昂・刃下心","effectText":"這張角色卡下面每有1張背面朝上卡片，這張角色卡的BP-1000。\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n當自己場上的〈阿良良木暦〉攻擊並戰勝時，將最多1張這張角色卡的背面朝上卡片放置在場外。\n【登場時】將3張自己卡組上面的卡片背面朝上放置在這張角色卡下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42ST/MGS-1-107":{"name":"德拉曼茲路基","effectText":"【衝擊無效】（與此角色進行對戰的角色，在該場對戰中會失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42ST/MGS-1-108":{"name":"羽川翼","effectText":"【我方回合中】這張角色卡BP+1000。\n【啟動主要】【若在前線時】【每回合1】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"UA42ST/MGS-1-109":{"name":"補習班廢墟","effectText":"【登場時】將3張自己卡組上面的卡片放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42ST/MGS-1-110":{"name":"阿良良木火憐","effectText":"若自己場上沒有卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA42ST/MGS-1-111":{"name":"千石撫子","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片以任意順序放置在自己卡組的上面，其餘卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42ST/MGS-1-112":{"name":"神原駿河","effectText":"【登場時】【若在能源線時】將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上，下方有2張以下背面朝上卡片的突襲狀態的〈神原駿河〉，將1張自己卡組上面的卡片背面朝上狀態放置在該角色卡下面，並在這個回合中，獲得「【攻擊時】抽最多1張卡片。」。〈神原駿河〉的此效果每回合只能發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42ST/MGS-1-064":{"name":"我不是什麼都知道，只知道我所知道的事","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA42ST/MGS-1-113":{"name":"戰場原黑儀","effectText":"【突襲】〈戰場原黑儀〉置為活動，並可移動至前線。\n【我方回合中】這張角色卡BP+500。\n【登場時】選擇以下1項。\n・抽最多1張卡片。\n・若這張角色卡的突襲來源能源需求為1以上時，這張角色卡在這個回合中，獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-002":{"name":"阿良良木曆","effectText":"【登場時】查看5張自己卡組上面的卡片。公開其中最多2張〈解咒的儀式〉或〈神原駿河〉或〈千石撫子〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【每回合1】僅限在這個回合中自己的〈蛇切繩〉已退場的情況下可發動。使這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-003":{"name":"斧乃木余接","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-005":{"name":"影縫余弦","effectText":"若對手場上有紫色或紅色的卡片，手牌中的這張卡片所減少能源需求【黃×1】。","triggerText":""},"UA42BT/MGS-1-006":{"name":"神原駿河","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-004":{"name":"貝木泥舟","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA42BT/MGS-1-007":{"name":"神原駿河","effectText":"【我方回合中】若自己場上有〈千石撫子〉時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-008":{"name":"神原駿河","effectText":"【登場時】將最多1張自己場外的〈解咒的儀式〉或能源需求1以下的〈千石撫子〉加入手牌。","triggerText":""},"UA42BT/MGS-1-009":{"name":"千石撫子","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-010":{"name":"千石撫子","effectText":"【啟動主要】【轉為休息】抽1張卡，將自己1張手牌放置在場外。","triggerText":""},"UA42BT/MGS-1-011":{"name":"千石撫子","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA42BT/MGS-1-001":{"name":"阿良良木曆","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・可將1張自己場上的場域卡退場。若有執行此動作時，抽1張卡片。","triggerText":""},"UA42BT/MGS-1-012":{"name":"千石撫子","effectText":"【登場時】查看7張自己卡組上面的卡片。公開其中最多1張黃色場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-013":{"name":"千石撫子","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張事件卡或場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA42BT/MGS-1-014":{"name":"千石撫子","effectText":"【登場時】選擇最多1張自己場上的〈阿良良木曆〉或〈神原駿河〉或〈千石撫子〉，在這個回合中，獲得「這張角色卡不能被BP4000以上的角色卡防禦。」。\n【啟動主要】【轉為休息】僅限在這個回合中自己的〈蛇切繩〉退場時可發動。發動這張角色卡的【登場時】效果。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-016":{"name":"羽川翼","effectText":"若這張角色卡為活動時，此角色產生能源+【黃】。","triggerText":""},"UA42BT/MGS-1-017":{"name":"羽川翼","effectText":"【登場時】使最多1張自己手牌中能源需求2以下的黃色角色卡以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-015":{"name":"千石撫子","effectText":"【突襲】〈千石撫子〉置為活動，並可移動至前線\n【我方回合中】在這個回合中若自己的〈蛇切繩〉退場時，這張角色卡獲得「這張角色卡不能被BP3000以下的角色卡防禦。」。\n【登場時】選擇以下其中一項。\n・查看7張自己卡組上面的卡片。從中使最多1張〈蛇切繩〉以休息狀態在自己能源線登場。其餘卡片依任意順序放置在自己卡組下面。\n・從自己手牌或場外，使最多1張〈蛇切繩〉以休息狀態在自己能源線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-018":{"name":"阿良良木火憐","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-021":{"name":"阿良良木火憐","effectText":"【突襲】〈阿良良木火憐〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】【若在能源線時】在我方角色戰鬥落敗的攻擊結束時，選擇1張自己前線的［特徵：火炎姊妹］，可以與這張角色卡互相交換位置。\n【登場時】使最多1張自己手牌中能源需求3以下消耗AP1擁有［特徵：火炎姊妹］的卡片以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-020":{"name":"阿良良木火憐","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-019":{"name":"阿良良木火憐","effectText":"【登場時】選擇最多1張自己場上［特徵：火炎姊妹］的卡片，移動至另一條戰線。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA42BT/MGS-1-023":{"name":"阿良良木月火","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：火炎姊妹］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA42BT/MGS-1-022":{"name":"阿良良木月火","effectText":"【登場時】選擇最多1張自己場上其他［特徵：火炎姊妹］的卡片，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-024":{"name":"阿良良木月火","effectText":"【攻擊時】抽最多1張卡片。","triggerText":""},"UA42BT/MGS-1-026":{"name":"神原駿河的房間","effectText":"【啟動主要】【轉為休息】將1張自己卡組上面的卡片放置在場外。\n【退場時】將最多1張自己場外的〈神原駿河〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-027":{"name":"蛇切繩","effectText":"【登場時】可以將1張自己手牌中的〈千石撫子〉放置在場外。若有執行此動作時，抽最多1張卡片。\n【退場時】選擇最多1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42BT/MGS-1-028":{"name":"快起來啊啊啊──哥哥！","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA42BT/MGS-1-025":{"name":"阿良良木月火","effectText":"這張角色卡以活動狀態登場。\n【攻擊時】【每回合1】可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上其他［特徵：火炎姊妹］的卡片，置為活動。\n【退場時】將這張卡片加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-029":{"name":"解咒的儀式","effectText":"使1張自己場上的場域卡退場。若有執行此動作時，抽1張卡片，在這個回合中，接下來使用手牌中的〈千石撫子〉的消耗AP-1。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-032":{"name":"白金級的令人火大","effectText":"使最多1張自己手牌中能源需求3以下消耗AP1的［特徵：火炎姊妹］以活動狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-031":{"name":"刷牙","effectText":"將1張自己前線活動狀態的〈阿良良木火憐〉轉為休息。若有執行此動作時，抽3張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-033":{"name":"身為淑女理所當然的修養","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA42BT/MGS-1-034":{"name":"阿良良木火憐","effectText":"若對手場上有黃色或紅色的卡片，則手牌中此卡的能源需求減少【紫×1】。","triggerText":""},"UA42BT/MGS-1-035":{"name":"阿良良木曆","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-030":{"name":"栂之木二中的火焰姊妹","effectText":"選擇1張對手前線『BP2000以下』的角色卡，使其退場。若自己場上有〈阿良良木火憐〉或〈阿良良木月火〉時，則替換成『BP4000以下』。若自己場上有〈阿良良木火憐〉與〈阿良良木月火〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42BT/MGS-1-036":{"name":"阿良良木曆","effectText":"若自己場上沒有卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【登場時】查看5張自己卡組上面的卡片。公開其中最多1張BP5000的〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA42BT/MGS-1-037":{"name":"阿良良木曆","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA42BT/MGS-1-038":{"name":"阿良良木曆","effectText":"【退場時】查看3張自己卡組上面的卡片。公開其中最多1張〈阿良良木曆〉或〈忍野忍〉或〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-039":{"name":"阿良良木 曆","effectText":"【我方回合中】若自己場上有〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉或〈羽川翼〉時，這張角色卡BP+1000。\n【退場時】將最多1張〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉從自己場外加入手牌。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA42BT/MGS-1-042":{"name":"忍野忍","effectText":"【啟動主要】【轉為休息】【每回合1】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-043":{"name":"忍野忍","effectText":"【登場時】選擇最多1張我方場上的其他角色，此回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-041":{"name":"忍野忍","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-046":{"name":"忍野忍","effectText":"【啟動主要】【若在前線時】【每回合1】將1張自己場上的〈阿良良木暦〉放回手牌。若有執行此動作時，發動放回手牌的角色卡的【退場時】效果，這張角色卡在這個回合中，BP+1000。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA42BT/MGS-1-045":{"name":"忍野忍","effectText":"【登場時】查看5張自己卡組上面的卡片。公開其中最多1張〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉或〈阿良良木暦〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-047":{"name":"忍野忍","effectText":"【突襲】〈忍野忍〉置為活動，並可移動至前線\n【登場時】使最多1張自己場外能源需求2以下的紫色〈阿良良木暦〉以休息狀態在自己場上登場。\n【啟動主要】【若在前線時】【每回合1】將1張自己前線活動狀態的〈阿良良木暦〉轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-048":{"name":"忍野咩咩","effectText":"【登場時】選擇最多1張對手前線BP4500以上的角色卡，在這個回合中，BP-4000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-040":{"name":"阿良良木月火","effectText":"【啟動主要】【轉為休息】【每回合1】此角色在此回合中，獲得產生能源+【紫】與「主要階段結束時，此角色退場。」。","triggerText":""},"UA42BT/MGS-1-049":{"name":"忍野咩咩","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-051":{"name":"戰場原黑儀","effectText":"【啟動主要】【每回合1】將1張自己的手牌放置在自己卡組的上面。若有執行此動作時，這張角色卡在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-050":{"name":"戰場原黑儀","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-052":{"name":"戰場原黑儀","effectText":"這張角色卡攻擊後被防禦時，抽1張卡片。","triggerText":""},"UA42BT/MGS-1-053":{"name":"戰場原黑儀","effectText":"【登場時】將最多1張自己場外能源需求2以下的〔〈阿良良木暦〉或〈羽川翼〉〕加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-054":{"name":"羽川翼","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":""},"UA42BT/MGS-1-055":{"name":"羽川翼","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-057":{"name":"羽川翼","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA42BT/MGS-1-056":{"name":"羽川翼","effectText":"【衝擊無效】（與此角色進行對戰的角色，在該場對戰中會失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-058":{"name":"羽川翼","effectText":"這張角色卡以活動狀態在自己場上登場。\n【登場時】指定1個能源需求數量。公開1張自己卡組上面的卡片。若公開的卡片的能源需求數量與此效果指定的數量相同時，將該張卡片加入手牌，並可再抽最多1張卡片。若沒有加入手牌時，將公開的卡片放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-059":{"name":"羽川翼","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。\n【啟動主要】【轉為休息】指定1個能源需求數量。公開1張自己卡組上面的卡片。若公開的卡片的能源需求數量與此效果指定的數量相同時，將該張卡片加入手牌。若沒有加入手牌時，將公開的卡片放置在自己卡組的上面。〈羽川翼〉的此效果每回合只能發動1次。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA42BT/MGS-1-060":{"name":"黑羽川","effectText":"這張卡片也視為〈羽川翼〉。\n【突襲】〈羽川翼〉置為活動，並可移動至前線\n【登場時】對手將1張自身的手牌放置在場外。\n【啟動主要】【若在前線時】【每回合1】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【每回合1】將1張自己手牌中的〈羽川翼〉放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-062":{"name":"甜甜圈店","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若加入手牌的卡片為〈忍野忍〉以外的卡片時，將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-061":{"name":"黑羽川","effectText":"這張卡片也視為〈羽川翼〉。\n【突襲】〈羽川翼〉置為活動，並可移動至前線\n這張角色卡攻擊後戰勝時，若自己能源線有〈阿良良木暦〉或〈戰場原黑儀〉時，對手將1張自身的手牌放置在場外。\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-2000。將自己任意張數的手牌放置在場外。因此效果每將1張卡片放置在場外，所選的角色卡在這個回合中，BP再-1500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-063":{"name":"想被我吃掉嗎喵？","effectText":"選擇1張對手前線『BP3000』以下的角色卡，使其退場。此效果可選擇的BP，會因自己場上每有1張〈羽川翼〉而增加1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42BT/MGS-1-064":{"name":"我不是什麼都知道，只知道我所知道的事","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA42BT/MGS-1-067":{"name":"妖刀心渡","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈姬絲秀忒・雅賽蘿拉莉昂・刃下心〉或〈忍野忍〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42BT/MGS-1-065":{"name":"將七台以斜77度排列、無奈嘶鳴的750cc重機，輕鬆並排後久久凝望","effectText":"自己前線每有1張〈羽川翼〉，手牌中這張卡片的能源需求減少【紫×1】。\n查看7張自己卡組上面的卡片。公開其中最多3張〈羽川翼〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-066":{"name":"太猛了！","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA42BT/MGS-1-070":{"name":"忍野忍","effectText":"【登場時】將1張我方場上其他能源需求為1以下的角色放回手牌。若無法放回，則將此角色放回手牌。","triggerText":""},"UA42BT/MGS-1-069":{"name":"阿良良木曆","effectText":"【我方回合中】若自己場上有〈神原駿河〉時，這張角色卡BP+1000。\n【對方回合中】若自己場上有〈八九寺真宵〉時，這張角色卡獲得【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）。\n【登場時】若自己場上有〈戰場原黑儀〉時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-071":{"name":"忍野咩咩","effectText":"【衝擊無效】（與此角色進行對戰的角色，在該場對戰中會失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-044":{"name":"忍野忍","effectText":"【我方回合中】若自己場上有〈阿良良木暦〉時，這張角色卡BP+500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-074":{"name":"神原駿河","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈戰場原黑儀〉或〈神原駿河〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA42BT/MGS-1-072":{"name":"神原駿河","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-073":{"name":"神原駿河","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-076":{"name":"神原駿河","effectText":"【突襲】〈神原駿河〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【攻擊時】若這張角色卡下面的背面朝上卡片在2張以下時，可將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。若有執行此動作時，這張角色卡在這個回合中，獲得BP+1000與【傷害（2）】。\n【退場時】將自己手牌放置在場外，數量等同於這張角色卡下面的背面朝上卡片張數。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-075":{"name":"神原駿河","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【突襲】〈神原駿河〉置為活動，並可移動至前線\n【攻擊時】若這張角色卡下面的背面朝上卡片在2張以下時，可將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。若有執行此動作時，抽1張卡片。\n【退場時】將自己手牌放置在場外，數量等同於這張角色卡下面的背面朝上卡片張數。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-078":{"name":"戰場原黑儀","effectText":"若自己場外的卡片在9張以下時，這張卡片在自己場上與作為突襲源時的能源需求減少【紅×1】。\n【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-079":{"name":"戰場原黑儀","effectText":"若自己場外的卡片在9張以下時，這張卡片在自己場上與作為突襲源時的能源需求減少【紅×3】。\n【我方回合中】攻擊階段結束時，可將活動狀態的這張角色卡轉為休息。若有執行此動作時，選擇最多1張自己場上突襲狀態的〈神原駿河〉，將該角色卡下面的所有卡片放置在場外。（包含背面朝上卡片）\n【登場時】【若在能源線時】使這張角色卡置為活動。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA42BT/MGS-1-068":{"name":"阿良良木曆","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA42BT/MGS-1-081":{"name":"戰場原黑儀","effectText":"若自己場外的卡片在9張以下時，這張卡片在自己場上與作為突襲源時的能源需求減少【紅×2】。\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n【啟動主要】【轉為休息】僅限這張角色卡的能源需求在1以上時可發動。發動這張角色卡的【登場時】效果。","triggerText":""},"UA42BT/MGS-1-077":{"name":"戰場原黑儀","effectText":"【登場時】抽1張卡片，將自己的1張手牌置於場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-080":{"name":"戰場原黑儀","effectText":"若自己場外的卡片在9張以下時，這張卡片在自己場上與作為突襲源時的能源需求減少【紅×3】。\n若自己場外的卡片在9張以下時，這張角色卡BP-1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-082":{"name":"戰場原黑儀","effectText":"若自己場外的卡片在9張以下時，這張卡片在自己場上與作為突襲源時的能源需求減少【紅×4】。\n若自己場外的卡片在9張以下時，這張角色卡BP-500。\n【啟動主要】【每回合1】這張角色卡在這個回合中，獲得BP-500與【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-084":{"name":"八九寺真宵","effectText":"這張卡片因自己的效果被放置在移除區時，將最多1張自己卡組上面的卡片放置在移除區。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-086":{"name":"八九寺真宵","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張能源需求3以下的紅色角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在移除區。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-083":{"name":"戰場原黑儀","effectText":"【突襲】〈戰場原黑儀〉置為活動，並可移動至前線\n【登場時】從以下選擇1項。\n・選擇最多1張對手前線BP3000以下的角色卡，使其退場。\n・若這張角色卡的突襲來源能源需求為1以上時，抽1張卡片，並使最多1張自己手牌中能源需求3以下消耗AP1的紅色角色卡以活動狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-087":{"name":"八九寺真宵","effectText":"【登場時】查看5張自己卡組上面的卡片。公開其中最多1張能源需求2以下的紅色卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。在這個回合中，下一張從手牌使用的能源需求2以下的紅色卡片，其消耗AP-1。\n【啟動主要】【每回合1】將1張自己的手牌放置在移除區。若有執行此動作時，選擇1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-085":{"name":"八九寺真宵","effectText":"這張卡片因自己的效果被放置在移除區時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA42BT/MGS-1-088":{"name":"八九寺真宵","effectText":"【突襲】〈八九寺真宵〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】可以將1張自己的手牌放置在移除區。若有執行此動作時，抽1張卡片，並選擇最多1張自己場上其他的角色卡，使該角色卡與這張角色卡在這個回合中，BP+1000。\n【退場時】將自己移除區任意張數的卡片放置在場外。若以此效果放置了3張以上時，將這張卡片以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA42BT/MGS-1-090":{"name":"羽川翼","effectText":"若這張角色卡為活動時，此角色產生能源+【紅】。","triggerText":""},"UA42BT/MGS-1-089":{"name":"羽川翼","effectText":"對手的場上有黃色或紫色的卡片時，減少手牌中這張卡片的能源需求【紅×1】。","triggerText":""},"UA42BT/MGS-1-093":{"name":"惡魔的左手","effectText":"從自己場外發動最多1張〈神原駿河〉的突襲，並將這張卡片背面朝上放置於該角色卡下方。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA42BT/MGS-1-092":{"name":"我愛你","effectText":"將2張自己卡組上面的卡片放置在場外。之後，從自己場外將最多1張〈戰場原黑儀〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-091":{"name":"鬼屋","effectText":"這張場域卡以活動狀態登場。\n【啟動主要】【轉為休息】自己場上所有的角色卡，在這個回合中，BP+500。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-098":{"name":"是發生了什麼好事嗎？","effectText":"選擇1張自己場上的角色卡，在這個回合中，獲得「【攻擊時】【每回合1】最多抽3張卡片。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-094":{"name":"那就是天津四、牛郎星、織女星。","effectText":"抽1張卡片。選擇最多各1張自己場上的〈戰場原黑儀〉與〈阿良良木曆〉，使被選擇的角色卡在這個回合中BP+1000。若以此效果選擇的角色卡的能源需求合計在4以上時，再使以此效果選擇的〈戰場原黑儀〉在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"UA42BT/MGS-1-099":{"name":"雨魔","effectText":"若自己場上有〈神原駿河〉時，手牌中這張卡片的消耗AP-1。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。選擇最多1張自己場上突襲狀態的〈神原駿河〉，在這個回合中，獲得「若這張角色卡下面的背面朝上卡片在2張以下，且這張角色卡因對手效果退場時，可改為將1張自己卡組上面的卡片背面朝上放置在這張角色卡下面。」。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42BT/MGS-1-095":{"name":"我咬到舌頭了","effectText":"抽2張卡片。\n當這張卡片因自己的效果被放置在移除區時，抽最多1張卡片。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA42BT/MGS-1-097":{"name":"為我著迷吧","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈戰場原黑儀〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA42BT/MGS-1-096":{"name":"你只是擅自一個人得救罷了","effectText":"選擇最多2張自己的AP卡，將其轉為活動狀態。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA43BT/SMD-1-003":{"name":"波伊魯","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【防禦時】若進行攻擊的對手角色卡的原本BP在3000以下時，這張角色卡在這場戰鬥中，BP+2000。","triggerText":""},"UA43BT/SMD-1-005":{"name":"真霜平助","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA43BT/SMD-1-004":{"name":"真霜平助","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA42BT/MGS-1-100":{"name":"我討厭你！！！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈八九寺真宵〉時，則替換成『BP4000以下』。\n【我方回合中】當這張卡片因自己的效果放置在移除區時，若自己的紅色產生能源在3以上時，可支付1AP。若有執行此動作時，選擇1張對手前線BP4000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA43BT/SMD-1-001":{"name":"帶黑","effectText":"【退場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+3000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-002":{"name":"嗶之助","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA43BT/SMD-1-009":{"name":"陸無糖","effectText":"【登場時】抽1張卡片。","triggerText":""},"UA43BT/SMD-1-011":{"name":"南雲","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-010":{"name":"陸無糖","effectText":"【登場時】若自己場上有〈陸少糖〉時，使這張角色卡置為活動。","triggerText":""},"UA43BT/SMD-1-006":{"name":"真霜平助","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】將1張自己背面朝上的生命卡置為正面朝上。若有執行此動作時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+2000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-008":{"name":"真霜平助","effectText":"【突襲】〈眞霜平助〉置為活動，並可移動至前線。\n【登場時】這張角色卡在這個回合中，獲得【狙擊】。將最多1張自己的生命卡置為正面朝上。對手選擇1張自身的生命卡，若該卡為背面朝上時，將其置為正面朝上。\n【啟動主要】【每回合1】若自己與對手的卡組與生命區中，正面朝上的卡片合計在3張以上時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-007":{"name":"真霜平助","effectText":"【登場時】選擇最多1張對手前線的角色卡，以正面朝上放置在對手的生命區。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-015":{"name":"朝倉新","effectText":"【攻擊時】若自己場上擁有不同卡片名稱［特徵：坂本商店］的卡片有3種以上時，選擇以下最多1項。\n・抽1張卡片。\n・這張角色卡在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-014":{"name":"朝倉新","effectText":"【登場時】查看3張自己卡組上面的卡片。從中公開最多1張［特徵：坂本商店］或〈眞霜平助〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-012":{"name":"南雲","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上沒有【突襲】的黃色角色卡，在這個回合中，自己擁有【突襲】的角色卡可對該角色卡發動突襲。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-013":{"name":"朝倉新","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。若放置在上面時，將該張卡片變為正面朝上。（若該卡不再位於卡組最上面時，則翻回背面朝上。）","triggerText":""},"UA43BT/SMD-1-016":{"name":"朝倉新","effectText":"【登場時】選擇以下1項。\n・查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或下面。若放置在上面時，將該張卡片變為正面朝上。\n・若自己或對手的卡組或生命區有正面朝上卡片時，在這個回合中，下一張從手牌中使用、原本消耗AP為2的卡片，其消耗AP-1。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA43BT/SMD-1-017":{"name":"朝倉新","effectText":"【突襲】〈朝倉新〉置為活動，並可移動至前線。\n【登場時】對手將自身所有手牌公開。自己從中選擇最多1張，以正面朝上放置在對手卡組的上面。\n【啟動主要】【若在前線時】【每回合1】抽1張卡片，並將1張自己卡組上面的卡片變為正面朝上。若使用這個效果抽到非正面的卡片時，將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-023":{"name":"坂本太郎","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-019":{"name":"坂本葵","effectText":"【登場時】【若在能源線時】若自己場上擁有不同卡片名稱［特徵：坂本商店］的卡片有3種以上時，使這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA43BT/SMD-1-018":{"name":"朝倉新","effectText":"【登場時】選擇最多1張對手前線的角色卡，轉為休息。下一次無法置為活動。若自己卡組上面有正面朝上卡片時，可將該張卡片加入手牌。若有執行此動作時，使這張角色卡置為活動，並將1張自己卡組上面的卡片變為正面朝上。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-020":{"name":"坂本葵","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA43BT/SMD-1-022":{"name":"坂本太郎","effectText":"【我方回合中】若自己場上擁有不同卡片名稱的［特徵：坂本商店］卡片有3種以上時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-021":{"name":"坂本太郎","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA43BT/SMD-1-029":{"name":"陸少糖","effectText":"突襲狀態的角色卡不能防禦這張角色卡。","triggerText":""},"UA43BT/SMD-1-028":{"name":"陸少糖","effectText":"【我方回合中】若自己場上擁有不同卡片名稱［特徵：坂本商店］的卡片有3種以上時，這張角色卡BP+2000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-027":{"name":"坂本花","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-025":{"name":"坂本太郎","effectText":"【突襲】〈坂本太郎〉置為活動，並可移動至前線。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】這張角色卡直到下一個我方回合開始前，獲得「這張角色卡不會退場，且不會受到減少BP的效果影響。」。選擇最多1張自己場上的角色卡，直到下一個我方回合開始前，獲得「這張角色卡無法被對手的〔角色卡・事件卡〕效果選擇。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-024":{"name":"坂本太郎","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【若在前線時】自己場上〈坂本太郎〉以外的［特徵：坂本商店］，無法被對手的〔角色卡・事件卡〕效果選擇。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA43BT/SMD-1-026":{"name":"坂本太郎","effectText":"【突襲】〈坂本太郎〉置為活動，並可移動至前線。\n自己的攻擊階段結束時，將突襲狀態的這張角色卡最上面的卡片放置在場外。\n【登場時】這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。查看5張自己卡組上面的卡片。從中將最多1張〈坂本商店〉或BP3500以下消耗AP1的黃色角色卡以活動狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-034":{"name":"憩來坂商店街大生存遊戲大會","effectText":"【每回合1】自己場上的角色卡攻擊後戰勝時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-035":{"name":"坂本商店","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】選擇1張自己場上擁有［特徵：坂本商店］且原始BP3500以下的角色卡，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-030":{"name":"陸少糖","effectText":"【我方回合中】若自己場上擁有不同卡片名稱［特徵：坂本商店］的卡片有3種以上時，這張角色卡獲得「BP4000以上的角色卡不能防禦這張角色卡。」。\n這張角色卡攻擊後沒有被防禦時，抽1張卡片。","triggerText":""},"UA43BT/SMD-1-032":{"name":"Asakura","effectText":"【登場時】抽1張卡片，並將1張自己卡組上面的卡片翻為正面朝上。若以此效果抽到的卡片非正面朝上的卡片時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-031":{"name":"陸少糖","effectText":"【啟動主要】將『6張』自己的手牌放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得BP+2000與【雙重攻擊】。自己場上每有1種［特徵：坂本商店］的卡片名稱，以此效果放置在場外的手牌張數-1。〈陸少糖〉的這個效果，每回合只能發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-033":{"name":"Asakura","effectText":"若在自己或對手的卡組或生命區有正面朝上的卡片時，手牌中這張卡片的消耗AP-1。\n【啟動主要】【轉為休息】選擇以下1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・將1張自己卡組上面的卡片翻為正面朝上。","triggerText":""},"UA43BT/SMD-1-041":{"name":"X","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":""},"UA43BT/SMD-1-040":{"name":"全都聽得一清二楚…","effectText":"若自己場上有〈朝倉新〉時，手牌中這張卡片的消耗AP-1。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA43BT/SMD-1-038":{"name":"傳說中的男人","effectText":"選擇1張對手前線『BP2000以下』的角色卡，使其退場。若自己場上有〈坂本太郎〉時，則替換成『BP5000以下』。若自己場上擁有不同卡片名稱［特徵：坂本商店］的卡片有5種以上時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA43BT/SMD-1-036":{"name":"坂本家家訓","effectText":"在這個回合的攻擊階段結束時，若在這個回合中對手前線的角色卡沒有退場時，最多抽4張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-037":{"name":"超能力","effectText":"抽2張卡片。對手公開其所有手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-046":{"name":"大佛","effectText":"【突襲】〈大佛〉置為活動，並可移動至前線。\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【攻擊時】在這個回合中若自己有進行額外抽卡時，抽最多1張卡片。若在這張角色卡登場的回合中，這張角色卡在這個回合中，獲得BP+1000與【傷害（2）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-045":{"name":"大佛","effectText":"【若在前線時】自己可不支付AP進行額外抽卡。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA43BT/SMD-1-043":{"name":"大佛","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA43BT/SMD-1-044":{"name":"大佛","effectText":"【我方回合中】若在這個回合中自己進行了額外抽卡，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-042":{"name":"大佛","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-039":{"name":"沒什麼特別的日常","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA43BT/SMD-1-052":{"name":"神神廻","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-051":{"name":"坂本太郎","effectText":"【突襲】〈坂本太郎〉置為活動，並可移動至前線。\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【每回合1】查看5張自己卡組上面的卡片。將其中最多1張能源需求2以下的紫色卡片放置在場外，其餘卡片依任意順序放置在自己卡組下面。之後，發動因這個效果而放置在場外的卡片的【觸發】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-047":{"name":"坂本太郎","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-050":{"name":"坂本太郎","effectText":"【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己前線非突襲狀態的角色卡，並發動該張角色卡的【觸發】。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-048":{"name":"坂本太郎","effectText":"在這個回合中若自己或對手的【觸發】有發動時，這張角色卡BP+1000。","triggerText":""},"UA43BT/SMD-1-049":{"name":"坂本太郎","effectText":"【登場時】查看3張自己卡組上面的卡片。將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-057":{"name":"南雲","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-055":{"name":"神神廻","effectText":"【突襲】〈神神廻〉置為活動，並可移動至前線。\n【登場時】若在這個回合中自己有進行額外抽卡時，選擇1～2張自己休息狀態的AP卡，置為活動。〈神神廻〉的這個效果，每回合僅可發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-056":{"name":"篁","effectText":"這張卡片僅限於自己進行額外抽卡的回合中可登場。\n【登場時】使這張角色卡置為活動。選擇最多1張對手前線的角色卡或對手場上的場域卡，使其退場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-053":{"name":"神神廻","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA43BT/SMD-1-054":{"name":"神神廻","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】僅限於自己進行額外抽卡的回合中可發動。在這個回合中，這張角色卡的產生能源+【紫】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-058":{"name":"南雲","effectText":"自己的擁有【突襲】的角色卡可藉由觸發效果對這張角色卡發動突襲。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA43BT/SMD-1-064":{"name":"入侵者排除系統","effectText":"【登場時】若對手前線上有4張以上BP4000以上的角色卡時，抽1張卡片，將這張角色卡置為活動，且這張角色卡直到下一個我方回合開始前BP+2000。","triggerText":""},"UA43BT/SMD-1-063":{"name":"鹿島","effectText":"【登場時】【攻擊時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：LABO］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA43BT/SMD-1-059":{"name":"南雲","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場戰鬥中，失去【衝擊】）\n【我方回合中】在這個回合中若自己或對手的【觸發】已發動時，這張角色卡獲得「這張角色卡不會被BP4000以上的角色卡阻擋。」。","triggerText":""},"UA43BT/SMD-1-062":{"name":"豹","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：ORDER］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA43BT/SMD-1-061":{"name":"南雲","effectText":"【突襲】〈南雲〉置為活動，並可移動至前線\n【登場時】【若在前線時】從自己場外選擇最多1張擁有『【顏色觸發】』的紫色角色卡，發動該卡片的【觸發】。可將突襲狀態的這張角色卡最上面的卡片放置在自己場外。若有執行此動作時，則替換成『〈南雲〉以外的【突襲觸發】』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-060":{"name":"南雲","effectText":"發動這張卡片的【獲得觸發】時，可改為【抽牌觸發】或【活動觸發】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-069":{"name":"勢羽夏生","effectText":"【突襲】〈勢羽夏生〉置為活動，並可移動至前線\n【對方回合中】當對手因角色卡的效果或事件卡的效果而選擇這張角色卡時，必須追加支付1AP才可以選擇。\n【啟動主要】【若在前線時】【每回合1】在這張角色卡登場的回合中無法發動。抽1張卡片。若自己場上擁有3張以上［特徵：LABO］卡，且對手的生命值在3以上時，造成對手玩家1傷害。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA43BT/SMD-1-070":{"name":"田中","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-068":{"name":"勢羽夏生","effectText":"【登場時】抽1張卡片。\n【攻擊時】使最多1張自己手牌中能源需求4以下消耗AP1的紫色［特徵：LABO］卡以活動狀態在自己場上登場，或發動突襲。無法以這個效果對這張角色卡發動突襲。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-066":{"name":"勢羽夏生","effectText":"【登場時】選擇最多1張自己場上的［特徵：LABO］，在這個回合中，BP+1000。\n【攻擊時】自己場上所有的［特徵：LABO］在這個回合中，BP+1000。","triggerText":""},"UA43BT/SMD-1-065":{"name":"勢羽夏生","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-067":{"name":"勢羽夏生","effectText":"【攻擊時】若自己場上有3張以上［特徵：LABO］時，這張角色卡在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA43BT/SMD-1-075":{"name":"以秩序之名","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA43BT/SMD-1-076":{"name":"好運習俗","effectText":"〈好運習俗〉在1個回合中只能使用1張。\n抽1張卡片。在這個回合中若自己已進行額外抽卡時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-074":{"name":"ORDER","effectText":"查看5張自己卡組上面的卡片。公開其中最多2張［特徵：ORDER］的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA43BT/SMD-1-071":{"name":"透明戰衣","effectText":"這張角色卡無法以突襲以外的方式登場。\n【突襲】能源需求4以下的紫色角色卡 置為活動，並可移動至前線，這張角色卡不會被對手的效果選擇。\n這張角色卡獲得其突襲源卡片所擁有的所有【登場時】與【攻擊時】效果。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA43BT/SMD-1-073":{"name":"LABO","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】選擇1張自己場上的［特徵：LABO］卡，在這個回合中，該卡不會被BP4000以上的角色卡防禦。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA43BT/SMD-1-072":{"name":"瘋狂堀口","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA43BT/SMD-1-080":{"name":"有趣的實驗要開始啦～","effectText":"選擇最多1張自己的AP卡，置為活動。在下一個對手回合的移動階段，對手無法將能源線的角色卡移動至前線，但可以將前線的角色卡移動至能源線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44ST/EVA-1-069":{"name":"綾波零","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA43BT/SMD-1-079":{"name":"偽裝高手","effectText":"選擇1張對手前線BP5000以下的角色卡，放置在對手卡組上面或下面的『對手選擇的一方』。若自己場上有〈南雲〉時，則替換成『自己選擇的一方』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44ST/EVA-1-068":{"name":"赤木律子","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA43BT/SMD-1-077":{"name":"在B5大鬧一場果然沒錯啊","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈神神迴〉或〈大佛〉時，則替換成『BP4000以下』。若自己場上有〈神神迴〉與〈大佛〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA43BT/SMD-1-078":{"name":"差不多下班時間了，我先走啦","effectText":"選擇1張對手前線的角色卡，在這個回合中，自己場上每有1張［特徵：LABO］，該角色卡的BP-1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44ST/EVA-1-085":{"name":"葛城美里","effectText":"【登場時】從以下選擇1項。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n・選擇最多1張自己場上的角色卡，移動至別的線。","triggerText":"[抽卡] 抽1張卡片。"},"UA44ST/EVA-1-083":{"name":"加持良治","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA44ST/EVA-1-072":{"name":"碇源堂＆冬月耕造","effectText":"【啟動主要】【轉為休息】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA44ST/EVA-1-073":{"name":"碇真嗣","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44ST/EVA-1-076":{"name":"伊吹摩耶","effectText":"若對手場上有黃色或紫色卡片時，手牌中這張卡片的能源需求減少【紅×1】。","triggerText":""},"UA44ST/EVA-1-095":{"name":"大輸出功率型第2次試作自走460mm陽電子炮","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈碇真嗣〉或卡片名稱包含「初號機」的角色卡時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44ST/EVA-1-105":{"name":"新世紀福音戰士 零號機","effectText":"【突襲】〈綾波零〉置為活動，並可移動至前線\n【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）\n【退場時】抽2張卡片。之後，可將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求1以下的紅色〈綾波零〉以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44ST/EVA-1-101":{"name":"相田劍介","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44ST/EVA-1-103":{"name":"碇真嗣","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA44ST/EVA-1-102":{"name":"綾波零","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44ST/EVA-1-100":{"name":"微笑就可以了","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44ST/EVA-1-104":{"name":"新世紀福音戰士 初號機","effectText":"【突襲】〈碇真嗣〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【攻擊時】將任意張數自己能源線活動狀態的卡片轉為休息。根據以此效果轉為休息的卡片的能源需求合計，這張角色卡在這個回合中，獲得以下所有效果。\n・4以上：BP+3000。\n・8以上：【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44ST/EVA-1-110":{"name":"綾波零","effectText":"【退場時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44ST/EVA-1-111":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44ST/EVA-1-107":{"name":"鈴原冬二","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44ST/EVA-1-106":{"name":"式波・明日香・蘭格雷","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n若自己場上有4張以上不持有【觸發】的卡片時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA44ST/EVA-1-109":{"name":"你不會死的。我會保護你的","effectText":"選擇最多1張自己場上的〈碇真嗣〉或卡片名稱包含「初號機」的角色卡，直到下一個我方回合開始前，BP+3000。可將1張自己場上活動狀態的〈綾波零〉轉為休息。若有執行此動作時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44ST/EVA-1-108":{"name":"特務機關NERV","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，抽2張卡片。\n【啟動主要】【轉為休息】【使這張卡片退場】抽1張卡片。","triggerText":""},"UA44BT/EVA-1-003":{"name":"綾波零","effectText":"【我方回合中】若在這個回合中，自己場上有持有【獲得觸發】的角色卡登場時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-004":{"name":"綾波零","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA44BT/EVA-1-002":{"name":"綾波零","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【對方回合中】這張角色卡不會移動、不會返回手牌，且不會受到減少BP的效果影響。","triggerText":""},"UA44BT/EVA-1-001":{"name":"綾波零","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA44ST/EVA-1-113":{"name":"式波・明日香・蘭格雷","effectText":"當這張角色卡被突襲時，從以下選擇1項。（發動突襲的角色卡的【登場時】與這個效果可以依任意順序處理）\n・抽1張卡片。\n・選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":""},"UA44ST/EVA-1-112":{"name":"渚薰","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【啟動主要】【轉為休息】將這張卡片以背面朝上放置在自己場上的〈新世紀福音戰士第13號機〉下面。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-010":{"name":"式波・明日香・蘭格雷","effectText":"【登場時】選擇最多1張自己場上的角色卡，在這個回合中，賦予其【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":""},"UA44BT/EVA-1-008":{"name":"葛城美里","effectText":"【對方回合中】當自己發動滿足能源需求的角色卡的【獲得觸發】時，可改為將該張卡片以休息狀態在自己場上登場。若有執行此動作時，將1張自己的手牌放置在場外。〈葛城美里〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-009":{"name":"式波・明日香・蘭格雷","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-007":{"name":"葛城美里","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA44BT/EVA-1-012":{"name":"式波・明日香・蘭格雷","effectText":"【登場時】可使1張自己場上其他的角色卡退場。若有執行此動作時，從以下選擇1項。\n・抽2張卡片。\n・抽1張卡片，並選擇最多1張自己場上的角色卡，置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-014":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-013":{"name":"式波・明日香・蘭格雷","effectText":"【登場時】使這張角色卡置為活動，並從以下選擇1項。\n・選擇最多1張對手前線的角色卡，轉為休息。\n・若為我方回合中，可使1張自己場上的角色卡退場。若有執行此動作時，選擇最多1張對手前線BP5000以下的角色卡，使其退場，並在這個回合中，下一次從手牌中使用能源需求2以下的黃色角色卡的消耗AP-1。\n【啟動主要】【將2張手牌放置在場外】【每回合1】這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-006":{"name":"葛城美里","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】選擇1張自己場上的黃色角色卡，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-005":{"name":"綾波零","effectText":"當這張角色卡因自己或對手的效果或對戰而離場時，可將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求2以下的黃色〈綾波零〉以活動狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-011":{"name":"式波・明日香・蘭格雷","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA44BT/EVA-1-018":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【對方回合中】【若在前線時】發動自己的【抽牌觸發】或【活動觸發】時，可改為發動【獲得觸發】。\n【攻擊時】可支付1AP。若有執行此動作時，抽1張卡片，並選擇最多1張自己場上〈真希波・真理・伊拉絲多莉亞斯〉以外的角色卡，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-020":{"name":"你是笨蛋嗎？","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈式波・明日香・蘭格雷〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-015":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"若對手場上有紫色或紅色卡片時，手牌中這張卡片的能源需求減少【黃×1】。","triggerText":""},"UA44BT/EVA-1-017":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【登場時】查看4張自己卡組上面的卡片。從中公開最多1張擁有【獲得觸發】的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA44BT/EVA-1-016":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-019":{"name":"第3新東京市市立第一中學","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張能源需求3以下的黃色角色卡加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-025":{"name":"綾波零（暫稱）","effectText":"【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":""},"UA44BT/EVA-1-026":{"name":"綾波零（暫稱）","effectText":"在我方回合開始時，若這張角色卡下面有3張以上背面朝上的卡片時，使這張角色卡退場。\n【我方回合中】這張角色卡下面每有1張背面朝上的卡片，這張角色卡BP+500。\n【攻擊時】將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。","triggerText":""},"UA44BT/EVA-1-024":{"name":"綾波零（暫稱）","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-021":{"name":"和碇同學在一起的時候感覺很溫暖","effectText":"選擇1張自己場上的角色卡，置為活動。若選擇的角色卡為〈綾波零〉時，選擇最多1張自己的AP卡，置為活動。若自己場上有黃色以外的〈碇真嗣〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-022":{"name":"你挺有趣的嘛","effectText":"選擇1張對手前線的角色卡，轉為休息。若選擇的角色卡不持有【突襲】時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-023":{"name":"泡澡可是對生命的洗滌喔","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44BT/EVA-1-032":{"name":"碇源堂","effectText":"【登場時】從自己手牌或場外，使最多1張能源需求2以下的紫色〔〈綾波零（暫稱）〉或〈渚薰〉或場域卡〕以休息狀態在自己場上登場。若從場外登場時，將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-031":{"name":"碇真嗣","effectText":"手牌中與場外的這張卡片的能源需求減少【紫×2】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【我方回合中】若自己場上有能源需求5以上的其他卡片時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-030":{"name":"碇真嗣","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】將最多1張自己場上卡片下面的背面朝上卡片放置在場外。\n【啟動主要】【若在能源線時】將這張角色卡移動至前線。","triggerText":""},"UA44BT/EVA-1-028":{"name":"碇真嗣","effectText":"【啟動主要】【轉為休息】將1張自己卡組上面的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-027":{"name":"碇真嗣","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-029":{"name":"碇真嗣","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA44BT/EVA-1-038":{"name":"渚薰","effectText":"【登場時】查看4張自己卡組上面的卡片。從其中公開最多1張〈碇真嗣〉或〈新世紀福音戰士 第13號機〉或〈莉莉絲〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA44BT/EVA-1-037":{"name":"渚薰","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA44BT/EVA-1-036":{"name":"福音戰士 Mark.09","effectText":"【突襲】〈綾波零（暫稱）〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+500。\n【登場時】抽2張卡片，並將2張自己的手牌放置在場外。\n【退場時】可將1張自己的手牌放置在場外。若有執行此動作時，使這張卡片以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-033":{"name":"新世紀福音戰士 初號機（蓋烏斯之槍）","effectText":"【突襲】〈碇真嗣〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】抽1張卡片，並從自己手牌中，使最多1張消耗AP1且不持有【突襲】的紫色角色卡以活動狀態在自己場上登場。\n【啟動主要】【若在前線時】【每回合1】使1張自己前線其他的角色卡退場。若有執行此動作時，發動這張角色卡的【登場時】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-035":{"name":"福音戰士 Mark.06","effectText":"【突襲】〈渚薰〉置為活動，並可移動至前線\n【登場時】抽1張卡片。選擇最多1張自己或對手場上的卡片，將該張卡片下面的所有卡片放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-034":{"name":"新世紀福音戰士 第13號機","effectText":"【突襲】〈碇真嗣〉／〈渚薰〉置為活動，並可移動至前線\n【我方回合中】依據自己場外的卡片張數，這張角色卡獲得以下所有效果。\n・13張以上：BP+1000與【傷害（2）】\n・26張以上：BP+1000與【衝擊（4）】\n【啟動主要】【若在前線時】【每回合1】將1張自己場上卡片下面的背面朝上卡片放置在場外。若有執行此動作時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-044":{"name":"葛城美里","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-043":{"name":"福音戰士新2號機","effectText":"【突襲】〈式波・明日香・蘭格雷〉置為活動，並可移動至前線\n這張角色卡攻擊結束時，可將4張自己場外的［特徵：WILLE］放置在移除區。若有執行此動作時，將這張角色卡置為活動，這張角色卡在這個回合中，獲得BP+3000與「BP3000以下的角色卡無法防禦這張角色卡。」，並將這張角色卡的突襲來源卡放置在場外。\n【登場時】若對手前線有2張以上BP比原本BP還低的角色卡時，這張角色卡在這個回合中，獲得【雙重攻擊】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-042":{"name":"新世紀福音戰士 改8號機","effectText":"【突襲】〈真希波・真理・伊拉絲多莉亞斯〉置為活動，並可移動至前線\n這張角色卡下面每有1張背面朝上卡片，這張角色卡BP+500。\n【登場時】抽2張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【若在前線時】【每回合1】選擇1張對手前線的角色卡，在這個回合中，BP-1000。若以此效果使對手角色卡的BP變為0以下時，可將最多1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-039":{"name":"渚薰","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+500。\n【啟動主要】【若在能源線時】選擇1張自己能源線休息狀態的〈碇真嗣〉，置為活動。若有執行此動作時，將這張角色卡置為活動。〈渚薰〉的這個效果每回合僅可發動1次。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA44BT/EVA-1-040":{"name":"赤木律子","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA44BT/EVA-1-041":{"name":"新世紀福音戰士 改2號機","effectText":"【突襲】〈式波・明日香・蘭格雷〉置為活動，並可移動至前線\n若這張角色卡將退場時，可改為將突襲狀態最上面的這張卡片放置在場外。\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-050":{"name":"式波・明日香・蘭格雷","effectText":"【啟動主要】【若在前線時】【每回合1】將1張自己手牌的［特徵：WILLE］放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-049":{"name":"式波・明日香・蘭格雷","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-047":{"name":"北上綠","effectText":"若對手場上有黃色或紅色卡片時，手牌中這張卡片的能源需求減少【紫×１】。","triggerText":""},"UA44BT/EVA-1-045":{"name":"葛城美里","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】選擇最多1張自己場上能源需求5以上的紫色角色卡，在這個回合中，賦予其【衝擊（1）】或【傷害（2）】。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-046":{"name":"葛城美里","effectText":"【啟動主要】【轉為休息】將1張自己手牌的［特徵：WILLE］放置在場外。若有執行此動作時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-048":{"name":"式波・明日香・蘭格雷","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-055":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：WILLE］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA44BT/EVA-1-056":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【啟動主要】【每回合1】僅限在這張角色卡登場的回合中可發動。選擇1張自己場上的［特徵：WILLE］，在這個回合中，賦予其「這張角色卡攻擊後沒有被防禦時，抽最多1張卡片。」。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA44BT/EVA-1-053":{"name":"AAA Wunder","effectText":"【突襲】〈葛城美里〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得「對手必須盡可能防禦這張角色卡的攻擊。」。\n【退場時】查看5張自己卡組上面的卡片。從中公開最多2張能源需求5以上的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-051":{"name":"式波・明日香・蘭格雷","effectText":"【我方回合中】這張角色卡BP+1000。\n【登場時】抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-054":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-052":{"name":"鈴原櫻","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己場外將1張〈碇真嗣〉或［特徵：WILLE］加入手牌。","triggerText":""},"UA44BT/EVA-1-062":{"name":"歡迎回來 碇真嗣。我一直在等你","effectText":"從自己場外使1張紫色的〈碇真嗣〉以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-061":{"name":"謹遵吩咐――公主殿下！","effectText":"選擇最多1張對手前線的角色卡，在這個回合中，BP-3000。選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-059":{"name":"不錯嘛，和你一起的音色…","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44BT/EVA-1-060":{"name":"但是請別再駕駛EVA了","effectText":"將1張自己前線的活動狀態角色卡轉為休息。若有執行此動作時，抽3張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-057":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【攻擊時】可以將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求3以下消耗AP1的紫色〈碇真嗣〉以休息狀態在自己場上登場。","triggerText":""},"UA44BT/EVA-1-058":{"name":"莉莉絲","effectText":"【登場時】將2張自己卡組上面的卡片以背面朝上放置在這張場域卡的下面。\n【啟動主要】【轉為休息】僅限在這張場域卡下面沒有背面朝上卡片時可發動。使這張場域卡退場。\n【退場時】將最多1張自己場外的角色卡加入手牌。若為我方回合中，可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己的AP卡，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-066":{"name":"哼。那樣子――連笨蛋都算不上…就是個小鬼","effectText":"選擇1張對手前線的角色卡，在這個回合中，BP-1000。選擇最多1張自己的AP卡，置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-063":{"name":"蓋烏斯之槍","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。若自己場上有〈碇真嗣〉或〈新世紀福音戰士 初號機（蓋烏斯之槍）〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-064":{"name":"收到收到","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44BT/EVA-1-068":{"name":"赤木律子","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA44BT/EVA-1-067":{"name":"我知道這很亂來","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44BT/EVA-1-065":{"name":"絕望之槍 朗基努斯","effectText":"若自己場上有〈碇真嗣〉或〈新世紀福音戰士 第13號機〉時，手牌中這張卡片的消耗AP-1。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-071":{"name":"綾波零","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【啟動主要】【每回合1】僅限自己場外有2種以上能源需求各不相同的紅色〈綾波零〉時可發動。這張角色卡直到下一個我方回合開始前，產生能源+【紅】。","triggerText":""},"UA44BT/EVA-1-074":{"name":"碇真嗣","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【登場時】查看1張自己卡組上面的卡片。將該張卡片放置在自己卡組的上面或場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA44BT/EVA-1-069":{"name":"綾波零","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA44BT/EVA-1-073":{"name":"碇真嗣","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-072":{"name":"碇源堂＆冬月耕造","effectText":"【啟動主要】【轉為休息】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA44BT/EVA-1-070":{"name":"綾波零","effectText":"【登場時】查看3張自己卡組上面的卡片。將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-080":{"name":"新世紀福音戰士 零號機","effectText":"【突襲】〈綾波零〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【使這張卡片退場】選擇最多1張對手前線的角色卡，使其退場。在這個回合中，下一張從手牌中使用〈碇真嗣〉或卡片名稱包含「初號機」的角色卡的能源需求減少【紅×1】，消耗AP-1。\n【退場時】抽2張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-075":{"name":"碇真嗣","effectText":"【啟動主要】【若在場外時】【將2張手牌放置在場外】【支付1AP】僅限滿足這張卡片的能源需求時可發動。使場外的這張卡片以休息狀態在自己場上登場。\n【登場時】可以選擇1張與這張角色卡位於不同戰線的自己角色卡，與這張角色卡互相交換位置。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA44BT/EVA-1-078":{"name":"新世紀福音戰士 3號機","effectText":"【登場時】可以使1張自己場上的〈式波・明日香・蘭格雷〉退場。若有執行此動作時，將這張角色卡置為活動，並抽1張卡片。","triggerText":""},"UA44BT/EVA-1-077":{"name":"新世紀福音戰士 暫設5號機","effectText":"【突襲】〈真希波・真理・伊拉絲多莉亞斯〉置為活動，並可移動至前線\n【登場時】若自己場上有4張以上不具備【觸發】的卡片時，抽1張卡片。\n【退場時】選擇最多1張對手前線的角色卡，轉為休息。","triggerText":""},"UA44BT/EVA-1-076":{"name":"伊吹摩耶","effectText":"若對手場上有黃色或紫色卡片時，手牌中這張卡片的能源需求減少【紅×1】。","triggerText":""},"UA44BT/EVA-1-079":{"name":"新世紀福音戰士 初號機 擬似神化","effectText":"【突襲】〈碇真嗣〉置為活動，並可移動至前線\n依據這張角色卡下面背面朝上卡片的張數，這張角色卡獲得以下效果。\n・0張：【我方回合中】這張角色卡BP+5000與【衝擊（3）】\n・4張以上：這張角色卡不會被對手的觸發效果選擇。\n這張角色卡攻擊結束時，查看這張角色卡下面的背面朝上卡片，公開最多2張並加入手牌。若有加入2張手牌時，將這張角色卡置為活動。\n【登場時】從自己場外，將各能源需求的紅色〈綾波零〉最多各1張，以背面朝上放置在這張角色卡下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-085":{"name":"葛城美里","effectText":"【登場時】從以下選擇1項。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n・選擇最多1張自己場上的角色卡，移動至別的線。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-083":{"name":"加持良治","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA44BT/EVA-1-081":{"name":"新世紀福音戰士 2號機","effectText":"【突襲】〈式波・明日香・蘭格雷〉置為活動，並可移動至前線\n【登場時】使最多1張自己手牌中能源需求『0』以下不持有【觸發】的紅色角色卡以休息狀態在自己場上登場。每有1張自己場上不持有【觸發】的卡片，藉由此效果登場的角色卡的能源需求範圍+1。若自己場上有4張以上不持有【觸發】的卡片時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-084":{"name":"葛城美里","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-086":{"name":"式波・明日香・蘭格雷","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":""},"UA44BT/EVA-1-082":{"name":"新世紀福音戰士 2號機 獸化","effectText":"【突襲】〈真希波・真理・伊拉絲多莉亞斯〉置為活動，並可移動至前線\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【每回合1】這張角色卡攻擊結束時，若對手前線有角色卡時，可將2張自己手牌中不持有【觸發】的卡片放置在場外。若有執行此動作時，將這張角色卡置為活動，並在這個回合中，BP+3000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA44BT/EVA-1-091":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【登場時】查看3張自己卡組上面的卡片。從其中公開最多1張卡片名稱包含「2號機」的角色卡或不持有【觸發】的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA44BT/EVA-1-088":{"name":"式波・明日香・蘭格雷","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【登場時】查看1張自己卡組上面的卡片，若該張卡片為不持有【觸發】的卡片時，可公開並加入手牌。若不加入手牌時，將該張卡片放置在自己卡組的上面。","triggerText":""},"UA44BT/EVA-1-090":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【登場時】查看2張自己卡組上面的卡片。從其中將最多1張不持有【觸發】的紅色卡片放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":""},"UA44BT/EVA-1-089":{"name":"片片","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA44BT/EVA-1-092":{"name":"真希波・真理・伊拉絲多莉亞斯","effectText":"【對方回合中】當自己的生命區中不持有【觸發】的卡片被放置在場外時，若自己場上有4張以上不持有【觸發】的卡片時，可將活動狀態的這張角色卡轉為休息。若有執行此動作時，將最多1張被放置在場外的該卡片加入手牌。〈真希波・真理・伊拉絲多莉亞斯〉的這個效果每回合僅可發動1次。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA44BT/EVA-1-087":{"name":"式波・明日香・蘭格雷","effectText":"【對方回合中】當自己的生命區中不持有【觸發】的卡片被放置在場外時，可將這張角色卡在這個回合中，BP+2000。〈式波・明日香・蘭格雷〉的這個效果每回合僅可發動1次。","triggerText":""},"UA44BT/EVA-1-095":{"name":"大輸出功率型第2次試作自走460mm陽電子炮","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈碇真嗣〉或卡片名稱包含「初號機」的角色卡時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-093":{"name":"作戰室（屋島作戰）","effectText":"【登場時】查看5張自己卡組上面的卡片。從其中公開最多1張卡片名稱包含「零號機」或「初號機」的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【每回合1】選擇1張自己能源線的卡片，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA44BT/EVA-1-098":{"name":"超電磁洋弓槍","effectText":"選擇1張對手前線『BP2000』以下的角色卡，使其退場。自己場上每有1張不持有【觸發】的卡片，此效果可選擇的角色卡BP範圍+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-097":{"name":"和別人說說心裡話還挺愉快的","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44BT/EVA-1-094":{"name":"綾波！把手給我…！！過來！！","effectText":"這張卡片僅限自己場上有〈碇真嗣〉或卡片名稱包含「初號機」的角色卡時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。將最多1張自己場外的〈綾波零〉，以背面朝上放置在自己場上沒有背面朝上卡片的〈碇真嗣〉下面。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA44BT/EVA-1-096":{"name":"傀儡系統啟動","effectText":"選擇1張自己場上持有【突襲】且非突襲狀態的角色卡，置為活動，並在這個回合中，給予其BP+1000與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[抽卡] 抽1張卡片。"},"UA44BT/EVA-1-100":{"name":"微笑就可以了","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA44BT/EVA-1-099":{"name":"不入虎穴 焉得虎子！","effectText":"抽2張卡片。若自己場上有4張以上不持有【觸發】的卡片時，再抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-001":{"name":"霧崎恭子","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己前線的〈倫・艾爾西・裘利亞〉。若有執行此動作時，使該角色卡與這張角色卡在這個回合中BP+1000，且這張角色卡在這個回合中獲得【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-002":{"name":"古手川唯","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA45BT/TLR-1-004":{"name":"提亞悠・露娜提克","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）","triggerText":""},"UA45BT/TLR-1-003":{"name":"西連寺春菜","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA45BT/TLR-1-008":{"name":"御門涼子","effectText":"【登場時】將自己所有的手牌放置在場外，並抽5張卡片。","triggerText":""},"UA45BT/TLR-1-007":{"name":"魔法少女恭子","effectText":"這張卡片也視為〈霧崎恭子〉。\n【登場時】若對手的生命值在4以上時，可支付1AP。若有執行此動作時，對手受到1點傷害。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-010":{"name":"茉茉・貝莉雅・戴比路克","effectText":"【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面。","triggerText":""},"UA45BT/TLR-1-006":{"name":"娜娜·阿絲達·戴比路克","effectText":"【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，將最多1張自己場外的〈黑咲芽亞〉加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-009":{"name":"村雨靜","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張對手前線BP4000以下的角色卡，轉為休息。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-005":{"name":"提亞悠・露娜提克","effectText":"【登場時】從自己手牌中，使最多1張能源需求3以下消耗AP1的黃色〈金色闇影〉以休息狀態在自己場上登場。","triggerText":""},"UA45BT/TLR-1-012":{"name":"結城美柑","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張能源需求3以下的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-015":{"name":"結城美柑","effectText":"【突襲】〈結城美柑〉置為活動，並可移動至前線\n【登場時】抽1張卡片。選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n【啟動主要】【轉為休息】選擇1張自己場上能源需求3以下的其他角色卡，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。〈結城美柑〉的這個效果每回合僅可發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-014":{"name":"結城美柑","effectText":"【登場時】【若在能源線時】若自己前線有2張以上能源需求3以下的角色卡時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA45BT/TLR-1-011":{"name":"結城美柑","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-016":{"name":"菈菈・薩塔琳・戴比路克","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA45BT/TLR-1-013":{"name":"結城美柑","effectText":"【登場時】選擇最多1張自己場上能源需求3以下的其他角色卡，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":""},"UA45BT/TLR-1-020":{"name":"黑咲芽亞","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-021":{"name":"黑咲芽亞","effectText":"【登場時】若自己場上有〈涅墨西斯〉時，選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-022":{"name":"黑咲芽亞","effectText":"【我方回合中】這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-018":{"name":"倫・艾爾西・裘利亞","effectText":"【攻擊時】若自己前線有〈霧崎恭子〉時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-017":{"name":"倫・艾爾西・裘利亞","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-019":{"name":"黑咲芽亞","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-024":{"name":"金色闇影","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-023":{"name":"黑咲芽亞","effectText":"【突襲】〈黑咲芽亞〉置為活動，並可移動至前線\n這張角色卡若在前線時也可產生能源。\n【登場時】選擇最多1張對手前線的角色卡，使其轉為休息。若選擇的角色卡的BP在2500以上時，該張角色卡直到下一個我方回合開始前，BP-2000。\n【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-025":{"name":"金色闇影","effectText":"若對手場上有BP4000以上的角色卡時，這張角色卡BP+500。","triggerText":""},"UA45BT/TLR-1-027":{"name":"金色闇影","effectText":"【我方回合中】若自己場上有〈結城美柑〉時，這張角色卡BP+1000。\n【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，使這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-028":{"name":"金色闇影","effectText":"【突襲】〈金色闇影〉置為活動，並可移動至前線\n【我方回合中】若自己場上有〈結城美柑〉時，這張角色卡BP+1500。\n【每回合1】這張角色卡的攻擊結束時，可以將2張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動，並在這個回合中，獲得【衝擊（1）】。\n【登場時】抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-026":{"name":"金色闇影","effectText":"【啟動主要】【每回合1】將1張自己前線活動狀態的其他角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-032":{"name":"涅墨西斯","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：變身兵器］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA45BT/TLR-1-031":{"name":"涅墨西斯","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-029":{"name":"闇影","effectText":"這張卡片也視為〈金色闇影〉。\n這張角色卡以活動狀態登場。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【我方回合中】這張角色卡BP+1000。\n這張角色卡攻擊後戰勝時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-030":{"name":"闇影","effectText":"這張卡片也視為〈金色闇影〉。\n【突襲】〈金色闇影〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】選擇最多2張對手前線BP合計6000以下的角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-033":{"name":"涅墨西斯","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA45BT/TLR-1-034":{"name":"涅墨西斯","effectText":"【登場時】抽1張卡片。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA45BT/TLR-1-040":{"name":"出包王女","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA45BT/TLR-1-039":{"name":"暗物質","effectText":"選擇1張對手前線『BP3000以下』的角色卡，放置在移除區。若自己場上有〈涅墨西斯〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA45BT/TLR-1-037":{"name":"我討厭色色的事。","effectText":"選擇1張對手前線『BP3000』以下的角色卡，使其退場。若自己場上有〈金色闇影〉時，自己前線每有1張能源需求3以下的角色卡，這個效果可選擇的角色卡BP範圍+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA45BT/TLR-1-038":{"name":"精神侵入","effectText":"抽2張卡片。對手公開其所有手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-035":{"name":"涅墨西斯","effectText":"【突襲】〈涅墨西斯〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n這張角色卡的產生能源+【黃】【黃】。\n【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：變身兵器］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-036":{"name":"露娜提克號","effectText":"若自己前線有〈金色闇影〉時，這張場域卡的產生能源+【黃】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-046":{"name":"古手川唯","effectText":"這張角色卡攻擊後沒有被防禦時，抽1張卡片，並將1張自己的手牌放置在場外。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA45BT/TLR-1-043":{"name":"九条凜","effectText":"使這張角色卡以活動狀態在場上登場。\n【登場時】從自己手牌中，使最多1張紅色的〔〈天条院沙姫〉或能源需求1以下的角色卡〕以休息狀態在自己場上登場。若自己場上有〈天条院沙姫〉時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-045":{"name":"古手川唯","effectText":"若自己場上有5張以上其他的卡片時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-044":{"name":"古手川唯","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-041":{"name":"美柑的手料理","effectText":"自己前線所有的角色卡，在這個回合中，BP+1000。抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-042":{"name":"新井紗彌香","effectText":"【登場時】【退場時】查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-052":{"name":"西連寺春菜","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，『BP+1000』。若自己場上擁有5張以上其他卡片時，則替換成『BP+2000』。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-049":{"name":"西連寺春菜","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-050":{"name":"西連寺春菜","effectText":"【登場時】若自己場上擁有5張以上其他卡片時，抽1張卡片。","triggerText":""},"UA45BT/TLR-1-051":{"name":"西連寺春菜","effectText":"【登場時】使最多1張自己手牌中能源需求2以下消耗AP1的紅色角色卡以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-047":{"name":"古手川唯","effectText":"【登場時】選擇最多1張對手前線『BP2000以下』的角色卡，在這個回合中，獲得「這張角色卡無法防禦。」。若自己場上擁有5張以上其他卡片時，則替換成『BP3000以下』。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA45BT/TLR-1-048":{"name":"古手川唯","effectText":"【突襲】〈古手川唯〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得「【攻擊時】選擇最多1張BP比這張角色卡還低的對手前線角色卡，使其退場。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-053":{"name":"西連寺春菜","effectText":"【突襲】〈西連寺春菜〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】選擇1張〈西連寺春菜〉以外自己前線的角色卡。若有執行此動作時，將該張角色卡在這個回合中BP+1000，並抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-057":{"name":"天條院沙姬","effectText":"【登場時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-054":{"name":"澤田未央","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA45BT/TLR-1-055":{"name":"賽菲・米迦菈・戴比路克","effectText":"【登場時】從以下選擇1項。\n・選擇最多1張自己場上卡片名稱包含「戴比路克」的其他角色卡，在這個回合中，獲得「這張角色卡不會被對手的效果選擇。」。\n・選擇最多1張對手前線BP4500以上的角色卡，在這個回合中，獲得「這張角色卡無法防禦卡片名稱包含「戴比路克」的角色卡。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-056":{"name":"席琳","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA45BT/TLR-1-058":{"name":"娜娜・阿絲達・戴比路克","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-060":{"name":"娜娜・阿絲達・戴比路克","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】若自己前線有空格時，選擇最多1張自己能源線卡片名稱包含「戴比路克」的其他角色卡，移動至前線。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-059":{"name":"娜娜・阿絲達・戴比路克","effectText":"【退場時】若自己場上擁有〈茉茉・貝莉雅・戴比路克〉時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-061":{"name":"娜娜・阿絲達・戴比路克","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】若自己場上擁有〈茉茉・貝莉雅・戴比路克〉時，這張角色卡BP+1500。","triggerText":""},"UA45BT/TLR-1-062":{"name":"娜娜・阿絲達・戴比路克","effectText":"【突襲】〈娜娜・阿絲達・戴比路克〉置為活動，並可移動至前線\n【攻擊時】從以下選擇最多1項。在這個回合中〈娜娜・阿絲達・戴比路克〉已選擇的效果無法選擇。\n・使最多1張自己手牌中能源需求3以下卡片名稱包含「戴比路克」的紅色角色卡以休息狀態在自己場上登場。\n・將最多1張自己場外能源需求2以下的〈茉茉・貝莉雅・戴比路克〉加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-063":{"name":"藤崎綾","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。若選擇的角色卡為〈天條院沙姬〉時，將該張角色卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-064":{"name":"籾岡里紗","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA45BT/TLR-1-067":{"name":"茉茉・貝莉雅・戴比路克","effectText":"若自己場上有〈娜娜・阿絲達・戴比路克〉時，這張角色卡獲得【雙重防禦】與【衝擊無效】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-066":{"name":"茉茉・貝莉雅・戴比路克","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「戴比路克」的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA45BT/TLR-1-068":{"name":"茉茉・貝莉雅・戴比路克","effectText":"【登場時】若自己場上有〈娜娜・阿絲達・戴比路克〉時，抽1張卡片。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA45BT/TLR-1-065":{"name":"茉茉・貝莉雅・戴比路克","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA45BT/TLR-1-069":{"name":"茉茉・貝莉雅・戴比路克","effectText":"【突襲】〈茉茉・貝莉雅・戴比路克〉置為活動，並可移動至前線\n【攻擊時】從以下選擇最多1項。在這個回合中，無法選擇〈茉茉・貝莉雅・戴比路克〉已選擇過的效果。\n・查看3張自己卡組上面的卡片。公開其中最多1張卡片名稱包含「戴比路克」的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n・可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上的〈娜娜・阿絲達・戴比路克〉，置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-070":{"name":"結城美柑","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-072":{"name":"菈菈・薩塔琳・戴比路克","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"UA45BT/TLR-1-075":{"name":"菈菈・薩塔琳・戴比路克","effectText":"【突襲】〈菈菈・薩塔琳・戴比路克〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】抽1張卡片。可以將1張自己場上其他的角色卡放回手牌。若有執行此動作時，使最多1張自己手牌中能源需求4以下消耗AP1的紅色角色卡以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA45BT/TLR-1-073":{"name":"菈菈・薩塔琳・戴比路克","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【對方回合中】這張角色卡BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-071":{"name":"菈菈・薩塔琳・戴比路克","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-076":{"name":"金色闇影","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-074":{"name":"菈菈・薩塔琳・戴比路克","effectText":"【衝擊無効】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）\n【登場時】可以將1張自己場上其他的角色卡放回手牌。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA45BT/TLR-1-080":{"name":"樂園計畫","effectText":"查看5張自己卡組上面的卡片。從中公開最多3張不同卡片名稱的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-081":{"name":"真是恬不知恥!!","effectText":"從以下選擇1項。\n・選擇1張對手前線BP4000以下的角色卡，使其退場。\n・選擇最多1張自己場上的〈古手川唯〉，在這個回合中，獲得BP+2000與【衝擊（1）】。抽1張卡片。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA45BT/TLR-1-082":{"name":"蹦蹦跳跳傳送君","effectText":"若自己場上有〈菈菈・薩塔琳・戴比路克〉時，手牌中這張卡片的消耗AP-1。\n選擇1張對手前線BP5000以下的角色卡，放置在對手卡組下面。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA45BT/TLR-1-079":{"name":"出包王女","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA45BT/TLR-1-077":{"name":"彩南高中","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】抽1張卡片。之後，使最多1張自己手牌中能源需求3以下消耗AP1的紅色角色卡以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA45BT/TLR-1-078":{"name":"加農砲花","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈茉茉・貝莉雅・戴比路克〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-003":{"name":"座村伊織","effectText":"【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-002":{"name":"漣伯理","effectText":"【啟動主要】【轉為休息】 【每回合1】在這個回合中，這張角色卡的產生能源+【紫】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA46BT/KGR-1-005":{"name":"座村伊織","effectText":"【登場時】【若在能源線時】將這張角色卡置為活動。\n【啟動主要】【轉為休息】僅限自己場上有〈六平千鉱〉或［特徵：卷墨］時可發動。從以下選擇1項。\n・查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面。\n・將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA46BT/KGR-1-001":{"name":"漣京羅","effectText":"【登場時】查看5張自己卡組上面的卡片，將3張以背面朝上放置在這張角色卡下面。其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【若在前線時】 【支付1AP】 【每回合1】公開最多1張這張角色卡下面或自己場上〈樂座市〉下面的背面朝上卡片，『將其加入手牌，並將這張角色卡置為活動』。若公開的卡片為［特徵：濤］時，可替換成『以活動狀態在自己場上登場』。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-006":{"name":"座村伊織","effectText":"這張卡片僅限自己場上有〈六平千鉱〉或［特徵：卷墨］時才能發動突襲。\n【突襲】〈座村伊織〉置為活動，並可移動至前線\n【若在前線時】對手的角色卡攻擊時，可「查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面。」。\n【登場時】查看3張自己卡組上面的卡片，將最多1張加入手牌，其餘卡片依任意順序放置在自己卡組的上面。\n【防禦時】可將1張自己卡組上面的卡片放置在場外。若以此效果將〈座村伊織〉或［特徵：居合白禊流］放置在場外時，這張角色卡在這場對戰中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA46BT/KGR-1-004":{"name":"座村伊織","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-007":{"name":"柴登吾","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA46BT/KGR-1-008":{"name":"雙城嚴一","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-010":{"name":"雙城嚴一","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【支付1AP】【每回合1】從以下選擇1項。\n・抽1張卡片。\n・若這張角色卡位於前線時，查看3張自己卡組上面的卡片，公開其中最多1張〈雙城嚴一〉或〈刳雲鳴〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若沒有加入手牌時，抽1張卡片。","triggerText":""},"UA46BT/KGR-1-009":{"name":"雙城嚴一","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-011":{"name":"雙城嚴一","effectText":"【突襲】〈雙城嚴一〉置為活動，並可移動至前線\n【登場時】抽1張卡片。選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】將最多3張自己的手牌放置在場外，選擇最多『1張』BP比原本的BP還低的對手前線角色卡，在這個回合中，BP-2000。因此效果每將1張卡片放置在場外，可選擇的角色卡張數+1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA46BT/KGR-1-012":{"name":"六平千鉱","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-015":{"name":"六平千鉱","effectText":"【突襲】〈六平千鉱〉置為活動，並可移動至前線\n這張角色卡不會被BP2000以下的角色卡防禦。\n【登場時】抽2張卡片，並將1張自己的手牌放置在自己卡組的上面。\n【攻擊時】可將1張自己卡組上面的卡片放置在場外。若〈座村伊織〉或持有［特徵：居合白禊流］的角色卡被放置在場外時，這張角色卡在這個攻擊中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。若〈居合白禊流〉被放置在場外時，可「將2張自己的手牌放置在場外，並無視其需求能源且不支付AP來使用該事件卡。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA46BT/KGR-1-017":{"name":"漆羽洋児","effectText":"這張角色卡不會被BP2000以下的角色卡防禦。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-016":{"name":"漆羽洋児","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-013":{"name":"六平千鉱","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-018":{"name":"漆羽洋児","effectText":"【我方回合中】若自己場上有〈六平千鉱〉或〈座村清市〉時，這張角色卡BP+1000。\n【退場時】抽1張卡片。若為對方回合中，將1張自己的手牌放置在場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA46BT/KGR-1-014":{"name":"六平千鉱","effectText":"【登場時】選擇最多1張自己場上的〈六平千鉱〉，在這個回合中，獲得BP+1000與【衝擊（1）】。","triggerText":""},"UA46BT/KGR-1-024":{"name":"漣珠紀","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張〈漣京羅〉或［特徵：濤］或〈樂座市〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-022":{"name":"漣圓慈","effectText":"【登場時】若在這個回合中自己曾因角色卡的效果支付AP時，選擇最多1張自己場上的〈漣京羅〉或［特徵：濤］，在這個回合中，BP+2000。","triggerText":""},"UA46BT/KGR-1-021":{"name":"座村清市","effectText":"使這張角色卡以活動狀態在場上登場。\n【對方回合中】【若在前線時】自己場上的〈座村伊織〉不會被對手的效果選擇，且不會被【狙擊】指定。\n【啟動主要】【若在前線時】使1張自己場上的角色卡退場。若有執行此動作時，使該張卡片以活動狀態在自己場上登場。〈座村清市〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-023":{"name":"漣宗也","effectText":"【登場時】若在這個回合中自己曾因角色卡的效果支付AP時，可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，移動至能源線。〈漣宗也〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-019":{"name":"座村清市","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA46BT/KGR-1-020":{"name":"座村清市","effectText":"當這張卡片因自己的效果從自己卡組放置在場外時，可將這張卡片加入手牌。\n【啟動主要】【將2張手牌放置在場外】【每回合1】這張角色卡在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-030":{"name":"幽","effectText":"這張角色卡無法在前線登場，且無法在移動階段進行移動。\n【啟動主要】【若在能源線時】【將1張手牌放置在場外】僅限這張角色卡為活動狀態，且在這個回合中曾因自己角色的效果支付AP時才可發動。將1張自己的AP卡置為活動。將這張角色卡移動至前線。這張角色卡在這個回合中，獲得【衝擊（1）】。〈幽〉的這個效果每回合僅可發動1次。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA46BT/KGR-1-027":{"name":"斗斗","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】僅限在這個回合中自己曾因角色卡的效果支付AP時可發動。選擇1張自己的AP卡，置為活動。〈斗斗〉的這個效果每回合僅可發動1次。","triggerText":""},"UA46BT/KGR-1-028":{"name":"晝彥","effectText":"【攻擊時】若在這個回合中，曾因自己角色的效果支付AP時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-029":{"name":"晝彥","effectText":"【登場時】可支付1AP。若有執行此動作時，使這張角色卡置為活動，並選擇最多1張對手前線的角色卡，使其轉為休息。若在這個回合中，也因自己其他角色的效果支付了AP時，選擇的角色卡下一次無法置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-025":{"name":"漣天理","effectText":"【啟動主要】【每回合1】僅限在這個回合中自己曾因角色卡的效果支付AP時可發動。這張角色卡在這個回合中，獲得「攻擊階段結束時，使這張角色卡退場。」、BP+2000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-026":{"name":"久久李","effectText":"【攻擊時】從以下選擇1項。\n・將1張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。\n・可將這張角色卡下面所有背面朝上的卡片放置在場外。若有執行此動作時，每有1張以此效果放置在場外的卡片，這張角色卡在這個回合中BP+1000。若放置了2張以上時，這張角色卡在這個回合中再獲得【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-033":{"name":"郎","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中1張〈六平千鉱〉或〈座村伊織〉或擁有［特徵：居合白禊流］的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA46BT/KGR-1-032":{"name":"杢","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】選擇1張自己場上的〈六平千鉱〉或〈座村伊織〉或［特徵：居合白禊流］，直到下一個我方回合開始前，獲得「對手無法以角色的效果選擇這張角色卡。」。","triggerText":""},"UA46BT/KGR-1-031":{"name":"炭","effectText":"【登場時】選擇1張自己場上的〈六平千鉱〉或〈座村伊織〉或［特徵：居合白禊流］，將其移動至另一條戰線，或與另一條戰線的1張角色卡交換位置。","triggerText":""},"UA46BT/KGR-1-034":{"name":"樂座市","effectText":"這張場域卡以活動狀態登場。\n【啟動主要】【轉為休息】從以下選擇1項。\n・將1張自己卡組上面的卡片以背面朝上放置在這張場域卡的下面。\n・將1張自己的手牌放置在場外。若有執行此動作時，公開這張場域卡下面所有背面朝上的卡片，並『加入手牌』。對手可將2張自身的手牌放置在場外。若對手如此做時，則替換成『放置在場外』。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-035":{"name":"雫天石","effectText":"選擇1張自己場上的角色卡，在這個回合中，獲得「攻擊階段結束時，使這張角色卡退場。」與BP+3000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）與【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-037":{"name":"毘灼","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA46BT/KGR-1-038":{"name":"想守護校園生活","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA46BT/KGR-1-041":{"name":"勾罪 蜈","effectText":"當這張卡片因自己場上〈漣京羅〉的效果公開並加入手牌時，可無視能源需求且不支付AP來使用這張卡片。\n選擇1張對手前線『BP4000以下』的角色卡，使其退場。若自己場上有〈漣京羅〉或〈樂座市〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-040":{"name":"刳雲 鳴","effectText":"選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。之後，若自己場上有〈雙城嚴一〉時，選擇最多1張對手前線BP4000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-039":{"name":"居合白禊流","effectText":"選擇1張對手前線『BP2000以下』的角色卡，使其退場。若自己場上有〈六平千鉱〉與〔〈座村伊織〉或［特徵：居合白禊流］〕時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-036":{"name":"血鶴","effectText":"若自己場上有〈晝彥〉時，手牌中這張卡片的能源需求減少【紫×2】。\n選擇最多1張對手前線『BP4000以下』的角色卡，使其退場。若在這個回合中，曾因自己角色的效果支付AP時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-042":{"name":"鏡凪夏爾","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【退場時】可將這張卡片放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-047":{"name":"漣伯理","effectText":"這張卡片僅限自己場上有〈六平千鉱〉或〈柴登吾〉時才能發動突襲。\n【突襲】〈漣伯理〉置為活動，並可移動至前線\n【登場時】從以下選擇1項。\n・將2張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。\n・選擇最多1張對手前線的角色卡，移動至能源線。\n【啟動主要】【若在前線時】【每回合1】將1張這張角色卡下面的背面朝上卡片加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA46BT/KGR-1-045":{"name":"漣伯理","effectText":"若自己前線有〈六平千鉱〉或〈柴登吾〉時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-046":{"name":"漣伯理","effectText":"【登場時】若自己場上有〈六平千鉱〉或〈柴登吾〉時，查看3張自己卡組上面的卡片，將其中最多1張以背面朝上放置在這張角色卡下面，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-044":{"name":"漣伯理","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-043":{"name":"鏡凪夏爾","effectText":"因自己〈六平千鉱〉的效果，從自己手牌中將〈六平千鉱〉或〈鏡凪夏爾〉放置在場外時，可將活動狀態的這張角色卡轉為休息。若有執行此動作時，將最多1張被放置在場外的該卡片加入手牌。〈鏡凪夏爾〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-053":{"name":"Mr.閃電","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紅】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA46BT/KGR-1-051":{"name":"緋魚","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA46BT/KGR-1-052":{"name":"緋魚","effectText":"【登場時】查看4張自己卡組上面的卡片。將其中最多1張放置在自己卡組的上面，其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-050":{"name":"柴登吾","effectText":"在我方攻擊階段開始時，若自己前線有〈六平千鉱〉與〈漣伯理〉，且自己的紅色產生能源在4以上時，可將手牌中這張卡片以活動狀態在自己前線登場。若有執行此動作時，將1張自己場上其他的卡片放置在自己卡組的上面或下面。〈柴登吾〉的這個效果每回合僅可發動1次。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA46BT/KGR-1-049":{"name":"柴登吾","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】自己場上所有的其他角色卡獲得【階梯】。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-048":{"name":"柴登吾","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-056":{"name":"六平千鉱","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA46BT/KGR-1-058":{"name":"六平千鉱","effectText":"【攻擊時】可以將1張這張角色卡下面的背面朝上卡片放置在場外。若有執行此動作時，這張角色卡在這個回合中，BP+2000。\n【防禦時】可以將2張自己的手牌放置在場外。若有執行此動作時，這張角色卡在這場對戰中，獲得BP+2000與「在戰鬥中勝利時，將1張自己卡組上面的卡片以背面朝上放置在這張角色卡的下面。」","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-057":{"name":"六平千鉱","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】這張角色卡在這個回合中，獲得BP+1000與「這張角色卡的產生能源+【紅】」。","triggerText":""},"UA46BT/KGR-1-055":{"name":"六平千鉱","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-054":{"name":"六平國重","effectText":"當這張卡片因自己紅色的〈六平千鉱〉的效果而從手牌放置在場外時，抽1張卡片。","triggerText":""},"UA46BT/KGR-1-059":{"name":"六平千鉱","effectText":"這張角色卡以活動狀態登場。\n【登場時】抽1張卡片。\n【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】自己前線所有的〈六平千鉱〉、〈漣伯理〉與〈柴登吾〉，在這個回合中，BP+1000。\n【啟動主要】【將1張手牌放置在場外】【每回合1】這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-064":{"name":"香刈緋雪","effectText":"【我方回合中】若自己場上有4張以上［特徵：神奈備］時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-063":{"name":"香刈緋雪","effectText":"【登場時】查看2張自己卡組上面的卡片，將最多1張［特徵：神奈備］放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":""},"UA46BT/KGR-1-065":{"name":"香刈緋雪","effectText":"【我方回合中】若對手的生命值在3以下時，這張角色卡BP+500。\n【登場時】若對手的生命值在4以上，且自己場上有4張以上［特徵：神奈備］時，可將1張自己的生命卡加入手牌。若有執行此動作時，對手受到1點傷害。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-060":{"name":"六平千鉱","effectText":"【突襲】〈六平千鉱〉置為活動，並可移動至前線\n【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得「【攻擊時】【每回合1】選擇最多1張對手前線BP4000以下的角色卡，使其退場。」。\n【啟動主要】【將3張手牌放置在場外】【每回合1】 這張角色卡在這個回合中，獲得【雙重攻擊】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA46BT/KGR-1-061":{"name":"薊奏士郎","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA46BT/KGR-1-062":{"name":"薊奏士郎","effectText":"【登場時】抽1張卡片。從自己手牌中，使最多1張滿足能源需求且消耗AP1，擁有［特徵：神奈備］的角色卡以休息狀態在自己場上登場。之後，可將1張自己的手牌放置在場外。若有執行此動作時，將登場的角色卡置為活動，並在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-067":{"name":"香刈緋雪","effectText":"【突襲】〈香刈緋雪〉置為活動，並可移動至前線\n【登場時】若自己場上有4張以上［特徵：神奈備］時，這張角色卡在這個回合中，獲得【衝擊（1）】或【傷害（2）】。\n【攻擊時】若對手的生命值在4以上時，這張角色卡在這個回合中，獲得「【每回合1】這張角色卡攻擊後戰勝時，抽1張卡片。」。若對手的生命值在3以下時，發動這張角色卡的【登場時】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA46BT/KGR-1-068":{"name":"美原多福","effectText":"【登場時】選擇最多1張自己場上的〈香刈緋雪〉，在這個回合中，BP+1000。若對手的生命值在3以下時，再於這個回合中，獲得「這張角色卡攻擊後沒有被防禦時，抽1張卡片。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-070":{"name":"卯月清彦","effectText":"【登場時】若自己場上有4張以上［特徵：神奈備］時，選擇最多1張對手前線BP2500以下的角色卡，轉為休息。","triggerText":""},"UA46BT/KGR-1-069":{"name":"美原多福","effectText":"【啟動主要】【每回合1】僅限在這張角色卡登場的回合中可發動。選擇1張對手前線BP3000以下的角色卡，與1張自己前線的〈香刈緋雪〉。被選擇的對手角色卡在這個回合中，必須盡可能防禦被選擇的〈香刈緋雪〉的攻擊。","triggerText":""},"UA46BT/KGR-1-066":{"name":"香刈緋雪","effectText":"【我方回合中】若自己場上有4張以上［特徵：神奈備］時，這張角色卡獲得「【每回合1】這張角色卡攻擊後戰勝時，若對手的生命值在4以上時，抽1張卡片。若對手的生命值在3以下時，將這張角色卡置為活動。」。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA46BT/KGR-1-075":{"name":"真智卡札涅","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：神奈備］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-073":{"name":"萩原幾兎","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態時可發動。選擇1張自己場上擁有［特徵：神奈備］的其他角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-072":{"name":"具柄一","effectText":"【攻擊時】若這張角色卡的BP在4000以上，且自己場上有4張以上［特徵：神奈備］時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-074":{"name":"張間梓弓","effectText":"【對方回合中】若自己場上有4張以上［特徵：神奈備］時，這張角色卡獲得BP+1000與【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-076":{"name":"神奈備本部","effectText":"使這張場域卡以活動狀態登場。\n【啟動主要】【轉為休息】選擇1張自己場上擁有［特徵：神奈備］的角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA46BT/KGR-1-071":{"name":"笠原誠","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】僅限自己場上有4張以上［特徵：神奈備］時可發動。這張角色卡在這個回合中，BP+1000。","triggerText":""},"UA46BT/KGR-1-082":{"name":"淵天涅","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈六平千鉱〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-079":{"name":"炎骨陸郎","effectText":"選擇1張對手前線『BP2000以下』的角色卡，使其退場。若自己場上有〈香刈緋雪〉時，則替換成『BP5000以下』。若自己場上有4張以上［特徵：神奈備］時，查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA46BT/KGR-1-081":{"name":"不再手下留情","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA46BT/KGR-1-080":{"name":"我必須斬了那些傢伙","effectText":"抽1張卡片。選擇最多1張自己場上的〈六平千鉱〉，在這個回合中，獲得BP+2000與「在這張角色卡的第一次攻擊中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA46BT/KGR-1-078":{"name":"威葬","effectText":"選擇1張對手前線的角色卡，移動至能源線。（移動時若能源線沒有空格，對手需選擇1張能源線的卡片放置在移除區後再進行移動）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA46BT/KGR-1-077":{"name":"「那一天」是我的原動力，如今已變得更加鮮明。","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA47ST/TKG-1-038":{"name":"金木研","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47ST/TKG-1-036":{"name":"詩","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA47ST/TKG-1-056":{"name":"笛口涼子","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紫】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA47ST/TKG-1-045":{"name":"霧嶋董香","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47ST/TKG-1-044":{"name":"神代利世","effectText":"【啟動主要】【若在場外時】選擇1張自己場上沒有背面朝上卡片的〈金木研〉，將場外的這張卡片以背面朝上放置在被選擇的角色卡下面。可將1張自己的手牌放置在場外。若有執行此動作時，使以此效果選擇的角色卡置為活動，並在這個回合中，BP-1000。","triggerText":""},"UA47ST/TKG-1-054":{"name":"笛口雛實","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA47ST/TKG-1-103":{"name":"霧嶋董香","effectText":"【我方回合中】這張角色卡BP+500。\n【登場時】可以將1張自己前線能源需求4以下活動狀態的〈金木研〉轉為休息。若有執行此動作時，將這張角色卡置為活動。","triggerText":""},"UA47ST/TKG-1-101":{"name":"金木研","effectText":"若這張角色卡下面有背面朝上的卡片時，這張角色卡獲得【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）。\n【我方回合中】若這張角色卡下面有背面朝上的卡片時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47ST/TKG-1-061":{"name":"珈琲","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA47ST/TKG-1-058":{"name":"四方蓮示","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47ST/TKG-1-057":{"name":"芳村","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA47ST/TKG-1-102":{"name":"金木研","effectText":"【突襲】〈金木研〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】抽2張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡下面有背面朝上卡片時可發動。將這張角色卡置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47ST/TKG-1-104":{"name":"霧嶋董香","effectText":"這張角色卡以活動狀態登場。\n【啟動主要】【每回合1】將1張自己前線能源需求4以下活動狀態的〈金木研〉轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）與「在這張角色卡這個回合的第二次攻擊中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47ST/TKG-1-107":{"name":"安定區","effectText":"【登場時】選擇最多1張自己場上的角色卡，置為活動。\n【啟動主要】【轉為休息】【使這張卡片退場】選擇1張自己場上的角色卡，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47ST/TKG-1-108":{"name":"金木的面具","effectText":"抽3張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA47ST/TKG-1-106":{"name":"西尾錦","effectText":"【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47ST/TKG-1-105":{"name":"永近英良","effectText":"【登場時】從自己場外，將最多1張能源需求4以下的〈金木研〉放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47ST/TKG-1-112":{"name":"金木研","effectText":"依據自己的生命值，這張角色卡獲得以下所有效果。\n・5以下：【我方回合中】這張角色卡BP+500。\n・3以下：【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】可以將1張自己的生命卡加入手牌。若有執行此動作時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA47ST/TKG-1-110":{"name":"有馬貴將","effectText":"【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47ST/TKG-1-113":{"name":"鈴屋什造","effectText":"若自己場上有4張以上［特徵：CCG］時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-001":{"name":"阿原半兵衛","effectText":"【登場時】『查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面』。若自己場上有〈鈴屋什造〉時，則替換成『查看2張自己卡組上面的卡片，將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片依任意順序放置在自己卡組下面』。","triggerText":"[抽卡] 抽1張卡片。"},"UA47ST/TKG-1-111":{"name":"佐佐木琲世","effectText":"【突襲】〈佐佐木琲世〉置為活動，並可移動至前線\n【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：真戶班］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】使1張自己手牌中能源需求3以下消耗AP1的黃色［特徵：真戶班］以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47ST/TKG-1-109":{"name":"這裡沒有半樣東西是屬於你的","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈霧嶋董香〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA47BT/TKG-1-006":{"name":"宇井郡","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA47BT/TKG-1-004":{"name":"有馬貴將","effectText":"【突襲】〈有馬貴將〉置為活動，並可移動至前線\n各回合中此角色的第1次攻擊中，此角色獲得【傷害（2）】。\n【每回合1】這張角色卡的攻擊結束時，若在這個回合中對手的角色卡已退場時，將這張角色卡置為活動，並抽1張卡片。\n【登場時】這張角色卡直到下一個我方回合開始前，獲得「對手以效果選擇這張角色卡時，必須追加將1張自身手牌放置在場外才可以選擇。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-005":{"name":"伊丙入","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA47BT/TKG-1-007":{"name":"鈴屋什造","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-003":{"name":"有馬貴將","effectText":"若對手前線有角色卡，或在這個回合中對手的角色卡已退場時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA47BT/TKG-1-009":{"name":"鈴屋什造","effectText":"【登場時】可支付1AP。若有執行此動作時，選擇最多1張對手前線BP2000以下的角色卡，使其退場。\n【攻擊時】若在這個回合中對手的角色卡已退場時，這張角色卡在這個回合中，BP+1000。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA47BT/TKG-1-012":{"name":"舊多二福","effectText":"若對手場上有紫色或紅色卡片時，手牌中這張卡片的能源需求減少【黃×1】。","triggerText":""},"UA47BT/TKG-1-010":{"name":"鈴屋什造","effectText":"【突襲】〈鈴屋什造〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】對手將1張自身前線的角色卡退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-008":{"name":"鈴屋什造","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【攻擊時】若在這個回合中對手的角色卡已退場時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA47BT/TKG-1-011":{"name":"平子丈","effectText":"【登場時】查看5張自己卡組上面的卡片，公開其中最多1張〈有馬貴將〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-013":{"name":"佐佐木琲世","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-017":{"name":"真戶曉","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA47BT/TKG-1-016":{"name":"佐佐木琲世","effectText":"【突襲】〈佐佐木琲世〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【啟動主要】【每回合1】僅限在這張角色卡登場的回合中可發動。將自己所有的AP卡置為活動。在這個回合中，自己無法使用手牌。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】自己場上所有的［特徵：真戶班］，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-015":{"name":"佐佐木琲世","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：真戶班］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA47BT/TKG-1-014":{"name":"佐佐木琲世","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【啟動主要】【若在前線時】【支付1AP】【每回合1】 將1張自己場外能源需求2以下的［特徵：真戶班］加入手牌。","triggerText":""},"UA47BT/TKG-1-020":{"name":"瓜江久生","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【支付1AP】【每回合1】這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-021":{"name":"不知吟士","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n若自己場上有4張以上［特徵：真戶班］時，這張角色卡BP+1000。\n【啟動主要】【支付1AP】【每回合1】將這張角色卡移動至別的線，或與別的線的角色卡互相交換位置。","triggerText":""},"UA47BT/TKG-1-018":{"name":"真戶曉","effectText":"【登場時】【若在能源線時】若自己場上有6張以上［特徵：真戶班］時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的［特徵：真戶班］。在這個回合中，該張角色卡發動【啟動主要】時，可不執行【支付1AP】來發動。〈真戶曉〉的這個效果每回合僅可發動1次。","triggerText":""},"UA47BT/TKG-1-019":{"name":"瓜江久生","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【支付1AP】【每回合1】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-022":{"name":"不知吟士","effectText":"【啟動主要】【若在前線時】【支付1AP】【每回合1】從以下選擇1項。\n・將這張角色卡置為活動。\n・若這張角色卡為活動時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-027":{"name":"CCG本部","effectText":"【每回合1】當自己的［特徵：CCG］攻擊並在戰鬥中獲勝時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-024":{"name":"六月透","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：真戶班］，在這個回合中，BP+1000。\n【啟動主要】【支付1AP】【每回合1】選擇1張自己場上其他的［特徵：真戶班］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-026":{"name":"米林才子","effectText":"若在這回合中，這張角色卡已發動包含【支付1AP】的【啟動主要】時，這張角色卡BP+2000。\n這張角色卡的【啟動主要】的【支付1AP】，可替換成【將1張手牌放置在場外】。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上其他的［特徵：真戶班］。這張角色卡在這個回合中，獲得1個所選擇的角色卡持有的包含【支付1AP】的【啟動主要】。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-025":{"name":"米林才子","effectText":"【啟動主要】【支付1AP】【每回合1】這張角色卡在這個回合中，BP+3000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-023":{"name":"六月透","effectText":"若自己場上有4張以上［特徵：真戶班］時，這張角色卡BP+500。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-029":{"name":"CCG的死神","effectText":"若自己場上有〈有馬貴將〉時，手牌中這張卡片的消耗AP-1。\n選擇1張對手前線BP5000以下的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA47BT/TKG-1-032":{"name":"給我…勇氣…","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈佐佐木琲世〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA47BT/TKG-1-028":{"name":"佐佐木的認真","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA47BT/TKG-1-030":{"name":"鈴屋前輩是不會拋棄部下的","effectText":"從以下選擇1項。\n・從自己場外，使最多1張滿足能源需求且消耗AP為1的〈阿原半兵衛〉以休息狀態在自己場上登場。\n・查看6張自己卡組上面的卡片。公開其中最多1張〈鈴屋什造〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若自己場上有〈阿原半兵衛〉時，將1張自己的AP卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-031":{"name":"重要的事情是有順序的","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA47BT/TKG-1-036":{"name":"詩","effectText":"【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】選擇1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-035":{"name":"入見萱","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA47BT/TKG-1-034":{"name":"伊鳥","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-037":{"name":"詩","effectText":"【登場時】查看4張自己卡組上面的卡片，將其中最多1張放置在場外，並公開其中最多1張持有【突襲】的角色卡或消耗AP2以上的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】【使這張卡片退場】查看3張自己卡組上面的卡片，將其中最多1張加入手牌，並將其餘卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-033":{"name":"米林才子，要工作了！","effectText":"查看5張自己卡組上面的卡片。公開其中最多3張不同卡片名稱的［特徵：真戶班］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-002":{"name":"有馬貴將","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-041":{"name":"金木研","effectText":"若自己場外有5種以上不同能源需求的卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n使這張角色卡以活動狀態登場。\n【我方回合中】這張角色卡BP+1000。\n【登場時】這張角色卡在這個回合中，獲得「對手必須盡可能防禦這張角色卡的第一次攻擊。」與「【每回合1】這張角色卡攻擊後戰勝時，將這張角色卡置為活動。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-043":{"name":"神代利世","effectText":"【退場時】選擇最多1張自己場上，下方沒有背面朝上卡片的〈金木研〉，將這張卡片背面朝上放置在選擇的角色卡下面。","triggerText":""},"UA47BT/TKG-1-039":{"name":"金木研","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為活動狀態時可發動。查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":""},"UA47BT/TKG-1-040":{"name":"金木研","effectText":"若自己場外有5種以上不同能源需求的卡片時，這張角色卡獲得【傷害（2）】。\n【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA47BT/TKG-1-038":{"name":"金木研","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-042":{"name":"金木研","effectText":"發動這張卡片的突襲時，自己場外每有1種不同能源需求的卡片，其能源需求便減少【紫×1】。\n【突襲】〈金木研〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【攻擊時】對手可將7張自己場外的卡片放置在移除區。若對手執行此動作時，自己抽2張卡片，並將1張自己的手牌放置在場外。若對手未執行此動作時，自己選擇最多1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-048":{"name":"古間圓兒","effectText":"若對手場上有黃色或紅色卡片時，手牌中這張卡片的能源需求減少【紫×1】。","triggerText":""},"UA47BT/TKG-1-049":{"name":"月山習","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-047":{"name":"霧嶋董香","effectText":"【突襲】〈霧嶋董香〉置為活動，並可移動至前線\n【登場時】從以下選擇1項。\n・選擇最多1張自己場上能源需求3以下的角色卡，置為活動。\n・抽1張卡片。\n【啟動主要】【若在前線時】【每回合1】將1張自己前線能源需求4以下活動狀態的〈金木研〉轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得【雙重攻擊】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-044":{"name":"神代利世","effectText":"【啟動主要】【若在場外時】選擇1張自己場上沒有背面朝上卡片的〈金木研〉，將場外的這張卡片以背面朝上放置在被選擇的角色卡下面。可將1張自己的手牌放置在場外。若有執行此動作時，使以此效果選擇的角色卡置為活動，並在這個回合中，BP-1000。","triggerText":""},"UA47BT/TKG-1-046":{"name":"霧嶋董香","effectText":"【啟動主要】【若在前線時】【每回合1】將1張自己前線能源需求4以下的活動狀態〈金木研〉轉為休息。若有執行此動作時，這張角色卡在這個回合中，BP+2000。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA47BT/TKG-1-052":{"name":"月山習","effectText":"【突襲】〈月山習〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。可以將自己場外的角色卡與事件卡以相同張數任意放置在移除區。每以此效果放置1張卡片在移除區，所選的角色卡在這個回合中，BP再-500。\n【攻擊時】可以將1張自己場外的角色卡與1張事件卡放置在移除區。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-050":{"name":"月山習","effectText":"【登場時】查看2張自己卡組上面的卡片，公開其中最多1張事件卡並加入手牌。其餘卡片放置在場外。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA47BT/TKG-1-053":{"name":"西尾錦","effectText":"【登場時】將2張自己卡組上面的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-051":{"name":"月山習","effectText":"【登場時】可以將2張以上自己場外的卡片放置在移除區。若有執行此動作時，若自己移除區有10張以上卡片時，將這張角色卡置為活動。〈月山習〉的這個效果每回合僅可發動1次。\n【退場時】可以將2張自己場外其他的〈月山習〉放置在移除區。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-054":{"name":"笛口雛實","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA47BT/TKG-1-057":{"name":"芳村","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA47BT/TKG-1-055":{"name":"笛口雛實","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・若為我方回合中，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-058":{"name":"四方蓮示","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n【啟動主要】【若在前線時】【支付1AP】【每回合1】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-056":{"name":"笛口涼子","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紫】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA47BT/TKG-1-059":{"name":"四方蓮示","effectText":"若自己場外與移除區的卡片合計在10張以上時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-045":{"name":"霧嶋董香","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-064":{"name":"變態？真是出乎我的意料…","effectText":"〈變態？真教人心外…〉在1個回合中只能使用1張。\n抽1張卡片。若自己場上有〈月山習〉時，將1張自己的AP卡置為活動。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA47BT/TKG-1-063":{"name":"那樣就好了喔…金木同學…","effectText":"查看2張自己卡組上面的卡片，將其中最多1張加入手牌，其餘卡片放置在場外。在這個回合中，下一張從手牌中使用，原本能源需求為5以上的〈金木研〉，其消耗AP-1。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-062":{"name":"在舌尖上深度纏繞交織的美妙合音！！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA47BT/TKG-1-060":{"name":"喰種餐廳","effectText":"【登場時】將最多2張自己移除區的卡片放置在場外。\n【啟動主要】【轉為休息】僅限自己場上有〈月山習〉時可發動。將2張自己場外的卡片放置在移除區。若有執行此動作時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-061":{"name":"珈琲","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置到自己的生命區。"},"UA47BT/TKG-1-065":{"name":"就算被我吃掉也是沒辦法的吧…","effectText":"若自己場上有〈金木研〉，且自己場外的卡片能源需求有3種以上時，手牌中這張卡片的能源需求減少【紫×2】。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA47BT/TKG-1-070":{"name":"金木研","effectText":"【啟動主要】【每回合1】將1張自己的生命卡加入手牌。若有執行此動作時，這張角色卡在這個回合中，BP+1000。\n【退場時】若這張角色卡因對戰而退場，且自己的生命值在3以下時，可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，轉為休息。","triggerText":""},"UA47BT/TKG-1-066":{"name":"是我的東西!!","effectText":"若自己場上有〈月山習〉時，手牌中這張卡片的能源需求減少【紫×2】。\n當使用這張卡片，且選擇的對象是下方有背面朝上卡片的角色卡時，這張卡片的能源需求減少【紫×2】。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA47BT/TKG-1-071":{"name":"金木研","effectText":"這張角色卡無法以突襲以外的方式登場。\n【突襲】〈金木研〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n對手攻擊階段結束時，可將1張自己的生命卡加入手牌，或使這張角色卡退場並抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-068":{"name":"金木研","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-067":{"name":"艾特","effectText":"【登場時】若自己的生命值在4～5時，抽1張卡片，並將1張自己的手牌放置在場外。若自己的生命值在3以下時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-069":{"name":"金木研","effectText":"若自己的生命值在5以下時，這張角色卡BP+1000。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-075":{"name":"霧嶋絢都","effectText":"【突襲】〈霧嶋絢都〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得【雙重攻擊】。\n【退場時】從自己手牌中，使最多1張能源需求『1以下』消耗AP1的紅色角色卡以休息狀態在自己場上登場。若自己的生命值在3以下時，則替換成『3以下』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-076":{"name":"奈白＆黑奈","effectText":"若對手場上有黃色或紫色卡片時，手牌中這張卡片的能源需求減少【紅×1】。","triggerText":""},"UA47BT/TKG-1-077":{"name":"多多良","effectText":"使這張角色卡以活動狀態在場上登場。\n【登場時】若自己的生命值在5以下時，選擇最多1張對手前線『BP2500以下』的角色卡，使其退場。若自己的生命值在3以下時，則替換成『BP3500以下』。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-072":{"name":"霧嶋絢都","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-073":{"name":"霧嶋絢都","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA47BT/TKG-1-074":{"name":"霧嶋絢都","effectText":"【登場時】若自己的生命值在6以上時，抽1張卡片，並將1張自己的手牌放置在場外。若自己的生命值在5以下時，抽1張卡片。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA47BT/TKG-1-082":{"name":"亞門鋼太朗","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【若在前線時】【轉為休息】【每回合1】選擇最多2張自己場上的［特徵：CCG］，在這個回合中，BP+1000。若自己場上有8張以上［特徵：CCG］時，抽1張卡片。","triggerText":""},"UA47BT/TKG-1-081":{"name":"亞門鋼太朗","effectText":"【登場時】查看2張自己卡組上面的卡片。公開其中最多1張［特徵：CCG］或〈亞門的伏地挺身〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA47BT/TKG-1-083":{"name":"亞門鋼太朗","effectText":"【突襲】〈亞門鋼太朗〉置為活動，並可移動至前線\n【登場時】若自己場上有4張以上［特徵：CCG］時，抽1張卡片。\n【啟動主要】【若在前線時】【轉為休息】【每回合1】抽1張卡片。之後，可將1張自己場外的〈亞門的伏地挺身〉放置在移除區。若有執行此動作時，將1張自己的AP卡置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-078":{"name":"納基","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【攻擊時】【防禦時】若自己的生命值在3以下時，這張角色卡在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-080":{"name":"亞門鋼太朗","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-079":{"name":"野呂","effectText":"【退場時】從以下選擇最多1項。\n・可以將1張自己的生命卡加入手牌。若有執行此動作時，使這張卡片以休息狀態在自己場上登場。\n・可以將2張自己的手牌放置在場外。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-088":{"name":"鈴屋什造","effectText":"【我方回合中】若自己場上有4張以上［特徵：CCG］時，這張角色卡BP+500。","triggerText":""},"UA47BT/TKG-1-087":{"name":"鈴屋什造","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-089":{"name":"鈴屋什造","effectText":"從手牌發動這張卡片的突襲時，若自己場上有8張以上［特徵：CCG］時，消耗AP-1。\n【突襲】〈鈴屋什造〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP為自己場上［特徵：CCG］的張數×500以下的角色卡，使其退場。〈鈴屋什造〉的這個效果每回合僅可發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA47BT/TKG-1-085":{"name":"黑磐巖","effectText":"若自己場上有4張以上［特徵：CCG］時，這張角色卡獲得【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）與【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-086":{"name":"篠原幸紀","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的〈鈴屋什造〉，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-084":{"name":"有馬貴將","effectText":"自己場上每有1張［特徵：CCG］，手牌中這張卡片的能源需求減少【紅×1】。\n這張角色卡以活動狀態登場。\n【啟動主要】【每回合1】僅限自己場上有8張以上［特徵：CCG］時可發動。這張角色卡在這個回合中，獲得【衝擊（1）】與【傷害（2）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-095":{"name":"「青桐樹」的據點","effectText":"這張場域卡以活動狀態登場。\n【啟動主要】【轉為休息】【將1張手牌放置在場外】僅限自己的生命值在5以下時可發動。選擇1張自己場上的角色卡，在這個回合中，BP+1500。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-094":{"name":"真戶曉","effectText":"【登場時】若自己場上有4張以上［特徵：CCG］時，抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【將1張手牌放置在場外】【每回合1】選擇1張在這個回合中曾因自己的效果從活動轉為休息的自己場上的〈亞門鋼太朗〉，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA47BT/TKG-1-093":{"name":"平子丈","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA47BT/TKG-1-091":{"name":"永近英良","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA47BT/TKG-1-090":{"name":"瀧澤政道","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合中，這張角色卡的產生能源+【紅】。主要階段結束時，使這張角色卡退場。","triggerText":""},"UA47BT/TKG-1-092":{"name":"永近英良","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA47BT/TKG-1-100":{"name":"梟討伐作戰","effectText":"選擇1張對手前線BP為自己場上［特徵：CCG］的張數×1000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA47BT/TKG-1-099":{"name":"半赫者","effectText":"若自己場上有〈金木研〉時，手牌中這張卡片的消耗AP-1。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。若自己的生命值在3以下時，選擇最多1張自己前線的〈金木研〉，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48ST/KGD-1-034":{"name":"嬴政","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA47BT/TKG-1-096":{"name":"亞門的伏地挺身","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA47BT/TKG-1-098":{"name":"…你太大了","effectText":"選擇1張自己場上的〈亞門鋼太朗〉，在這個回合中，獲得BP+3000與【衝擊（+1）】（衝擊造成的傷害+1，若未持有衝擊，則獲得【衝擊（1）】）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA47BT/TKG-1-097":{"name":"可以請問你的名字嗎","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48ST/KGD-1-051":{"name":"松左","effectText":"【登場時】查看2張自己卡組上面的卡片，公開其中最多1張［特徵：飛信隊］並加入手牌。將其餘卡片放置在場外。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA48ST/KGD-1-059":{"name":"尾平","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：飛信隊］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48ST/KGD-1-052":{"name":"信","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48ST/KGD-1-045":{"name":"河了貂","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：飛信隊］，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":""},"UA48ST/KGD-1-036":{"name":"漂","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA48ST/KGD-1-049":{"name":"羌瘣","effectText":"使這張角色卡以活動狀態在場上登場。\n【登場時】若自己場上擁有［特徵：飛信隊］的卡片名稱有4種以上時，可將1張自己的手牌放置在場外。若有執行此動作時，將最多1張自己場外能源需求2以下的藍色事件卡加入手牌。\n【攻擊時】從自己手牌中，不支付AP使用最多1張能源需求2以下的藍色事件卡。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48ST/KGD-1-104":{"name":"河了貂","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己場外，使最多1張〈河了貂〉以外能源需求2以下的藍色［特徵：飛信隊］以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA48ST/KGD-1-103":{"name":"壁","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48ST/KGD-1-102":{"name":"王騎","effectText":"使這張角色卡以活動狀態登場。\n【攻擊時】抽1張卡片。\n【退場時】選擇最多1張自己場上的〈信〉，置為活動，並在這個回合中，BP+3000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48ST/KGD-1-101":{"name":"嬴政","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上其他的角色卡，在這個回合中，獲得「【攻擊時】抽最多1張卡片。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA48ST/KGD-1-063":{"name":"飛信隊，跟上！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48ST/KGD-1-067":{"name":"唔喔喔喔！！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈信〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48ST/KGD-1-110":{"name":"媧燐","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【我方回合中】這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA48ST/KGD-1-109":{"name":"在那裡開闢道路的，就是飛信隊的軍師！！","effectText":"查看6張自己卡組上面的卡片。從中公開最多2張不同卡片名稱的［特徵：飛信隊］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA48ST/KGD-1-108":{"name":"飛信隊","effectText":"若自己場上擁有不同卡片名稱［特徵：飛信隊］的卡片有4種以上時，這張場域卡的產生能源+【藍】。\n【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48ST/KGD-1-105":{"name":"羌瘣","effectText":"【啟動主要】【每回合1】將這張角色卡移動至別的線。","triggerText":""},"UA48ST/KGD-1-107":{"name":"信","effectText":"【突襲】〈信〉置為活動，並可移動至前線。\n【我方回合中】這張角色卡的BP增加（自己場上［特徵：飛信隊］的卡片名稱種類數×500）。依據這張角色卡的BP，這張角色卡獲得以下所有效果。\n・BP6000以上：【攻擊時】選擇最多1張自己場上的［特徵：飛信隊］，在這個回合中，BP+1000。\n・BP7000以上：【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】使最多1張自己手牌中能源需求2以下消耗AP1的藍色［特徵：飛信隊］以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48ST/KGD-1-106":{"name":"信","effectText":"若自己場上擁有不同卡片名稱［特徵：飛信隊］的卡片有4種以上時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-002":{"name":"奧爾多","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【我方回合中】若自己場上黃色卡片的特徵有3種以上時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-001":{"name":"奧爾多","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這回合中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48ST/KGD-1-112":{"name":"王翦","effectText":"【登場時】可以將1張自己場上能源需求2以下的角色卡放回手牌。若有執行此動作時，將這張角色卡置為活動。\n【退場時】若自己前線沒有持有【突襲】的角色卡時，可將1張自己的手牌放置在場外。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA48ST/KGD-1-111":{"name":"李牧","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】【每回合1】選擇1張自己能源線的卡片，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA48ST/KGD-1-113":{"name":"桓騎","effectText":"【登場時】可使1張自己場上其他的［特徵：桓騎軍］退場。若有執行此動作時，將這張角色卡置為活動。\n【啟動主要】使1張自己場上其他的［特徵：桓騎軍］退場。若有執行此動作時，這張角色卡在這個回合中，獲得BP+1000與【雙重攻擊】（這張角色卡在這個回合的第一次攻擊時置為活動）。〈桓騎〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-003":{"name":"成恢","effectText":"【登場時】若為我方回合中，且自己場上黃色卡片的特徵有3種以上時，可將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張對手前線BP3000以下的角色卡，轉為休息。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-009":{"name":"媧燐","effectText":"這張卡片無法在前線登場，且無法透過此卡片的【啟動主要】以外的方式移動至前線。\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【啟動主要】【每回合1】僅限這張角色卡的BP在5000以上時可發動。將這張角色卡移動至另一條戰線。\n【突襲】〈媧燐〉置為活動，並可移動至前線\n【啟動主要】【每回合1】使這張角色卡的突襲來源卡以活動狀態在自己前線登場。該張角色卡在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-005":{"name":"吳鳳明","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA48BT/KGD-1-006":{"name":"吳鳳明","effectText":"【突襲】〈吳鳳明〉置為活動，並可移動至前線。\n【攻擊時】從以下選擇1項。\n・從自己卡組上面查看卡片，張數等同於自己場上黃色卡片的特徵種類數。從中公開最多1張角色卡或場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n・這張角色卡在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。〈吳鳳明〉的這個效果每回合僅可選擇1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-008":{"name":"媧燐","effectText":"【攻擊時】若這張角色卡的BP在4000以上時，抽1張卡片。","triggerText":""},"UA48BT/KGD-1-007":{"name":"媧燐","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：楚］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA48BT/KGD-1-004":{"name":"吳鳳明","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-012":{"name":"汗明","effectText":"【突襲】〈汗明〉置為活動，並可移動至前線。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【我方回合中】【若在前線時】自己場上所有的［特徵：楚］，BP+2000。\n【啟動主要】【若在前線時】【每回合1】抽1張卡片。若自己前線沒有其他角色卡時，在這個回合中，下一次從手牌中使用〈誰為至強!?!?〉或〈咚咚隆 咚咚 汗明!!〉的消耗AP-1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-011":{"name":"汗明","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA48BT/KGD-1-010":{"name":"汗明","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-014":{"name":"春申君","effectText":"這張卡片無法在前線登場，且無法移動至前線。\n【啟動主要】【轉為休息】選擇任意張數自己前線的黃色角色卡，並將其移動至能源線。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-015":{"name":"白麗","effectText":"【啟動主要】【轉為休息】【每回合1】從以下選擇1項。\n・選擇最多1張自己場上原始BP為4000以上的角色卡，在這個回合中，BP+1000。\n・將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-013":{"name":"項翼","effectText":"若這張角色卡的BP在4000以上時，這張角色卡獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-021":{"name":"傅抵","effectText":"【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA48BT/KGD-1-020":{"name":"慶舎","effectText":"【對方回合中】對手以效果選擇這張角色卡，或以【狙擊】指定這張角色卡時，必須追加將1張自身手牌放置在場外才可以選擇。\n【登場時】抽2張卡片，並將1張自己的手牌放置在場外。若自己場上黃色卡片的特徵有3種類以上時，將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-019":{"name":"凱涅","effectText":"【退場時】若自己場上有〈李牧〉時，從自己手牌中，使最多1張〈凱妮〉以外能源需求2以下消耗AP1的黃色角色卡以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-018":{"name":"凱涅","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA48BT/KGD-1-017":{"name":"臨武君","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，使最多1張自己場外能源需求2以下的黃色［特徵：楚］以活動狀態在自己場上登場。\n【啟動主要】【每回合1】僅限這張角色卡的BP在5000以上時可發動。將這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-016":{"name":"巴繆","effectText":"若自己場上有〈媧燐〉時，這張角色卡獲得BP+1000與【階梯】（在自己的移動階段可以從前線移動至能源線）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-026":{"name":"李牧","effectText":"【突襲】〈李牧〉置為活動，並可移動至前線\n【登場時】查看4張自己卡組上面的卡片，使最多1張能源需求『0』以下消耗AP1的黃色角色卡以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。自己場上每有1種黃色卡片的特徵，藉由此效果登場的角色卡的能源需求範圍+1。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己前線的其他角色卡與1張自己能源線的角色卡，互相交換其位置。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-027":{"name":"井闌車","effectText":"【登場時】若自己場上有〈吳鳳明〉時，選擇最多1張自己場上的角色卡，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。\n【啟動主要】【轉為休息】【使這張卡片退場】選擇最多1張自己場上的角色卡，移動至別的線。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-022":{"name":"龐煖","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【若在前線時】在自己攻擊階段結束時，若自己前線有原始BP4500以上的其他角色卡，或在這回合中這張角色卡沒有移動時，將這張角色卡放置在自己卡組下面。\n【攻擊時】這張角色卡在這個回合中，獲得【衝擊（1）】或【傷害（2）】。\n【退場時】將這張卡片放置在自己卡組下面。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA48BT/KGD-1-023":{"name":"萬極","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA48BT/KGD-1-025":{"name":"李牧","effectText":"【登場時】查看2張自己卡組上面的卡片。將其中任意張數的卡片依任意順序放置在自己卡組的上面，並將其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"UA48BT/KGD-1-024":{"name":"李牧","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-032":{"name":"連萬分之一的勝算都沒有","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈李牧〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48BT/KGD-1-033":{"name":"我乃武神龐煖","effectText":"公開1張自己卡組下面的卡片並『加入手牌』。若公開的卡片為消耗AP1的黃色〈龐煖〉時，可替換成『以休息狀態在自己場上登場』。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-031":{"name":"咚咚隆 咚咚 汗明!!","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48BT/KGD-1-028":{"name":"合縱軍集結","effectText":"抽2張卡片。若自己場上黃色卡片的特徵有3種以上時，再抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-029":{"name":"全軍前進","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48BT/KGD-1-030":{"name":"誰為至強!?","effectText":"選擇1張對手前線BP為自己場上［特徵：楚］的張數×1000以下的角色卡，使其退場。若自己場上有BP5000以上的［特徵：楚］時，選擇最多1張自己場上的［特徵：楚］，移動至別的線。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48BT/KGD-1-038":{"name":"蒙恬","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張〈信〉或〈王賁〉或〈蒙恬〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-039":{"name":"蒙恬","effectText":"【登場時】選擇最多1張自己場上的〔〈信〉或〈王賁〉或〈蒙恬〉〕，移動至別的線。\n【若在能源線時】【每回合1】自己的角色卡攻擊時，可支付1AP。若有執行此動作時，選擇最多1張自己前線的角色卡，在這個回合中，獲得「這張角色卡不會被對手的效果選擇。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-037":{"name":"蒙恬","effectText":"【啟動主要】【轉為休息】【每回合1】在這個回合的攻擊階段開始時，選擇最多1張自己的AP卡，置為活動。這張角色卡在這個回合中，獲得「主要階段結束時，使這張角色卡退場。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-036":{"name":"漂","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA48BT/KGD-1-035":{"name":"王騎","effectText":"使這張角色卡以活動狀態在自己場上登場。\n在我方回合開始時，使這張角色卡退場。\n【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，選擇最多1張自己場上其他的角色卡，置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-034":{"name":"嬴政","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA48BT/KGD-1-044":{"name":"王賁","effectText":"【突襲】〈王賁〉置為活動，並可移動至前線。\n這張角色卡攻擊後沒有被防禦時，抽『1張』卡片。若自己前線有〈信〉與〈蒙恬〉時，則替換成『2張』。\n【登場時】選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。\n【攻擊時】可「支付1AP，並選擇1張對手前線的角色卡。」。若有執行此動作時，對手不能用被選擇角色以外的角色卡防禦這次攻擊。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-045":{"name":"河了貂","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：飛信隊］，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":""},"UA48BT/KGD-1-043":{"name":"王賁","effectText":"這張角色卡攻擊結束時，可支付1AP。若有執行此動作時，可從自己手牌中，使最多1張滿足能源需求的〈王賁〉發動突襲，並使該角色卡在這個回合中獲得【衝擊（1）】。〈王賁〉的這個效果每回合僅可發動1次。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA48BT/KGD-1-042":{"name":"王賁","effectText":"【攻擊時】可支付1AP。若有執行此動作時，這張角色卡在這個回合中，獲得BP+1000與「這張角色卡不會被BP2000以下的角色卡防禦。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-041":{"name":"王賁","effectText":"【攻擊時】可支付1AP。若有執行此動作時，這張角色卡在這個回合中，BP+2500。","triggerText":""},"UA48BT/KGD-1-040":{"name":"蒙恬","effectText":"【突襲】〈蒙恬〉置為活動，並可移動至前線。\n【若在前線時】自己的攻擊階段開始時，將最多1張自己的AP卡置為活動。\n【登場時】抽『2張』卡片，並將1張自己的手牌放置在場外。若自己前線有〈信〉與〈王賁〉時，則替換成『3張』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-051":{"name":"松左","effectText":"【登場時】查看2張自己卡組上面的卡片，公開其中最多1張［特徵：飛信隊］並加入手牌。將其餘卡片放置在場外。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA48BT/KGD-1-050":{"name":"羌瘣","effectText":"【突襲】〈羌瘣〉置為活動，並可移動至前線。\n【登場時】從以下選擇『1項』。若為我方回合中，且這張角色卡是以自己的效果登場時，則替換成『2項』。\n・選擇最多1張對手前線突襲狀態的卡片，將該突襲狀態最上面的卡片放置在場外。\n・選擇最多1張對手前線能源需求3以下的角色卡，放回手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-048":{"name":"羌瘣","effectText":"【登場時】若這張角色卡是因自己的效果而登場時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-047":{"name":"羌瘣","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張藍色的［特徵：飛信隊］放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-049":{"name":"羌瘣","effectText":"使這張角色卡以活動狀態在場上登場。\n【登場時】若自己場上擁有4種以上不同卡片名稱的［特徵：飛信隊］時，可將1張自己的手牌放置在場外。若有執行此動作時，可從自己場外將最多1張能源需求2以下的藍色事件卡加入手牌。\n【攻擊時】可從自己手牌中，不支付AP使用1張能源需求2以下的藍色事件卡。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-046":{"name":"河了貂","effectText":"【登場時】從自己場外，將最多1張能源需求2以下的〔［特徵：飛信隊］或事件卡〕加入手牌。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA48BT/KGD-1-057":{"name":"澤圭","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA48BT/KGD-1-056":{"name":"楚水","effectText":"【登場時】『抽1張卡片，並將1張自己的手牌放置在場外』。若自己場上有4種以上不同卡片名稱的［特徵：飛信隊］時，可替換成『抽1張卡片』。","triggerText":""},"UA48BT/KGD-1-055":{"name":"信","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n當自己的角色卡發動突襲時，若為我方回合中，可將休息狀態的這張角色卡置為活動。若有執行此動作時，這張角色卡在這個回合中，BP+1000。〈信〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-054":{"name":"信","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-052":{"name":"信","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-053":{"name":"信","effectText":"【我方回合中】這張角色卡BP+1000。","triggerText":""},"UA48BT/KGD-1-063":{"name":"飛信隊，跟上！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48BT/KGD-1-062":{"name":"切磋琢磨","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48BT/KGD-1-060":{"name":"龍川","effectText":"【對方回合中】若自己場上有4種以上不同卡片名稱的［特徵：飛信隊］時，這張角色卡獲得【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）與「這張角色卡不會移動、不會放回手牌，且不會受到減少BP的效果影響。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-058":{"name":"田有","effectText":"【我方回合中】若自己場上有4種以上不同卡片名稱的［特徵：飛信隊］時，這張角色卡BP+1000。","triggerText":""},"UA48BT/KGD-1-061":{"name":"論功行賞","effectText":"使這張場域卡以活動狀態在場上登場。\n自己的攻擊階段結束時，可「將活動狀態的這張場域卡轉為休息，並支付1AP」。若有執行此動作時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-059":{"name":"尾平","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：飛信隊］，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-068":{"name":"嬴政","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-067":{"name":"唔喔喔喔！！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈信〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48BT/KGD-1-069":{"name":"嬴政","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-064":{"name":"咚噹噹","effectText":"抽1張卡片。從以下選擇1項。\n・使最多1張自己手牌中滿足能源需求且消耗AP1的〈羌瘣〉以休息狀態在自己場上登場，或發動突襲。無法以這個效果對消耗AP2的〈羌瘣〉發動突襲。\n・選擇最多1張自己場上的［特徵：飛信隊］，在這個回合中，BP+1000。若選擇的角色卡為〈羌瘣〉時，再於這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-065":{"name":"戰友之形","effectText":"查看6張自己卡組上面的卡片。公開其中最多各1張〈信〉、〈王賁〉與〈蒙恬〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-066":{"name":"龍指","effectText":"選擇1張對手前線BP5000以下的角色卡，『放回手牌』。若自己場上有〈王賁〉時，可替換成『使其退場』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48BT/KGD-1-073":{"name":"昌平君","effectText":"【登場時】從以下選擇1項。\n・查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。\n・可將1張自己場上能源需求2以下的角色卡放回手牌。若有執行此動作時，選擇最多1張自己場上其他的角色卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-074":{"name":"張唐","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-075":{"name":"騰","effectText":"這張角色卡不會被BP2000以下的角色卡防禦。\n若自己前線有4種以上不同卡片名稱的角色卡時，這張角色卡獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-072":{"name":"昌文君","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA48BT/KGD-1-071":{"name":"蕞的住民","effectText":"【退場時】若自己場上有〈嬴政〉時，抽1張卡片。","triggerText":""},"UA48BT/KGD-1-070":{"name":"嬴政","effectText":"【突襲】〈嬴政〉置為活動，並可移動至前線。\n【登場時】使最多1張自己場外能源需求4以下消耗AP1不持有【突襲】的紅色角色卡以休息狀態在自己場上登場。若有登場時，可將活動狀態的這張角色卡轉為休息。若有執行此動作時，將該張角色卡置為活動。\n【啟動主要】【若在前線時】【轉為休息】【每回合1】選擇1張自己場上其他的角色卡，置為活動。若選擇的角色卡的能源需求為0時，該張角色卡在這個回合中，BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-081":{"name":"楊端和","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】若自己場上有〈嬴政〉時，可支付1AP。若有執行此動作時，將這張角色卡置為活動，使這張角色卡在這個回合中獲得「【若在能源線時】自己角色卡的攻擊結束時，可選擇1張自己前線的角色卡，與這張角色卡互相交換位置。」，並選擇最多1張自己場上的角色卡，在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-079":{"name":"呂不韋","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，抽『1張』卡片。若放置在場外的卡片為〈嬴政〉時，則替換成『2張』。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-080":{"name":"巴吉歐","effectText":"【我方回合中】若自己場上有〈楊端和〉時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-076":{"name":"麃公","effectText":"【攻擊時】從以下選擇1項。\n・這張角色卡在這個回合中，獲得「這張角色卡的攻擊沒有被防禦時，抽最多1張卡片。」。\n・若自己前線有4種以上不同卡片名稱的角色卡時，抽1張卡片。","triggerText":""},"UA48BT/KGD-1-078":{"name":"蒙武","effectText":"【登場時】若為我方回合中，可支付1AP。若有執行此動作時，從以下選擇1項。\n・選擇最多1張對手前線BP4500以上的角色卡，使其退場。\n・若自己前線有4種以上不同卡片名稱的角色卡時，選擇最多1張對手前線BP3500以上的角色卡，使其退場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-077":{"name":"蒙驁","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA48BT/KGD-1-085":{"name":"桓騎","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【啟動主要】【若在前線時】【每回合1】使1張自己場上其他的［特徵：桓騎軍］退場。若有執行此動作時，這張角色卡在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-087":{"name":"黑櫻","effectText":"【登場時】可使1張自己場上其他的［特徵：桓騎軍］退場。若有執行此動作時，抽2張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-086":{"name":"桓騎","effectText":"【突襲】〈桓騎〉置為活動，並可移動至前線。\n【登場時】選擇最多1張自己場上其他的［特徵：桓騎軍］，置為活動。\n【啟動主要】【若在前線時】【每回合1】僅限在這個回合中曾因角色卡的效果而有角色卡退場時可發動。從以下選擇1項。在這個回合中〈桓騎〉已選擇的效果無法選擇。\n・在這個回合中，下一張從手牌中使用［特徵：桓騎軍］的消耗AP-1。\n・抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA48BT/KGD-1-084":{"name":"桓騎","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：桓騎軍］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA48BT/KGD-1-082":{"name":"奧義子","effectText":"【退場時】若在我方回合中，將1張自己的AP卡置為活動。〈奧紀〉的這個效果每回合僅可發動1次。","triggerText":""},"UA48BT/KGD-1-083":{"name":"桓騎","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA48BT/KGD-1-093":{"name":"信","effectText":"【我方回合中】若自己場上有〈嬴政〉時，這張角色卡BP+2000。\n【若在能源線時】【每回合1】自己角色卡的攻擊結束時，可以選擇1張自己前線在這個回合中尚未攻擊的角色卡，與這張角色卡互相交換位置。\n【啟動主要】【將2張手牌放置在場外】【每回合1】這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA48BT/KGD-1-092":{"name":"厘玉","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：桓騎軍］放置在場外。將其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-091":{"name":"雷土","effectText":"若自己場上有〈桓騎〉時，手牌中這張卡片的能源需求減少【紅×1】。\n【我方回合中】若在這個回合中曾因角色卡的效果而有角色卡退場時，這張角色卡獲得BP+1000與【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":""},"UA48BT/KGD-1-090":{"name":"摩論","effectText":"【登場時】選擇最多1張自己場上〈摩論〉以外的［特徵：桓騎軍］，在這個回合中，獲得「【退場時】將這張卡片加入手牌。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA48BT/KGD-1-089":{"name":"那貴","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA48BT/KGD-1-088":{"name":"澤諾","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【登場時】若自己場上有〈桓騎〉時，對手將1張自身前線的角色卡退場。\n【啟動主要】【每回合1】將1張自己手牌中的［特徵：桓騎軍］放置在場外。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-097":{"name":"你也太得意忘形了吧","effectText":"這張卡片僅限自己場上有〈桓騎〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。若在這個回合中因角色卡的效果使角色卡退場時，選擇最多1張自己場上的［特徵：桓騎軍］，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48BT/KGD-1-098":{"name":"人所擁有的本質是───光","effectText":"這張卡片僅限自己場上有〈嬴政〉時才能使用。\n選擇1張對手前線BP為自己場上［特徵：秦］的張數×1000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA48BT/KGD-1-099":{"name":"本能型的武將","effectText":"選擇1張自己場上的角色卡，在這個回合中，BP+2000。若選擇的角色卡為〈麃公〉或〈信〉時，再獲得【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA48BT/KGD-1-096":{"name":"一切都會順利的","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48BT/KGD-1-095":{"name":"祝君武運","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA48BT/KGD-1-094":{"name":"函谷關","effectText":"【啟動主要】【使這張卡片退場】選擇最多1張自己場上的［特徵：秦］，直到下一個我方回合開始前，BP+2000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-004":{"name":"和倉優希（無窮之鎖）","effectText":"若自己場上沒有〈羽前京香〉時，這張卡片無法在前線〔登場・移動〕。\n【登場時】從以下選擇最多2項，其條件為自己場外〈羽前京香〉與〈和倉優希（無窮之鎖）〉的合計張數。\n・5張以上：選擇1張自己場上的〈和倉優希（無窮之鎖）〉，在這個回合中，獲得【衝擊（1）】。\n・10張以上：選擇1張自己場上的角色卡，置為活動。〈和倉優希（無窮之鎖）〉的這個效果每回合僅可選擇1次。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA49BT/MSS-1-003":{"name":"和倉優希（無窮之鎖）","effectText":"若自己場上沒有〈羽前京香〉時，這張卡片無法在前線〔登場・移動〕。\n【我方回合中】若自己場外有〈羽前京香〉與〈和倉優希（無窮之鎖）〉合計5張以上時，這張角色卡BP+1000。\n【退場時】若自己前線有〈羽前京香〉時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-005":{"name":"和倉優希（無窮之鎖・岩融）","effectText":"若自己場上沒有〈駿河朱朱〉時，這張卡片無法在前線〔登場・移動〕。\n【我方回合中】若這張角色卡與〈駿河朱朱〉位於同一條戰線時，這張角色卡獲得BP+2000與【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）。\n【攻擊時】這張角色卡下一次無法置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-001":{"name":"和倉優希（無窮之鎖）","effectText":"若自己場上沒有〈羽前京香〉時，這張卡片無法〔登場・移動〕至前線。\n【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。\n【退場時】若自己前線有〈羽前京香〉時，查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":""},"UA48BT/KGD-1-100":{"name":"我等的國家絕對要守護到底！！","effectText":"從自己場外，使最多『1張』能源需求0的紅色角色卡以休息狀態在自己場上登場。若自己前線有〈嬴政〉時，則替換成『2張』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-002":{"name":"和倉優希（無窮之鎖）","effectText":"若自己場上沒有〈羽前京香〉時，這張卡片無法在前線〔登場・移動〕。\n若自己場外有〈羽前京香〉與〈和倉優希（無窮之鎖）〉合計10張以上時，這張角色卡獲得【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-010":{"name":"東日萬凜","effectText":"【若在前線時】這張角色卡的攻擊結束時，可將這張角色卡移動至能源線。若有執行此動作時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-009":{"name":"東日萬凜","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA49BT/MSS-1-011":{"name":"東日萬凜","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【若在能源線時】自己角色卡的攻擊結束時，若自己場上擁有4種以上不同卡片名稱的［特徵：七番組］，且自己前線有空格時，可將這張角色卡移動至前線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-006":{"name":"和倉優希（無窮之鎖・煌星）","effectText":"若自己場上沒有〈大川村寧〉時，這張卡片無法在前線〔登場・移動〕。\n【登場時】【攻擊時】若這張角色卡與〈大川村寧〉位於同一條戰線時，查看2張自己卡組上面的卡片，並將其以任意張數及任意順序分別放置在自己卡組的上面與下面。","triggerText":""},"UA49BT/MSS-1-008":{"name":"東日萬凜","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-007":{"name":"和倉優希（無窮之鎖・旋風）","effectText":"若自己場上沒有〈東日萬凜〉時，這張卡片無法在前線〔登場・移動〕。\n【若在能源線時】自己角色卡的攻擊結束時，若自己前線有〈東日萬凜〉，且自己前線有空格時，可將這張角色卡移動至前線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-016":{"name":"羽前京香","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【攻擊時】若自己場外有〈羽前京香〉與〈和倉優希（無窮之鎖）〉合計5張以上時，選擇最多1張自己場上的〈和倉優希（無窮之鎖）〉，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-015":{"name":"羽前京香","effectText":"【登場時】將最多2張自己卡組上面的卡片放置在場外。若自己場外有〈羽前京香〉與〈和倉優希（無窮之鎖）〉合計5張以上時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-017":{"name":"羽前京香","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA49BT/MSS-1-013":{"name":"東日萬凜","effectText":"【突襲】〈東日萬凜〉置為活動，並可移動至前線\n【登場時】若自己場上［特徵：七番組］的卡片名稱有4種以上時，這張角色卡在這個回合中，獲得【狙擊】。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上能源需求2以下的角色卡，並發動該張角色卡的【登場時】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-012":{"name":"東日萬凜","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n若自己場上［特徵：七番組］的卡片名稱有4種以上，且自己前線有空格，且在這個回合中自己的角色卡沒有從能源線攻擊時，這張角色卡可從能源線攻擊。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-014":{"name":"羽前京香","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-022":{"name":"大川村寧","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源＋【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA49BT/MSS-1-021":{"name":"羽前京香","effectText":"【登場時】從自己手牌中，使最多1張滿足能源需求且消耗AP為1的［特徵：七番組］以休息狀態在自己場上登場。若自己場上擁有4種以上不同卡片名稱的［特徵：七番組］時，將這張角色卡置為活動。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上其他的［特徵：七番組］，在這個回合中，獲得【衝擊（1）】。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA49BT/MSS-1-018":{"name":"羽前京香","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：七番組］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA49BT/MSS-1-019":{"name":"羽前京香","effectText":"【突襲】〈羽前京香〉置為活動，並可移動至前線\n【登場時】將最多3張自己卡組上面的卡片放置在場外。從自己場外將最多1張〈和倉優希（無窮之鎖）〉加入手牌。\n【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】僅限自己場外有合計10張以上〈羽前京香〉與〈和倉優希（無窮之鎖）〉時可發動。選擇1張自己場上的〈和倉優希（無窮之鎖）〉，在這個回合中，BP+1000與【傷害（2）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-020":{"name":"羽前京香","effectText":"【突襲】〈羽前京香〉置為活動，並可移動至前線\n【登場時】抽1張卡片。可將活動狀態的這張角色卡轉為休息。若有執行此動作時，『使最多1張自己手牌中的〈和倉優希（無窮之鎖）〉以活動狀態在自己場上登場』。若自己場外有合計10張以上〈羽前京香〉與〈和倉優希（無窮之鎖）〉時，可替換成『將1張自己的手牌放置在場外，並使最多1張自己場外的〈和倉優希（無窮之鎖）〉以活動狀態在自己場上登場』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-023":{"name":"大川村寧","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA49BT/MSS-1-028":{"name":"駿河朱朱","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-024":{"name":"大川村寧","effectText":"【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-026":{"name":"大川村寧","effectText":"【啟動主要】【每回合1】僅限在這張角色卡登場的回合中，且自己場上擁有4種以上不同卡片名稱的［特徵：七番組］時可發動。選擇1張自己場上其他的角色卡，置為活動，並在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-027":{"name":"大川村寧","effectText":"【登場時】從以下選擇1項。\n・查看2張自己卡組上面的卡片，將其依任意張數及任意順序分別放置在自己卡組的上面與下面。\n・選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n・若自己場上擁有4種以上不同卡片名稱的［特徵：七番組］時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-025":{"name":"大川村寧","effectText":"【啟動主要】【轉為休息】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-029":{"name":"駿河朱朱","effectText":"【退場時】從自己手牌中，使最多1張能源需求3以下消耗AP1的黃色［特徵：七番組］以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-031":{"name":"駿河朱朱","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【我方回合中】若自己場上［特徵：七番組］的卡片名稱有4種以上時，這張角色卡BP+500。","triggerText":""},"UA49BT/MSS-1-033":{"name":"駿河朱朱","effectText":"【突襲】〈駿河朱朱〉置為活動，並可移動至前線\n這張角色卡攻擊後戰勝時，抽1張卡片。\n【攻擊時】若自己場上［特徵：七番組］的卡片名稱有4種以上時，從以下選擇最多1項。\n・若自己前線有空格時，這張角色卡直到下一個我方回合開始前，獲得BP+1000與【傷害（2）】。\n・這張角色卡在這個回合中，獲得BP-1000與「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-032":{"name":"駿河朱朱","effectText":"【攻擊時】【防禦時】若自己場上［特徵：七番組］的卡片名稱有4種以上，且自己前線有空格時，這張角色卡在這個回合中，BP+2000。〈駿河朱朱〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-035":{"name":"出雲天花","effectText":"若自己場上有〈羽前京香〉時，使這張角色卡以活動狀態登場。\n【登場時】選擇最多1張自己場上的角色卡，移動至別的線，或與別的線的1張角色卡交換位置。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-034":{"name":"東八千穗","effectText":"若自己的手牌在2張以上，且自己場上的〈東日萬凜〉因對手的事件卡效果將離場時，可改為「將活動狀態的這張角色卡轉為休息，並將2張自己的手牌放置在場外。」。","triggerText":""},"UA49BT/MSS-1-030":{"name":"駿河朱朱","effectText":"若自己場上擁有4種以上不同卡片名稱的［特徵：七番組］時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA49BT/MSS-1-039":{"name":"無窮之鎖","effectText":"這張卡片僅限自己場上有〈羽前京香〉時才能使用。\n將最多3張自己卡組上面的卡片放置在場外。從自己場外將最多1張〈和倉優希（無窮之鎖）〉加入手牌。將1張自己的AP卡置為活動。","triggerText":""},"UA49BT/MSS-1-036":{"name":"若狹佐原","effectText":"【攻擊時】可將1張自己前線的〈駿河朱朱〉放回手牌。若有執行此動作時，選擇最多1張對手前線的〔持有【衝擊無效】的角色卡或原始BP5000以上的角色卡〕，使其退場。","triggerText":""},"UA49BT/MSS-1-038":{"name":"是時候屈服了！","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈羽前京香〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA49BT/MSS-1-037":{"name":"七番組宿舍","effectText":"【登場時】可以將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張能源需求3以下的［特徵：七番組］加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-041":{"name":"這是能力的代價！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA49BT/MSS-1-040":{"name":"男生也挺行的嘛","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA49BT/MSS-1-044":{"name":"錢函可可","effectText":"【對方回合中】若自己場上擁有合計4張以上［特徵：人型醜鬼］與［特徵：醜鬼］時，這張角色卡獲得BP+1000與【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-043":{"name":"一根角（鬼童丸）","effectText":"【我方回合中】若自己前線有〈和倉青羽〉時，這張角色卡BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-045":{"name":"錢函可可","effectText":"【退場時】抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-042":{"name":"魔都精兵的七番組","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。抽1張卡片，並將1張自己的手牌放置在場外。若自己場上擁有不同卡片名稱［特徵：七番組］的卡片有4種以上時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA49BT/MSS-1-046":{"name":"錢函可可","effectText":"若自己場上擁有合計4張以上［特徵：人型醜鬼］與［特徵：醜鬼］時，這張角色卡的產生能源+【綠】。","triggerText":""},"UA49BT/MSS-1-051":{"name":"湯野波音","effectText":"這張角色卡不會被BP4000以上的角色卡防禦。\n【登場時】若自己場上有合計4張以上的［特徵：人型醜鬼］與［特徵：醜鬼］時，可將1張自己場外的〈魔都之桃〉放置在移除區。若有執行此動作時，將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-047":{"name":"錢函可可","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【退場時】若自己場上擁有合計3張以上其他的［特徵：人型醜鬼］與［特徵：醜鬼］時，可「將2張自己的手牌放置在場外，或將1張自己場外的〈魔都之桃〉放置在移除區。」。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-050":{"name":"湯野波音","effectText":"【登場時】若自己場上有合計4張以上的［特徵：人型醜鬼］與［特徵：醜鬼］時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-048":{"name":"湯野波音","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA49BT/MSS-1-049":{"name":"湯野波音","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：人型醜鬼］或［特徵：醜鬼］或〈魔都之桃〉放置在場外，其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-057":{"name":"東日萬凜","effectText":"【啟動主要】【將2張手牌放置在場外】【每回合1】僅限自己前線有〈東八千穗〉時可發動。這張角色卡在這個回合中，獲得BP+1000與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-056":{"name":"備前銀奈","effectText":"【登場時】自己在這個回合中，獲得「自己與對手場上所有的角色卡，不會因效果而退場。」。","triggerText":""},"UA49BT/MSS-1-054":{"name":"和倉青羽","effectText":"【我方回合中】若自己場上有合計4張以上的［特徵：人型醜鬼］與［特徵：醜鬼］時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-055":{"name":"和倉青羽","effectText":"【突襲】〈和倉青羽〉置為活動，並可移動至前線\n【登場時】將最多1張自己場外或移除區的卡片以背面朝上放置在這張角色卡下面。若該張卡片為〈魔都之桃〉時，抽1張卡片。\n【攻擊時】從以下選擇1項。\n・將1張這張角色卡下面背面朝上的卡片放置在場外。若有執行此動作時，選擇最多1張對手前線BP5000以下的角色卡，使其退場。\n・發動這張角色卡的【登場時】。這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-053":{"name":"和倉青羽","effectText":"【登場時】查看3張自己卡組上面的卡片。公開其中最多1張［特徵：人型醜鬼］或［特徵：醜鬼］或〈魔都之桃〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-061":{"name":"東八千穗","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-059":{"name":"大川村寧","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA49BT/MSS-1-058":{"name":"羽前京香","effectText":"【攻擊時】若自己前線有〈出雲天花〉時，可將1張自己的手牌放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-062":{"name":"東八千穗","effectText":"【登場時】若自己前線有3張以上［特徵：六番組］時，抽1張卡片。","triggerText":""},"UA49BT/MSS-1-052":{"name":"和倉青羽","effectText":"【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":""},"UA49BT/MSS-1-060":{"name":"駿河朱朱","effectText":"【傷害（2）】（這張角色卡的攻擊直接造成傷害時，替換成2傷害）\n【每回合1】當自己的〈若狹沙原〉攻擊或防禦時，這張角色卡在這個回合中，BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-065":{"name":"出雲天花","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-066":{"name":"出雲天花","effectText":"此角色為活動狀態時，此角色的產生能量+【綠】。","triggerText":""},"UA49BT/MSS-1-067":{"name":"出雲天花","effectText":"【登場時】查看4張自己卡組上面的卡片。公開其中最多1張［特徵：六番組］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA49BT/MSS-1-064":{"name":"東八千穗","effectText":"【突襲】〈東八千穗〉置為活動，並可移動至前線\n【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。抽1張卡片。\n【啟動主要】【若在前線時】 【轉為休息】 ＃將1張手牌放置在場外＃這張角色卡下一次無法置為活動。使最多1張自己場外能源需求2以下消耗AP1的綠色［特徵：魔防隊］以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-063":{"name":"東八千穗","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【啟動主要】【若在前線時】 【轉為休息】選擇1張對手場上的角色卡，直到下一個我方回合開始前，使其無法移動。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-071":{"name":"若狹佐原","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-072":{"name":"若狹佐原","effectText":"【啟動主要】【若在前線時】【支付1AP】【每回合1】選擇這張角色卡，或1張自己能源線的［特徵：魔防隊］，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA49BT/MSS-1-068":{"name":"出雲天花","effectText":"【啟動主要】【每回合1】僅限這張角色卡在這回合中登場，且自己前線有3張以上［特徵：六番組］時可發動。從以下選擇1項。\n・選擇1張自己場上的［特徵：魔防隊］，移動至別的線，或與另一條戰線的1張角色卡交換位置。\n・抽1張卡片。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA49BT/MSS-1-069":{"name":"出雲天花","effectText":"【啟動主要】【每回合1】從以下選擇1項。在這個回合中〈出雲天花〉已選擇的效果無法選擇。\n・若這張角色卡在能源線時，將這張角色卡置為活動。\n・若這張角色卡在前線時，選擇1張自己場上的［特徵：魔防隊］，移動至別的線，或與另一條戰線的1張角色卡交換位置。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-073":{"name":"若狹佐原","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，會失去【衝擊】）\n【攻擊時】若自己前線有3張以上［特徵：六番組］時，這張角色卡在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-070":{"name":"出雲天花","effectText":"【突襲】〈出雲天花〉置為活動，並可移動至前線\n【階梯】（在自己的移動階段可以從前線移動至能源線）\n【若在能源線時】【每回合1】各回合中自己第一張角色卡的攻擊結束時，可「將這張角色卡移動至前線，或與1張自己前線的［特徵：魔防隊］交換位置。」。\n【啟動主要】【每回合1】若自己前線有3張以上［特徵：六番組］時，選擇任意張數自己場上的角色卡，移動至別的線或互相交換其位置。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA49BT/MSS-1-078":{"name":"魔都交流戰","effectText":"從自己場外將最多1張［特徵：六番組］加入手牌。從自己手牌中，使最多1張滿足能源需求且消耗AP為1的［特徵：六番組］以休息狀態在自己場上登場，或發動突襲。","triggerText":""},"UA49BT/MSS-1-079":{"name":"魔都之桃","effectText":"〈魔都之桃〉在1個回合中只能使用1張。\n抽1張卡片。選擇最多1張自己場上的［特徵：人型醜鬼］，在這個回合中，獲得「這張卡片的產生能源+【綠】。」。若自己場上有〈和倉青羽〉時，將1張自己的AP卡置為活動。","triggerText":"[顏色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA49BT/MSS-1-077":{"name":"我為姊姊","effectText":"若自己場上有〈和倉青羽〉時，手牌中這張卡片的消耗AP-1。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA49BT/MSS-1-076":{"name":"天御鳥命","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈出雲天花〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA49BT/MSS-1-074":{"name":"若狹佐原","effectText":"【登場時】將2張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。\n【啟動主要】【每回合1】僅限自己前線有3張以上［特徵：六番組］時可發動。將1～2張這張角色卡下面的背面朝上卡片放置在場外。若有執行此動作時，依據放置在場外的張數，這張角色卡在這個回合中，獲得以下所有效果。\n・1張以上：這張角色卡BP+1000。\n・2張以上：這張角色卡BP+1000與【衝擊（1）】。\n【啟動主要】【若在前線時】【轉為休息】發動這張角色卡的【登場時】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-075":{"name":"隱世村","effectText":"使這張場域卡以活動狀態登場。\n【啟動主要】【轉為休息】僅限自己場上合計有4張以上［特徵：人型醜鬼］與［特徵：醜鬼］時可發動。從以下選擇1項。\n・抽1張卡片。\n・這張場域卡在這個回合中，產生能源+【綠】【綠】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA49BT/MSS-1-080":{"name":"優希是千兆分的帥哥喔！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA50BT/IYS-1-004":{"name":"殺生丸","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-001":{"name":"阿吽","effectText":"【登場時】選擇最多1張自己場上不具備特徵的其他角色卡，移動至另一條線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA49BT/MSS-1-081":{"name":"我們與義姊的未來","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA50BT/IYS-1-003":{"name":"邪見","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張不具備特徵的角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA50BT/IYS-1-002":{"name":"邪見","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-010":{"name":"殺生丸的母親","effectText":"【登場時】從自己場外，將最多1張能源需求4以下不具備特徵的紫色角色卡加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-008":{"name":"殺生丸","effectText":"【我方回合中】若在這個回合中自己的角色卡曾從場外登場時，這張角色卡獲得【傷害（2）】。\n【登場時】從自己場外，使最多1張能源需求3以下消耗AP1不具備特徵的紫色角色卡以休息狀態在自己場上登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-006":{"name":"殺生丸","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若在這個回合中自己的角色卡曾從場外登場時，這張角色卡BP+1000。","triggerText":""},"UA50BT/IYS-1-009":{"name":"殺生丸","effectText":"【突襲】〈殺生丸〉置為活動，並可移動至前線\n【我方回合中】若在這個回合中，有自己的角色卡從場外登場時，這張角色卡獲得BP+500與【衝擊（1）】。\n【登場時】從自己場外，使最多1張能源需求3以下消耗AP1不具備特徵的紫色角色卡以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA50BT/IYS-1-005":{"name":"殺生丸","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【登場時】查看2張自己卡組上面的卡片，將最多1張不具備特徵的紫色角色卡放置在場外。其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-007":{"name":"殺生丸","effectText":"【攻擊時】若在這個回合中自己的角色卡曾從場外登場時，抽最多1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-014":{"name":"赤子","effectText":"【退場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：奈落一派］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":""},"UA50BT/IYS-1-013":{"name":"鈴","effectText":"若自己前線有〈殺生丸〉時，這張角色卡的產生能源+【紫】。\n【登場時】若這張角色卡是從場外登場時，選擇最多1張自己場上的〈殺生丸〉，置為活動。","triggerText":""},"UA50BT/IYS-1-016":{"name":"神樂","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-011":{"name":"鈴","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA50BT/IYS-1-015":{"name":"鬼蜘蛛","effectText":"【退場時】抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-012":{"name":"鈴","effectText":"【登場時】若自己場上有〈殺生丸〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-021":{"name":"神無","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：奈落一派］或〈神無之鏡〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-022":{"name":"神無","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外，或以背面朝上放置在自己場上1張〈奈落〉的下面。\n【啟動主要】從自己場外將1張［特徵：奈落一派］或〈四魂碎片〉以背面朝上放置在自己場上1張〈奈落〉的下面。〈神無〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-019":{"name":"神樂","effectText":"【登場時】從自己場外使最多1張能源需求2以下消耗AP1的紫色角色卡以休息狀態在自己場上登場。使該張角色卡在這個回合中，獲得「主要階段結束時，使這張角色卡退場。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-020":{"name":"獸郎丸&影郎丸","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA50BT/IYS-1-018":{"name":"神樂","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。\n【啟動主要】【每回合1】選擇最多1張自己場上其他的［特徵：奈落一派］，在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。使1張自己場上其他的［特徵：奈落一派］退場。","triggerText":""},"UA50BT/IYS-1-017":{"name":"神樂","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA50BT/IYS-1-028":{"name":"奈落","effectText":"【突襲】〈奈落〉置為活動，並可移動至前線\n依據這張角色卡下面背面朝上卡片的張數，獲得以下所有效果。\n・2張以上：若這張角色卡將離場時，可改為將這張卡片放回手牌。\n・3張以上：當這張角色卡從自己場上放回手牌時，若這張角色卡的突襲元卡能源需求為2以下且位於場外時，可使最多1張該卡片以休息狀態在自己場上登場。\n【啟動主要】【每回合1】從自己場外將1張［特徵：奈落一派］或〈四魂碎片〉以背面朝上放置在自己場上1張〈奈落〉的下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA50BT/IYS-1-027":{"name":"奈落","effectText":"【啟動主要】【每回合1】選擇最多1張對手前線的角色卡，使其在這個回合中BP-1000，將這張角色卡置為活動，並在這回合中獲得【衝擊（1）】。使1張自己場上的［特徵：奈落一派］退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-023":{"name":"悟心鬼","effectText":"【我方回合中】若在這個回合中自己場上的角色卡已退場時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-025":{"name":"奈落","effectText":"【登場時】選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。","triggerText":""},"UA50BT/IYS-1-031":{"name":"夢幻的白夜","effectText":"【退場時】將最多2張自己卡組上面的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-029":{"name":"白童子","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-030":{"name":"人見蔭刀","effectText":"這張卡片也視為〈奈落〉。\n【登場時】若自己場上所有的角色卡皆為［特徵：奈落一派］時，查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面，或以背面朝上放置在自己場上1張〈奈落〉的下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-024":{"name":"琥珀","effectText":"【退場時】將這張卡片加入手牌。","triggerText":""},"UA50BT/IYS-1-026":{"name":"奈落","effectText":"若這張角色卡下面有背面朝上卡片時，這張角色卡獲得【衝擊無效】。\n【我方回合中】若這張角色卡下面有背面朝上卡片時，這張角色卡BP+1000。","triggerText":"[顏色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA50BT/IYS-1-033":{"name":"最猛勝","effectText":"抽2張卡片。若自己場上有〈奈落〉時，對手將2張自身場外的事件卡依任意順序放置在自身卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-034":{"name":"四魂碎片","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA50BT/IYS-1-037":{"name":"爆碎牙","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈殺生丸〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA50BT/IYS-1-036":{"name":"天生牙","effectText":"抽1張卡片，並將1張自己的手牌放置在場外。之後，從自己場外使最多1張能源需求3以下消耗AP1不具備特徵的紫色角色卡以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-035":{"name":"瘴氣","effectText":"選擇1張對手前線的角色卡，自己場上每有1張［特徵：奈落一派］，該角色卡在這個回合中BP-1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA50BT/IYS-1-032":{"name":"神無之鏡","effectText":"【啟動主要】【轉為休息】從自己場外將1張［特徵：奈落一派］或〈四魂碎片〉以背面朝上放置在自己場上1張〈奈落〉的下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-039":{"name":"融合","effectText":"這張卡片僅限自己場上有角色卡時才能使用。\n將1張自己的AP卡置為活動。抽2張卡片。使1張自己場上的角色卡退場。可將這張卡片以背面朝上放置在自己場上1張〈奈落〉的下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-041":{"name":"阿波的八衛門狸","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張紅色的事件卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA50BT/IYS-1-040":{"name":"與鈴的性命對等之物——根本不存在！！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA50BT/IYS-1-038":{"name":"風刃之舞","effectText":"選擇1張對手前線BP3000以下的角色卡，使其退場。","triggerText":""},"UA50BT/IYS-1-042":{"name":"犬夜叉","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-043":{"name":"犬夜叉","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【啟動主要】【每回合1】僅限在這張角色卡在這回合中曾因自己的效果從活動轉為休息時才可發動。將這張角色卡置為活動，並在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-048":{"name":"桔梗","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-045":{"name":"犬夜叉","effectText":"【啟動主要】【每回合1】僅限在這張角色卡在這回合中曾因自己的效果從活動轉為休息時才可發動。將這張角色卡置為活動。\n【攻擊時】若這張角色卡的BP在4000以上時，抽1張卡片。","triggerText":""},"UA50BT/IYS-1-047":{"name":"楓","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-046":{"name":"犬夜叉","effectText":"【突襲】〈犬夜叉〉置為活動，並可移動至前線\n【每回合1】這張角色卡攻擊後沒有被防禦時，抽1張卡片。\n【啟動主要】【每回合1】僅限在這張角色卡在這回合中曾因自己的效果從活動轉為休息時才可發動。將這張角色卡置為活動，並在這個回合中，獲得『BP+1000與【衝擊（1）】』。若這張角色卡在這回合中登場時，可替換成『【雙重攻擊】』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA50BT/IYS-1-049":{"name":"桔梗","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【每回合1】僅限在這張角色卡登場的回合中可發動。將1張自己前線活動狀態的〈犬夜叉〉轉為休息。若有執行此動作時，從以下選擇1項。\n・將這張角色卡置為活動，並在這個回合中，BP+1000。\n・選擇最多1張對手前線的角色卡，轉為休息。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-044":{"name":"犬夜叉","effectText":"若這張角色卡下面沒有背面朝上卡片時，這張角色卡無法防禦。\n這張角色卡以活動狀態在場上登場\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，這張角色卡造成的直接傷害為2）\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡為休息狀態時可發動。將這張角色卡置為活動。\n【啟動主要】【若在前線時】【每回合1】將1張自己場外的〈鐵碎牙〉以背面朝上放置在這張角色卡下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-050":{"name":"雲母","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":""},"UA50BT/IYS-1-052":{"name":"銀太＆白角","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-051":{"name":"雲母","effectText":"【我方回合中】若在這個回合中自己的〈珊瑚〉曾進行攻擊時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-056":{"name":"珊瑚","effectText":"【登場時】查看2張自己卡組上面的卡片，將最多1張紅色的事件卡放置在場外。將其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-055":{"name":"琥珀","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA50BT/IYS-1-053":{"name":"鋼牙","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA50BT/IYS-1-057":{"name":"珊瑚","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈珊瑚〉或〈彌勒〉或〈雲母〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA50BT/IYS-1-054":{"name":"鋼牙","effectText":"【登場時】若自己場上有〈日暮籬〉時，可將這張角色卡置為活動。若有執行此動作時，這張角色卡在這個回合中，獲得「在自己攻擊階段結束時，若這張角色卡的BP在4000以下時，將這張角色卡放回手牌。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-060":{"name":"七寶","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA50BT/IYS-1-059":{"name":"珊瑚","effectText":"【突襲】〈珊瑚〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】抽『1張』卡片，並將1張自己的手牌放置在場外。若自己場上有〈彌勒〉時，可替換成『2張』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA50BT/IYS-1-061":{"name":"七寶","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。\n【啟動主要】【轉為休息】【使這張卡片退場】從自己場外，使最多1張〈七寶〉以外能源需求0的紅色角色卡以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-062":{"name":"刀刀齋","effectText":"【登場時】從自己場外將最多1張紅色的事件卡加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-058":{"name":"珊瑚","effectText":"【我方回合中】若自己場上有〈彌勒〉時，這張角色卡BP+1000。\n【登場時】查看3張自己卡組上面的卡片，將最多1張紅色的事件卡放置在場外。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-065":{"name":"日暮籬","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張〈犬夜叉〉或〈日暮籬〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-064":{"name":"日暮籬","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA50BT/IYS-1-067":{"name":"冥加","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA50BT/IYS-1-063":{"name":"日暮籬","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-068":{"name":"彌勒","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-069":{"name":"彌勒","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-070":{"name":"彌勒","effectText":"【啟動主要】【若在前線時】【每回合1】僅限自己場上有〈珊瑚〉時可發動。將1張自己場外的事件卡放置在移除區。若有執行此動作時，這張角色卡在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA50BT/IYS-1-071":{"name":"彌勒","effectText":"【突襲】〈彌勒〉置為活動，並可移動至前線\n【登場時】將自己場外的事件卡任意張數放置在移除區，選擇最多1張對手前線『BP2500以下』的角色卡，使其退場。若自己場上有〈珊瑚〉時，以此效果從場外放置在移除區的卡片每有1張，此效果可選擇的角色卡BP範圍+500。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA50BT/IYS-1-066":{"name":"日暮籬","effectText":"【突襲】〈日暮籬〉置為活動，並可移動至前線\n【登場時】從自己手牌中，使最多1張能源需求3以下消耗AP1的紅色〔〈犬夜叉〉或〈日暮籬〉〕以休息狀態在自己場上登場。\n【啟動主要】【若在前線時】【每回合1】將1張自己前線活動狀態的〈犬夜叉〉轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得「這張角色卡不會被BP4000以上的角色卡防禦。」，並選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA50BT/IYS-1-073":{"name":"這代表你可以選擇自己的活法","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA50BT/IYS-1-072":{"name":"食骨之井","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張〈犬夜叉〉或〈日暮籬〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA50BT/IYS-1-075":{"name":"我必須振作起來才行","effectText":"選擇最多1張自己場上的角色卡，在這個回合中，BP+2000。若自己場上有〈七寶〉時，將1張自己的AP卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-076":{"name":"我會賭上性命保護你","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA50BT/IYS-1-078":{"name":"結界","effectText":"抽2張卡片，並將2張自己的手牌放置在場外。若自己場上有〈彌勒〉時，將1張自己的AP卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA50BT/IYS-1-077":{"name":"風穴","effectText":"若自己場上有〈彌勒〉時，手牌中這張卡片的消耗AP-1。\n選擇最多1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA50BT/IYS-1-080":{"name":"飛來骨","effectText":"選擇1張對手前線的角色卡，轉為休息。\n當這張卡片因自己的效果從手牌放置在場外時，若自己場上有〈珊瑚〉時，抽1張卡片。","triggerText":""},"UA50BT/IYS-1-079":{"name":"鐵碎牙","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈犬夜叉〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA52BT/KJN-1-003":{"name":"歐蘿拉","effectText":"【啟動主要】選擇1張自己場上下面沒有背面朝上卡片的〈克萊兒·卡蓋諾〉，將這張角色卡以背面朝上放置在該角色卡下面。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-005":{"name":"亞蕾克西雅·米德加","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或下面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-002":{"name":"歐蘿拉","effectText":"【啟動主要】選擇1張自己場上下面沒有背面朝上卡片的〈克萊兒·卡蓋諾〉，將這張角色卡以背面朝上放置在該角色卡下面。若有執行此動作時，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA52BT/KJN-1-004":{"name":"歐蘿拉","effectText":"當這張卡片被放置在場外時，可將這張卡片從場外放置在自己卡組的上面。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】選擇1張自己場上下面沒有背面朝上卡片的〈克萊兒·卡蓋諾〉，將這張角色卡以背面朝上放置在該角色卡下面。若有執行此動作時，抽2張卡片。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA52BT/KJN-1-001":{"name":"愛麗絲·米德加","effectText":"這張角色卡以活動狀態在場上登場。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，這張角色卡造成的直接傷害為2）\n若可以的話，對手必須以BP高於這張角色卡的角色卡對這張角色卡的攻擊進行防禦。\n【每回合1】當這張角色卡攻擊後在對戰中敗北時，將這張角色卡置為活動，這張角色卡在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA52BT/KJN-1-007":{"name":"亞蕾克西雅·米德加","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈亞蕾克西雅·米德加〉或〈蘿絲·奧里亞納〉或〈夏目·卡夫卡〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-008":{"name":"亞蕾克西雅·米德加","effectText":"【啟動主要】【將1張手牌放置在場外】僅限這張角色卡登場的回合可發動。在這個回合中，下一張從移除區使用的卡片消耗AP-1。〈亞蕾克西雅·米德加〉的這個效果每回合僅可發動1次。","triggerText":""},"UA52BT/KJN-1-009":{"name":"亞蕾克西雅·米德加","effectText":"【突襲】〈亞蕾克西雅·米德加〉置為活動，並可移動至前線\n【登場時】查看2張自己卡組上面的卡片，將最多1張加入手牌，其餘依任意順序放置在自己卡組的上面。\n【啟動主要】【若在前線時】【每回合1】將1張自己卡組上面的卡片放置在移除區。在這個回合中，自己可從移除區使用該卡片。（使用時需滿足能源需求並支付消耗AP）","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-010":{"name":"安妮蘿潔·弗西亞納斯","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-006":{"name":"亞蕾克西雅·米德加","effectText":"【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】將1張自己卡組上面的卡片放置在移除區。在這個回合中，自己可從移除區使用該卡片。（使用時需滿足能源需求並支付消耗AP）","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-012":{"name":"克萊兒·卡蓋諾","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA52BT/KJN-1-011":{"name":"伊莉莎白","effectText":"這張角色卡無法在前線登場，且若其下面有背面朝上卡片時，無法移動。\n【傷害（2）】（這張角色卡的攻擊直接造成傷害時，這張角色卡造成的直接傷害為2）\n【登場時】將3張自己卡組上面的卡片以背面朝上放置在這張角色卡下面。\n【啟動主要】【若在能源線時】【轉為休息】將1張這張角色卡下面的背面朝上卡片放置在場外。之後，若這張角色卡下面沒有背面朝上卡片時，將這張角色卡置為活動，並移動至前線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-013":{"name":"克萊兒·卡蓋諾","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張『〈克萊兒·卡蓋諾〉或〈席德·卡蓋諾〉』並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。若自己場上有〈席德·卡蓋諾〉時，『〈克萊兒·卡蓋諾〉或〈席德·卡蓋諾〉』改為『角色卡』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-014":{"name":"克萊兒·卡蓋諾","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。若以此效果將〈歐蘿拉〉放置在場外時，可將該卡片以背面朝上放置在1張自己場上下面沒有背面朝上卡片的〈克萊兒·卡蓋諾〉下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-016":{"name":"克萊兒·卡蓋諾","effectText":"【突襲】〈克萊兒·卡蓋諾〉置為活動，並可移動至前線\n若這張角色卡下面有背面朝上卡片時，這張角色卡獲得BP+1000、【雙重攻擊】與「【退場時】將最多1張自己場外能源需求1以下的〈克萊兒·卡蓋諾〉加入手牌。」。\n【登場時】若自己場上有〈席德·卡蓋諾〉時，這張角色卡在這個回合中，獲得「若可以的話，對手必須對這張角色卡的第一次攻擊進行防禦。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-015":{"name":"克萊兒·卡蓋諾","effectText":"【突襲】〈克萊兒·卡蓋諾〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若這張角色卡下面有背面朝上卡片時，這張角色卡獲得BP+1000與【衝擊（1）】。\n【登場時】使最多1張自己場外能源需求2以下消耗AP1的黃色〈席德·卡蓋諾〉以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-017":{"name":"雪莉·巴奈特","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張黃色事件卡或黃色場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA52BT/KJN-1-018":{"name":"席德·卡蓋諾","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA52BT/KJN-1-019":{"name":"席德·卡蓋諾","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA50BT/IYS-1-074":{"name":"給我坐下！","effectText":"這張卡片僅限自己場上有〈日暮籬〉時才能使用。\n抽1張卡片。選擇最多1張自己場上的〈犬夜叉〉，在這個回合中，BP+1000。可將1張自己前線活動狀態的〈犬夜叉〉轉為休息。若有執行此動作時，將1張自己的AP卡置為活動。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA52BT/KJN-1-020":{"name":"席德·卡蓋諾","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-022":{"name":"夏目·卡夫卡","effectText":"這張卡片也視為〈貝塔〉。\n【登場時】若這張卡片是從移除區使用時，選擇最多1張自己場上的角色卡，置為活動。","triggerText":""},"UA52BT/KJN-1-024":{"name":"夏目·卡夫卡","effectText":"這張卡片也視為〈貝塔〉。\n【我方回合中】若在這個回合中自己有從移除區使用卡片時，這張角色卡BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-023":{"name":"夏目·卡夫卡","effectText":"這張卡片也視為〈貝塔〉。\n【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在自己卡組的上面或下面。\n・將1張自己的手牌放置在場外。若有執行此動作時，將1張自己卡組上面的卡片放置在移除區。在這個回合中，自己可從移除區使用該卡片。（使用時需滿足能源需求並支付消耗AP）","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-025":{"name":"夏目·卡夫卡","effectText":"這張卡片也視為〈貝塔〉。\n【啟動主要】【若在前線時】【每回合1】抽1張卡片，並將1張自己的手牌放置在自己卡組的上面。\n【啟動主要】【若在前線時】【每回合1】僅限在這個回合中自己有從移除區使用卡片時可發動。選擇1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[顔色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA52BT/KJN-1-027":{"name":"貝阿朵莉絲","effectText":"【啟動主要】【每回合1】僅限對手前線有BP4500以上的角色卡時可發動。這張角色卡在這個回合中，BP+2000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-021":{"name":"席德·卡蓋諾","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA52BT/KJN-1-026":{"name":"貝阿朵莉絲","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA52BT/KJN-1-028":{"name":"貝阿朵莉絲","effectText":"【我方回合中】這張角色卡BP+1000。\n【登場時】若對手前線有BP4500以上的角色卡時，將這張角色卡置為活動，並選擇最多1張對手前線BP4500以上的角色卡，轉為休息。〈貝阿朵莉絲〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA52BT/KJN-1-029":{"name":"瑪莉","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己前線BP1500以上的〈克萊兒·卡蓋諾〉，在這個回合中，BP-1000。若有執行此動作時，抽1張卡片，並將1張自己的手牌放置在場外，這張角色卡在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-030":{"name":"蘿絲·奧里亞納","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張〈亞蕾克西雅·米德加〉或〈蘿絲·奧里亞納〉或〈夏目·卡夫卡〉放置在場外，其餘依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-032":{"name":"蘿絲·奧里亞納","effectText":"【啟動主要】【每回合1】僅限這張角色卡登場的回合可發動。將1張自己卡組上面的卡片放置在移除區。在這個回合中，自己可從移除區使用該卡片。（使用時需滿足能源需求並支付消耗AP）","triggerText":""},"UA52BT/KJN-1-031":{"name":"蘿絲·奧里亞納","effectText":"【登場時】從以下選擇1項。\n・查看3張自己卡組上面的卡片，並依任意順序放置在自己卡組的上面。\n・將1張自己的手牌放置在場外。若有執行此動作時，將1張自己卡組上面的卡片放置在移除區。在這個回合中，自己可從移除區使用該卡片。（使用時需滿足能源需求並支付消耗AP）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-033":{"name":"蘿絲·奧里亞納","effectText":"【啟動主要】【轉為休息】從以下選擇1項。\n・將1張自己的手牌放置在自己卡組的上面。若有執行此動作時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n・若在這個回合中自己有從移除區使用卡片時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-034":{"name":"蘿絲·奧里亞納","effectText":"【突襲】〈蘿絲·奧里亞納〉置為活動，並可移動至前線\n【登場時】若這張卡片是從移除區使用時，選擇最多1張對手前線BP4000以下的角色卡，使其退場。\n【啟動主要】僅限在這個回合中自己有從移除區使用卡片時可發動。將1張這張角色卡的突襲元卡放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-035":{"name":"鬥技場","effectText":"這張場域卡以活動狀態在場上登場。\n【啟動主要】【轉為休息】分別選擇1張自己前線的角色卡與1張對手前線BP3500以上的活動角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA52BT/KJN-1-037":{"name":"我將斷罪你！","effectText":"選擇1張對手前線『BP2000以下』的角色卡，使其退場。若自己場上有〈蘿絲·奧里亞納〉時，改為『BP5000以下』。若這張卡片是從移除區使用時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA52BT/KJN-1-038":{"name":"覺醒之刻","effectText":"選擇最多1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈克萊兒·卡蓋諾〉時，改為『BP5000以下』。選擇最多1張自己場上處於突襲狀態且下面有背面朝上卡片的〈克萊兒·卡蓋諾〉，在這個回合中，獲得「對手以效果選擇這張角色卡時，若未額外將1張自己的手牌放置在場外，則無法選擇。」。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA52BT/KJN-1-040":{"name":"559","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】若自己場上有〈席德·卡蓋諾〉時，查看2張自己卡組上面的卡片，將任意張數依任意順序放置在自己卡組的上面，其餘放置在場外。\n【攻擊時】自己場外每有10張卡片，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-039":{"name":"這樣我們就是夥伴了喔","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA52BT/KJN-1-041":{"name":"664","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA52BT/KJN-1-043":{"name":"666","effectText":"這張卡片也視為〈蘿絲·奧里亞納〉。\n【退場時】將最多2張自己卡組上面的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-042":{"name":"665","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA52BT/KJN-1-044":{"name":"席德·卡蓋諾","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA52BT/KJN-1-036":{"name":"如果你找到了真正的我，請把我……","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA52BT/KJN-1-045":{"name":"席德·卡蓋諾","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA52BT/KJN-1-047":{"name":"闇影","effectText":"這張卡片也視為〈席德·卡蓋諾〉。\n若自己場外有10張以上卡片時，這張角色卡獲得【衝擊無效】。\n【登場時】【若在前線時】若自己場外有10張以上卡片時，可將這張角色卡置為活動。〈席德·卡蓋諾〉的這個效果每回合僅可發動1次。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA52BT/KJN-1-049":{"name":"闇影","effectText":"這張卡片也視為〈席德·卡蓋諾〉。\n【突襲】〈席德·卡蓋諾〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】在這個回合中，下一張從手牌使用的不持有【突襲】的卡片消耗AP-1。從自己場外選擇最多『1張』〔不持有【突襲】的［特徵：闇影庭園］或〈我是……〉〕，將所選卡片加入手牌。自己場外每有10張卡片，以這個效果可選擇的張數『+1張』。以這個效果選擇的卡片，原本的能源需求不能相同。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-048":{"name":"闇影","effectText":"這張卡片也視為〈席德·卡蓋諾〉。\n【突襲】〈席德·卡蓋諾〉置為活動，並可移動至前線\n這張角色卡在前線也能產生能源。\n【登場時】查看2張自己卡組上面的卡片，將1張加入手牌，其餘放置在場外。\n【退場時】可將1張自己的手牌放置在場外。若有執行此動作時，使最多1張這張角色卡的突襲元卡以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-050":{"name":"紐","effectText":"若自己場外有10張以上卡片時，這張角色卡BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-054":{"name":"阿爾法","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：七陰］並加入手牌。其餘依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA52BT/KJN-1-053":{"name":"阿爾法","effectText":"若自己場外有10張以上卡片，且自己場上有〈席德·卡蓋諾〉時，這張角色卡獲得「這張角色卡在前線也能產生能源。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-052":{"name":"阿爾法","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-055":{"name":"阿爾法","effectText":"【登場時】若自己場上有〈席德·卡蓋諾〉時，可將最多2張自己的手牌放置在場外。若有執行此動作時，抽與以此效果放置在場外的卡片張數相同數量的卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-046":{"name":"席德·卡蓋諾","effectText":"當這張角色卡被突襲時，進行突襲的角色卡在這個回合中，獲得【衝擊（1）】或【傷害（2）】。（被突襲的角色卡的【登場時】與這個效果可以依任意順序處理）","triggerText":""},"UA52BT/KJN-1-051":{"name":"紐","effectText":"自己場外每有10張卡片，這張角色卡的產生能源+【紫】。\n【登場時】查看2張自己卡組上面的卡片，將任意張數依任意順序放置在自己卡組的上面，其餘放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-058":{"name":"希妲","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-057":{"name":"希妲","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA52BT/KJN-1-059":{"name":"伊普西龍","effectText":"【登場時】查看3張自己卡組上面的卡片，並依任意順序放置在自己卡組的上面。","triggerText":""},"UA52BT/KJN-1-061":{"name":"伊普西龍","effectText":"【啟動主要】【若在前線時】【每回合1】將1張自己場上其他的［特徵：七陰］卡片放置在自己卡組下面。若有執行此動作時，使最多1張自己場外中，除〈伊普西龍〉以外，能源需求3以下消耗AP1的紫色［特徵：七陰］角色卡以休息狀態在自己場上登場。以這個效果登場的角色卡，其【登場時】不會發動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-060":{"name":"伊普西龍","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA52BT/KJN-1-063":{"name":"伽瑪","effectText":"【啟動主要】【轉為休息】【將1張手牌放置在場外】【每回合1】將最多1張自己卡組上面的卡片放置在場外。若自己場外有10張以上卡片時，這張角色卡在這個回合中，獲得產生能源+【紫】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-064":{"name":"伽瑪","effectText":"【登場時】抽1張卡片。\n【啟動主要】【轉為休息】【每回合1】若自己場上有7種以上不同卡片名稱的［特徵：七陰］時，選擇1張自己前線其他的［特徵：七陰］角色卡，置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-062":{"name":"伽瑪","effectText":"【啟動主要】【轉為休息】【每回合1】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA52BT/KJN-1-065":{"name":"潔塔","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-067":{"name":"戴爾塔","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-069":{"name":"戴爾塔","effectText":"【登場時】依自己場上［特徵：七陰］的不同卡片名稱種類數，以下效果全部發動。〈戴爾塔〉的這個效果每回合僅可發動1次。\n・5種以上：將這張角色卡置為活動。\n・7種以上：這張角色卡在這個回合中，獲得【狙擊】。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA52BT/KJN-1-070":{"name":"貝塔","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己前線的活動角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，獲得產生能源+【紫】。","triggerText":""},"UA52BT/KJN-1-068":{"name":"戴爾塔","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】僅限自己場上有5種以上不同卡片名稱的［特徵：七陰］時可發動。將這張角色卡置為活動。這張角色卡在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-071":{"name":"貝塔","effectText":"【登場時】使最多1張自己手牌中，能源需求2以下消耗AP1的紫色［特徵：七陰］角色卡以休息狀態在自己場上登場。","triggerText":""},"UA52BT/KJN-1-066":{"name":"潔塔","effectText":"若自己場上有7種以上不同卡片名稱的［特徵：七陰］時，這張角色卡獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。\n【登場時】若自己場上有5種以上不同卡片名稱的［特徵：七陰］，且為我方回合中時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-072":{"name":"貝塔","effectText":"【我方回合中】若自己場上有5種以上不同卡片名稱的［特徵：七陰］時，這張角色卡BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-056":{"name":"阿爾法","effectText":"【突襲】〈阿爾法〉置為活動，並可移動至前線\n【登場時】公開2張自己卡組上面的卡片，將其中不同卡片名稱的［特徵：七陰］各最多1張加入手牌。其餘放置在場外。\n【啟動主要】【若在前線時】『這張角色卡在這個回合中，獲得【衝擊（1）】』。若自己場上有7種以上不同卡片名稱的［特徵：七陰］時，改為『選擇1張自己場上的［特徵：七陰］，在這個回合中，獲得BP+1000與【衝擊（1）】』。〈阿爾法〉的這個效果每回合僅可發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-073":{"name":"貝塔","effectText":"若自己前線有〈席德·卡蓋諾〉時，這張角色卡的產生能源+【紫】。\n【登場時】將最多2張自己卡組上面的卡片放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA52BT/KJN-1-074":{"name":"貝塔","effectText":"【突襲】〈貝塔〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】可使1張自己手牌或場外中，能源需求2以下消耗AP1的紫色［特徵：七陰］以休息狀態在自己場上登場。若有執行此動作時，且自己場上不同卡片名稱的［特徵：七陰］在4種以下，將1張自己場上的卡片（以此效果登場的卡片除外）放置在自己卡組下面。\n【啟動主要】【若在前線時】【每回合1】若自己場上有7種以上不同卡片名稱的［特徵：七陰］時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA52BT/KJN-1-075":{"name":"亞歷山德里亞","effectText":"這張場域卡以活動狀態在場上登場。\n【啟動主要】【轉為休息】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。之後，若自己場外有10張以上卡片時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA52BT/KJN-1-076":{"name":"我是……","effectText":"若自己場上有〈席德·卡蓋諾〉時，手牌中這張卡片的能源需求減少【紫×2】。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA52BT/KJN-1-077":{"name":"解除惡魔附身","effectText":"將1張自己場外消耗AP1的［特徵：七陰］『加入手牌』。若自己場上沒有與該卡片同名的卡片，且自己滿足該卡片的能源需求時，可改為『使其以休息狀態在自己場上登場』。","triggerText":""},"UA52BT/KJN-1-080":{"name":"照亮黑暗的月光","effectText":"抽3張卡片，並將2張自己的手牌放置在場外。選擇最多1張自己場上的〈席德·卡蓋諾〉，在這個回合中，獲得產生能源+【紫】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA52BT/KJN-1-079":{"name":"闇影庭園","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA53BT/CSM-1-001":{"name":"小紅","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-003":{"name":"淀治","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紫】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA53BT/CSM-1-005":{"name":"淀治","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紫】。","triggerText":""},"UA53BT/CSM-1-007":{"name":"淀治","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】僅限在這個回合中自己使用了2張以上事件卡，且自己場上有〈真紀真〉時可發動。將這張角色卡置為活動。〈淀治〉的這個效果每回合僅可發動1次。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA52BT/KJN-1-078":{"name":"七陰","effectText":"選擇1張對手前線BP在自己場上［特徵：七陰］的張數×1000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA53BT/CSM-1-004":{"name":"淀治","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紫×2】。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-006":{"name":"淀治","effectText":"【退場時】『抽1張卡片』。若這張角色卡因自己的效果而退場時，可替換成『查看4張自己卡組上面的卡片，公開其中最多1張〈蕾潔〉或〈淀治〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。』","triggerText":""},"UA53BT/CSM-1-002":{"name":"颱風惡魔","effectText":"若在同一條線上有〈蕾潔〉時，這張角色卡獲得BP+1000與【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-008":{"name":"淀治","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。若以此效果將〈真紀真〉加入手牌時，選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。若以此效果將〈蕾潔〉加入手牌時，選擇最多1張對手前線BP1500以上的角色卡，在這個回合中，BP-1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-012":{"name":"帕瓦","effectText":"這張角色卡攻擊後戰勝時，將1張自己的手牌放置在場外。","triggerText":""},"UA53BT/CSM-1-010":{"name":"天使惡魔","effectText":"【我方回合中】若自己場上有〈真紀真〉時，依據在這個回合中自己使用的事件卡張數，這張角色卡獲得以下所有效果。\n・1張以上：BP+1000。\n・2張以上：這張角色卡不會被BP4000以上的角色卡防禦。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-009":{"name":"天使惡魔","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA53BT/CSM-1-011":{"name":"早川秋","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA53BT/CSM-1-013":{"name":"帕瓦","effectText":"【攻擊時】若自己場上有〈淀治〉時，這張角色卡在這個回合中，BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-014":{"name":"比姆","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】選擇最多1張自己場上的〈淀治〉，在這個回合中，使其BP+1000並獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-018":{"name":"真紀真","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-015":{"name":"暴力魔人","effectText":"【我方回合中】在這個回合中自己每使用1張事件卡，這張角色卡BP+500。","triggerText":""},"UA53BT/CSM-1-017":{"name":"波姆","effectText":"這張卡片也視為〈蕾潔〉。\n【突襲】〈蕾潔〉置為活動，並可移動至前線\n【登場時】從以下選擇1項。\n・選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。\n・若為我方回合中，且自己場上與場外BP4000以上的卡片僅有〈蕾潔〉時，可使1張自己場上其他的角色卡退場。若有執行此動作時，選擇最多1張對手前線的角色卡，在這個回合中，BP-5000。\n【啟動主要】【每回合1】這張角色卡在這個回合中，獲得【衝擊（1）】。將1張這張角色卡的突襲元卡放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-016":{"name":"波姆","effectText":"這張卡片也視為〈蕾潔〉。\n【我方回合中】若在這個回合中自己場上的〈淀治〉已退場時，這張角色卡獲得【傷害（2）】。\n【登場時】若自己場上與場外BP4000以上的卡片僅有〈蕾潔〉時，可使1張自己場上其他的角色卡退場。若有執行此動作時，將這張角色卡與1張自己的AP卡置為活動，這張角色卡在這個回合中，獲得BP+1000與【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-021":{"name":"真紀真","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-022":{"name":"真紀真","effectText":"【若在前線時】〈真紀真〉以外的自己紫色角色卡在所有區域也視為事件卡。\n【啟動主要】【若在前線時】【每回合1】僅限在這個回合中自己使用了事件卡時可發動。選擇1張自己場上其他的角色卡，在這個回合中，給予【衝擊（1）】。","triggerText":""},"UA53BT/CSM-1-019":{"name":"真紀真","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-024":{"name":"真紀真","effectText":"【突襲】〈真紀真〉置為活動，並可移動至前線\n【若在前線時】〈真紀真〉以外的自己紫色角色卡在所有區域也視為事件卡。\n【登場時】在這個回合中，下一張從手牌中使用不持有【特殊觸發】與【最終觸發】的事件卡的消耗AP-1。從以下選擇1項。\n・抽1張卡片。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-025":{"name":"蕾潔","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-026":{"name":"蕾潔","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-028":{"name":"蕾潔","effectText":"【登場時】從自己手牌中，使最多1張能源需求2以下消耗AP1的紫色〔〈蕾潔〉或〈淀治〉或〈咖啡廳「二道」〉〕以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-020":{"name":"真紀真","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-029":{"name":"蕾潔","effectText":"這張角色卡攻擊後沒有被防禦時，若在這個回合中自己場上的〈淀治〉已退場時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-030":{"name":"蕾潔","effectText":"【登場時】可使1張自己場上其他的角色卡退場。若有執行此動作時，從以下選擇1項。\n・抽1張卡片。選擇最多1張自己場上其他的角色卡，在這個回合中，BP+2000。\n・抽2張卡片。","triggerText":"[顔色] 使1張自己場外能源需求2以下消耗AP1的紫色角色卡以活動狀態在自己前線登場。"},"UA53BT/CSM-1-031":{"name":"蕾潔","effectText":"【突襲】〈蕾潔〉置為活動，並可移動至前線\n【登場時】抽1張卡片。從以下選擇1項。\n・選擇最多1張對手前線的角色卡，在這個回合中，BP-1000。\n・若為我方回合中，且在這個回合中自己場上的〈淀治〉已退場時，將1張自己的AP卡置為活動。〈蕾潔〉的這個效果每回合僅可選擇1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-032":{"name":"電影院","effectText":"【登場時】若自己場上有〈真紀真〉時，從自己場外將最多1張能源需求3以下的〔〈淀治〉或〈約會〉〕加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-034":{"name":"有喔。","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA53BT/CSM-1-035":{"name":"我絕對不會喜歡上別人的！！","effectText":"查看6張自己卡組上面的卡片，公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若以此效果將〈真紀真〉加入手牌時，從自己場外將最多1張〈約會〉加入手牌。若以此效果將〈蕾潔〉加入手牌時，從自己場外將最多1張能源需求1以下的〈淀治〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-036":{"name":"因為我喜歡你啊，淀治君","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA53BT/CSM-1-037":{"name":"約會","effectText":"從以下選擇1項。\n・選擇1張自己場上的角色卡，在這個回合中，BP+1000。在這個回合中，〈真紀真〉以外自己紫色的角色卡在所有區域也視為事件卡。將1張自己的AP卡置為活動。\n・抽2張卡片，並將1張自己的手牌放置在場外。若在這個回合中自己使用了其他的事件卡時，將1張自己的AP卡置為活動。〈約會〉的這個效果每回合僅可選擇1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-038":{"name":"淀治君的心臟我就收下了喔……","effectText":"這張卡片僅限自己場上有〈蕾潔〉時才能使用。\n使1張自己場上的角色卡退場。若有執行此動作時，將1張自己的AP卡置為活動，並抽2張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-039":{"name":"砰。","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈蕾潔〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA53BT/CSM-1-027":{"name":"蕾潔","effectText":"【我方回合中】若在這個回合中自己場上的〈淀治〉已退場時，這張角色卡BP+1000。","triggerText":""},"UA53BT/CSM-1-040":{"name":"我也喜歡鄉下老鼠。","effectText":"這張卡片僅限自己場上有〈真紀真〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。若在這個回合中自己使用了其他的事件卡時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA53BT/CSM-1-033":{"name":"咖啡廳「二道」","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張角色卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若將〈蕾潔〉以外的卡片加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-041":{"name":"荒井","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-023":{"name":"真紀真","effectText":"【突襲】〈真紀真〉置為活動，並可移動至前線\n【啟動主要】【若在前線時】【每回合1】從自己場外將1張不持有【特殊觸發】與【最終觸發】的事件卡加入手牌。\n【啟動主要】【若在前線時】【每回合1】僅限在這個回合中自己使用了事件卡時可發動。選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-043":{"name":"小紅","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-042":{"name":"岸邊","effectText":"這張角色卡以活動狀態在場上登場。\n【啟動主要】【若在前線時】【每回合1】選擇最多2張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-044":{"name":"小紅","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA53BT/CSM-1-045":{"name":"小紅","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-049":{"name":"淀治","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA53BT/CSM-1-046":{"name":"小紅","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n當這張角色卡在自己的移動階段以外移動時，這張角色卡在這個回合中，獲得「不會被BP4000以上的角色卡防禦。」與「這張角色卡攻擊後沒有被防禦時，抽最多1張卡片。」。","triggerText":""},"UA53BT/CSM-1-047":{"name":"鏈鋸人","effectText":"這張卡片也視為〈淀治〉。\n【突襲】〈淀治〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【退場時】從以下選擇1項。\n・抽2張卡片。\n・若這張角色卡下面有背面朝上卡片時，使這張卡片以活動狀態在自己前線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-048":{"name":"鏈鋸人","effectText":"這張卡片也視為〈淀治〉。\n【突襲】〈淀治〉置為活動，並可移動至前線\n在這張角色卡的攻擊結束時，若這張角色卡下面有背面朝上卡片時，將這張角色卡置為活動，這張角色卡在這個回合中，獲得【衝擊（1）】。之後，將1張這張角色卡下面的背面朝上卡片放置在場外。若以此效果放置在場外的卡片為〈波奇塔〉時，可將最多1張該卡片以休息狀態在自己能源線登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-053":{"name":"早川秋","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈早川秋〉或〈姬野〉或〈真紀真〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-050":{"name":"淀治","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-052":{"name":"早川秋","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-054":{"name":"早川秋","effectText":"【登場時】若自己場上有〈姬野〉時，抽1張卡片，並將1張自己的手牌以背面朝上放置在這張角色卡下面。\n【攻擊時】可將1張自己前線的〈早川秋〉下面的背面朝上卡片放置在場外。若有執行此動作時，這張角色卡在這個回合中，BP+1500。","triggerText":""},"UA53BT/CSM-1-055":{"name":"早川秋","effectText":"【啟動主要】【若在前線時】【將1張手牌放置在場外】【每回合1】從以下選擇1項。在這個回合中，無法選擇〈早川秋〉已選擇過的效果。\n・選擇1張自己場上的角色卡，在這個回合中，給予「這張角色卡不會被BP3000以下的角色卡防禦。」的效果。\n・查看3張自己卡組上面的卡片，公開其中最多1張〈早川秋〉或〈淀治〉或〈帕瓦〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若沒有加入手牌時，抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-056":{"name":"早川秋","effectText":"【突襲】〈早川秋〉置為活動，並可移動至前線\n在我方回合開始時，若這張角色卡下面沒有背面朝上卡片時，使這張角色卡退場。\n這張角色卡攻擊時，將1張這張角色卡下面的背面朝上卡片加入手牌。之後，若自己場上有〈姬野〉，且這張角色卡下面沒有背面朝上卡片時，這張角色卡在這個回合中，獲得【狙擊】與【衝擊（1）】。\n【登場時】這張角色卡在這個回合中，BP+1000。將3張自己卡組上面的卡片以背面朝上放置在這張角色卡的下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-057":{"name":"帕瓦","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-051":{"name":"淀治","effectText":"【登場時】查看2張自己卡組上面的卡片，將任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。之後，選擇最多1張自己場上非突襲狀態且下面沒有背面朝上卡片的〈淀治〉，從自己場外將最多1張〈波奇塔〉或〈作為交換…讓我看看你的夢想吧〉以背面朝上放置在該角色卡下面。","triggerText":""},"UA53BT/CSM-1-058":{"name":"帕瓦","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA53BT/CSM-1-060":{"name":"帕瓦","effectText":"【登場時】若自己場上有〈淀治〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-059":{"name":"帕瓦","effectText":"【啟動主要】【將1張手牌放置在場外】【每回合1】這張角色卡在這個回合中，產生能源+【紅】。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-062":{"name":"比姆","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】選擇最多1張自己場上的〈淀治〉，在這個回合中，獲得「【攻擊時】抽最多1張卡片。」。","triggerText":""},"UA53BT/CSM-1-061":{"name":"帕瓦","effectText":"【突襲】〈帕瓦〉置為活動，並可移動至前線\n【每回合1】BP500以上的這張角色卡將退場時，可改為使1張自己前線BP4000以上的其他角色卡退場作為代替。\n這張角色卡攻擊後戰勝時，抽1張卡片。\n【登場時】若自己場上有〈淀治〉時，這張角色卡在這個回合中，獲得BP+1000與「對手必須盡可能防禦這張角色卡的攻擊。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-063":{"name":"姬野","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-066":{"name":"姬野","effectText":"【突襲】〈姬野〉置為活動，並可移動至前線\n這張角色卡的攻擊結束時，可使這張角色卡退場。\n【若在前線時】在自己結束階段開始時，可選擇1張自己前線〈姬野〉以外的角色卡與1張自己能源線的角色卡，並互相交換其位置。\n【登場時】抽1張卡片。\n【退場時】若自己場上與場外沒有原始BP4500以上的卡片時，選擇最多1張自己能源線的角色卡，在這個回合中，BP+2000，並移動至前線。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-067":{"name":"波奇塔","effectText":"這張卡片無法在前線登場，且無法移動至前線。\n【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。\n【啟動主要】【轉為休息】【使這張卡片退場】可從自己場外，使最多1張能源需求1以下的紅色〈淀治〉以活動狀態在自己能源線登場。若有執行此動作時，將因這個效果而退場的這張卡片以背面朝上放置在該〈淀治〉的下面。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA53BT/CSM-1-068":{"name":"真紀真","effectText":"【退場時】可將2張自己手牌中的角色卡或1張事件卡放置在場外。若有執行此動作時，將這張卡片加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-069":{"name":"真紀真","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA53BT/CSM-1-064":{"name":"姬野","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-071":{"name":"未來惡魔","effectText":"【啟動主要】【轉為休息】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-065":{"name":"姬野","effectText":"【啟動主要】【轉為休息】【每回合1】選擇1張自己能源線的卡片，置為活動。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA53BT/CSM-1-072":{"name":"幽靈惡魔","effectText":"【攻擊時】在這個回合中，若這張角色卡曾在移動階段以外的時機移動時，從自己場外將最多1張能源需求2以下的〈早川秋〉加入手牌。","triggerText":""},"UA53BT/CSM-1-073":{"name":"早川家","effectText":"【登場時】查看4張自己卡組上面的卡片，公開其中最多1張〈早川秋〉或〈淀治〉或〈帕瓦〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-075":{"name":"開槍！","effectText":"選擇1張自己場上的角色卡，在這個回合中，BP+2000。可將1張自己場上〈早川秋〉下面的背面朝上卡片放置在場外。若有執行此動作時，將1張自己的AP卡置為活動，並選擇最多1張自己場上的〈早川秋〉，在這個回合中，給予【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[抽卡] 抽1張卡片。"},"UA53BT/CSM-1-077":{"name":"…叩。","effectText":"這張卡片僅限自己場上有〈早川秋〉時才能使用。\n選擇1張對手前線BP5000以下的角色卡，使其退場。可將1張自己場上〈早川秋〉下面的背面朝上卡片放置在場外。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA53BT/CSM-1-076":{"name":"作為交換…讓我看看你的夢想吧","effectText":"從以下選擇1項。\n・查看2張自己卡組上面的卡片，將其中任意張數依任意順序放置在自己卡組的上面，其餘卡片放置在場外。之後，可「從自己場外，使1張能源需求1以下的紅色〈淀治〉以活動狀態在自己能源線登場，並將這張卡片以背面朝上放置在該〈淀治〉下面。」。\n・將這張卡片以背面朝上放置在自己場上沒有背面朝上卡片的〈淀治〉下面。若該〈淀治〉非突襲狀態時，將1張自己的AP卡置為活動。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA53BT/CSM-1-070":{"name":"真紀真","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己能源線的角色卡，與這張角色卡交換位置。\n【攻擊時】使1張自己場上〈真紀真〉以外的角色卡退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA53BT/CSM-1-079":{"name":"不是約好了嗎？","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA54BT/MST-1-001":{"name":"艾莉絲","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-002":{"name":"艾莉絲","effectText":"","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-004":{"name":"艾莉絲","effectText":"【登場時】若這張角色卡是因自己的效果而登場時，將這張角色卡置為活動。","triggerText":""},"UA53BT/CSM-1-078":{"name":"最強的麵包","effectText":"抽『2張』卡片。若自己場上有〈早川家〉，或自己場上〈淀治〉的下面有背面朝上卡片時，則替換成『3張』。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-005":{"name":"艾莉絲","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若在這個回合中，已因自己的效果使角色卡〔登場或發動突襲〕時，這張角色卡BP+500。","triggerText":""},"UA53BT/CSM-1-080":{"name":"我喜歡壞傢伙喔～？","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈淀治〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA54BT/MST-1-006":{"name":"艾莉絲","effectText":"【登場時】可支付1AP。若有執行此動作時，抽1張卡片，並從自己手牌中使最多1張能源需求3以下消耗AP1的藍色〔〈魯迪烏斯〉或〈艾莉絲〉或〈瑞傑路德〉〕以休息狀態在自己場上登場，或發動突襲。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA54BT/MST-1-007":{"name":"艾莉絲","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・若這張角色卡是因自己的效果而登場時，從自己手牌中使最多1張能源需求3以下消耗AP1的藍色〔〈魯迪烏斯〉或〈艾莉絲〉或〈瑞傑路德〉〕以休息狀態在自己場上登場，或發動突襲。〈艾莉絲〉的這個效果每回合僅可選擇1次。","triggerText":""},"UA54BT/MST-1-008":{"name":"艾莉絲","effectText":"【突襲】〈艾莉絲〉置為活動，並可移動至前線\n這張角色卡攻擊後沒有被防禦時，抽最多1張卡片。\n【每回合1】這張角色卡攻擊後在對戰中敗北時，將這張角色卡置為活動，且這張角色卡在這個回合中，BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA53BT/CSM-1-074":{"name":"輕鬆的復仇！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA54BT/MST-1-003":{"name":"艾莉絲","effectText":"若自己場上有〈魯迪烏斯〉與〈瑞傑路德〉時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-010":{"name":"奇希莉卡・奇希里斯","effectText":"【登場時】查看3張自己卡組上面的卡片，並依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-011":{"name":"基列奴","effectText":"【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的〈艾莉絲〉，在這個回合中，BP+1000。","triggerText":""},"UA54BT/MST-1-013":{"name":"希露菲葉特","effectText":"【退場時】抽1張卡片。","triggerText":""},"UA54BT/MST-1-012":{"name":"希露菲葉特","effectText":"【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-015":{"name":"聖獸","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-016":{"name":"塞妮絲","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA54BT/MST-1-017":{"name":"諾倫＆愛夏","effectText":"【登場時】抽1張卡片。","triggerText":""},"UA54BT/MST-1-019":{"name":"莉莉雅","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA54BT/MST-1-018":{"name":"保羅","effectText":"【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-014":{"name":"希露菲葉特","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【我方回合中】在這個回合中若自己使用了事件卡，且在同一條線上擁有〈魯迪烏斯〉時，這張角色卡BP+1500。\n【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-020":{"name":"瑞傑路德","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-021":{"name":"瑞傑路德","effectText":"【登場時】從自己手牌中，使最多1張能源需求3以下消耗AP1的藍色〔〈魯迪烏斯〉或〈艾莉絲〉或〈瑞傑路德〉〕以休息狀態在自己場上登場，或發動突襲。\n【啟動主要】【每回合1】僅限自己場上有〈魯迪烏斯〉與〈艾莉絲〉時才可發動。將這張角色卡置為活動。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-024":{"name":"魯迪烏斯","effectText":"【我方回合中】若自己場上有〈洛琪希〉時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-023":{"name":"魯迪烏斯","effectText":"【登場時】若這張角色卡是因自己的效果而登場時，抽1張卡片。","triggerText":""},"UA54BT/MST-1-026":{"name":"魯迪烏斯","effectText":"這張卡片無法在前線登場，且無法以自己的效果以外的方式移動。\n【攻擊時】從以下選擇1項。\n・選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。\n・抽1張卡片。\n・若在這個回合中自己已使用〈豪雷積層雲〉時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-025":{"name":"魯迪烏斯","effectText":"【突襲】〈魯迪烏斯〉置為活動，並可移動至前線\n【登場時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。\n【啟動主要】【若在前線時】【每回合1】從以下選擇1項。\n・發動這張角色卡的【登場時】。\n・選擇1張自己場上突襲狀態的〈艾莉絲〉，在這個回合中，獲得【狙擊】，並將這張角色卡最上面的卡片放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-009":{"name":"艾莉絲","effectText":"【突襲】〈艾莉絲〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【我方回合中】這張角色卡BP+500。\n【登場時】若這張角色卡是因自己的效果而登場時，從以下選擇1項。\n・這張角色卡直到下一個我方回合開始前，BP+1000。\n・這張角色卡在這個回合中，獲得「這張角色卡的攻擊結束時，可選擇1張自己能源線的角色卡，與這張角色卡互相交換位置。」的效果。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-022":{"name":"魯迪烏斯","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-029":{"name":"洛琪希","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA54BT/MST-1-027":{"name":"洛琪希","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-028":{"name":"洛琪希","effectText":"【登場時】查看2張自己卡組上面的卡片，公開其中最多1張〈魯迪烏斯〉或〈洛琪希〉或能源需求2以下的事件卡並加入手牌。其餘卡片放置在場外。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-030":{"name":"洛琪希","effectText":"【啟動主要】【轉為休息】僅限在這個回合中自己使用了事件卡時可發動。從以下選擇1項。\n・選擇1張自己場上的角色卡，在這個回合中，BP+1000。\n・抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA54BT/MST-1-031":{"name":"洛琪希","effectText":"【突襲】〈洛琪希〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【我方回合中】若在這個回合中自己已使用事件卡時，這張角色卡獲得【衝擊（1）】。\n【登場時】在這個回合中，下一張從手牌中使用能源需求3以下的事件卡的消耗AP-1。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-032":{"name":"洛琪希","effectText":"【突襲】〈洛琪希〉置為活動，並可移動至前線\n【登場時】從自己場外將最多1張能源需求2以下的卡片加入手牌。\n【啟動主要】【若在前線時】【每回合1】僅限在這個回合中自己使用了事件卡時可發動。選擇1張自己場上能源需求3以下的角色卡，置為活動。\n【啟動主要】【若在前線時】【每回合1】選擇1張自己場上的〈魯迪烏斯〉，移動至另一條線。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-035":{"name":"你是戰士","effectText":"從以下選擇最多3項。\n・若自己場上有〈魯迪烏斯〉時，抽1張卡片。\n・若自己場上有〈艾莉絲〉時，抽1張卡片。\n・若自己場上有〈瑞傑路德〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-033":{"name":"死路一條","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張〈魯迪烏斯〉或〈艾莉絲〉或〈瑞傑路德〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n【啟動主要】【轉為休息】【使這張卡片退場】從自己手牌中，將1張能源需求3以下消耗AP1的藍色角色卡以休息狀態在自己場上登場，或發動突襲。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-036":{"name":"豪雷積層雲","effectText":"這張卡片僅限自己場上有〈洛琪希〉時才能使用。\n自己場外每有2張事件卡，在所有區域這張卡片的能源需求減少【イ藍×1】。\n選擇1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA54BT/MST-1-038":{"name":"來自師父的禮物","effectText":"選擇1張自己場上的角色卡，在這個回合中，BP+1000。若自己場上有〈洛琪希〉時，將1張自己的AP卡置為活動。\n【啟動主要】【若在場外時】僅限在這個回合中自己的〈魯迪烏斯〉或〈洛琪希〉已發動突襲時可發動。將1張自己的手牌放置在場外。若有執行此動作時，將場外的這張卡片加入手牌。〈來自師父的禮物〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-037":{"name":"御神體","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自分の生命區。"},"UA54BT/MST-1-039":{"name":"魯迪烏斯很厲害的喔！","effectText":"從以下選擇1項。\n・選擇1張自己場上的〈艾莉絲〉，在這個回合中，獲得BP+500與【狙擊】（可以指定攻擊對手前線的角色卡，指定時，對手無法進行防禦）。\n・若自己場上有〈艾莉絲〉時，從自己場外使最多1張消耗AP1的藍色〈魯迪烏斯〉以休息狀態在自己場上登場，或發動突襲。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA54BT/MST-1-040":{"name":"因為有我在","effectText":"這張卡片僅限自己場上有〈洛琪希〉時才能使用。\n從自己手牌中，使最多1張滿足能源需求且消耗AP為1的藍色〔〈魯迪烏斯〉或〈洛琪希〉〕以休息狀態在自己場上登場，或發動突襲。抽1張卡片。選擇最多1張自己場上的〈魯迪烏斯〉，移動至另一條線。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA54BT/MST-1-041":{"name":"愛夏","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-034":{"name":"請教艾莉絲魔術喵☆","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自分の生命區。"},"UA54BT/MST-1-042":{"name":"艾莉娜麗潔","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】僅限在這個回合中自己場上的場域卡已退場時可發動。將這張角色卡置為活動。〈艾莉娜麗潔〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-043":{"name":"基斯","effectText":"【登場時】查看5張自己卡組上面的卡片，公開其中最多1張綠色場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA54BT/MST-1-044":{"name":"莎拉","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA54BT/MST-1-047":{"name":"保羅","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-046":{"name":"塔爾韓德","effectText":"若在這個回合中自己場上的場域卡已退場時，這張角色卡的產生能源+【綠】。\n【啟動主要】【若在前線時】【每回合1】使1張自己場上的場域卡退場。若有執行此動作時，這張角色卡在這個回合中，BP+1000。","triggerText":""},"UA54BT/MST-1-045":{"name":"塞妮絲","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA54BT/MST-1-049":{"name":"魯迪烏斯","effectText":"【登場時】可使1張自己場上的場域卡退場。若有執行此動作時，將這張角色卡置為活動，並查看4張自己卡組上面的卡片，公開其中最多1張不具備特徵的〔角色卡或場域卡〕並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-048":{"name":"保羅","effectText":"【登場時】可使1張自己場上的場域卡退場。若有執行此動作時，將這張角色卡置為活動。\n【攻擊時】若自己場外有6張以上場域卡時，可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡置為活動。〈保羅〉的這個效果每回合僅可發動1次。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-051":{"name":"洛琪希","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-050":{"name":"洛琪希","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-053":{"name":"洛琪希","effectText":"【對方回合中】可將自己綠色【顏色觸發】效果中記載的「角色卡」替換為「場域卡」。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【啟動主要】【若在前線時】【每回合1】可使1張自己場上的場域卡退場。若有執行此動作時，抽1張卡片。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA54BT/MST-1-052":{"name":"洛琪希","effectText":"【退場時】若自己場上有場域卡時，抽1張卡片。","triggerText":""},"UA54BT/MST-1-054":{"name":"洛琪希","effectText":"【突襲】〈洛琪希〉置為活動，並可移動至前線\n【登場時】若自己場外有場域卡時，選擇最多1張對手前線的角色卡，轉為休息。該張角色卡直到下一個對手攻擊階段結束前，失去所有原本的效果，且無法置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-055":{"name":"愛麗兒","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：拉諾亞魔法大學］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-057":{"name":"克里夫","effectText":"這張角色卡若在前線時也可產生能源。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-059":{"name":"希露菲葉特","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・選擇最多1張自己前線其他的［特徵：拉諾亞魔法大學］，在這個回合中，獲得「這張角色卡若在前線時也可產生能源。」的效果。","triggerText":""},"UA54BT/MST-1-058":{"name":"札諾巴＆茱麗葉","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【每回合1】僅限自己的產生能源在7以上，且自己場上的角色卡全部為［特徵：拉諾亞魔法大學］時可發動。這張角色卡直到下一個我方回合開始前，BP+500。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-056":{"name":"艾莉娜麗潔","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己前線的活動角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，產生能源+【綠】。","triggerText":""},"UA54BT/MST-1-060":{"name":"希露菲葉特","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【啟動主要】【若在前線時】【每回合1】抽1張卡片，並將1張自己的手牌放置在場外。選擇最多1張自己前線其他的［特徵：拉諾亞魔法大學］，在這個回合中，獲得「這張角色卡若在前線時也可產生能源。」的效果。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-061":{"name":"七星","effectText":"【登場時】選擇最多1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA54BT/MST-1-062":{"name":"七星","effectText":"【登場時】從以下選擇1項。\n・可將1張自己場上〈七星〉以外的角色卡放回手牌。若有執行此動作時，在這個回合中，下一張從手牌中使用，原始產生能源為2以上的角色卡，其消耗AP-1。\n・抽1張卡片。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA54BT/MST-1-064":{"name":"巴迪岡迪","effectText":"這張角色卡以活動狀態在場上登場。\n【退場時】可將這張卡片加入手牌。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-065":{"name":"菲茲","effectText":"這張卡片也視為〈希露菲葉特〉。\n【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：拉諾亞魔法大學］放置在場外。將其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA54BT/MST-1-066":{"name":"菲茲","effectText":"這張卡片也視為〈希露菲葉特〉。\n【我方回合中】若自己的產生能源在7以上時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-067":{"name":"菲茲","effectText":"這張卡片也視為〈希露菲葉特〉。\n【突襲】〈希露菲葉特〉置為活動，並可移動至前線\n【登場時】選擇最多1張自己場上原始產生能源1以上的［特徵：拉諾亞魔法大學］，直到下一個我方回合開始前，獲得「這張角色卡不會被對手的效果選擇。」。\n【退場時】使最多1張這張角色卡的突襲元卡以休息狀態在自己場上登場，或加入手牌。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-063":{"name":"諾倫","effectText":"【登場時】若自己的產生能源在7以上時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-070":{"name":"莉妮亞娜","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-071":{"name":"魯迪烏斯","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":""},"UA54BT/MST-1-068":{"name":"菲茲","effectText":"這張卡片也視為〈希露菲葉特〉。\n【突襲】〈希露菲葉特〉置為活動，並可移動至前線\n若自己的產生能源在7以上時，這張角色卡獲得【衝擊（1）】。\n【登場時】從以下選擇1項。\n・查看5張自己卡組上面的卡片，公開其中最多1張［特徵：拉諾亞魔法大學］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n・選擇最多1張對手前線的角色卡，移動至能源線。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA54BT/MST-1-069":{"name":"普露塞娜","effectText":"【登場時】查看1張自己卡組上面的卡片，並將其放置在自己卡組的上面或場外。","triggerText":""},"UA54BT/MST-1-073":{"name":"魯迪烏斯","effectText":"這張卡片無法在能源線〔登場・移動〕，且無法因自己的效果以外的方式置為活動。\n【啟動主要】僅限自己的產生能源在7以上時可發動。將這張角色卡置為活動。抽1張卡片。選擇最多1張自己場上的角色卡，在這個回合中，BP+2000。這張角色卡在這個回合中，獲得「在自己攻擊階段結束時，將這張角色卡置為活動。」。〈魯迪烏斯〉的這個效果每回合僅可發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-072":{"name":"魯迪烏斯","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【綠】。","triggerText":""},"UA54BT/MST-1-076":{"name":"迷宮的守護者 魔石多頭龍","effectText":"【退場時】從自己場外，將最多1張能源需求『1』以下消耗AP1且不具備特徵的綠色角色卡以休息狀態在自己場上登場，或發動突襲。自己場外每有1張其他場域卡，藉由此效果登場的角色卡的能源需求範圍+1。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA54BT/MST-1-075":{"name":"迷宮都市拉潘","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【退場時】抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA54BT/MST-1-078":{"name":"守護術師菲茲","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有〈希露菲葉特〉時，則替換成『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA54BT/MST-1-077":{"name":"一直以來謝謝你","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自分の生命區。"},"UA54BT/MST-1-079":{"name":"塞妮絲救出作戰","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自分の生命區。"},"UA55ST/IMC-1-088":{"name":"澀谷凜","effectText":"","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55ST/IMC-1-089":{"name":"澀谷凜","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA54BT/MST-1-080":{"name":"沒錯，我就是希露菲葉特","effectText":"抽2張卡片。選擇最多1張自己前線的［特徵：拉諾亞魔法大學］，在這個回合中，獲得「這張角色卡若在前線時也可產生能源。」的效果。","triggerText":"[抽卡] 抽1張卡片。"},"UA54BT/MST-1-074":{"name":"轉移迷宮","effectText":"【登場時】可使1張自己場上的角色卡退場。若有執行此動作時，抽2張卡片。\n【退場時】從以下選擇1項。\n・可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外使最多1張能源需求1以下的綠色〈洛琪希〉以休息狀態在自己場上登場。\n・從自己場外將最多1張〈迷宮的守護者 魔石多頭龍〉加入手牌。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA55ST/IMC-1-096":{"name":"本田未央","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA55ST/IMC-1-095":{"name":"本田未央","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA55ST/IMC-1-092":{"name":"島村卯月","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA55ST/IMC-1-097":{"name":"本田未央","effectText":"這張角色卡不能攻擊。\n在自己的攻擊階段開始時，可支付1AP。若有執行此動作時，這張角色卡在這個回合中失去所有原本的效果。\n【對方回合中】這張角色卡BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55ST/IMC-1-091":{"name":"島村卯月","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA55ST/IMC-1-100":{"name":"千川千尋的支援","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA55ST/IMC-1-103":{"name":"島村卯月","effectText":"【攻擊時】若自己前線有3張以上原始BP為4000的［特徵：new generations］時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55ST/IMC-1-101":{"name":"澀谷凜","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】若自己場上有3張以上原始BP為4000的［特徵：new generations］時，抽1張卡片。","triggerText":""},"UA55ST/IMC-1-102":{"name":"澀谷凜","effectText":"【突襲】〈澀谷凜〉置為活動，並可移動至前線\n【登場時】這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。選擇最多1張BP在自己場上其他原始BP為4000的［特徵：new generations］張數×1000以下的對手前線角色卡，使其退場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55ST/IMC-1-105":{"name":"本田未央","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：new generations］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55ST/IMC-1-104":{"name":"島村卯月","effectText":"若自己場上有〈澀谷凜〉與〈本田未央〉時，手牌中這張卡片的消耗AP-1。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA55ST/IMC-1-106":{"name":"本田未央","effectText":"【突襲】〈本田未央〉置為活動，並可移動至前線\n【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：new generations］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若自己場上有4張以上原始BP為4000的［特徵：new generations］時，選擇最多1張自己場上的［特徵：new generations］，置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55ST/IMC-1-107":{"name":"事務所","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】抽1張卡片。之後，使最多1張自己手牌中能源需求3以下消耗AP1的紅色角色卡以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA55ST/IMC-1-109":{"name":"new generations","effectText":"選擇1張BP在自己場上的［特徵：new generations］張數×1000以下的對手前線角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA55ST/IMC-1-108":{"name":"S(mile)ING!","effectText":"自己前線所有的角色卡，在這個回合中，BP+1000。抽1張卡片。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55ST/IMC-1-110":{"name":"城崎莉嘉","effectText":"【啟動主要】【若在前線時】【每回合1】僅限這張角色卡的BP在4000以上時可發動。從以下選擇1項。\n・選擇1張自己場上的角色卡，在這個回合中，BP+1000。\n・選擇1張自己場上BP3000以上的角色卡，在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55ST/IMC-1-111":{"name":"本田未央","effectText":"【登場時】可支付1AP。若有執行此動作時，將1張自己場外持有【突襲】的黃色［特徵：Positive Passion］加入手牌。\n【攻擊時】若自己場上有持有【突襲】的黃色［特徵：Positive Passion］時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55ST/IMC-1-112":{"name":"澀谷凜","effectText":"【突襲】〈澀谷凜〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】可將1張自己場上的角色卡放置在自己卡組下面。若有執行此動作時，查看3張自己卡組上面的卡片。從其中將最多1張藍色［特徵：Girls in the Frontier］以休息狀態在自己場上登場，將其中1張加入手牌，其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55ST/IMC-1-090":{"name":"澀谷凜","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA55ST/IMC-1-113":{"name":"速水奏","effectText":"若自己場上有4張以上［特徵：LiPPS］時，這張角色卡的產生能源+【藍】。\n【登場時】選擇最多1張對手前線的角色卡，或最多1張〈速水奏〉以外的自己場上的［特徵：LiPPS］，在這個回合中，BP+500。","triggerText":""},"UA55BT/IMC-1-001":{"name":"千川千尋","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【黃】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA55BT/IMC-1-002":{"name":"大槻唯","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA55BT/IMC-1-003":{"name":"大槻唯","effectText":"【對方回合中】這張角色卡獲得BP+1000與【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）。\n【啟動主要】【每回合1】僅限自己場上有其他BP5000以上的角色卡時可發動。這張角色卡在這個回合中，BP+1000。\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡的BP在5000以上時可發動。將這張角色卡置為活動。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-005":{"name":"緒方智繪里","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA55BT/IMC-1-004":{"name":"緒方智繪里","effectText":"當這張卡片因自己的［特徵：BEYOND THE STARLIGHT］效果而從手牌放置在場外時，選擇最多1張自己場上的［特徵：BEYOND THE STARLIGHT］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-008":{"name":"川島瑞樹","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的［特徵：BEYOND THE STARLIGHT］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-006":{"name":"緒方智繪里","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【黃×2】。\n【啟動主要】【每回合1】僅限自己場上有其他BP5000以上的角色卡時可發動。這張角色卡在這個回合中，BP+1000。\n【攻擊時】若這張角色卡的BP在5000以上時，公開1張自己卡組上面的卡片。若公開的卡片為［特徵：BEYOND THE STARLIGHT］時，可將該卡片加入手牌。若沒有加入手牌時，放置在卡組上面或下面。","triggerText":""},"UA55BT/IMC-1-007":{"name":"川島瑞樹","effectText":"","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-010":{"name":"城崎莉嘉","effectText":"【登場時】查看7張自己卡組上面的卡片，公開其中最多1張黃色場域卡並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA55BT/IMC-1-009":{"name":"川島瑞樹","effectText":"這張角色卡以活動狀態登場。\n【登場時】抽1張卡片，並從自己手牌中，使最多1張能源需求3以下、消耗AP1且持有［特徵：BEYOND THE STARLIGHT］的黃色角色卡以休息狀態在自己場上登場，或發動突襲。登場或發動突襲的角色卡原本的能源需求每有1，這張角色卡在這個回合中，BP-1000。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-013":{"name":"北條加蓮","effectText":"【登場時】選擇最多1張自己場上其他的［特徵：BEYOND THE STARLIGHT］，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-011":{"name":"城崎莉嘉","effectText":"【每回合1】當這張角色卡的BP增加時，若是在我方回合中，這張角色卡在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-012":{"name":"城崎莉嘉","effectText":"【突襲】〈城崎莉嘉〉置為活動，並可移動至前線\n【每回合1】當這張角色卡的BP增加時，若是在我方回合中，這張角色卡在這個回合中，BP+500。\n【登場時】這張角色卡在這個回合中，獲得「若這張角色卡的BP在7000以上時，這張角色卡獲得【狙擊】。」。\n【攻擊時】若這張角色卡的BP在5000以上時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-014":{"name":"北條加蓮","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：BEYOND THE STARLIGHT］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA55BT/IMC-1-015":{"name":"北條加蓮","effectText":"【攻擊時】若自己場上有其他BP5000以上的角色卡時，抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-017":{"name":"高森藍子","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA55BT/IMC-1-018":{"name":"高森藍子","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Positive Passion］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-016":{"name":"北條加蓮","effectText":"【突襲】〈北條加蓮〉置為活動，並可移動至前線\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。從自己場外將最多1張能源需求3以下的［特徵：BEYOND THE STARLIGHT］加入手牌。\n【啟動主要】【若在前線時】【每回合1】僅限這張角色卡的BP在5000以上時可發動。查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。選擇自己場上其他的角色卡『1張』，在這個回合中，BP+1000。若這張角色卡的BP在7000以上時，改為『全部』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-020":{"name":"高森藍子","effectText":"【突襲】〈高森藍子〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線的角色卡，轉為休息。若這張角色卡因自己的效果而發動突襲時，那張角色卡下一次無法置為活動。\n【啟動主要】【若在前線時】【轉為休息】【每回合1】從自己的手牌中，對最多1張滿足能源需求的〈本田未央〉或〈日野茜〉發動突襲。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-022":{"name":"日野茜","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己前線的活動角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，產生能源+【黃】。","triggerText":""},"UA55BT/IMC-1-023":{"name":"日野茜","effectText":"【登場時】【若在前線時】從自己手牌中，使最多1張能源需求2以下的黃色［特徵：Positive Passion］以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-019":{"name":"高森藍子","effectText":"【登場時】抽1張卡片。","triggerText":"[顏色] 選擇1張對手前線的角色卡，轉為休息。下一次無法置為活動。"},"UA55BT/IMC-1-021":{"name":"日野茜","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-024":{"name":"日野茜","effectText":"【突襲】〈日野茜〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】這張角色卡在這個回合中，BP+1000。若這張角色卡因自己的效果而發動突襲時，這張角色卡在這個回合中，再獲得【傷害（2）】。\n【攻擊時】抽1張卡片。若這是這個回合中自己的角色卡首次攻擊時，可支付1AP。若有執行此動作時，從自己的手牌中，對最多1張滿足能源需求的〈本田未央〉或〈高森藍子〉發動突襲。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-027":{"name":"本田未央","effectText":"若自己場上有4張以上［特徵：Positive Passion］時，這張角色卡的產生能源+【黃】。","triggerText":""},"UA55BT/IMC-1-025":{"name":"本田未央","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-029":{"name":"BEYOND THE STARLIGHT","effectText":"這張場域卡以活動狀態登場。\n【啟動主要】【將1張手牌放置在場外】選擇最多1張自己場上的角色卡，在這個回合中，『BP+1000』。若以這個效果將持有【特殊觸發】的卡片放置在場外時，改為『BP+3000』。\n【啟動主要】【轉為休息】僅限自己場上的角色卡全部為［特徵：BEYOND THE STARLIGHT］時可發動。選擇1張自己場上BP7000以上的角色卡，在這個回合中，賦予【衝擊（1）】。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA55BT/IMC-1-026":{"name":"本田未央","effectText":"【我方回合中】這張角色卡BP+1000。","triggerText":""},"UA55BT/IMC-1-030":{"name":"熱情Fun Fun Fanfare","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有3張以上［特徵：Positive Passion］時，改為『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA55BT/IMC-1-028":{"name":"本田未央","effectText":"【突襲】〈本田未央〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）\n【登場時】從以下選擇最多2項。\n・可將1張自己場上能源需求3以下的［特徵：Positive Passion］放回手牌。若有執行此動作時，從自己手牌中，使最多1張滿足能源需求且消耗AP1的〈日野茜〉或〈高森藍子〉以休息狀態在自己場上登場，或發動突襲。\n・若這張角色卡因自己的效果而發動突襲時，選擇最多1張自己場上的［特徵：Positive Passion］，置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-033":{"name":"三顆星☆☆★","effectText":"查看6張自己卡組上面的卡片，公開其中〈本田未央〉、〈日野茜〉與〈高森藍子〉各最多1張並加入手牌。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-031":{"name":"千川千尋的支援","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA55BT/IMC-1-032":{"name":"DOKIDOKI節奏","effectText":"抽1張卡片。選擇最多1張自己場上的［特徵：BEYOND THE STARLIGHT］，在這個回合中，BP+2000。若以這個效果選擇了〈城崎莉嘉〉時，在這個回合中，再賦予【衝擊（1）】。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-035":{"name":"木村夏樹","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-034":{"name":"千川千尋","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA55BT/IMC-1-037":{"name":"木村夏樹","effectText":"【登場時】若這張角色卡是因自己的角色卡效果而登場時，抽1張卡片。\n【攻擊時】可支付1AP。若有執行此動作時，這張角色卡在這個回合中，獲得【衝擊（1）】。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-036":{"name":"木村夏樹","effectText":"【我方回合中】若在這個回合中有自己的角色卡因自己的效果而登場時，這張角色卡BP+1000。","triggerText":""},"UA55BT/IMC-1-040":{"name":"澀谷凜","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA55BT/IMC-1-038":{"name":"小日向美穗","effectText":"【退場時】抽1張卡片。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-039":{"name":"小日向美穗","effectText":"【我方回合中】若在這個回合中這張角色卡因自己的效果而〔登場或移動〕時，這張角色卡BP+1000。\n【啟動主要】【若在能源線時】【將1張手牌放置在場外】僅限自己前線有3張［特徵：Girls in the Frontier］時可發動。將這張角色卡移動至前線。這張角色卡在這個回合中，獲得「這張角色卡的攻擊結束時，將這張角色卡移動至能源線。」。","triggerText":""},"UA55BT/IMC-1-042":{"name":"澀谷凜","effectText":"【登場時】從自己手牌中，使最多1張能源需求2以下的藍色［特徵：Girls in the Frontier］以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-041":{"name":"澀谷凜","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Girls in the Frontier］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-044":{"name":"早坂美玲","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-043":{"name":"澀谷凜","effectText":"【突襲】〈澀谷凜〉置為活動，並可移動至前線\n【退場時】將這張角色卡的突襲元卡最多1張放回手牌。\n【攻擊時】可將1張自己場上的角色卡放置在自己卡組下面。若有執行此動作時，查看3張自己卡組上面的卡片，將其中最多1張藍色［特徵：Girls in the Frontier］以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。之後，可將1張自己的手牌放置在場外。若有執行此動作時，將登場的角色卡置為活動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-045":{"name":"早坂美玲","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA55BT/IMC-1-047":{"name":"一之瀨志希","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：LiPPS］放置在場外。其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-050":{"name":"城崎美嘉","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-048":{"name":"一之瀨志希","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":""},"UA55BT/IMC-1-051":{"name":"城崎美嘉","effectText":"【登場時】從自己場外將最多1張能源需求2以下的［特徵：LiPPS］加入手牌。\n【啟動主要】【轉為休息】【使這張卡片退場】僅限對手場上有BP4500以上的角色卡時可發動。從自己場外，使最多1張能源需求2以下的藍色［特徵：LiPPS］以休息狀態在自己場上登場。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA55BT/IMC-1-052":{"name":"速水奏","effectText":"【啟動主要】【轉為休息】選擇1張對手前線的角色卡，或1張〈速水奏〉以外的自己場上的［特徵：LiPPS］，在這個回合中，BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-054":{"name":"速水奏","effectText":"這張角色卡不會被BP4500以上的角色卡防禦。\n【啟動主要】僅限對手場上有BP4500以上的角色卡時可發動。將這張角色卡置為活動。〈速水奏〉的這個效果每回合僅可發動1次。\n【啟動主要】【若在前線時】【每回合1】選擇1張對手前線的角色卡，或1張〈速水奏〉以外的自己場上的［特徵：LiPPS］，在這個回合中，BP+500。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA55BT/IMC-1-053":{"name":"速水奏","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA55BT/IMC-1-046":{"name":"早坂美玲","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【登場時】選擇最多1張自己場上的［特徵：Girls in the Frontier］，在這個回合中，賦予「這張角色卡不會被BP4000以上的角色卡防禦。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-049":{"name":"一之瀨志希","effectText":"【突襲】〈一之瀨志希〉置為活動，並可移動至前線\n【登場時】選擇最多1張對手前線BP2500以下或BP4500以上的角色卡，放回手牌。\n【攻擊時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-056":{"name":"宮本‧芙蕾德莉卡","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：LiPPS］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-055":{"name":"宮本‧芙蕾德莉卡","effectText":"【啟動主要】【每回合1】僅限對手場上有BP4500以上的角色卡時可發動。這張角色卡在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-058":{"name":"鹽見周子","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-057":{"name":"宮本‧芙蕾德莉卡","effectText":"【突襲】〈宮本‧芙蕾德莉卡〉置為活動，並可移動至前線\n【每回合1】這張角色卡攻擊後在對戰中敗北時，將這張角色卡置為活動。\n【登場時】從自己手牌中，使最多1張能源需求2以下的藍色［特徵：LiPPS］以休息狀態在自己場上登場。若對手場上有BP4500以上的角色卡時，抽1張卡片。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-061":{"name":"鹽見周子","effectText":"這張角色卡攻擊後沒有被防禦時，抽最多1張卡片。\n【登場時】將這張角色卡置為活動。可將1張自己的AP卡置為活動。若有執行此動作時，這張角色卡在這個回合中，獲得「攻擊階段結束時，將這張角色卡放回手牌。」。","triggerText":"[顏色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA55BT/IMC-1-059":{"name":"鹽見周子","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-060":{"name":"鹽見周子","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【啟動主要】【每回合1】僅限對手場上有BP4500以上的角色卡時可發動。這張角色卡在這個回合中，BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-062":{"name":"Girls in the Frontier","effectText":"選擇1張對手前線『BP3000以下』的角色卡，使其退場。若自己場上有3張以上［特徵：Girls in the Frontier］時，改為『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA55BT/IMC-1-063":{"name":"千川千尋的支援","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA55BT/IMC-1-067":{"name":"千川千尋","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA55BT/IMC-1-064":{"name":"Tulip","effectText":"選擇1張對手前線BP5000以下的角色卡，『放回手牌』。若自己場上有3張以上［特徵：LiPPS］時，也可改為『使其退場』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA55BT/IMC-1-066":{"name":"Hotel Moonside","effectText":"抽2張卡片。若對手場上有BP4500以上的角色卡時，再抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-069":{"name":"小日向美穗","effectText":"【登場時】『抽1張卡片，並將1張自己的手牌放置在場外』。若自己場上與場外有合計6種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，改為『抽1張卡片』。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-068":{"name":"神崎蘭子","effectText":"【登場時】從以下選擇最多1項。\n・可使1張自己場上其他的角色卡退場。若有執行此動作時，抽2張卡片，並從自己手牌中使最多2張能源需求3以下且消耗AP1的紅色［特徵：拜託了！灰姑娘］以休息狀態在自己場上登場。\n・若自己場上與場外有合計9種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，選擇最多1張對手前線BP5000以下的角色卡，使其退場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA55BT/IMC-1-071":{"name":"城崎莉嘉","effectText":"【我方回合中】若自己場上與場外有合計6種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，這張角色卡BP+1500。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-070":{"name":"城崎美嘉","effectText":"若自己場上與場外有合計6種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，這張角色卡BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-072":{"name":"多田李衣菜","effectText":"這張角色卡攻擊後戰勝時，若自己場上與場外有合計9種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，抽最多1張卡片。\n【登場時】可將1張自己手牌中的［特徵：拜託了！灰姑娘］放置在場外。若有執行此動作時，將這張角色卡置為活動。","triggerText":""},"UA55BT/IMC-1-073":{"name":"双葉杏","effectText":"這張卡片不能在前線登場，且不能移動至前線。\n【登場時】『抽1張卡片』。若自己場上與場外有合計9種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，改為『查看2張自己卡組上面的卡片，將最多1張加入手牌，其餘放置在場外。』","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-074":{"name":"三村加奈子","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【攻擊時】若自己場上與場外有合計9種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，選擇最多2張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-075":{"name":"諸星琪拉莉","effectText":"【我方回合中】若自己場上與場外有合計6種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，這張角色卡BP+1000。\n【登場時】可將1張自己場上能源需求1以下的［特徵：拜託了！灰姑娘］放回手牌。若有執行此動作時，從自己手牌中，使最多1張能源需求1以下的紅色［特徵：拜託了！灰姑娘］以休息狀態在自己場上登場。","triggerText":""},"UA55BT/IMC-1-076":{"name":"安娜斯塔西婭","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：Starry-Go-Round］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-077":{"name":"安娜斯塔西婭","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【紅×2】。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-078":{"name":"安娜斯塔西婭","effectText":"【突襲】〈安娜斯塔西婭〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】查看6張自己卡組上面的卡片，將其中最多1張能源需求為2的紅色［特徵：Starry-Go-Round］以休息狀態在自己場上登場。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-079":{"name":"大槻唯","effectText":"【登場時】從自己手牌中，使最多1張能源需求2以下的紅色［特徵：Starry-Go-Round］以休息狀態在自己場上登場。","triggerText":""},"UA55BT/IMC-1-081":{"name":"二宮飛鳥","effectText":"若自己場上有3張以上能源需求為2的［特徵：Starry-Go-Round］時，這張角色卡BP+1500。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-082":{"name":"二宮飛鳥","effectText":"若自己場上有3張以上能源需求為2的［特徵：Starry-Go-Round］時，這張角色卡的產生能源+【紅】。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA55BT/IMC-1-083":{"name":"姬川友紀","effectText":"【我方回合中】若自己場上有3張以上能源需求為2的［特徵：Starry-Go-Round］時，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-084":{"name":"姬川友紀","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【我方回合中】若自己場上有3張以上能源需求為2的［特徵：Starry-Go-Round］時，這張角色卡BP+1500。","triggerText":""},"UA55BT/IMC-1-085":{"name":"前川未來","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張［特徵：Starry-Go-Round］放置在場外。其餘卡片依任意順序放置在自己卡組上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-086":{"name":"前川未來","effectText":"【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）","triggerText":""},"UA55BT/IMC-1-087":{"name":"前川未來","effectText":"【突襲】〈前川未來〉置為活動，並可移動至前線\n【登場時】從自己場外將最多『1張』能源需求為2的［特徵：Starry-Go-Round］加入手牌。若自己場上有3張以上能源需求為2的［特徵：Starry-Go-Round］時，改為『2張』。\n【攻擊時】選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-080":{"name":"大槻唯","effectText":"【登場時】【若在能源線時】若自己場上有3張以上能源需求為2的［特徵：Starry-Go-Round］時，將這張角色卡置為活動。\n【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-089":{"name":"澀谷凜","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA55BT/IMC-1-090":{"name":"澀谷凜","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA55BT/IMC-1-065":{"name":"Never say never","effectText":"查看3張自己卡組上面的卡片，將其中最多1張藍色［特徵：Girls in the Frontier］以休息狀態在自己場上登場，或發動突襲。其餘卡片依任意順序放置在自己卡組下面。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-093":{"name":"島村卯月","effectText":"【登場時】若自己場上與場外有合計6種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，選擇最多1張自己場上的［特徵：拜託了！灰姑娘］，在這個回合中，BP+1000。若合計有9種以上時，在這個回合中，再賦予【衝擊（1）】。","triggerText":"[顏色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA55BT/IMC-1-094":{"name":"島村卯月","effectText":"【突襲】〈島村卯月〉置為活動，並可移動至前線\n【登場時】查看2張自己卡組上面的卡片，將最多1張加入手牌，其餘放置在場外。\n【攻擊時】可將1張自己的手牌放置在場外。若有執行此動作時，將這張角色卡的突襲元卡1張以休息狀態在自己場上登場。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA55BT/IMC-1-088":{"name":"澀谷凜","effectText":"","triggerText":"[活動] 選擇1張自己場上の角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-095":{"name":"本田未央","effectText":"【登場時】查看2張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-096":{"name":"本田未央","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA55BT/IMC-1-092":{"name":"島村卯月","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA55BT/IMC-1-097":{"name":"本田未央","effectText":"這張角色卡不能攻擊。\n在自己的攻擊階段開始時，可支付1AP。若有執行此動作時，這張角色卡在這個回合中失去所有原本的效果。\n【對方回合中】這張角色卡BP-1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-091":{"name":"島村卯月","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA55BT/IMC-1-098":{"name":"拜託了！灰姑娘","effectText":"抽1張卡片。在這個回合中，下一張從手牌使用的［特徵：拜託了！灰姑娘］消耗AP-1。若自己場上與場外有合計6種以上不同卡片名稱的［特徵：拜託了！灰姑娘］時，在這個回合中，『下一張在自己場上登場的［特徵：拜託了！灰姑娘］』以活動狀態登場。若合計有9種以上時，改為『在自己場上登場的［特徵：拜託了！灰姑娘］全部』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA56BT/TTG-1-002":{"name":"維拉爾","effectText":"【啟動主要】【轉為休息】【每回合1】將1張自己前線的活動角色卡轉為休息。若有執行此動作時，這張角色卡在這個回合中，產生能源+【綠】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA55BT/IMC-1-099":{"name":"Starry-Go-Round","effectText":"選擇1張對手前線『BP2000』以下的角色卡，使其退場。若自己場上有3張以上［特徵：Starry-Go-Round］時，改為『BP5000』以下。若自己場上有4張以上能源需求為2的［特徵：Starry-Go-Round］時，選擇最多1張自己場上的角色卡，在這個回合中，BP+1000。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA55BT/IMC-1-100":{"name":"千川千尋的支援","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA56BT/TTG-1-001":{"name":"維拉爾","effectText":"【登場時】查看1張自己卡組上面的卡片，將其放置在自己卡組的上面或場外。","triggerText":""},"UA56BT/TTG-1-003":{"name":"維拉爾","effectText":"【啟動主要】【若在前線時】【每回合1】若自己的能源在6以上時，這張角色卡在這個回合中，獲得「這張角色卡即使在前線也會產生能源。」。若自己的能源在8以上時，自己在這個回合中，獲得「自己場上的所有角色卡即使在前線也會產生能源。」。\n【啟動主要】【若在前線時】若自己的能源在20以上時，選擇1張自己場上的角色卡，置為活動。〈維拉爾〉的這個效果1回合僅能發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-006":{"name":"奇坦","effectText":"【我方回合中】若自己的能源在6以上時，這張角色卡BP+1000。","triggerText":""},"UA56BT/TTG-1-007":{"name":"吉米","effectText":"若自己場上有〈達莉〉時，這張角色卡BP+1000。\n【登場時】若這張角色卡是從手牌登場時，可支付1AP。若有執行此動作時，從自己場外使最多1張滿足能源需求的〈達莉〉以休息狀態在自己場上登場。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-004":{"name":"維拉爾","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【若在前線時】當自己卡片名稱包含「紅蓮螺巖」的角色卡發動突襲時，若其突襲元為〈西蒙〉，則從自己的手牌或場外將最多1張〈維拉爾〉背面朝上放置在該突襲角色卡下面；若其突襲元為〈維拉爾〉，則從自己的手牌或場外將最多1張〈西蒙〉背面朝上放置在該突襲角色卡下面。若從手牌放置時，抽1張卡片。〈維拉爾〉的這個效果1回合僅能發動1次。（突襲的角色卡的【登場時】與此效果可依任意順序處理）","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-005":{"name":"奇坦","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-011":{"name":"西蒙","effectText":"【我方回合中】若自己的能源在8以上時，這張角色卡BP+1500。\n【啟動主要】【每回合1】這張角色卡直到下一個自己回合開始時為止，獲得以下1項效果。\n・這張角色卡的產生能源+【綠】。\n・這張角色卡即使在前線也會產生能源。","triggerText":""},"UA56BT/TTG-1-012":{"name":"西蒙","effectText":"這張角色卡僅能在前線登場，並以活動狀態登場。\n【登場時】查看6張自己卡組上面的卡片，公開其中最多1張〈妮亞〉或能源需求8以上的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。將1張以上自己的手牌放置在場外，『將1張自己的AP卡置為活動』。若放置在場外的卡片原先的能源需求合計在15以上時，可替換成『選擇最多1張對手前線的角色卡，使其退場』。\n【啟動主要】在這張角色卡未登場的回合中，若自己的能源在8以上時，自己在這個回合中，獲得「自己場上的所有卡片的產生能源變為2倍。」。〈西蒙〉的這個效果1回合僅能發動1次。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-013":{"name":"達莉","effectText":"若自己場上有〈吉米〉時，這張角色卡BP+1000。\n【登場時】若這張角色卡是從手牌登場時，可支付1AP。若有執行此動作時，從自己場外使最多1張滿足能源需求的〈吉米〉以休息狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-008":{"name":"小紅蓮螺巖","effectText":"【突襲】［特徵：大紅蓮團］置為活動，並可移動至前線\n【登場時】抽1張卡片。發動以下效果。\n・若這張角色卡的突襲元為〈吉米〉時，這張角色卡在這個回合中，獲得【衝擊（1）】（攻擊後戰勝時，給予對手1點傷害）。\n・若這張角色卡的突襲元為〈達莉〉時，這張角色卡在這個回合中，獲得「這張角色卡的攻擊未被防禦時，抽1張卡片。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-014":{"name":"妮亞","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA56BT/TTG-1-015":{"name":"妮亞","effectText":"【啟動主要】【支付1AP】【每回合1】抽1張卡片。這張角色卡在這個回合中，產生能源+【綠】。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-016":{"name":"妮亞","effectText":"【登場時】可將最多2張自己的手牌放置在場外。若有執行此動作時，抽出與以此效果而放置在場外的卡片相同數量的卡片。\n【啟動主要】【轉為休息】若自己的能源在20以上時，抽1張卡片。〈妮亞〉的這個效果1回合僅能發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-017":{"name":"妮亞","effectText":"【登場時】從以下選擇1項。\n・查看4張自己卡組上面的卡片，公開其中最多1張〈西蒙〉或能源需求8以上的卡片並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。\n・從自己場外將最多1張〈西蒙〉或能源需求8以上的卡片放置在自己卡組的上面。\n【啟動主要】【每回合1】若自己的能源在8以上時，這張角色卡在這個回合中，產生能源+【綠】【綠】。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA56BT/TTG-1-010":{"name":"西蒙","effectText":"【登場時】查看3張自己卡組上面的卡片，公開其中最多1張［特徵：大紅蓮團］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-019":{"name":"庸子","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【綠】。","triggerText":""},"UA56BT/TTG-1-018":{"name":"布塔","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA56BT/TTG-1-020":{"name":"庸子","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。\n【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-022":{"name":"夜子老師","effectText":"這張卡片也視為〈庸子〉。\n【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，將這張角色卡放回手牌。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-021":{"name":"庸子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）\n【若在能源線時】自己攻擊階段開始時，若自己場上有下面有背面朝上卡片的卡片名稱包含「紅蓮螺巖」的角色卡時，可「將這張角色卡移動至前線。這張角色卡在這個回合中，BP+1000。」。〈庸子〉的這個效果1回合僅能發動1次。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-023":{"name":"李龍","effectText":"【登場時】查看5張自己卡組上面的卡片，公開其中最多1張［特徵：顏面］並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。","triggerText":""},"UA56BT/TTG-1-009":{"name":"西蒙","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-024":{"name":"麗迪","effectText":"自己手牌中所有的場域卡能源需求減少【綠×1】。\n若自己場上有［特徵：顏面］時，這張角色卡的產生能源+【綠】。","triggerText":""},"UA56BT/TTG-1-025":{"name":"羅傑儂","effectText":"這張角色卡僅在自己的能源在6以上時才能進行攻擊與防禦。\n【啟動主要】【若在前線時】【轉為休息】【使這張卡片退場】僅在自己的能源在6以上時才可發動。選擇1張自己場上的〈西蒙〉，在這個回合中，給予產生能源+【綠】【綠】【綠】，並將1張自己的AP卡置為活動。","triggerText":""},"UA56BT/TTG-1-026":{"name":"羅修","effectText":"【登場時】從以下選擇1項。\n・查看7張自己卡組上面的卡片，公開其中最多1張〈方舟紅蓮〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。\n・從自己場外將最多1張〈方舟紅蓮〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-029":{"name":"紅蓮螺巖","effectText":"【突襲】〈西蒙〉/〈維拉爾〉置為活動，並可移動至前線\n【登場時】【若在前線時】從自己場外『將最多1張能源需求3以下消耗AP1的綠色［特徵：大紅蓮團］加入手牌』。若自己的能源在6以上時，可替換成『以休息狀態在自己場上登場』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-028":{"name":"紅蓮螺巖","effectText":"【突襲】〈西蒙〉/〈維拉爾〉置為活動，並可移動至前線\n【登場時】抽1張卡片。若為自己回合中時，選擇最多1張對手前線的角色卡，直到下一個自己回合開始時為止，給予「這張角色卡無法攻擊。」。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-027":{"name":"方舟紅蓮螺巖","effectText":"這張卡片可將突襲狀態的〈紅蓮螺巖〉最上面的卡片背面朝上放置在該突襲元下面，並在該突襲元上發動突襲。\n【突襲】〈西蒙〉/〈維拉爾〉置為活動，並可移動至前線\n這張角色卡獲得BP+1000與【衝擊（1）】。\n【登場時】根據這張角色卡下面背面朝上卡片的張數，發動以下所有效果。\n・1張以上：選擇最多1張對手前線BP5000以下的角色卡，使其退場。\n・3張以上：將1張自己的AP卡置為活動。\n【攻擊時】可將2張這張角色卡下面背面朝上的卡片放置在場外。若有執行此動作時，這張角色卡在這個回合中，獲得【傷害（2）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-030":{"name":"宇宙大王奇坦","effectText":"【突襲】〈奇坦〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【退場時】將最多1張這張角色卡的突襲元『以休息狀態』在自己場上登場。若自己的能源在6以上時，替換為『以活動狀態』。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-031":{"name":"超銀河紅蓮螺巖","effectText":"這張卡片可將突襲狀態的〈方舟紅蓮螺巖〉最上面的卡片背面朝上放置在該突襲元下面，並在該突襲元上發動突襲。\n【突襲】〈西蒙〉/〈維拉爾〉置為活動，並可移動至前線\n這張角色卡獲得BP+1000與【傷害（2）】。\n【登場時】這張角色卡直到下一個自己回合開始時為止，獲得BP+5000與「這張角色卡不會被對手的效果選擇。」。若自己的能源在20以上時，將1張自己的AP卡置為活動。在50以上時，抽2張卡片。〈超銀河紅蓮螺巖〉的這個效果1回合僅會發動1次。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-032":{"name":"天元突破紅蓮螺巖","effectText":"這張卡片可將這個回合中未發動突襲的突襲狀態的〈超銀河紅蓮螺巖〉最上面的卡片背面朝上放置在該突襲元下面，並在該突襲元上發動突襲，且僅能以此方式登場。\n若自己場上有〈天元突破紅蓮螺巖〉時，這張卡片無法發動突襲。\n【突襲】〈西蒙〉/〈維拉爾〉置為活動，並可移動至前線\n這張角色卡不會被對手的效果選擇。\n【我方回合中】這張角色卡獲得【衝擊（4）】與【傷害（7）】。\n【登場時】將自己前線任意張數的其他角色卡背面朝上放置在這張角色卡下面。\n【攻擊時】可將2張這張角色卡下面背面朝上的卡片放置在場外。若有執行此動作時，選擇最多1張對手前線的角色卡，使其退場。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA56BT/TTG-1-035":{"name":"時空烈斷火紅螺旋拳","effectText":"選擇1張對手前線『BP3000以下』的角色卡，放置在移除區。若自己場上或自己的角色卡的突襲元有〈西蒙〉時，替換為『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA56BT/TTG-1-038":{"name":"等著我，妮亞。","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA56BT/TTG-1-037":{"name":"妮亞，我不會忘記妳。","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA56BT/TTG-1-039":{"name":"螺巖衝擊","effectText":"選擇1張自己場上卡片名稱包含「螺巖」的角色卡或〈西蒙〉，在這個回合中，增加等同於自己場上角色卡最大BP的BP，並給予【衝擊（1）】（攻擊後戰勝時，給予對手1點傷害）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-036":{"name":"自己所選擇的，就是你宇宙的真實。","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA56BT/TTG-1-040":{"name":"你以為我們是誰啊!!","effectText":"〈你以為我們是誰啊!!〉1回合僅能從手牌使用1次。\n這張卡片因使用以外的原因放置在移除區時，改為放置在場外。\n抽2張卡片。自己在這個回合中，獲得「自己場上的所有角色卡即使在前線也會產生能源。」。將這張卡片放置在移除區。\n【啟動主要】【若在移除區時】【每回合1】僅在自己的能源在8以上時才可發動。自己在這個回合中，獲得「自己場上的所有卡片的產生能源變為2倍。」。（此效果可疊加）","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-041":{"name":"這就是我們大紅蓮團！","effectText":"選擇任意張數自己場上特徵擁有「大紅蓮團」的角色卡。以此效果不能選擇相同卡片名稱的角色卡。在這個回合中，所有選擇的角色卡的BP增加以此效果選擇的角色卡張數×1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-033":{"name":"方舟紅蓮","effectText":"當自己的〈方舟紅蓮螺巖〉發動突襲時，可將這張卡片背面朝上放置在該突襲的角色卡下面。若有執行此動作時，抽2張卡片。〈方舟紅蓮〉的這個效果1回合僅能發動1次。（突襲的角色卡的【登場時】與此效果可依任意順序處理）\n若這張場域卡為活動時，這張場域卡的產生能源+【綠】。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA56BT/TTG-1-042":{"name":"卡米那","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-034":{"name":"超銀河大紅蓮","effectText":"若自己場上沒有場域卡時，手牌中這張卡片的能源需求減少【綠×3】。\n這張卡片下面每有1張背面朝上的卡片，這張卡片的產生能源+【綠】。\n【每回合1】當自己場上的角色卡退場時，可將1張該角色卡從自己場外背面朝上放置在這張卡片下面。\n當自己的〈超銀河紅蓮螺巖〉發動突襲時，可「將這張卡片下面所有背面朝上的卡片加入手牌。將這張卡片背面朝上放置在該突襲的角色卡下面。」。（突襲的角色卡的【登場時】與此效果可依任意順序處理）","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-044":{"name":"卡米那","effectText":"【我方回合中】若自己場上或自己的角色卡的突襲元有〈西蒙〉時，這張角色卡BP+500。\n這張角色卡的攻擊未被防禦時，可「查看7張自己卡組上面的卡片，公開其中最多1張〈紅蓮〉並加入手牌。其餘卡片依任意順序放置在自己卡組下面。若有加入手牌時，將1張自己的手牌放置在場外。」。","triggerText":""},"UA56BT/TTG-1-047":{"name":"奇坦","effectText":"【攻擊時】若為這個回合中自己角色卡的首次攻擊時，這張角色卡在這個回合中，BP+1500。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-045":{"name":"卡米那","effectText":"在自己回合中，當這張角色卡被突襲時，選擇最多1張自己場上的［特徵：大紅蓮團］，在這個回合中，BP+1000。之後，若突襲在這張卡片上的角色卡下面有背面朝上的卡片時，抽1張卡片。（突襲的角色卡的【登場時】與此效果可依任意順序處理）","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA56BT/TTG-1-048":{"name":"奇坦","effectText":"【攻擊時】若為這個回合中自己角色卡的首次攻擊時，這張角色卡直到下一個自己回合開始時為止，獲得BP+500與【衝擊無效】與【雙重防禦】（這張角色卡在這個回合中初次防禦時，將其置為活動）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-049":{"name":"吉米&達莉","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA56BT/TTG-1-050":{"name":"奇揚&奇儂&奇雅露","effectText":"【登場時】若自己場上或自己的角色卡的突襲元有〈奇坦〉時，抽1張卡片。\n【啟動主要】【將1張手牌放置在場外】【每回合1】將這張角色卡置為活動。\n【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，產生能源+【紅】。\n【啟動主要】【將1張手牌放置在場外】【每回合1】這張角色卡在這個回合中，BP+1000。","triggerText":""},"UA56BT/TTG-1-051":{"name":"西蒙","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-046":{"name":"卡米那","effectText":"【啟動主要】【若在前線時】【每回合1】僅在這個回合中自己的角色卡有發動突襲時才可發動。從以下選擇最多2項。\n・將這張角色卡置為活動。〈卡米那〉的這個效果1回合僅能選擇1次。\n・選擇1張自己場上的［特徵：大紅蓮團］，在這個回合中，BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-052":{"name":"西蒙","effectText":"【登場時】可將1張自己的手牌放置在場外。若有執行此動作時，從自己場外將最多1張能源需求2以下的紅色卡片加入手牌。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-053":{"name":"西蒙","effectText":"【啟動主要】【轉為休息】將1張自己卡組上面的卡片放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-056":{"name":"西蒙","effectText":"這張角色卡僅在自己場上有〈妮亞〉，且自己的卡組在20張以下時才能攻擊。\n這張角色卡的攻擊結束時，可使自己手牌中的1張紅色〔〈螺巖〉或〈紅蓮螺巖〉〕在這張角色卡上發動突襲。若有執行此動作時，突襲的角色卡在這個回合中，BP+1000。以此效果不能將與這個回合中突襲的角色卡相同卡片名稱的卡片發動突襲。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA56BT/TTG-1-054":{"name":"西蒙","effectText":"若自己場上有〈妮亞〉，且自己的卡組在20張以下時，這張角色卡獲得「【我方回合中】這張角色卡BP+1500。」與【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）。\n【登場時】將最多1張自己卡組上面的卡片放置在場外。","triggerText":""},"UA56BT/TTG-1-055":{"name":"西蒙","effectText":"【登場時】將最多2張自己卡組上面的卡片放置在場外。之後，可將1張自己的手牌放置在場外。若有執行此動作時，從以此效果由卡組放置在場外的卡片中，將最多1張加入手牌。","triggerText":""},"UA56BT/TTG-1-057":{"name":"達雅卡","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【登場時】選擇最多1張自己場上的其他角色卡，直到下一個自己回合開始時為止，給予【衝擊無效】。","triggerText":""},"UA56BT/TTG-1-058":{"name":"妮亞","effectText":"若自己場上或自己的角色卡的突襲元有〈卡米那〉時，這張卡片無法登場，且當這張角色卡在自己場上時，自己場上無法讓〈卡米那〉登場。\n【登場時】選擇最多1張自己場上的其他角色卡，在這個回合中，『BP+1000』。若選擇的角色卡為〈西蒙〉或突襲元為〈西蒙〉的角色卡時，替換為『BP+1500』。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-060":{"name":"妮亞","effectText":"若自己場上或自己的角色卡的突襲元有〈卡米那〉時，這張卡片無法登場，且當這張角色卡在自己場上時，自己場上無法讓〈卡米那〉登場。\n若自己前線有〈西蒙〉或突襲元為〈西蒙〉的角色卡時，這張角色卡的產生能源+【紅】。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-061":{"name":"妮亞","effectText":"若自己場上或自己的角色卡的突襲元有〈卡米那〉時，這張卡片無法登場，且當這張角色卡在自己場上時，自己場上無法讓〈卡米那〉登場。\n【登場時】從以下選擇『1項』。若自己的卡組在20張以下時，替換為『2項』。\n・從自己場外將最多1張能源需求2以下的〈西蒙〉加入手牌。\n・從自己手牌中，使最多1張能源需求2以下的紅色〈西蒙〉以活動狀態在自己場上登場。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-043":{"name":"卡米那","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-062":{"name":"妮亞","effectText":"若自己場上或自己的角色卡的突襲元有〈卡米那〉時，這張卡片無法登場，且當這張角色卡在自己場上時，自己場上無法讓〈卡米那〉登場。\n【登場時】選擇最多1張自己場上能源需求3以下的〈西蒙〉，發動該角色卡的【登場時】。\n【啟動主要】【轉為休息】僅在自己的卡組在20張以下時才可發動。選擇1張自己場上的〈西蒙〉或突襲元為〈西蒙〉的角色卡，在這個回合中，BP+1000。可將1張自己的手牌放置在場外。若有執行此動作時，將該角色卡置為活動。","triggerText":"[顔色] 選擇1張對手前線BP2500以下的角色卡，使其退場。"},"UA56BT/TTG-1-064":{"name":"庸子","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-065":{"name":"庸子","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）","triggerText":""},"UA56BT/TTG-1-059":{"name":"妮亞","effectText":"若自己場上或自己的角色卡的突襲元有〈卡米那〉時，這張卡片無法登場，且當這張角色卡在自己場上時，自己場上無法讓〈卡米那〉登場。\n【啟動主要】【轉為休息】選擇1張自己場上的〈西蒙〉或突襲元為〈西蒙〉的角色卡，在這個回合中，BP+1000。","triggerText":""},"UA56BT/TTG-1-067":{"name":"庸子","effectText":"這張角色卡以活動狀態登場。\n這張角色卡不會被BP4000以上的角色卡防禦。\n【登場時】這張角色卡在這個回合中，獲得「這張角色卡攻擊後戰勝時，抽1張卡片。」與【狙擊】（可以指定對手前線的角色卡攻擊，若如此做則不會被防禦）。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA56BT/TTG-1-066":{"name":"庸子","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【紅】。","triggerText":""},"UA56BT/TTG-1-063":{"name":"布塔","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【紅】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA56BT/TTG-1-068":{"name":"庸子","effectText":"【我方回合中】這張角色卡的BP增加這個回合中自己的角色卡發動突襲的次數×1000。\n【啟動主要】【若在能源線時】【將1張手牌放置在場外】這張角色卡在這個回合中，獲得「這張角色卡可以從能源線攻擊。」。自己在這個回合中，獲得「合計最多僅能攻擊4次。」。〈庸子〉的這個效果1回合僅能發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-071":{"name":"大王奇坦DX","effectText":"【突襲】〈奇坦〉置為活動，並可移動至前線\n【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）\n【攻擊時】若為這個回合中自己角色卡的首次攻擊時，選擇最多1張自己場上的其他角色卡，在這個回合中，BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-073":{"name":"紅蓮螺巖","effectText":"這張卡片僅在自己場上或自己的角色卡的突襲元有〔〈西蒙〉與〈卡米那〉〕時才可發動突襲。\n這張卡片可將突襲狀態的〈螺巖〉或〈紅蓮〉最上面的卡片背面朝上放置在該突襲元下面，並在該突襲元上發動突襲。\n【突襲】〈西蒙〉/〈卡米那〉置為活動，並可移動至前線\n若這張角色卡下面有背面朝上的卡片時，這張角色卡獲得以下所有效果。\n・BP+1000與【衝擊（1）】\n・【登場時】選擇最多1張對手前線BP5000以下的角色卡，使其退場。\n・當BP500以上的這張角色卡離開場上時，可改為將1張這張角色卡下面背面朝上的卡片放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-074":{"name":"紅蓮螺巖","effectText":"這張卡片僅在自己場上有〈妮亞〉時才可發動突襲。\n這張卡片可將突襲狀態的〈螺巖〉或〈紅蓮〉最上面的卡片背面朝上放置在該突襲元下面，並在該突襲元上發動突襲。\n【突襲】〈西蒙〉置為活動，並可移動至前線\n【衝擊（1）】（攻擊後戰勝時，給予對手1點傷害）\n【登場時】抽1張卡片。發動以下所有效果。\n・若這張角色卡下面有背面朝上的卡片時，抽1張卡片。\n・若自己的卡組在20張以下時，這張角色卡在這個回合中，獲得BP+1000與【傷害（2）】。若在5張以下時，這張角色卡在這個回合中再BP+3000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-076":{"name":"螺巖","effectText":"【突襲】〈西蒙〉置為活動，並可移動至前線\n【登場時】查看2張自己卡組上面的卡片，將其中1張加入手牌，其餘卡片放置在場外。\n【啟動主要】【轉為休息】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA56BT/TTG-1-077":{"name":"大紅蓮","effectText":"【登場時】從自己場外將最多1張［特徵：顏面］加入手牌。","triggerText":""},"UA56BT/TTG-1-070":{"name":"羅修","effectText":"若自己場上沒有〈卡米那〉時，自己持有【突襲】的〔〈紅蓮〉與〈紅蓮螺巖〉〕可發動突襲在這張角色卡上。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-078":{"name":"相信相信著你的我！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA56BT/TTG-1-079":{"name":"我就是我，挖洞的西蒙！","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA56BT/TTG-1-075":{"name":"大紅蓮團的顏面","effectText":"【啟動主要】【每回合1】若自己場上有〈妮亞〉時，自己場上每有1張［特徵：顏面］，從以下選擇最多1項。（不能選擇相同的選項）\n・這張角色卡在這個回合中，BP+1000。\n・這張角色卡直到下一個自己回合開始時為止，獲得【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）。\n・這張角色卡直到下一個自己回合開始時為止，獲得【雙重防禦】（這張角色卡在這個回合中初次防禦時，將其置為活動）。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-080":{"name":"你以為我是誰啊！","effectText":"這張卡片僅在自己場上或自己的角色卡的突襲元有〈卡米那〉時才能使用。\n從自己場外將最多1張〈螺巖〉或〈紅蓮〉或〈紅蓮螺巖〉加入手牌。在這個回合中，下一次從手牌發動突襲的〈螺巖〉或〈紅蓮〉或〈紅蓮螺巖〉的消耗AP-1。","triggerText":""},"UA56BT/TTG-1-069":{"name":"李龍","effectText":"【啟動主要】【轉為休息】【使這張卡片退場】從自己場外將1張［特徵：顏面］加入手牌。","triggerText":""},"UA56BT/TTG-1-081":{"name":"巨鑽爆擊","effectText":"選擇1張對手場上『BP3000以下』的角色卡，使其退場。若自己場上或自己的角色卡的突襲元有〔〈西蒙〉或〈卡米那〉〕時，替換為『BP5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA57BT/STG-1-001":{"name":"阿萬音鈴羽","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-003":{"name":"阿萬音鈴羽","effectText":"這張角色卡以活動狀態在場上登場。\n【登場時】可以將1張自己的手牌放置在場外。若如此做，從自己的場外將最多1張能源需求3以下且不具有\n【最終觸發】的事件卡加入手牌。【啟動主要】【每回合1】選擇1張這個回合中曾因自己的效果從活動變為休息的自己場上其他角色卡，將其置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-004":{"name":"阿萬音鈴羽","effectText":"【我方回合中】在這個回合中自己使用了事件卡時，這張角色卡BP+1000。\n【登場時】自己場外能源需求3以下的藍色事件卡的【觸發】為3種以下時，抽1張卡片，並將1張自己的手牌放置在場外。為4種以上時，抽1張卡片。","triggerText":""},"UA57BT/STG-1-006":{"name":"漆原琉華","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-005":{"name":"漆原琉華","effectText":"【雙重防禦】（這張角色卡在這個回合的第一次防禦時置為活動）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-007":{"name":"岡部倫太郎","effectText":"","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-002":{"name":"阿萬音鈴羽","effectText":"","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-009":{"name":"岡部倫太郎","effectText":"【登場時】自己場上有〈椎名真由里〉時，抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-008":{"name":"岡部倫太郎","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。\n【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-011":{"name":"岡部倫太郎","effectText":"這張卡片因手牌或線路的張數上限處理而要放置到移除區時，改為放置到場外。 自己的場外有7張以上藍色的〈椎名真由里〉，且這張角色卡要離開場上時，可以改為將這張卡片放置到移除區。\n【突襲】〈岡部倫太郎〉置為活動，並可移動至前線\n【登場時】從自己的場外將最多1張能源需求為『2以下』且消耗AP為1的藍色〈椎名真由里〉以休息狀態在自己場上登場，或使其發動突襲。若這張角色卡是從移除區登場，則改為『4以下』。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-010":{"name":"岡部倫太郎","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去\n【衝擊】）【登場時】查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。【啟動主要】【每回合1】將自己前線1張活動狀態的〈牧瀨紅莉栖〉置為休息。若如此做，從以下選擇1項。\n・這張角色卡在這個回合中獲得【衝擊（1）】。\n・選擇最多1張對手前線BP1500以上的角色卡，在這個回合中BP-1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-012":{"name":"桐生萌郁","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【藍】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA57BT/STG-1-013":{"name":"桐生萌郁","effectText":"【登場時】可使1張自己場上其他的角色卡退場。若有執行此動作時，抽2張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-015":{"name":"椎名真由里","effectText":"【登場時】查看自己卡組上面的4張卡片，公開其中最多1張〈岡部倫太郎〉、〈椎名真由里〉或〈橋田至〉並加入手牌。其餘卡片以任意順序放置在卡組下面。若有加入手牌，將1張自己的手牌放置在場外。","triggerText":""},"UA57BT/STG-1-014":{"name":"椎名真由里","effectText":"【退場時】自己場上有〈岡部倫太郎〉時，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA56BT/TTG-1-072":{"name":"紅蓮","effectText":"【突襲】〈卡米那〉置為活動，並可移動至前線\n【我方回合中】這張角色卡BP+500。\n【登場時】抽1張卡片。選擇最多1張對手前線BP3000以下的角色卡，轉為休息。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-016":{"name":"椎名真由里","effectText":"【登場時】查看自己卡組上面的『2張』卡片，將任意張數以任意順序放置在卡組上面，其餘放置在場外。若這張角色卡是因角色卡的效果而登場，則改為『3張』。","triggerText":""},"UA57BT/STG-1-018":{"name":"椎名真由里","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去\n【衝擊】）\n【登場時】若這張角色卡不是因角色卡的效果而登場，直到下次自己回合開始時為止，這張角色卡獲得「對手攻擊階段結束時，使這張角色卡退場。」。【攻擊時】查看自己卡組上面的3張卡片，公開其中最多1張〈岡部倫太郎〉、〈椎名真由里〉、〈橋田至〉或〈真由氏～的懷懷停了……〉並加入手牌。其餘卡片以任意順序放置在卡組下面。若有加入手牌，將1張自己的手牌放置在場外。【啟動主要】將這張角色卡置為活動。〈椎名真由里〉的這個效果每回合僅可發動1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-020":{"name":"橋田至","effectText":"【我方回合中】在這個回合中自己使用了事件卡時，這張角色卡BP+1500。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-021":{"name":"橋田至","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・選擇自己場上最多1張〈阿萬音鈴羽〉或〈橋田至〉，在這個回合中BP+2000。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-019":{"name":"天王寺綯","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA57BT/STG-1-023":{"name":"菲伊麗絲・喵喵","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【藍】。","triggerText":""},"UA57BT/STG-1-017":{"name":"椎名真由里","effectText":"【突襲】〈椎名真由里〉置為活動，並可移動至前線\n【登場時】抽1張卡片。選擇最多1張對手前線的角色卡。直到下次自己回合開始時為止，『所選角色卡獲得「這張角色卡無法攻擊。」；這張〈椎名真由里〉獲得「對手攻擊階段結束時，使這張角色卡退場。」』。若這張〈椎名真由里〉是因角色卡的效果而登場，則改為『所選角色卡獲得「這張角色卡無法攻擊也無法防禦。」』。\n【攻擊時】選擇自己場上最多1張角色卡，在這個回合中BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-022":{"name":"菲伊麗絲・喵喵","effectText":"這張角色卡不受使BP降低的效果影響。\n【我方回合中】這張角色卡BP+500。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-025":{"name":"牧瀨紅莉栖","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【藍×2】。 當這張角色卡被突襲時，若自己場外能源需求3以下的藍色事件卡的【觸發】有3種以上，抽1張卡片。（突襲角色卡的【登場時】與這個效果可以任意順序處理）","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA57BT/STG-1-028":{"name":"牧瀨紅莉栖","effectText":"【突襲】〈牧瀨紅莉栖〉置為活動，並可移動至前線\n【啟動主要】\n【若在前線時】在這個回合中，接下來從手牌使用的1張能源需求3以下且不具有【最終觸發】的事件卡，其消耗AP-1。〈牧瀨紅莉栖〉的這個效果每回合僅可發動1次。【啟動主要】【若在前線時】【每回合1】僅可在這張角色卡為休息狀態時發動。選擇自己場上1張其他角色卡，在這個回合中BP+2000。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-029":{"name":"牧瀨紅莉栖","effectText":"【突襲】〈牧瀨紅莉栖〉置為活動，並可移動至前線\n【登場時】選擇對手前線最多1張BP在「自己場外能源需求3以下的藍色事件卡的【觸發】種類數×1000」以下的角色卡，使其退場。若自己場外能源需求3以下的藍色事件卡的【觸發】有5種以上，這張角色卡在這個回合中獲得【衝擊（1）】。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-027":{"name":"牧瀨紅莉栖","effectText":"【登場時】可以將1張自己的手牌放置在場外。若如此做，從自己的場外將最多1張能源需求3以下的〈岡部倫太郎〉加入手牌。\n【啟動主要】【轉為休息】【將1張手牌放置在場外】【每回合1】使自己移除區1張已滿足能源需求的〈岡部倫太郎〉發動突襲，該角色卡在這個回合中BP+1000並獲得【衝擊（1）】。這張角色卡在這個回合中獲得「無法對這張角色卡發動突襲。」與「主要階段結束時，使這張角色卡退場。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-030":{"name":"伯朗先生","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-031":{"name":"未來工具研究所","effectText":"【登場時】查看自己卡組上面的3張卡片，公開其中最多1張角色卡並加入手牌。其餘卡片以任意順序放置在卡組下面。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-032":{"name":"El Psy Kongroo","effectText":"抽2張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-026":{"name":"牧瀨紅莉栖","effectText":"【登場時】查看自己卡組上面的『3張』卡片，公開其中最多1張能源需求3以下且不具有【最終觸發】的事件卡並加入手牌。其餘卡片以任意順序放置在卡組下面。若有加入手牌，將1張自己的手牌放置在場外。若自己場外能源需求3以下的藍色事件卡的【觸發】有3種以上，則改為查看『5張』。","triggerText":""},"UA57BT/STG-1-033":{"name":"Operation．Skuld","effectText":"查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。之後，從自己的場外將最多1張能源需求為『3以下』且消耗AP為1的藍色角色卡以休息狀態在自己場上登場，或使其發動突襲。選擇自己場上最多1張角色卡，將其置為活動。若自己場外能源需求3以下的藍色事件卡的【觸發】有5種以上，則改為『4以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA57BT/STG-1-034":{"name":"這就是命運石之門的選擇","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA57BT/STG-1-036":{"name":"星塵握手","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA57BT/STG-1-039":{"name":"真由氏～的巴掌","effectText":"從以下選擇最多2項。若自己場外能源需求3以下的其他藍色事件卡的【觸發】有3種以上，將自己1張AP卡置為活動。\n・選擇自己場上1張角色卡，將其置為活動。\n・選擇自己場上1張角色卡，在這個回合中BP+2000。\n・選擇對手前線1張角色卡，將其置為休息。〈真由氏～的巴掌〉的這個效果每回合僅可選擇1次。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-037":{"name":"跨越1％的世界線變動率之壁","effectText":"這張卡片僅可在自己場上有〈岡部倫太郎〉時使用。 選擇1張對手前線BP5000以下的角色卡，使其退場。若自己的場外有7張以上藍色的〈椎名真由里〉，可以將自己場上或場外最多1張〈岡部倫太郎〉放置到移除區。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA57BT/STG-1-040":{"name":"當然。呵～哈哈哈！","effectText":"選擇自己場上1張〈牧瀨紅莉栖〉，在這個回合中使其BP+1500並獲得「這張角色卡不會被BP4000以上的角色卡防禦。」。若自己場外能源需求3以下的其他藍色事件卡的【觸發】有3種以上，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-042":{"name":"阿萬音鈴羽","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-041":{"name":"秋葉留未穗","effectText":"【登場時】可以使自己場上1張場域退場。若如此做，從自己的場外將最多1張與以這個效果退場的場域卡名不同的綠色場域卡，以休息狀態在自己的能源線登場。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-045":{"name":"阿萬音鈴羽","effectText":"【階梯】（在自己的移動階段可以從前線移動至能源線）【我方回合中】自己場上其他所有角色卡獲得【階梯】。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-038":{"name":"真由氏～的懷懷停了……","effectText":"從自己的場外或移除區，將1張已滿足能源需求且消耗AP為1的〈岡部倫太郎〉以休息狀態在自己場上登場，或使其發動突襲。若以這個效果從移除區使該〈岡部倫太郎〉發動突襲，該角色卡在這個回合中獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。","triggerText":"[顔色] 選擇1張對手前線BP3500以下的角色卡，放回手牌。"},"UA57BT/STG-1-044":{"name":"阿萬音鈴羽","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少【綠×2】。 自己的攻擊階段開始時，若自己的前線有空位，這張角色卡在這個回合中BP+1000。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-043":{"name":"阿萬音鈴羽","effectText":"【攻擊時】若這個回合中自己使用了事件卡，可以抽1張卡片。若如此做，將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-048":{"name":"漆原琉華","effectText":"【啟動主要】【每回合1】僅可在這個回合中自己已使用事件卡時發動。直到下次自己回合開始時為止，這張角色卡BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-024":{"name":"牧瀨紅莉栖","effectText":"【登場時】查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-046":{"name":"阿萬音鈴羽","effectText":"【每回合1】這張角色卡攻擊結束時，若自己的前線有空位，可以將1張自己的手牌放置在場外。若如此做，將這張角色卡置為活動，並選擇自己場上最多1張角色卡，在這個回合中BP+1000。【若在能源線時】自己角色卡攻擊結束時，若自己的前線有空位，可以將這張角色卡移動至前線。【登場時】抽1張卡片。將這張角色卡置為活動。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-051":{"name":"岡部倫太郎","effectText":"這張角色卡在對戰中獲勝時，若這張角色卡在這個回合中曾移動，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-049":{"name":"漆原琉華","effectText":"若自己場上沒有任何卡片時，手牌中這張卡片的能源需求減少\n【綠×2】。【登場時】查看自己卡組上面的4張卡片，公開其中最多1張場域卡或〈D郵件〉並加入手牌。其餘卡片以任意順序放置在卡組下面。若有加入手牌，將1張自己的手牌放置在場外。","triggerText":""},"UA57BT/STG-1-047":{"name":"漆原琉華","effectText":"【登場時】查看1張自己卡組上面的卡片，將該張卡片放置在自己卡組的上面或場外。","triggerText":""},"UA57BT/STG-1-052":{"name":"岡部倫太郎","effectText":"若這張角色卡為活動時，這張角色卡的產生能源+【綠】。","triggerText":""},"UA57BT/STG-1-050":{"name":"漆原琉華","effectText":"【啟動主要】【若在前線時】【每回合1】選擇自己場上1張消耗AP為1且不具有【突襲】的其他角色卡，在這個回合中獲得以下其中1項。這個回合中〈漆原琉華〉已選擇過的效果無法再次選擇。\n・這張角色卡不會被BP4000以上的角色卡防禦。\n・BP+1000，並獲得「在這個回合中自己使用了事件卡時，這張角色卡獲得【衝擊（1）】。」。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-054":{"name":"桐生萌郁","effectText":"【登場時】可以將1張自己的手牌放置在場外。若如此做，從自己的場外將最多1張〈IBN5100〉加入手牌。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-057":{"name":"椎名真由里","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-055":{"name":"桐生萌郁","effectText":"【啟動主要】【每回合1】僅可在這個回合中自己已使用事件卡時發動。直到下次自己回合開始時為止，這張角色卡獲得「這張角色卡若在前線時也可產生能源。」。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-035":{"name":"欺騙過去的自己 欺騙世界","effectText":"將自己前線1張活動狀態的〈牧瀨紅莉栖〉置為休息。若如此做，抽3張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-058":{"name":"椎名真由里","effectText":"【若在能源線時】自己的攻擊階段結束時，若自己的前線有空位，可以將這張角色卡移動至自己的前線。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-059":{"name":"椎名真由里","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）【登場時】從自己的手牌將最多1張能源需求2以下且消耗AP為1的綠色〔〈阿萬音鈴羽〉、〈岡部倫太郎〉、〈椎名真由里〉、〈橋田至〉或〈牧瀨紅莉栖〉〕以休息狀態在自己場上登場。","triggerText":""},"UA57BT/STG-1-053":{"name":"桐生萌郁","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）","triggerText":""},"UA57BT/STG-1-056":{"name":"桐生萌郁","effectText":"【衝擊無效】（與這張角色卡對戰的角色卡在這場對戰中，失去【衝擊】）【登場時】可以使自己場上1張其他卡片退場。若如此做，選擇對手前線最多1張角色卡，將其移動至能源線。若這個回合中自己使用了事件卡，直到下次自己回合開始時為止，所選角色卡獲得「這張角色卡無法移動。」。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA57BT/STG-1-060":{"name":"椎名真由里","effectText":"【突襲】〈椎名真由里〉置為活動，並可移動至前線\n【攻擊時】選擇自己場上最多1張角色卡，在這個回合中BP+1000。若自己的前線有空位且所選角色卡位於能源線，將該角色卡移動至前線。\n【退場時】選擇自己能源線最多1張角色卡，在這個回合中BP+2000，並將其移動至前線。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-064":{"name":"菲伊麗絲・喵喵","effectText":"","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-063":{"name":"橋田至","effectText":"【登場時】將1張自己場上其他能源需求1以下的角色卡放回手牌。若無法放回手牌時，將這張角色卡放回手牌。","triggerText":""},"UA57BT/STG-1-062":{"name":"橋田至","effectText":"【啟動主要】【轉為休息】選擇1張自己場上其他的角色卡，在這個回合中，BP+1000。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-066":{"name":"菲伊麗絲・喵喵","effectText":"【突襲】〈菲伊麗絲・喵喵〉置為活動，並可移動至前線\n【登場時】抽最多1張卡片。選擇自己場上最多1張角色卡，在這個回合中BP+1000。\n【攻擊時】若這個回合中自己使用了事件卡且自己場上有場域，使這張角色卡的【登場時】發動。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-067":{"name":"牧瀨紅莉栖","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-061":{"name":"橋田至","effectText":"【啟動主要】【轉為休息】【每回合1】這張角色卡在這個回合中，獲得產生能源+【綠】與「主要階段結束時，使這張角色卡退場。」。","triggerText":""},"UA57BT/STG-1-069":{"name":"牧瀨紅莉栖","effectText":"【登場時】從以下選擇1項。\n・抽1張卡片，並將1張自己的手牌放置在場外。\n・選擇自己場上最多1張其他角色卡，在這個回合中BP+1000。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA57BT/STG-1-068":{"name":"牧瀨紅莉栖","effectText":"【登場時】查看自己卡組上面的3張卡片，公開其中最多1張〈阿萬音鈴羽〉、〈岡部倫太郎〉、〈椎名真由里〉、〈橋田至〉或〈牧瀨紅莉栖〉並加入手牌。其餘卡片以任意順序放置在卡組下面。若有加入手牌，將1張自己的手牌放置在場外。","triggerText":""},"UA57BT/STG-1-065":{"name":"菲伊麗絲・喵喵","effectText":"【登場時】查看3張自己卡組上面的卡片，將其中最多1張卡片放置在場外，其餘卡片依任意順序放置在自己卡組的上面。","triggerText":""},"UA57BT/STG-1-070":{"name":"牧瀨紅莉栖","effectText":"【突襲】〈牧瀨紅莉栖〉置為活動，並可移動至前線\n【登場時】選擇自己場上最多1張其他角色卡，直到下次自己回合開始時為止，獲得「這張角色卡不會被對手的效果選擇。」。\n【攻擊時】從以下選擇1項。\n・這張角色卡在這個回合中獲得【衝擊（1）】。\n・若自己的前線有空位，抽2張卡片，並將1張自己的手牌放置在場外。","triggerText":"[突襲] 將這張卡片加入手牌，或若是滿足能源需求時，可發動突襲。"},"UA57BT/STG-1-071":{"name":"IBN5100","effectText":"【登場時】可以將自己手牌中的1張事件卡或場域卡放置在場外。若如此做，查看自己卡組上面的2張卡片，將其中1張加入手牌，其餘放置在場外。\n【退場時】從以下選擇1項。\n・選擇自己場上最多1張〈桐生萌郁〉，將其置為活動。\n・抽1張卡片。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-074":{"name":"我是狂氣的瘋狂科學家！鳳凰院凶真！","effectText":"自己場上所有角色卡在這個回合中BP+1000。選擇自己場上最多1張消耗AP為1的角色卡，在這個回合中獲得【衝擊（1）】（攻擊後戰勝時，造成對手玩家1傷害）。若自己場上有〈岡部倫太郎〉，抽1張卡片。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-075":{"name":"但是是男的","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA57BT/STG-1-076":{"name":"才不是傲嬌！","effectText":"選擇1張對手前線BP『3000以下』的角色卡，使其退場。若自己場上有〈牧瀨紅莉栖〉，則改為『5000以下』。","triggerText":"[特別] 選擇1張對手前線的角色卡，使其退場。"},"UA57BT/STG-1-077":{"name":"D郵件","effectText":"將自己場上1張活動狀態的場域置為休息。若如此做，抽1張卡片，並將1張自己的手牌放置在場外。從自己的手牌將最多1張能源需求4以下、消耗AP為1且不具有【突襲】的綠色角色卡，以活動狀態在自己場上登場。 發動這張卡片的【顏色觸發】時，可以將效果中記載的「能源需求2以下且消耗AP為1的綠色角色卡」改為「綠色場域卡」。","triggerText":"[顔色] 使1張自己手牌中能源需求2以下消耗AP1的綠色角色卡以活動狀態在自己場上登場。"},"UA57BT/STG-1-078":{"name":"嘟嘟嚕～♪","effectText":"選擇最多2張自己的AP卡，置為活動。","triggerText":"[最終] 若自己沒有生命卡時，將1張自己卡組上面的卡片放置在自己的生命區。"},"UA57BT/STG-1-073":{"name":"MayQueen+娘²","effectText":"【登場時】抽1張卡片，並將1張自己的手牌放置在場外。\n【退場時】抽1張卡片。","triggerText":"[活動] 選擇1張自己場上的角色卡，置為活動，在這個回合中，BP+3000。"},"UA57BT/STG-1-072":{"name":"電話微波爐（暫名）","effectText":"【登場時】從自己的場外將最多1張〈D郵件〉加入手牌。若為自己的回合，選擇自己場上最多1張角色卡，在這個回合中BP+1000。","triggerText":"[獲得] 將這張卡片加入手牌。"},"UA57BT/STG-1-079":{"name":"工讀生戰士","effectText":"抽1張卡片。選擇自己場上最多1張〈阿萬音鈴羽〉，在這個回合中使其BP+1000並獲得「【攻擊時】抽1張卡片。」。","triggerText":"[抽卡] 抽1張卡片。"},"UA57BT/STG-1-080":{"name":"看著眼睛攪拌攪拌","effectText":"查看自己卡組上面的5張卡片，公開其中最多1張並加入手牌。其餘卡片以任意順序放置在卡組下面。若公開的卡片為〈菲伊麗絲・喵喵〉或場域卡，將自己1張AP卡置為活動。","triggerText":""}};